INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Jackiexiao/jackie-skills-creator/baoyu-cover-image', 'baoyu-cover-image', 'Jackiexiao', 'jackie-skills-creator', 'community', 'baoyu-cover-image Jackiexiao jackie-skills-creator community baoyu-cover-image是一款集成OpenClaw技能的AI智能工具，提供一键式解决方案 baoyu-cover-imageは、OpenClawスキルを統合したAIエージェントです baoyu-cover-image는 OpenClaw 스킬을 통합한 AI 에이전트입니다 Paquete de habilidades de OpenClaw curadas con un solo comando para desarrolladores Pack de compétences OpenClaw curator avec une seule commande pour les développeurs Kuratiertes OpenClaw-Skill-Paket mit einem einzigen Befehl für Entwickler Abaoyu-cover-image é uma ferramenta de imagem de capa em AI que simplifica o processo de criação de conteúdo. Baoyu-cover-image - это инструмент для создания обложек в AI, который упрощает процесс создания контента. baoyu-cover-image هي أداة إدارة الصور في AI التي تبسط عملية إنشاء المحتوى. Curated one-command OpenClaw skills pack AI智能工具 OpenClaw技能包 一键式解决方案 开发效率提升 CLI命令 baoyu-cover-image安装 baoyu-cover-image教程 Curated one-command OpenClaw skills pack');
