INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('richardgill/nix/tmux-debug', 'tmux-debug', 'richardgill', 'nix', 'community', 'tmux-debug richardgill nix community tmux-debug is a skill that allows developers to capture screen content from tmux panes and debug other terminal sessions. It benefits developers who need to monitor background processes or inspect command output. tmux-debug是用于捕获tmux面板内容的工具，用于调试其他终端会话、监控后台进程或检查命令输出 tmux-debugは、tmuxパネルの内容をキャプチャするツールで、他のターミナルセッションのデバッグ、バックグラウンドプロセスの監視、コマンド出力的検査に使用 tmux-debug는 tmux 패널 내용을 캡처하는 도구로서, 다른 터미널 세션의 디버깅, 백그라운드 프로세스 모니터링, 명령어 출력 검사에 사용 tmux-debug es una herramienta para capturar contenido de pantalla de paneles tmux y depurar otras sesiones de terminal tmux-debug est un outil pour capturer le contenu de l''écran des panneaux tmux et déboguer d''autres sessions de terminal tmux-debug ist ein Werkzeug, um Bildschirminhalte von tmux-Panes zu erfassen und andere Terminal-Sitzungen zu debuggen O Tmux Debug é uma ferramenta para capturar conteúdo de telas de painéis Tmux e depurar outras sessões de terminal Tmux Debug — это инструмент для захвата экрана панелей Tmux и отладки других терминальных сессий Tmux Debug هو أداة لالتقاط المحتوى الشاشة من ألواح Tmux وتصحيح أخطاء الجلسات النصية الأخرى how to use tmux-debug tmux-debug alternative tmux-debug setup guide what is tmux-debug tmux-debug vs screen tmux-debug install debugging terminal sessions capturing tmux pane content tmux list-panes command tmux capture-pane command tmux-debug 终端调试 监控工具 命令输出检查 ANSI颜色支持 AIエージェント 终端会话管理 Captures screen content from tmux panes using tmux capture-pane command Lists all panes using tmux list-panes command with -a and -F options Supports capturing current pane with tmux capture-pane -p command Allows capturing specific pane using tmux capture-pane -t command Preserves ANSI colors with tmux capture-pane -p -e command tmux-debug is a terminal debugging tool that captures screen content from tmux panes to facilitate debugging of other terminal sessions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('edwnh/dqmc/dqmc-analyze', 'community', 'edwnh', 'dqmc', 'edwnh/dqmc', 'dqmc-analyze', 0, 0, 51, '2026-03-07T12:46:33.396Z', '2026-03-07T12:51:40.033Z', '42f232bde81522a141b371bfba2c16a4e4c9ffb49ebc7882d089f59674c6ad65', '{"id":"edwnh/dqmc/dqmc-analyze","name":"dqmc-analyze","description":{"en":"dqmc-analyze is a technical skill that analyzes simulation results, providing developers with valuable parameters and statistics. It benefits AI agent developers working with simulation data.","zh":"dqmc-analyze是一个用于分析模拟结果的工具，支持Python集成和数据分析","ja":"dqmc-analyzeはシミュレーション結果を分析するためのツールで、Pythonとの統合やデータ分析が可能","ko":"dqmc-analyze는 시뮬레이션 결과를 분석하는 도구로 Python 통합과 데이터 분석을 지원합니다","es":"dqmc-analyze es una herramienta para analizar resultados de simulaciones y obtener parámetros con errores estándar","fr":"dqmc-analyze est un outil pour analyser les résultats de simulations et obtenir des paramètres avec des erreurs standard","de":"dqmc-analyze ist ein Tool zur Analyse von Simulationsergebnissen und zur Gewinnung von Parametern mit Standardfehlern","pt":"O dqmc-analyze é uma ferramenta para análise de simulações que fornece resultados precisos com Python. Aprenda a configurá-lo para obter os melhores resultados.","ru":"ИИ Агент dqmc-analyze - это инструмент для анализа результатов симуляций, который предоставляет точные результаты с помощью Python. Узнайте, как его настроить.","ar":"dqmc-analyze هو أداة لتحليل نتائج Симуляций التي توفر نتائج دقيقة باستخدام Python. تعلم كيفية إعداده للحصول على أفضل النتائج"},"seo":{"title":{"en":"dqmc-analyze: Analyze Simulation Results for AI Agents | ...","zh":"dqmc-analyze Setup Guide: Python AI工具","ja":"dqmc-analyze の設定方法: Python AIエージェント","ko":"dqmc-analyze 설정 가이드: Python AI 에이전트","es":"Guía de configuración para dqmc-analyze: Análisis de resu...","fr":"Guide de configuration pour dqmc-analyze : Analyse de rés...","de":"Konfigurationsleitfaden für dqmc-analyze: Ergebnisanalyse","pt":"Guia de Configuração do dqmc-analyze para Análise de Simu...","ru":"ИИ Агенты: Настройка dqmc-analyze для Анализа Результатов...","ar":"إعداد dqmc-analyze لتحليل نتائج Симуляций"},"description":{"en":"Unlock insights from simulation data with dqmc-analyze. Learn how to analyze results and extract valuable parameters - get started now!","zh":"了解dqmc-analyze的设置和使用方法，包括Python集成和数据分析","ja":"dqmc-analyzeの設定と利用方法を学びます。Pythonとの統合やデータ分析など","ko":"dqmc-analyze 설정과 사용 방법을 알아보세요. Python 통합 및 데이터 분석 등","es":"Aprende a utilizar dqmc-analyze para analizar resultados de simulaciones y obtener parámetros con errores estándar","fr":"Découvrez comment utiliser dqmc-analyze pour analyser les résultats de simulations et obtenir des paramètres avec des erreurs standard","de":"Erfahren Sie, wie Sie dqmc-analyze verwenden, um Simulationsergebnisse zu analysieren und Parameter mit Standardfehlern zu erhalten","pt":"Aprenda a configurar o dqmc-analyze para análise de simulações e obtenha resultados precisos com Python","ru":"Узнайте, как настроить dqmc-analyze для анализа результатов симуляций и получите точные результаты с помощью Python","ar":"تعلم كيفية إعداد dqmc-analyze لتحليل نتائج Симуляций و الحصول على نتائج دقيقة باستخدام Python"},"definition":{"en":"dqmc-analyze is a skill that analyzes results from completed simulations, extracting parameters and statistics from bin_*.h5 files.","zh":"dqmc-analyze是一种用于分析模拟结果的AI工具","ja":"dqmc-analyzeはシミュレーション結果を分析するためのAIエージェント","ko":"dqmc-analyze는 시뮬레이션 결과를 분석하는 AI 에이전트입니다","es":"dqmc-analyze es una herramienta de análisis de resultados de simulaciones que proporciona parámetros con errores estándar","fr":"dqmc-analyze est un outil d''analyse de résultats de simulations qui fournit des paramètres avec des erreurs standard","de":"dqmc-analyze ist ein Analyse-Tool für Simulationsergebnisse, das Parameter mit Standardfehlern bereitstellt","pt":"O dqmc-analyze é uma ferramenta de análise de simulações que fornece resultados precisos com Python","ru":"ИИ Агент dqmc-analyze - это инструмент для анализа результатов симуляций","ar":"dqmc-analyze هو أداة لتحليل نتائج Симуляций"},"features":{"en":["Analyzes simulation results from directories containing bin_*.h5 files","Extracts parameters and statistics for observable names such as ''sign'', ''den'', and ''zzr''","Provides output as a dictionary with (mean, stderr) tuples for each observable","Utilizes the analyze_hub function from the dqmc_util library","Supports basic analysis of simulation results with Python"],"zh":["支持Python集成","能够分析模拟结果","提供数据分析功能","支持多个可观测变量","能够计算均值和标准误差"],"ja":["Pythonとの統合が可能","シミュレーション結果を分析可能","データ分析機能を提供","複数の可観測変数をサポート","平均値と標準誤差を計算可能"],"ko":["Python 통합 지원","시뮬레이션 결과 분석 가능","데이터 분석 기능 제공","여러 개의 관측 변수 지원","평균값과 표준 오차 계산 가능"],"es":["Análisis de resultados de simulaciones","Cálculo de parámetros con errores estándar","Compatibilidad con archivos `bin_*.h5`","Soporte para nombres de observables personalizados","Integración con la biblioteca `dqmc_util`","Implementación en Python"],"fr":["Analyse de résultats de simulations","Calcul de paramètres avec des erreurs standard","Compatibilité avec les fichiers `bin_*.h5`","Prise en charge de noms d''observables personnalisés","Intégration avec la bibliothèque `dqmc_util`","Implémentation en Python"],"de":["Analyse von Simulationsergebnissen","Berechnung von Parametern mit Standardfehlern","Kompatibilität mit Dateien `bin_*.h5`","Unterstützung für benutzerdefinierte Beobachternamen","Integration mit der Bibliothek `dqmc_util`","Implementierung in Python"],"pt":["Análise de simulações com Python","Obtenção de resultados precisos com o uso de tuplas (mean, stderr)","Suporte a observable names personalizados","Integração com o módulo dqmc_util","Análise básica de resultados com o uso de get"],"ru":["Анализ результатов симуляций с помощью Python","Получение точных результатов с помощью кортежей (mean, stderr)","Поддержка пользовательских observable names","Интеграция с модулем dqmc_util","Базовый анализ результатов с помощью get"],"ar":["تحليل نتائج Симуляций باستخدام Python","الحصول على نتائج دقيقة باستخدام أزواج (mean, stderr)","دعم أسماء observable مخصصة","التكامل مع وحدة dqmc_util","تحليل أساسي للنتائج باستخدام get"]},"keywords":{"en":["how to use dqmc-analyze","dqmc-analyze alternative","dqmc-analyze setup guide","what is dqmc-analyze","dqmc-analyze vs other analysis tools","dqmc-analyze install","analyzing simulation results with dqmc-analyze","dqmc-analyze for AI agents","dqmc-analyze tutorial"],"zh":["dqmc-analyze","Python AI工具","模拟结果分析","数据分析","可观测变量","均值和标准误差"],"ja":["dqmc-analyze","Python AIエージェント","シミュレーション結果分析","データ分析","可観測変数","平均値と標準誤差"],"ko":["dqmc-analyze","Python AI 에이전트","시뮬레이션 결과 분석","데이터 분석","관측 변수","평균값과 표준 오차"],"es":["dqmc-analyze","análisis de resultados de simulaciones","parámetros con errores estándar","Python","biblioteca dqmc_util","archivos bin_*.h5","nombres de observables personalizados","herramientas de análisis de simulaciones"],"fr":["dqmc-analyze","analyse de résultats de simulations","paramètres avec des erreurs standard","Python","bibliothèque dqmc_util","fichiers bin_*.h5","noms d''observables personnalisés","outils d''analyse de simulations"],"de":["dqmc-analyze","Analyse von Simulationsergebnissen","Parameter mit Standardfehlern","Python","Bibliothek dqmc_util","Dateien bin_*.h5","benutzerdefinierte Beobachternamen","Tools zur Analyse von Simulationsergebnissen"],"pt":["dqmc-analyze","análise de simulações","Python","resultados precisos","tuplas mean stderr","observable names","dqmc_util"],"ru":["ИИ Агенты","dqmc-analyze","анализ результатов симуляций","Python","точные результаты","кортежи mean stderr","observable names","dqmc_util"],"ar":["أدوات الذكاء الاصطناعي","dqmc-analyze","تحليل نتائج Симуляций","Python","نتائج دقيقة","أزواج mean stderr","observable names","dqmc_util"]}},"owner":"edwnh","repo":"dqmc","repoPath":"edwnh/dqmc","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.396Z","topics":[],"category":"community","skillMd":{"name":"dqmc-analyze","description":"Extract physical observables with error estimates from completed DQMC simulations. Use when computing density, double occupancy, spin correlations, structure factors, or any measured quantity from simulation data.","bodyPreview":"# Analyze Results\n\n## Inputs\n\n- Directory containing `bin_*.h5` files (completed simulations)\n- Observable names (see table below)\n\n## Outputs\n\n- Dictionary with parameters and `(mean, stderr)` tuples for each observable\n\n## Procedure\n\n**Basic analysis:**\n```python\nfrom dqmc_util import analyze_hub\n\ndata = analyze_hub.get(\"data/run/\", \"sign\", \"den\", \"zzr\")\n\nprint(f\"sign = {data[''sign''][0]:.4f} +/- {data[''sign''][1]:.4f}\")\nprint(f\"density = {data[''den''][0]:.4f} +/- {data[''den''][1]:.4f}\")\n```\n\n**Av","body":"# Analyze Results\n\n## Inputs\n\n- Directory containing `bin_*.h5` files (completed simulations)\n- Observable names (see table below)\n\n## Outputs\n\n- Dictionary with parameters and `(mean, stderr)` tuples for each observable\n\n## Procedure\n\n**Basic analysis:**\n```python\nfrom dqmc_util import analyze_hub\n\ndata = analyze_hub.get(\"data/run/\", \"sign\", \"den\", \"zzr\")\n\nprint(f\"sign = {data[''sign''][0]:.4f} +/- {data[''sign''][1]:.4f}\")\nprint(f\"density = {data[''den''][0]:.4f} +/- {data[''den''][1]:.4f}\")\n```\n\n**Available observables:**\n\n| Name | Description | Requires |\n|------|-------------|----------|\n| `sign` | Fermion sign | - |\n| `den` | Density <n> | - |\n| `docc` | Double occupancy <n_up n_down> | - |\n| `gr`, `gk` | Green''s function (real/k-space) | - |\n| `nnr`, `nnq` | Density correlator / structure factor | - |\n| `zzr`, `zzq` | Spin-z correlator / structure factor | - |\n| `xxr` | Spin-x correlator | - |\n| `swq0` | S-wave pair structure factor | - |\n| `nnrw0`, `zzrw0` | Zero-freq susceptibilities | `period_uneqlt > 0` |\n| `dwq0t` | D-wave pair susceptibility | `period_uneqlt > 0` |\n\n**Collect from multiple directories:**\n```python\nimport os\n\ndef collect_results(base_dir, observables):\n    results = []\n    for subdir in sorted(os.listdir(base_dir)):\n        path = os.path.join(base_dir, subdir)\n        if os.path.isdir(path):\n            try:\n                results.append(analyze_hub.get(path + \"/\", *observables))\n            except Exception as e:\n                print(f\"Skipping {path}: {e}\")\n    return results\n```\n\n**Compute derived quantities:**\n```python\n# Magnetic moment squared from spin correlator\npath = \"data/run/\"\ndata = analyze_hub.get(path, \"zzr\")\nmz2 = 4 * data[\"zzr\"][0][0, 0]       # [0] = mean, shape (Ny, Nx)\nmz2_err = 4 * data[\"zzr\"][1][0, 0]   # [1] = stderr\n```\n\n## Validation\n\n- [ ] Errorbar on sign is significantly less than mean. Otherwise, sign problem is too severe.\n- [ ] Errorbars on observable are reasonable (not >> mean)\n\n## Failure Modes\n\n| Symptom | Cause | Recovery |\n|---------|-------|----------|\n| KeyError for observable | Observable not computed | Check `period_uneqlt` setting |\n| \"No files found\" | Wrong path or no `bin_*.h5` | Verify directory structure |\n| Large error bars | Insufficient statistics | Run more sweeps or bins |\n"},"lastSynced":"2026-03-07T12:51:40.033Z","agentAnalysis":{"suitability":{"en":"Perfect for Scientific Computing Agents needing advanced simulation data analysis capabilities with Python","zh":"适合需要使用Python进行高级模拟数据分析的科学计算代理","ja":"Pythonを使用して高度なシミュレーションデータ分析機能を必要とする科学計算エージェントに適しています","ko":"Python을 사용하여 고급 시뮬레이션 데이터 분석 기능이 필요한 과학 계산 에이전트에 적합합니다","es":"Perfecto para agentes de computación científica que necesitan capacidades avanzadas de análisis de datos de simulación con Python","fr":"Parfait pour les agents de calcul scientifique nécessitant des capacités avancées d''analyse de données de simulation avec Python","de":"Perfekt für wissenschaftliche Computing-Agents, die erweiterte Simulationsdatenanalysefunktionen mit Python benötigen","pt":"Perfeito para Agentes de Computação Científica que precisam de capacidades avançadas de análise de dados de simulação com Python","ru":"Идеально подходит для агентов научных вычислений, требующих продвинутых возможностей анализа данных симуляции с помощью Python","ar":"مثالي لعميل حوسبة علمية يحتاج إلىقدرات متقدمة لتحليل بيانات المحاكاة باستخدام Python"},"recommendation":{"en":"Empowers agents to analyze simulation results from directories containing `bin_*.h5` files, providing valuable parameters and statistics using the `dqmc_util` library, and outputting dictionaries with mean and standard error values for observables like ''sign'' and ''den''","zh":"使代理能够分析包含`bin_*.h5`文件的目录中的模拟结果，使用`dqmc_util`库提供有价值的参数和统计数据，并输出可观测量（如''sign''和''den''）的均值和标准误差值的字典","ja":"`bin_*.h5`ファイルを含むディレクトリ内のシミュレーション結果を分析し、`dqmc_util`ライブラリを使用して有価値なパラメータと統計を提供し、''sign''や''den''などの可観測量の平均値と標準誤差値の辞書を出力するエージェントを可能にします","ko":"`bin_*.h5` 파일을 포함하는 디렉토리의 시뮬레이션 결과를 분석하고 `dqmc_util` 라이브러리를 사용하여 유용한 매개 변수와 통계를 제공하며 ''sign'' 및 ''den''과 같은 관찰 가능한 값의 평균 및 표준 오차 값의 사전을 출력하는 에이전트를 가능하게 합니다","es":"Permite a los agentes analizar los resultados de las simulaciones de directorios que contienen archivos `bin_*.h5`, proporcionando parámetros y estadísticas valiosas utilizando la biblioteca `dqmc_util` y generando diccionarios con valores de media y error estándar para observables como ''sign'' y ''den''","fr":"Permet aux agents d''analyser les résultats de simulation à partir de répertoires contenant des fichiers `bin_*.h5`, fournissant des paramètres et des statistiques précieuses en utilisant la bibliothèque `dqmc_util` et en produisant des dictionnaires avec des valeurs de moyenne et d''erreur standard pour des observables comme ''sign'' et ''den''","de":"Ermöglicht es den Agents, die Ergebnisse von Simulationen aus Verzeichnissen zu analysieren, die Dateien `bin_*.h5` enthalten, und liefert wertvolle Parameter und Statistiken unter Verwendung der Bibliothek `dqmc_util` und gibt Dictionaries mit Mittel- und Standardfehlerwerten für Beobachtungen wie ''sign'' und ''den'' aus","pt":"Habilita os agentes a analisar resultados de simulações de diretórios que contêm arquivos `bin_*.h5`, fornecendo parâmetros e estatísticas valiosas usando a biblioteca `dqmc_util` e produzindo dicionários com valores de média e erro padrão para observáveis como ''sign'' e ''den''","ru":"Наделяет агентов возможностью анализировать результаты симуляций из директорий, содержащих файлы `bin_*.h5`, предоставляя ценные параметры и статистику с помощью библиотеки `dqmc_util` и выдающие словари со средними и стандартными ошибками для наблюдаемых значений, таких как ''sign'' и ''den''","ar":"يمنح الوكيل khảية تحليل نتائج المحاكاة من المجلدات التي تحتوي على ملفات `bin_*.h5` ، وتقديم معلمات وإحصائيات قيمة باستخدام المكتبة `dqmc_util` ، وإخراج قواميس بقيم المتوسط والخطأ المعياري للملاحظات مثل ''sign'' و ''den''"},"useCases":{"en":["Analyzing completed simulations for key observables","Generating statistics for simulation data","Validating simulation results with mean and standard error values"],"zh":["分析完成的模拟以获取关键可观测量","为模拟数据生成统计数据","使用平均值和标准误差值验证模拟结果"],"ja":["完了したシミュレーションを分析して主要な可観測量を取得する","シミュレーションデータの統計を生成する","平均値と標準誤差値を使用してシミュレーション結果を検証する"],"ko":["완료된 시뮬레이션을 분석하여 주요 관찰 가능한 값을 얻는 것","시뮬레이션 데이터에 대한 통계를 생성하는 것","평균값 및 표준 오차 값을 사용하여 시뮬레이션 결과를 검증하는 것"],"es":["Análisis de simulaciones completadas para observables clave","Generación de estadísticas para datos de simulación","Validación de resultados de simulación con valores de media y error estándar"],"fr":["Analyse de simulations terminées pour des observables clés","Génération de statistiques pour des données de simulation","Validation des résultats de simulation avec des valeurs de moyenne et d''erreur standard"],"de":["Analyse abgeschlossener Simulationen für Schlüsselbeobachtungen","Erzeugung von Statistiken für Simulationsdaten","Validierung von Simulationsergebnissen mit Mittel- und Standardfehlerwerten"],"pt":["Analisar simulações concluídas para observáveis-chave","Gerar estatísticas para dados de simulação","Validar resultados de simulação com valores de média e erro padrão"],"ru":["Анализ завершенных симуляций для ключевых наблюдаемых","Генерация статистики для данных симуляции","Проверка результатов симуляции со средними и стандартными ошибками"],"ar":["تحليل المحاكاة المنتهية للاحتمالات الرئيسية","توليد الإحصائيات لبيانات المحاكاة","التحقق من نتائج المحاكاة بقيم المتوسط والخطأ المعياري"]},"limitations":{"en":["Requires `bin_*.h5` files in a directory","Limited to simulation data analysis","Python environment required"],"zh":["需要目录中包含`bin_*.h5`文件","仅限于模拟数据分析","需要Python环境"],"ja":["ディレクトリ内に`bin_*.h5`ファイルを必要とする","シミュレーションデータ分析のみに限定される","Python環境が必要"],"ko":["디렉토리에 `bin_*.h5` 파일이 필요","시뮬레이션 데이터 분석에만 제한됨","Python 환경이 필요"],"es":["Requiere archivos `bin_*.h5` en un directorio","Limitado al análisis de datos de simulación","Entorno de Python requerido"],"fr":["Nécessite des fichiers `bin_*.h5` dans un répertoire","Limité à l''analyse de données de simulation","Environnement Python requis"],"de":["Benötigt Dateien `bin_*.h5` in einem Verzeichnis","Begrenzt auf die Analyse von Simulationsdaten","Python-Umgebung erforderlich"],"pt":["Requer arquivos `bin_*.h5` em um diretório","Limitado à análise de dados de simulação","Ambiente Python necessário"],"ru":["Требует наличия файлов `bin_*.h5` в директории","Ограничен анализом данных симуляции","Требуется среда Python"],"ar":["يتطلب وجود ملفات `bin_*.h5` في مجلد","محدود بتحليل بيانات المحاكاة","يتطلب بيئة Python"]},"version":4},"contentHash":"42f232bde81522a141b371bfba2c16a4e4c9ffb49ebc7882d089f59674c6ad65","qualityScore":51}');
