INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('edwnh/dqmc/dqmc-analyze', 'dqmc-analyze', 'edwnh', 'dqmc', 'community', 'dqmc-analyze edwnh dqmc community dqmc-analyze is a technical skill that analyzes simulation results, providing developers with valuable parameters and statistics. It benefits AI agent developers working with simulation data. dqmc-analyze是一个用于分析模拟结果的工具，支持Python集成和数据分析 dqmc-analyzeはシミュレーション結果を分析するためのツールで、Pythonとの統合やデータ分析が可能 dqmc-analyze는 시뮬레이션 결과를 분석하는 도구로 Python 통합과 데이터 분석을 지원합니다 dqmc-analyze es una herramienta para analizar resultados de simulaciones y obtener parámetros con errores estándar dqmc-analyze est un outil pour analyser les résultats de simulations et obtenir des paramètres avec des erreurs standard dqmc-analyze ist ein Tool zur Analyse von Simulationsergebnissen und zur Gewinnung von Parametern mit Standardfehlern O dqmc-analyze é uma ferramenta para análise de simulações que fornece resultados precisos com Python. Aprenda a configurá-lo para obter os melhores resultados. ИИ Агент dqmc-analyze - это инструмент для анализа результатов симуляций, который предоставляет точные результаты с помощью Python. Узнайте, как его настроить. dqmc-analyze هو أداة لتحليل نتائج Симуляций التي توفر نتائج دقيقة باستخدام Python. تعلم كيفية إعداده للحصول على أفضل النتائج how to use dqmc-analyze dqmc-analyze alternative dqmc-analyze setup guide what is dqmc-analyze dqmc-analyze vs other analysis tools dqmc-analyze install analyzing simulation results with dqmc-analyze dqmc-analyze for AI agents dqmc-analyze tutorial dqmc-analyze Python AI工具 模拟结果分析 数据分析 可观测变量 均值和标准误差 Analyzes simulation results from directories containing bin_*.h5 files Extracts parameters and statistics for observable names such as ''sign'', ''den'', and ''zzr'' Provides output as a dictionary with (mean, stderr) tuples for each observable Utilizes the analyze_hub function from the dqmc_util library Supports basic analysis of simulation results with Python dqmc-analyze is a skill that analyzes results from completed simulations, extracting parameters and statistics from bin_*.h5 files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bodangren/git-workflow/skill-lister', 'community', 'bodangren', 'git-workflow', 'bodangren/git-workflow', 'skill-lister', 10, 2, 51, '2026-02-21T04:19:40Z', '2026-03-06T06:46:34.923Z', '018418e2594f050a211451b1a2e6027c121cbad72dff0b7f1ec6a36218f2532b', '{"id":"bodangren/git-workflow/skill-lister","name":"skill-lister","description":{"en":"The skill-lister provides a comprehensive overview of available AgenticDev skills, scanning the .claude/skills/ directory and extracting metadata from SKILL.md files for AI agents.","zh":"Skill Lister 是一个 Spec-Driven Git Workflow 插件，提供综合的开发工作流程，支持 GitHub 集成和斯普林特管理","ja":"Skill Lister は、GitHub 統合とスプリント管理を備えた包括的な開発ワークフロー プラグインです","ko":"Skill Lister는 GitHub 통합과 스프린트 관리를 지원하는 종합적인 개발 워크플로우 플러그인입니다","es":"El skill-lister es un plugin de flujo de trabajo de Git que proporciona una visión general de las habilidades disponibles en el proyecto","fr":"Le skill-lister est un plugin de flux de travail Git qui fournit une vue d''ensemble des compétences disponibles dans le projet","de":"Der skill-lister ist ein Git-Workflow-Plugin, das eine Übersicht über die verfügbaren Fähigkeiten im Projekt bietet","pt":"O skill-lister é um plugin de fluxo de trabalho baseado em especificações para Claude Code, que fornece uma visão geral abrangente de todas as habilidades AgenticDev disponíveis no projeto.","ru":"Skill-lister - это плагин рабочего процесса на основе спецификаций для Claude Code, который предоставляет всесторонний обзор всех доступных навыков AgenticDev в проекте.","ar":"skill-lister هو مكون إضافي لتدفق العمل القائم على المواصفات ل Claude Code، والذي يوفر نظرة عامة شاملة على جميع المهارات AgenticDev المتاحة في المشروع."},"seo":{"title":{"en":"skill-lister: Comprehensive Development Workflow Setup Gu...","zh":"Skill Lister 设置指南 - Spec-Driven Git Workflow 插件","ja":"Skill Lister 導入ガイド - GitHub 統合とスプリント管理","ko":"Skill Lister 사용 가이드 - Comprehensive 개발 워크플로우 플러그인","es":"Guía de configuración de skill-lister para Agentes de IA","fr":"Guide d''installation de skill-lister pour Outils d''IA","de":"Einrichtungsleitfaden für skill-lister für KI-Agents","pt":"Guia de Configuração do Skill Lister para Ferramentas de IA","ru":"Настройка skill-lister для ИИ Агентов: Комплексный Workflow","ar":"دليل إعداد skill-lister لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how skill-lister simplifies development workflows with GitHub integration and sprint management - get started with this Spec-Driven Git Workflow plu...","zh":"了解 Skill Lister 的功能和特点，包括 GitHub 集成、斯普林特管理和 Brownfield 迁移支持，AIエージェント开发必备","ja":"Skill Lister を使用して開発ワークフローを最適化する - GitHub 統合、スプリント管理、Brownfield 移行サポート","ko":"Skill Lister로 개발 효율성을 높여보세요 - GitHub 통합, 스프린트 관리, 브라운필드 마이그레이션 지원","es":"Descubre cómo configurar skill-lister para mejorar el flujo de trabajo de desarrollo con GitHub y gestión de sprint","fr":"Découvrez comment installer skill-lister pour améliorer le flux de travail de développement avec GitHub et gestion de sprint","de":"Erfahren Sie, wie Sie skill-lister einrichten, um den Entwicklungs-Workflow mit GitHub und Sprint-Management zu verbessern","pt":"Aprenda a configurar o skill-lister para melhorar o fluxo de trabalho de desenvolvimento com integração do GitHub e suporte à migração brownfield","ru":"Узнайте, как настроить skill-lister для улучшения рабочего процесса разработки с интеграцией GitHub и поддержкой миграции brownfield","ar":"تعرف على كيفية إعداد skill-lister لتحسين تدفق العمل التطويري مع دمج GitHub ودعم الهجرة brownfield"},"definition":{"en":"skill-lister is a Spec-Driven Git Workflow plugin for Claude Code, enabling comprehensive development workflows with GitHub integration, sprint management, and brownfield migration support","zh":"Skill Lister 是一个 AIエージェント工具，用于扫描和提取 SKILL.md 文件中的元数据","ja":"Skill Lister は、SKILL.md ファイルからメタデータを抽出して AIエージェントに提供するツールです","ko":"Skill Lister는 SKILL.md 파일에서 메타데이터를 추출하여 AI 에이전트에 제공하는 도구입니다","es":"El skill-lister es un plugin que escanea el directorio .claude/skills/ y devuelve una lista de habilidades con sus descripciones","fr":"Le skill-lister est un plugin qui analyse le répertoire .claude/skills/ et retourne une liste de compétences avec leurs descriptions","de":"Der skill-lister ist ein Plugin, das das Verzeichnis .claude/skills/ scannt und eine Liste von Fähigkeiten mit ihren Beschreibungen zurückgibt","pt":"O skill-lister é um plugin que fornece uma lista formatada de habilidades disponíveis em um projeto, incluindo descrições e caminhos de script.","ru":"Skill-lister - это плагин, который предоставляет форматированный список доступных навыков в проекте, включая описания и пути скриптов.","ar":"skill-lister هو مكون إضافي يوفر قائمة معدة من المهارات المتاحة في مشروع، بما في ذلك الوصف والمسارات النصية."},"features":{"en":["Scans the .claude/skills/ directory for available skills","Extracts skill metadata from SKILL.md files","Returns a formatted list of discovered skills with descriptions and script paths","Supports GitHub integration for streamlined development workflows","Enables sprint management for efficient project planning","Provides brownfield migration support for legacy projects"],"zh":["GitHub 集成","斯普林特管理","Brownfield 迁移支持","SKILL.md 文件元数据提取","综合的开发工作流程"],"ja":["GitHub 統合","スプリント管理","Brownfield 移行サポート","SKILL.md ファイルからメタデータの抽出","包括的な開発ワークフロー"],"ko":["GitHub 통합","스프린트 관리","브라운필드 마이그레이션 지원","SKILL.md 파일에서 메타데이터 추출","종합적인 개발 워크플로우"],"es":["Integración con GitHub","Gestión de sprint","Soporte para migración de brownfield","Escaneo del directorio .claude/skills/","Extracción de metadatos de habilidades de SKILL.md"],"fr":["Intégration à GitHub","Gestion de sprint","Prise en charge de la migration de brownfield","Analyse du répertoire .claude/skills/","Extraction de métadonnées de compétences de SKILL.md"],"de":["Integration mit GitHub","Sprint-Management","Unterstützung für Brownfield-Migration","Scannen des Verzeichnisses .claude/skills/","Extraktion von Fähigkeitsmetadaten aus SKILL.md"],"pt":["Integração com o GitHub","Suporte à migração brownfield","Visão geral abrangente de habilidades AgenticDev","Extração de metadados de habilidades de arquivos SKILL.md","Retorno de lista formatada de habilidades com descrições e caminhos de script"],"ru":["Интеграция с GitHub","Поддержка миграции brownfield","Всесторонний обзор навыков AgenticDev","Извлечение метаданных навыков из файлов SKILL.md","Возвращение форматированного списка навыков с описаниями и путями скриптов"],"ar":["دمج مع GitHub","دعم الهجرة brownfield","نظرة عامة شاملة على المهارات AgenticDev","استخراج بيانات وصفية للمهارات من ملفات SKILL.md","إرجاع قائمة معدة من المهارات مع الأوصاف ومسارات البرامج النصية"]},"keywords":{"en":["how to use skill-lister","what is skill-lister","skill-lister alternative","skill-lister vs Claude Code","skill-lister install","skill-lister setup guide","Spec-Driven Git Workflow plugin","GitHub integration for AI agents","sprint management tools"],"zh":["Skill Lister","AIエージェント","Spec-Driven Git Workflow","GitHub 集成","斯普林特管理","Brownfield 迁移","SKILL.md 文件","开发工作流程","AI开发工具"],"ja":["Skill Lister","AIエージェント","Spec-Driven Git Workflow","GitHub 統合","スプリント管理","Brownfield 移行","SKILL.md ファイル","開発ワークフロー","AI開発ツール"],"ko":["Skill Lister","AI 에이전트","Spec-Driven Git Workflow","GitHub 통합","스프린트 관리","브라운필드 마이그레이션","SKILL.md 파일","개발 워크플로우","AI 개발 도구"],"es":["Agentes de IA","Herramientas de desarrollo","Flujo de trabajo de Git","Integración con GitHub","Gestión de sprint","Migración de brownfield","SKILL.md","Desarrollo de software"],"fr":["Outils d''IA","Outils de développement","Flux de travail Git","Intégration à GitHub","Gestion de sprint","Migration de brownfield","SKILL.md","Développement de logiciels"],"de":["KI-Agents","Entwicklertools","Git-Workflow","Integration mit GitHub","Sprint-Management","Brownfield-Migration","SKILL.md","Softwareentwicklung"],"pt":["skill-lister","ferramentas de IA","fluxo de trabalho de desenvolvimento","integração do GitHub","suporte à migração brownfield","AgenticDev","SKILL.md","desenvolvimento de software"],"ru":["skill-lister","ИИ Агенты","рабочий процесс разработки","интеграция GitHub","поддержка миграции brownfield","AgenticDev","SKILL.md","разработка программного обеспечения"],"ar":["skill-lister","أدوات الذكاء الاصطناعي","تدفق العمل التطويري","دمج GitHub","دعم الهجرة brownfield","AgenticDev","SKILL.md","تطوير البرمجيات"]}},"owner":"bodangren","repo":"git-workflow","repoPath":"bodangren/git-workflow","stars":10,"forks":2,"updatedAt":"2026-02-21T04:19:40Z","topics":[],"category":"community","skillMd":{"name":"skill-lister","description":"Use this skill to discover all available AgenticDev skills and their capabilities. Provides a bootstrap context for AI agents by listing all skills, their descriptions, and script paths from the .claude/skills/ directory.","bodyPreview":"# Skill Lister\n\n## Purpose\n\nProvide a comprehensive overview of all available AgenticDev skills in the project. The skill-lister scans the `.claude/skills/` directory, extracts skill metadata from SKILL.md files, and returns a formatted list of all discovered skills with their descriptions and script paths. This enables AI agents to quickly understand what capabilities are available without manually exploring the directory structure.\n\n## When to Use\n\nUse this skill in the following situations:","body":"# Skill Lister\n\n## Purpose\n\nProvide a comprehensive overview of all available AgenticDev skills in the project. The skill-lister scans the `.claude/skills/` directory, extracts skill metadata from SKILL.md files, and returns a formatted list of all discovered skills with their descriptions and script paths. This enables AI agents to quickly understand what capabilities are available without manually exploring the directory structure.\n\n## When to Use\n\nUse this skill in the following situations:\n\n- At the beginning of any work session to understand available AgenticDev capabilities\n- When onboarding to a new project using AgenticDev\n- Before deciding which skill to use for a particular task\n- When documenting or auditing the project''s AgenticDev setup\n- To verify that all expected skills are installed and accessible\n\n## Prerequisites\n\n- The project must have a `.claude/skills/` directory\n- Skills should follow the convention of including SKILL.md files with YAML frontmatter\n- No additional tools required (pure bash implementation)\n\n## Workflow\n\n### Step 1: Run the Skill Lister\n\nExecute the helper script to scan all skills in the .claude/skills/ directory:\n\n```bash\nbash .claude/skills/skill-lister/scripts/list-skills.sh\n```\n\nThis will output a human-readable summary showing each skill''s metadata including:\n- Skill name\n- Description\n- Available scripts\n\nFor machine-readable JSON output (useful for programmatic processing):\n\n```bash\nbash .claude/skills/skill-lister/scripts/list-skills.sh -j\n```\n\n### Step 2: Review the Skills List\n\nThe scanner returns information about all skills found in `.claude/skills/`, including:\n\n- **Skill name**: The identifier for the skill (from YAML frontmatter)\n- **Description**: What the skill does and when to use it\n- **Script paths**: All executable scripts available for the skill\n- **Directory**: Location of the skill in the filesystem\n\n### Step 3: Choose the Appropriate Skill\n\nBased on the output, select the skill that best matches your current task:\n\n- Need to understand documentation? → Use `doc-indexer`\n- Starting work on an issue? → Use `issue-executor`\n- Proposing a change? → Use `spec-authoring`\n- Planning a sprint? → Use `sprint-planner`\n- Setting up a new project? → Use `project-init`\n\n## Error Handling\n\n### No Skills Directory Found\n\n**Symptom**: Script reports that `.claude/skills/` directory doesn''t exist\n\n**Solution**:\n- Verify you''re in the project root directory\n- Run `project-init` skill to set up AgenticDev\n- Check if skills are installed in a different location\n\n### Missing SKILL.md Files\n\n**Symptom**: Script lists skills but shows no metadata\n\n**Solution**:\n- Verify that each skill directory contains a SKILL.md file\n- Check that SKILL.md files have proper YAML frontmatter with `name` and `description` fields\n- Run validation script if available: `bash scripts/validate-skills.sh`\n\n### No Scripts Found\n\n**Symptom**: Skill is listed but shows no scripts\n\n**Solution**:\n- Verify that the skill''s `scripts/` directory exists and contains executable files\n- Check file permissions: `chmod +x .claude/skills/*/scripts/*`\n- Some skills may not have scripts (documentation-only skills)\n\n### Permission Denied\n\n**Symptom**: Cannot read skill directories or files\n\n**Solution**:\n- Check directory permissions: `ls -la .claude/skills/`\n- Ensure you have read access to the skills directory\n- Verify the script itself is executable: `chmod +x .claude/skills/skill-lister/scripts/list-skills.sh`\n\n## Notes\n\n- **Bootstrap context**: Designed to be run by agent-integrator to provide AI agents with skill discovery capability\n- **Lightweight**: Minimal dependencies, works with standard bash tools\n- **Extensible**: Automatically discovers new skills as they''re added\n- **JSON support**: Can output structured data for integration with other tools\n- **Convention-based**: Relies on standard AgenticDev skill structure (SKILL.md + scripts/)\n- **Safe to run**: Read-only operation with no side effects\n- **Discovery pattern**: Similar to doc-indexer but for skills instead of documentation\n"},"lastSynced":"2026-03-06T06:46:34.923Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing automated skill discovery and metadata extraction from SKILL.md files.","zh":"非常适合需要自动化技能发现和从SKILL.md文件中提取元数据的AI代理。","ja":"SKILL.mdファイルからの自動スキル発見とメタデータ抽出が必要なAIエージェントに最適です。","ko":"SKILL.md 파일에서 자동으로 스킬을 발견하고 메타데이터를 추출해야 하는 AI 에이전트에게 적합합니다.","es":"Perfecto para Agentes de IA que necesitan un descubrimiento de habilidades automatizado y extracción de metadatos de archivos SKILL.md.","fr":"Parfait pour les Agents IA nécessitant une découverte de compétences automatisée et une extraction de métadonnées à partir de fichiers SKILL.md.","de":"Perfekt für KI-Agents, die ein automatisiertes Skill-Discovery und Metadaten-Extraktion aus SKILL.md-Dateien benötigen.","pt":"Perfeito para Agentes de IA que necessitam de descoberta automática de habilidades e extração de metadados de arquivos SKILL.md.","ru":"Идеально для агентов ИИ, которым необходима автоматическая обнаружение навыков и извлечение метаданных из файлов SKILL.md.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى اكتشاف مهارات آلية واستخراج البيانات الوصفية من ملفات SKILL.md."},"recommendation":{"en":"Empowers agents to scan the .claude/skills/ directory, extracting skill metadata and returning a formatted list of discovered skills with their descriptions and script paths using file system access and metadata parsing.","zh":"赋予代理扫描.claude/skills/目录的能力，提取技能元数据，并使用文件系统访问和元数据解析返回格式化的已发现技能列表及其描述和脚本路径。","ja":".claude/skills/ディレクトリをスキャンし、スキルメタデータを抽出してファイルシステムアクセスとメタデータ解析を使用して発見されたスキルのリストとその説明とスクリプトパスをフォーマットして返すエージェントに権限を与えます。","ko":"에이전트가 .claude/skills/ 디렉토리를 스캔하여 스킬 메타데이터를 추출하고 파일 시스템 액세스 및 메타데이터 파싱을 사용하여 발견된 스킬 목록과 해당 설명 및 스크립트 경로를 형식화하여 반환하는 기능을 제공합니다.","es":"Permite a los agentes escanear el directorio .claude/skills/, extrayendo metadatos de habilidades y devolviendo una lista formateada de habilidades descubiertas con sus descripciones y rutas de script utilizando acceso al sistema de archivos y análisis de metadatos.","fr":"Permet aux agents de scanner le répertoire .claude/skills/, en extrayant les métadonnées de compétences et en renvoyant une liste formatée de compétences découvertes avec leurs descriptions et chemins de script en utilisant l''accès au système de fichiers et l''analyse de métadonnées.","de":"Ermöglicht es den Agents, das Verzeichnis .claude/skills/ zu scannen, Skill-Metadaten zu extrahieren und eine formatierte Liste der entdeckten Skills mit ihren Beschreibungen und Skriptpfaden zurückzugeben, indem es auf den Dateisystemzugriff und die Metadatenanalyse zugreift.","pt":"Habilita os agentes a varrer o diretório .claude/skills/, extrair metadados de habilidades e retornar uma lista formatada de habilidades descobertas com suas descrições e caminhos de script usando acesso ao sistema de arquivos e análise de metadados.","ru":"Наделяет агентов возможностью сканировать директорию .claude/skills/, извлекать метаданные навыков и возвращать отформатированный список обнаруженных навыков с их описаниями и путями скриптов с помощью доступа к файловой системе и парсинга метаданных.","ar":"تمكين الوكلاء من مسح الدليل .claude/skills/ ، واستخراج بيانات وصفية المهارات، وإرجاع قائمة مهارات تم اكتشافها مع описاتها ومسارات البرامج النصية باستخدام وصول نظام الملفات وتحليل البيانات الوصفية."},"useCases":{"en":["Automating skill inventory management","Generating skill documentation","Debugging skill metadata issues"],"zh":["自动化技能库存管理","生成技能文档","调试技能元数据问题"],"ja":["スキルインベントリ管理の自動化","スキルドキュメントの生成","スキルメタデータの問題のデバッグ"],"ko":["스킬 재고 관리 자동화","스킬 문서 생성","스킬 메타데이터 문제 디버깅"],"es":["Automatización de la gestión de inventario de habilidades","Generación de documentación de habilidades","Depuración de problemas de metadatos de habilidades"],"fr":["Automatisation de la gestion des compétences","Génération de documentation de compétences","Débogage des problèmes de métadonnées de compétences"],"de":["Automatisierung des Skill-Inventar-Management","Generierung von Skill-Dokumentation","Fehlerbehebung bei Skill-Metadaten-Problemen"],"pt":["Automatizar o gerenciamento de inventário de habilidades","Gerar documentação de habilidades","Depurar problemas de metadados de habilidades"],"ru":["Автоматизировать управление запасом навыков","Генерировать документацию навыков","Отладить проблемы метаданных навыков"],"ar":["أتمتة إدارة مخزون المهارات","توليد توثيق المهارات","تصحيح أخطاء بيانات وصفية المهارات"]},"limitations":{"en":["Requires filesystem access to .claude/skills/ directory","Limited to SKILL.md file format"],"zh":[".claude/skills/ 디렉토리에 대한 파일 시스템 액세스가 필요","SKILL.md 파일 형식으로 제한"],"ja":[".claude/skills/ディレクトリへのファイルシステムアクセスが必要","SKILL.mdファイル形式に限定"],"ko":[".claude/skills/ 디렉토리에 대한 파일시스템 액세스가 필요함","SKILL.md 파일 형식으로만 제한됨"],"es":["Requiere acceso al sistema de archivos al directorio .claude/skills/","Limitado al formato de archivo SKILL.md"],"fr":["Nécessite un accès au système de fichiers au répertoire .claude/skills/","Limité au format de fichier SKILL.md"],"de":["Benötigt Dateisystemzugriff auf das Verzeichnis .claude/skills/","Begrenzt auf das SKILL.md-Dateiformat"],"pt":["Requer acesso ao sistema de arquivos do diretório .claude/skills/","Limitado ao formato de arquivo SKILL.md"],"ru":["Требует доступа к файловой системе директории .claude/skills/","Ограничен форматом файла SKILL.md"],"ar":["يتطلب الوصول إلى نظام الملفات للدليل .claude/skills/","محدود بتنسيق ملف SKILL.md"]},"version":4},"contentHash":"018418e2594f050a211451b1a2e6027c121cbad72dff0b7f1ec6a36218f2532b","qualityScore":51}');
