INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bodangren/git-workflow/skill-lister', 'skill-lister', 'bodangren', 'git-workflow', 'community', 'skill-lister bodangren git-workflow community The skill-lister provides a comprehensive overview of available AgenticDev skills, scanning the .claude/skills/ directory and extracting metadata from SKILL.md files for AI agents. Skill Lister 是一个 Spec-Driven Git Workflow 插件，提供综合的开发工作流程，支持 GitHub 集成和斯普林特管理 Skill Lister は、GitHub 統合とスプリント管理を備えた包括的な開発ワークフロー プラグインです Skill Lister는 GitHub 통합과 스프린트 관리를 지원하는 종합적인 개발 워크플로우 플러그인입니다 El skill-lister es un plugin de flujo de trabajo de Git que proporciona una visión general de las habilidades disponibles en el proyecto Le skill-lister est un plugin de flux de travail Git qui fournit une vue d''ensemble des compétences disponibles dans le projet Der skill-lister ist ein Git-Workflow-Plugin, das eine Übersicht über die verfügbaren Fähigkeiten im Projekt bietet O skill-lister é um plugin de fluxo de trabalho baseado em especificações para Claude Code, que fornece uma visão geral abrangente de todas as habilidades AgenticDev disponíveis no projeto. Skill-lister - это плагин рабочего процесса на основе спецификаций для Claude Code, который предоставляет всесторонний обзор всех доступных навыков AgenticDev в проекте. skill-lister هو مكون إضافي لتدفق العمل القائم على المواصفات ل Claude Code، والذي يوفر نظرة عامة شاملة على جميع المهارات AgenticDev المتاحة في المشروع. how to use skill-lister what is skill-lister skill-lister alternative skill-lister vs Claude Code skill-lister install skill-lister setup guide Spec-Driven Git Workflow plugin GitHub integration for AI agents sprint management tools Skill Lister AIエージェント Spec-Driven Git Workflow GitHub 集成 斯普林特管理 Brownfield 迁移 SKILL.md 文件 开发工作流程 AI开发工具 Scans the .claude/skills/ directory for available skills Extracts skill metadata from SKILL.md files Returns a formatted list of discovered skills with descriptions and script paths Supports GitHub integration for streamlined development workflows Enables sprint management for efficient project planning Provides brownfield migration support for legacy projects skill-lister is a Spec-Driven Git Workflow plugin for Claude Code, enabling comprehensive development workflows with GitHub integration, sprint management, and brownfield migration support');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('whilp/world/dev', 'community', 'whilp', 'world', 'whilp/world', 'dev', 9, 3, 51, '2026-02-20T03:54:02Z', '2026-03-06T06:46:59.286Z', '5039fb9adf5722af8ecbafebe6fd332a247f7296c80c809064cbd5f710096bdb', '{"id":"whilp/world/dev","name":"dev","description":{"en":"The dev skill provides development workflow utilities for branching, PR management, and review feedback, benefiting developers and teams. It automates tasks such as creating branches and switching between them.","zh":"dev 工作流工具提供了分支创建、PR 管理和审查反馈的自动化功能，帮助开发者优化工作流程","ja":"dev を使用すると、ブランチの作成、PR 管理、レビュー フィードバックを自動化できます。開発ワークフローを最適化するために必要な機能を提供します","ko":"dev Arbeit 플로우 유틸리티는 브랜치 생성, PR 관리 및 리뷰 피드백을 자동화하여 개발자를 위한 워크플로우 최적화를 제공합니다","es":"Dev es una herramienta de desarrollo que facilita la creación de ramas y la gestión de solicitudes de extracción, mejorando el flujo de trabajo de desarrollo","fr":"Dev est un outil de développement qui facilite la création de branches et la gestion des demandes d''extraction, améliorant le flux de travail de développement","de":"Dev ist ein Entwicklungstool, das die Erstellung von Branches und die Verwaltung von Pull-Requests erleichtert, um den Entwicklungs-Workflow zu verbessern","pt":"O Dev é uma coleção de utilitários de fluxo de trabalho para desenvolvedores, incluindo criação de branches e gerenciamento de PR","ru":"Dev - это набор утилит для рабочего процесса разработки, включающий создание веток и управление PR","ar":"أداة Dev هي مجموعة من أدوات تدفق العمل التطويري، بما في ذلك إنشاء الفروع وإدارة ال PR"},"seo":{"title":{"en":"dev: Branch Management Setup Guide | AI Agent Skill","zh":"dev 工作流设置指南 - 分支和 PR 管理","ja":"dev Setup Guide - ブランチと PR 管理のベストプラクティス","ko":"dev 설정 가이드 - 브랜치 및 PR 관리","es":"Guía de configuración de dev para flujos de trabajo de de...","fr":"Guide de mise en place de dev pour les flux de travail de...","de":"Einrichtungsleitfaden für dev-Entwicklungsworkflows","pt":"Guia de Configuração do Dev: Ferramentas de Fluxo de Trab...","ru":"ИИ Агенты Dev: Руководство по Настройке Инструментов Разр...","ar":"دليل إعداد أداة Dev: أدوات تدفق العمل"},"description":{"en":"Streamline your development workflow with dev, a utility for branching, PR management, and review feedback. Learn how to create and manage branches efficiently.","zh":"dev 工作流工具，用于分支创建、PR 管理和审查反馈。了解如何创建短命命名分支和自动化工作流","ja":"dev を使用したブランチの作成、PR 管理、レビュー フィードバックの自動化。開発ワークフローを最適化する方法を学ぶ","ko":"dev Arbeit 플로우 유틸리티를 사용하여 브랜치 생성, PR 관리 및 리뷰 피드백을 자동화합니다. 개발 워크플로우를 최적화하는 방법을 살펴보세요","es":"Optimice su flujo de trabajo de desarrollo con dev, creando ramas y gestionando solicitudes de extracción de manera eficiente","fr":"Optimisez votre flux de travail de développement avec dev, en créant des branches et en gérant les demandes d''extraction de manière efficace","de":"Optimieren Sie Ihren Entwicklungs-Workflow mit dev, indem Sie Branches erstellen und Pull-Requests effizient verwalten","pt":"Aprenda a configurar o Dev para melhorar seu fluxo de trabalho de desenvolvimento com branching, PR e feedback de revisão","ru":"Узнайте, как настроить Dev для улучшения вашего рабочего процесса разработки с помощью веток, PR и обратной связи","ar":"تعلم كيفية إعداد أداة Dev لتحسين تدفق العمل التطويري الخاص بك مع الفروع ومراجعة ال PR"},"definition":{"en":"dev is a development workflow utility that automates branching, PR management, and review feedback tasks, enhancing the development process.","zh":"dev 是一个开发工作流工具，用于分支创建、PR 管理和审查反馈的自动化","ja":"dev は、ブランチの作成、PR 管理、レビュー フィードバックの自動化を提供する開発ワークフロー ツールです","ko":"dev는 브랜치 생성, PR 관리 및 리뷰 피드백을 자동화하는 개발 워크플로우 툴입니다","es":"Dev es un conjunto de utilidades para flujos de trabajo de desarrollo que incluye la creación de ramas y la gestión de solicitudes de extracción","fr":"Dev est un ensemble d''utilitaires pour les flux de travail de développement qui inclut la création de branches et la gestion des demandes d''extraction","de":"Dev ist eine Sammlung von Entwicklungswerkzeugen, die die Erstellung von Branches und die Verwaltung von Pull-Requests umfasst","pt":"O que é Dev? É um conjunto de ferramentas de fluxo de trabalho para desenvolvedores","ru":"Что такое Dev? Это набор утилит для рабочего процесса разработки","ar":"ما هي أداة Dev؟ هي مجموعة من أدوات تدفق العمل التطويري"},"features":{"en":["Creates a new branch off the latest default branch commit","Detects default branch (main or master) for branch creation","Generates short, kebab-case branch names based on tasks","Switches to new branch after creation","Supports workflow automation for PR management and review feedback"],"zh":["自动创建短命命名分支","支持 PR 管理和审查反馈","自动化工作流","支持 kebab-case 命名约定","集成 Git 工作流"],"ja":["短命命名ブランチの自動作成","PR 管理とレビュー フィードバックのサポート","ワークフローの自動化","kebab-case 命名規約のサポート","Git ワークフローの統合"],"ko":["자동 브랜치 생성","PR 관리 및 리뷰 피드백 지원","워크플로우 자동화","kebab-case 명명 규약 지원","Git 워크플로우 통합"],"es":["Creación de ramas a partir de la rama predeterminada","Detección automática de la rama predeterminada (main o master)","Generación de nombres de ramas descriptivos en formato kebab-case","Cambio a la nueva rama creada","Gestión de solicitudes de extracción y retroalimentación de revisión"],"fr":["Création de branches à partir de la branche par défaut","Détection automatique de la branche par défaut (main ou master)","Génération de noms de branches descriptifs au format kebab-case","Changement vers la nouvelle branche créée","Gestion des demandes d''extraction et de feedback de révision"],"de":["Erstellung von Branches aus der Standardbranch","Automatische Erkennung der Standardbranch (main oder master)","Generierung von beschreibenden Branchennamen im kebab-case-Format","Wechsel zur neu erstellten Branch","Verwaltung von Pull-Requests und Review-Feedback"],"pt":["Criação de branches a partir do commit mais recente","Detecção automática do branch padrão (main ou master)","Nomeação de branches em kebab-case","Suporte a feedback de revisão","Integração com fluxo de trabalho de desenvolvimento"],"ru":["Создание веток из последнего коммита","Автоматическое определение основной ветки (main или master)","Именование веток в kebab-case","Поддержка обратной связи при ревью","Интеграция с рабочим процессом разработки"],"ar":["إنشاء فروع من الالتزام الأخير","التحديد التلقائي للفرع الافتراضي (الرئيسي أو الرئيسي)","تسمية الفروع بالشكل kebab-case","دعم ملاحظات المراجعة","التكامل مع تدفق العمل التطويري"]},"keywords":{"en":["how to use dev for branch management","dev alternative to git flow","dev setup guide for AI agents","what is dev in development workflow","dev vs git workflow","install dev for automated branching"],"zh":["dev 工作流","分支创建","PR 管理","审查反馈","自动化工作流","Git 工作流","kebab-case 命名约定","开发工具","AI 工具"],"ja":["dev ワークフロー","ブランチの作成","PR 管理","レビュー フィードバック","ワークフローの自動化","Git ワークフロー","kebab-case 命名規約","開発ツール","AI エージェント"],"ko":["dev Arbeit 플로우","브랜치 생성","PR 관리","리뷰 피드백","워크플로우 자동화","Git 워크플로우","kebab-case 명명 규약","개발 도구","AI 툴"],"es":["dev herramientas de desarrollo","flujos de trabajo de desarrollo","creación de ramas","gestión de solicitudes de extracción","retroalimentación de revisión","desarrollo de software","herramientas de desarrollo de software"],"fr":["dev outils de développement","flux de travail de développement","création de branches","gestion des demandes d''extraction","feedback de révision","développement de logiciels","outils de développement de logiciels"],"de":["dev Entwicklungstools","Entwicklungs-Workflows","Erstellung von Branches","Verwaltung von Pull-Requests","Review-Feedback","Software-Entwicklung","Entwicklungstools für Software"],"pt":["dev ferramentas de fluxo de trabalho","criação de branches","gerenciamento de PR","feedback de revisão","desenvolvimento de software","ferramentas de desenvolvedor"],"ru":["ИИ Агенты Dev","инструменты рабочего процесса разработки","создание веток","управление PR","обратная связь при ревью","разработка программного обеспечения"],"ar":["أداة Dev","أدوات تدفق العمل التطويري","إنشاء فروع","إدارة ال PR","ملاحظات المراجعة","تطوير البرمجيات"]}},"owner":"whilp","repo":"world","repoPath":"whilp/world","stars":9,"forks":3,"updatedAt":"2026-02-20T03:54:02Z","topics":[],"category":"community","skillMd":{"name":"dev","description":"Development workflow for this repository. Run `make help` to see available targets.","bodyPreview":"# dev\n\nDevelopment workflow utilities for branching, PR management, and review feedback.\n\n## Creating branches\n\nCreate a new branch off the latest default branch commit.\n\n### Workflow\n\n1. Fetch latest from remote\n2. Detect default branch (main or master)\n3. Create branch with descriptive name based on task\n4. Switch to new branch\n\n### Branch naming\n\nGenerate a short, kebab-case name from the task:\n- `add-user-auth` not `add-user-authentication-feature`\n- `fix-login-bug` not `fix-the-bug-in-the-l","body":"# dev\n\nDevelopment workflow utilities for branching, PR management, and review feedback.\n\n## Creating branches\n\nCreate a new branch off the latest default branch commit.\n\n### Workflow\n\n1. Fetch latest from remote\n2. Detect default branch (main or master)\n3. Create branch with descriptive name based on task\n4. Switch to new branch\n\n### Branch naming\n\nGenerate a short, kebab-case name from the task:\n- `add-user-auth` not `add-user-authentication-feature`\n- `fix-login-bug` not `fix-the-bug-in-the-login-flow`\n- `refactor-api` not `refactor-api-endpoints-for-better-performance`\n\nUse a prefix if the repo convention requires one (check existing branches).\n\n```bash\n# Fetch and get default branch\ngit fetch origin\ngit remote show origin | sed -n ''/HEAD branch/s/.*: //p''\n\n# Create branch from latest default branch\ngit checkout -b <branch-name> origin/main\n\n# See existing branch naming patterns\ngit branch -r | head -20\n```\n\nIf branches use prefixes like `feature/`, `fix/`, or username prefixes like `wcm/`, follow that pattern.\n\n## Review feedback\n\nAddress GitHub PR review comments and reply to reviewers.\n\n### Workflow\n\n1. **Get pending review comments** - fetch unresolved comments\n2. **Address each comment** - make code changes to resolve feedback\n3. **Commit with clear message** - reference what feedback was addressed\n4. **Reply to reviewer** - concise reply with commit SHA and explanation\n\n### Getting review comments\n\n```bash\n# All comments on a PR (includes replies)\ngh pr view <pr-number> --comments --json comments\n\n# Review comments (code-level feedback)\ngh api repos/{owner}/{repo}/pulls/{pr}/comments --jq ''.[] | {id, path, line, body, user: .user.login, in_reply_to_id}''\n\n# Pending/unresolved comments (no replies yet)\ngh api repos/{owner}/{repo}/pulls/{pr}/comments --jq ''[.[] | select(.in_reply_to_id == null)] | .[] | {id, path, body: .body[0:100]}''\n```\n\n### Replying to comments\n\n```bash\n# Reply to a review comment\ngh api repos/{owner}/{repo}/pulls/{pr}/comments \\\n  --method POST \\\n  -f body=\"Fixed in abc1234 - renamed to run-test.js\" \\\n  -F in_reply_to=<comment-id>\n```\n\n### Good reply format\n\nReplies should be:\n- **Concise** - one sentence is often enough\n- **Reference commit SHA** - so reviewer can verify\n- **Explain how** - brief description of the fix\n\nExamples:\n- `Fixed in abc1234 - renamed to run-test.js as suggested`\n- `Addressed in def5678 - now uses a single rule in cook.mk`\n- `Good catch, fixed in 789abcd - removed the duplicate import`\n\n### Complete example\n\n```bash\n# 1. Get pending comments on PR #269\ngh api repos/whilp/world/pulls/269/comments \\\n  --jq ''.[] | select(.in_reply_to_id == null) | {id, path, body}''\n\n# Output:\n# {\"id\":2702089939,\"path\":\"lib/appscript/run-tests.js\",\"body\":\"run-tests.js should be run-test.js...\"}\n\n# 2. Make the fix and commit\ngit mv lib/appscript/run-tests.js lib/appscript/run-test.js\ngit commit -m \"appscript: rename run-tests.js to run-test.js\"\n# Commit SHA: abc1234\n\n# 3. Reply to the comment\ngh api repos/whilp/world/pulls/269/comments \\\n  --method POST \\\n  -f body=\"Fixed in abc1234 - renamed to run-test.js\" \\\n  -F in_reply_to=2702089939\n```\n\n### Batch processing\n\nFor multiple comments:\n\n```bash\n# Get all pending comments as JSON\ngh api repos/{owner}/{repo}/pulls/{pr}/comments \\\n  --jq ''[.[] | select(.in_reply_to_id == null)] | group_by(.path) | .[] | {path: .[0].path, comments: [.[] | {id, body}]}''\n```\n\nThis groups comments by file for efficient processing.\n"},"lastSynced":"2026-03-06T06:46:59.286Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring streamlined workflow utilities for branching, PR management, and review feedback.","zh":"非常适合需要简化分支、PR管理和审查反馈工作流程的开发Agent使用。","ja":"ブランチ管理、PR管理、レビュー対応の合理化されたワークフロー機能を必要とする開発エージェントに最適です。","ko":"분기, PR 관리 및 리뷰 피드백을 위한 간소화된 워크플로우 유틸리티가 필요한 개발 에이전트에 이상적입니다.","es":"Ideal para agentes de desarrollo que requieren utilidades de flujo de trabajo optimizadas para branching, gestión de PR y comentarios de revisión.","fr":"Idéal pour les agents de développement nécessitant des utilitaires de flux de travail rationalisés pour le branching, la gestion des PR et les retours d''avis.","de":"Ideal für Entwicklungs-Agents, die optimierte Workflow-Utilities für Branching, PR-Management und Review-Feedback benötigen.","pt":"Ideal para Agentes de Desenvolvimento que requerem utilitários de fluxo de trabalho simplificados para branching, gerenciamento de PR e feedback de revisão.","ru":"Идеально подходит для агентов разработки, требующих оптимизированных служебных программ рабочего процесса для ветвления, управления PR и отзывами на ревью.","ar":"مثالي لوكلاء التطوير الذين يحتاجون إلى أدوات سير عمل مبسطة للتفرع وإدارة طلبات السحب (PR) وملاحظات المراجعة."},"recommendation":{"en":"Empowers agents to automate tasks such as creating branches, switching between them, and managing PRs using descriptive kebab-case branch names, enhancing development workflow efficiency with features like fetching latest from remote and detecting default branches.","zh":"使Agent能够自动化创建分支、在分支之间切换以及使用描述性kebab-case分支名称管理PR等任务，通过从远程获取最新内容和检测默认分支等功能，提高开发工作流程效率。","ja":"説明的なkebab-caseブランチ名を使用したブランチの作成、ブランチ間の切り替え、PRの管理などのタスクを自動化する機能を提供し、リモートからの最新情報の取得やデフォルトブランチの検出などの機能により、開発ワークフローの効率を向上させます。","ko":"설명적인 kebab-case 브랜치 이름을 사용하여 브랜치 생성, 브랜치 간 전환, PR 관리와 같은 작업을 자동화하여 원격에서 최신 내용을 가져오고 기본 브랜치를 감지하는 기능 등으로 개발 워크플로우 효율성을 향상시킵니다.","es":"Permite a los agentes automatizar tareas como la creación de branches, el cambio entre ellos y la gestión de PRs utilizando nombres de branch descriptivos en kebab-case, mejorando la eficiencia del flujo de trabajo de desarrollo con funciones como la obtención de la última versión desde el remote y la detección de branches predeterminados.","fr":"Permet aux agents d''automatiser des tâches telles que la création de branches, la commutation entre elles et la gestion des PR en utilisant des noms de branches descriptifs en kebab-case, améliorant l''efficacité du flux de travail de développement avec des fonctionnalités comme la récupération de la dernière version depuis le remote et la détection des branches par défaut.","de":"Ermöglicht es Agents, Aufgaben wie das Erstellen von Branches, das Wechseln zwischen ihnen und das Verwalten von PRs mit beschreibenden kebab-case-Branchnamen zu automatisieren, was die Entwicklungsworkflow-Effizienz mit Funktionen wie dem Abrufen der neuesten Version vom Remote und der Erkennung von Default-Branches verbessert.","pt":"Capacita os agentes a automatizar tarefas como criar branches, alternar entre elas e gerenciar PRs usando nomes descritivos de branches no formato kebab-case, aumentando a eficiência do fluxo de trabalho de desenvolvimento com recursos como buscar o mais recente do remote e detectar branches padrão.","ru":"Позволяет агентам автоматизировать такие задачи, как создание веток, переключение между ними и управление PR с использованием описательных имен веток в kebab-case, повышая эффективность рабочего процесса разработки с такими функциями, как получение последних изменений с удаленного репозитория и определение веток по умолчанию.","ar":"يمكن الوكلاء من أتمتة مهام مثل إنشاء الفروع والتبديل بينها وإدارة طلبات السحب (PR) باستخدام أسماء فرع وصفيّة بنمط kebab-case، مما يعزّي كفاءة سير عمل التطوير بميزات مثل جلب أحدث التحديثات من remote واكتشاف الفروع الافتراضية."},"useCases":{"en":["Automating branch creation with descriptive names","Streamlining PR management and review feedback","Switching between branches efficiently"],"zh":["使用描述性名称自动化创建分支","简化PR管理和审查反馈","高效地在分支之间切换"],"ja":["説明的な名前を使用したブランチ作成の自動化","PR管理とレビューフィードバックの効率化","ブランチ間の効率的な切り替え"],"ko":["설명적인 이름으로 브랜치 생성 자동화","PR 관리 및 리뷰 피드백 간소화","브랜치 간 효율적인 전환"],"es":["Automatización de la creación de branches con nombres descriptivos","Optimización de la gestión de PRs y comentarios de revisión","Cambio entre branches de manera eficiente"],"fr":["Automatisation de la création de branches avec des noms descriptifs","Rationalisation de la gestion des PR et des retours d''avis","Commutation entre les branches efficacement"],"de":["Automatisierung der Branch-Erstellung mit beschreibenden Namen","Optimierung des PR-Managements und Review-Feedbacks","Effizientes Wechseln zwischen Branches"],"pt":["Automatização da criação de branches com nomes descritivos","Simplificação do gerenciamento de PR e feedback de revisão","Alternância eficiente entre branches"],"ru":["Автоматизация создания веток с описательными именами","Оптимизация управления PR и отзывов на ревью","Эффективное переключение между ветками"],"ar":["أتمتة إنشاء الفروع بأسماء وصفيّة","تبسيط إدارة طلبات السحب (PR) وملاحظات المراجعة","التبديل بكفاءة بين الفروع"]},"limitations":{"en":["Requires remote repository access","Limited to Git-based version control systems"],"zh":["需要远程仓库访问权限","仅限于基于Git的版本控制系统"],"ja":["リモートリポジトリへのアクセスが必要","Gitベースのバージョン管理システムに限定される"],"ko":["원격 저장소 액세스 필요","Git 기반 버전 관리 시스템으로 제한됨"],"es":["Requiere acceso al repositorio remoto","Limitado a sistemas de control de versiones basados en Git"],"fr":["Nécessite un accès au dépôt distant","Limité aux systèmes de contrôle de version basés sur Git"],"de":["Erfordert Remote-Repository-Zugriff","Beschränkt auf Git-basierte Versionskontrollsysteme"],"pt":["Requer acesso ao repositório remoto","Limitado a sistemas de controle de versão baseados em Git"],"ru":["Требует доступ к удаленному репозиторию","Ограничено системами контроля версий на основе Git"],"ar":["يتطلب الوصول إلى مستودع remote","يقتصر على أنظمة التحكم في الإصدارات القائمة على Git"]},"version":4},"contentHash":"5039fb9adf5722af8ecbafebe6fd332a247f7296c80c809064cbd5f710096bdb","qualityScore":51}');
