INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('whilp/world/dev', 'dev', 'whilp', 'world', 'community', 'dev whilp world community The dev skill provides development workflow utilities for branching, PR management, and review feedback, benefiting developers and teams. It automates tasks such as creating branches and switching between them. dev 工作流工具提供了分支创建、PR 管理和审查反馈的自动化功能，帮助开发者优化工作流程 dev を使用すると、ブランチの作成、PR 管理、レビュー フィードバックを自動化できます。開発ワークフローを最適化するために必要な機能を提供します dev Arbeit 플로우 유틸리티는 브랜치 생성, PR 관리 및 리뷰 피드백을 자동화하여 개발자를 위한 워크플로우 최적화를 제공합니다 Dev es una herramienta de desarrollo que facilita la creación de ramas y la gestión de solicitudes de extracción, mejorando el flujo de trabajo de desarrollo Dev est un outil de développement qui facilite la création de branches et la gestion des demandes d''extraction, améliorant le flux de travail de développement Dev ist ein Entwicklungstool, das die Erstellung von Branches und die Verwaltung von Pull-Requests erleichtert, um den Entwicklungs-Workflow zu verbessern O Dev é uma coleção de utilitários de fluxo de trabalho para desenvolvedores, incluindo criação de branches e gerenciamento de PR Dev - это набор утилит для рабочего процесса разработки, включающий создание веток и управление PR أداة Dev هي مجموعة من أدوات تدفق العمل التطويري، بما في ذلك إنشاء الفروع وإدارة ال PR how to use dev for branch management dev alternative to git flow dev setup guide for AI agents what is dev in development workflow dev vs git workflow install dev for automated branching dev 工作流 分支创建 PR 管理 审查反馈 自动化工作流 Git 工作流 kebab-case 命名约定 开发工具 AI 工具 Creates a new branch off the latest default branch commit Detects default branch (main or master) for branch creation Generates short, kebab-case branch names based on tasks Switches to new branch after creation Supports workflow automation for PR management and review feedback dev is a development workflow utility that automates branching, PR management, and review feedback tasks, enhancing the development process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('claudeaceae/samara-main/sync', 'community', 'claudeaceae', 'samara-main', 'claudeaceae/samara-main', 'sync', 8, 2, 51, '2026-02-09T21:03:00Z', '2026-03-06T13:03:51.694Z', '4197f9610839e4d1224ff7df6998c04f4d778cf81e2568ea8886e6785b4463a9', '{"id":"claudeaceae/samara-main/sync","name":"sync","description":{"en":"The sync skill bootstraps a persistent body, memory, and agency for Claude on a Mac, ensuring consistency between the repo and running system. It benefits developers working with AI agents.","zh":"Sync 技术通过运行 `sync-organism` 脚本来检测 Claude 的运行系统和仓库之间的差异","ja":"Sync 技術は `sync-organism` スクリプトを実行して Claude の実行システムとリポジトリの差異を検出します","ko":"Sync 기술은 `sync-organism` 스크립트를 실행하여 Claude의 실행 시스템과 저장소의 차이를 감지합니다","es":"Sync es una habilidad que permite a los desarrolladores configurar un cuerpo y memoria persistente para Claude en Mac","fr":"Sync est une compétence qui permet aux développeurs de configurer un corps et une mémoire persistante pour Claude sur Mac","de":"Sync ist eine Fähigkeit, die es Entwicklern ermöglicht, einen persistenten Körper und Speicher für Claude auf Mac zu konfigurieren","pt":"O sync é uma ferramenta que verifica e corrige a divergência entre o repositório e o sistema em execução, garantindo a consistência do agente de IA.","ru":"Синхронизация - это инструмент, который проверяет и исправляет расхождения между репозиторием и запущенной системой, обеспечивая согласованность ИИ агентов.","ar":"Sync هو أداة تتحقق من الانحراف بين المستودع والنظام التشغيلي، وتصححه لضمان توافق وكلاء الذكاء الاصطناعي."},"seo":{"title":{"en":"Sync: Bootstrap Specification Setup Guide | AI Agent Skill","zh":"Sync Setup Guide: Bootstrap Specification for Claude","ja":"Sync セットアップガイド: Claude の永続的なボディとメモリ","ko":"Sync 설정 가이드: Claude의 지속적인 바디와 메모리","es":"Configuración de Sync: Guía para desarrolladores de AI Ag...","fr":"Mise en place de Sync: Guide pour les développeurs d''outi...","de":"Sync-Setup: Anleitung für Entwickler von KI-Tools","pt":"Guia de Configuração do Sync: Ferramenta de Integração de...","ru":"Синхронизация ИИ Агентов: Руководство по Настройке","ar":"دليل إعداد Sync: أداة دمج وكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how to sync your Mac with Claude''s persistent body, memory, and agency. Learn the benefits and get started with our expert guide.","zh":"了解 Sync 技术，检测 Claude 的运行系统和仓库之间的差异，并修复 drift","ja":"Sync 技術で Claude の実行システムとリポジトリの差異を検出して修正する","ko":"Sync 기술로 Claude의 실행 시스템과 저장소의 차이를 감지하고 수정합니다","es":"Aprende a configurar Sync para desarrollar AI Agentes con persistencia y memoria en Mac","fr":"Découvrez comment configurer Sync pour développer des outils d''IA avec persistance et mémoire sur Mac","de":"Erfahren Sie, wie Sie Sync für die Entwicklung von KI-Tools mit Persistenz und Speicher auf Mac konfigurieren","pt":"Aprenda a configurar o sync para garantir a consistência entre o repositório e o sistema em execução, otimizando a funcionalidade do agente de IA","ru":"Понимайте, как настроить синхронизацию для обеспечения согласованности между репозиторием и запущенной системой, оптимизируя функциональность ИИ агентов","ar":"تعرف على كيفية إعداد Sync لضمان التوافق بين المستودع والنظام التشغيلي، لتحسين أداء وكلاء الذكاء الاصطناعي"},"definition":{"en":"sync is a bootstrap specification for maintaining consistency between a repository and a running system on a Mac, enabling Claude''s persistent body, memory, and agency.","zh":"Sync 是一种用于检测和修复 Claude 的运行系统和仓库之间的差异的技术","ja":"Sync は Claude の実行システムとリポジトリの差異を検出して修正する技術です","ko":"Sync는 Claude의 실행 시스템과 저장소의 차이를 감지하고 수정하는 기술입니다","es":"Sync es una habilidad de AI que verifica y corrige diferencias entre el repositorio y el sistema en ejecución","fr":"Sync est une compétence d''IA qui vérifie et corrige les différences entre le référentiel et le système en cours d''exécution","de":"Sync ist eine KI-Fähigkeit, die Unterschiede zwischen dem Repository und dem laufenden System überprüft und korrigiert","pt":"O que é sync? É uma ferramenta de sincronização para agentes de IA que verifica divergências entre repositório e sistema.","ru":"Что такое синхронизация? Это инструмент синхронизации для ИИ агентов, который проверяет расхождения между репозиторием и системой.","ar":"ما هو Sync؟ إنه أداة مزامنة لوكلاء الذكاء الاصطناعي التي تتحقق من الانحرافات بين المستودع والنظام."},"features":{"en":["Runs the `sync-organism` script to detect differences between the repo, running organism, and built app","Checks for correct Team ID (G4XVD3J52J) in Samara.app signing","Verifies skills symlinks for all skills properties","Utilizes the `~/Developer/samara-main/` repository and `~/.claude-mind/` running organism","Optionally fixes drift between the repository and running system"],"zh":["检测 Samara.app 签名的正确性","检查 Skills Symlinks 的完整性","运行 `sync-organism` 脚本来检测差异","支持 Team ID (G4XVD3J52J) 的检查","集成 `/Applications/Samara.app` 和 `~/.claude-mind/` 的检查"],"ja":["Samara.app サインの正しさを検出","Skills Symlinks の完全性を確認"," `sync-organism` スクリプトを実行して差異を検出","Team ID (G4XVD3J52J) の確認をサポート","/Applications/Samara.app と ~/.claude-mind/ の確認を統合"],"ko":["Samara.app 서명의 올바름을 감지","Skills Symlinks의 완전성을 확인","`sync-organism` 스크립트를 실행하여 차이를 감지","Team ID (G4XVD3J52J)의 확인을 지원","/Applications/Samara.app와 ~/.claude-mind/의 확인을 통합"],"es":["Verificación de diferencias entre el repositorio y el sistema en ejecución","Corrección de diferencias entre ~/Developer/samara-main/ y ~/.claude-mind/","Verificación de la firma de Samara.app con el ID de equipo correcto (G4XVD3J52J)","Creación de enlaces simbólicos para habilidades","Ejecución del script sync-organism para detectar diferencias"],"fr":["Vérification des différences entre le référentiel et le système en cours d''exécution","Correction des différences entre ~/Developer/samara-main/ et ~/.claude-mind/","Vérification de la signature de Samara.app avec l''ID d''équipe correct (G4XVD3J52J)","Création de liens symboliques pour les compétences","Exécution du script sync-organism pour détecter les différences"],"de":["Überprüfung von Unterschieden zwischen dem Repository und dem laufenden System","Korrektur von Unterschieden zwischen ~/Developer/samara-main/ und ~/.claude-mind/","Überprüfung der Signatur von Samara.app mit der korrekten Team-ID (G4XVD3J52J)","Erstellung von Symbolverknüpfungen für Fähigkeiten","Ausführung des Skripts sync-organism zur Erkennung von Unterschieden"],"pt":["Verificação de divergência entre o repositório e o sistema em execução","Correção de divergências para garantir a consistência do agente de IA","Suporte à integração com Samara.app","Verificação de assinatura de Samara.app","Criação de links simbólicos para habilidades","Execução do script sync-organism"],"ru":["Проверка расхождений между репозиторием и запущенной системой","Исправление расхождений для обеспечения согласованности ИИ агентов","Поддержка интеграции с Samara.app","Проверка подписи Samara.app","Создание симлинков для навыков","Выполнение скрипта sync-organism"],"ar":["التحقق من الانحرافات بين المستودع والنظام التشغيلي","تصحيح الانحرافات لضمان توافق وكلاء الذكاء الاصطناعي","دعم التكامل مع Samara.app","التحقق من توقيع Samara.app","إنشاء روابط رمزية للمهارات","تشغيل سكريبت sync-organism"]},"keywords":{"en":["how to use sync","sync setup guide","sync alternative","sync vs bootstrap","sync install mac","what is sync skill","sync benefits for developers","sync and Claude AI","sync repository consistency"],"zh":["Sync 技术","Claude AI","AIエージェント","Bootstrap Specification","Samara.app","Skills Symlinks","Team ID","G4XVD3J52J"],"ja":["Sync 技術","Claude AI","AIエージェント","Bootstrap Specification","Samara.app","Skills Symlinks","Team ID","G4XVD3J52J","CLI"],"ko":["Sync 기술","Claude AI","AI 에이전트","Bootstrap Specification","Samara.app","Skills Symlinks","Team ID","G4XVD3J52J","CLI","Python"],"es":["AI Agentes","desarrollo de AI","configuración de Sync","persistencia en Mac","memoria en Mac","verificación de diferencias","corrección de diferencias","Samara.app","CLI"],"fr":["outils d''IA","développement d''IA","configuration de Sync","persistance sur Mac","mémoire sur Mac","vérification de différences","correction de différences","Samara.app","CLI"],"de":["KI-Tools","Entwicklung von KI","Konfiguration von Sync","Persistenz auf Mac","Speicher auf Mac","Überprüfung von Unterschieden","Korrektur von Unterschieden","Samara.app","CLI"],"pt":["sync agente de ia","ferramenta de sincronização","integração samara.app","verificação de assinatura","links simbólicos para habilidades","script sync-organism","desenvolvimento de ia","ferramentas de desenvolvimento"],"ru":["синхронизация ии агентов","инструмент синхронизации","интеграция с samara.app","проверка подписи","симлинки для навыков","скрипт sync-organism","разработка ии","инструменты разработки"],"ar":["مزامنة وكلاء الذكاء الاصطناعي","أداة المزامنة","التكامل مع Samara.app","التحقق من التوقيع","روابط رمزية للمهارات","سكريبت sync-organism","تطوير الذكاء الاصطناعي","أدوات التطوير"]}},"owner":"claudeaceae","repo":"samara-main","repoPath":"claudeaceae/samara-main","stars":8,"forks":2,"updatedAt":"2026-02-09T21:03:00Z","topics":[],"category":"community","skillMd":{"name":"sync","description":"Check for drift between repo and running system. Use when checking if scripts or Samara are out of sync, verifying system integrity, or before/after rebuilds. Trigger words: sync, organism sync, check drift, system drift, repo sync.","bodyPreview":"# Sync Skill\n\nCheck for drift between the repo and running system, and optionally fix it.\n\n## What This Does\n\nRuns the `sync-organism` script to detect differences between:\n- `~/Developer/samara-main/` (the repo/genome)\n- `~/.claude-mind/` (the running organism)\n- `/Applications/Samara.app` (the built app)\n\n## Running the Check\n\n```bash\n~/.claude-mind/system/bin/sync-organism\n```\n\n## What It Checks\n\n1. **Samara.app Signing** - Correct Team ID (G4XVD3J52J)\n2. **Skills Symlinks** - All skills prop","body":"# Sync Skill\n\nCheck for drift between the repo and running system, and optionally fix it.\n\n## What This Does\n\nRuns the `sync-organism` script to detect differences between:\n- `~/Developer/samara-main/` (the repo/genome)\n- `~/.claude-mind/` (the running organism)\n- `/Applications/Samara.app` (the built app)\n\n## Running the Check\n\n```bash\n~/.claude-mind/system/bin/sync-organism\n```\n\n## What It Checks\n\n1. **Samara.app Signing** - Correct Team ID (G4XVD3J52J)\n2. **Skills Symlinks** - All skills properly linked from repo\n3. **Script Drift** - Differences between repo and runtime scripts\n4. **Samara Source** - Whether installed app matches source code\n\n## When to Use\n\n- After making changes to scripts in either location\n- Before/after `update-samara` rebuilds\n- During wake cycles (for monitoring)\n- When something \"should work but doesn''t\"\n\n## Output Example\n\n```\n## Samara.app Signing\n[OK] Samara.app signed with correct Team ID: G4XVD3J52J\n\n## Skills Symlinks\n[OK] 10 skills properly symlinked\n\n## Script Drift Analysis\n[OK] All shared scripts are identical\n\n## Samara.app Source Check\n[OK] Samara.app is up to date with source\n\nSUMMARY\nTotal drift: 0 issues\n```\n\n## Fixing Drift\n\nIf drift is detected, the script shows commands to fix it. Common fixes:\n- Copy runtime script to repo: `cp ~/.claude-mind/system/bin/X ~/Developer/samara-main/scripts/`\n- Rebuild Samara: `~/.claude-mind/system/bin/update-samara`\n- Recreate symlinks: Run `sync-skills` or manually create symlinks\n"},"lastSynced":"2026-03-06T13:03:51.694Z","agentAnalysis":{"suitability":{"en":"Perfect for Mac-based AI Agents needing consistent repo and system state synchronization.","zh":"适用于需要保持一致的仓库和系统状态的 Mac 基础 AI Agents。","ja":"Mac ベースの AI エージェントが一貫したレポジトリとシステム状態の同期を必要とする場合に最適です。","ko":"일관된 저장소 및 시스템 상태 동기화를 필요로하는 Mac 기반 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA basados en Mac que necesitan una sincronización de repositorio y estado del sistema coherente.","fr":"Parfait pour les agents d''IA basés sur Mac nécessitant une synchronisation cohérente du référentiel et de l''état du système.","de":"Perfekt für Mac-basierte KI-Agents, die eine konsistente Repo- und Systemzustands-Synchronisierung benötigen.","pt":"Perfeito para Agentes de IA baseados em Mac que necessitam de sincronização consistente do repositório e do estado do sistema.","ru":"Идеально подходит для агентов ИИ, основанных на Mac, требующих последовательной синхронизации репозитория и состояния системы.","ar":"مثالي لعميل إجمالي للمكتبات القائمة على ماك التي تحتاج إلى تناسق دائم بين مستودع النظام و حالة التشغيل."},"recommendation":{"en":"Empowers agents to detect and fix drift between the repo and running system, ensuring consistency in Samara.app signing and skills symlinks using the `sync-organism` script.","zh":"赋予代理检测和修复仓库与运行系统之间的偏差，确保在 Samara.app 签名和技能软链接中使用 `sync-organism` 脚本的一致性。","ja":"`sync-organism` スクリプトを使用して Samara.app の署名とスキルのシンボリックリンクの一貫性を保つために、エージェントがレポジトリと実行中のシステムの間のズレを検出して修正できるようにします。","ko":"`sync-organism` 스크립트를 사용하여 Samara.app 서명 및 스킬 심볼릭 링크에서 일관성을 보장하기 위해 에이전트가 저장소 및 실행 중인 시스템 간의 드리프트를 감지하고 수정할 수 있도록 합니다.","es":"Habilita a los agentes a detectar y corregir desviaciones entre el repositorio y el sistema en ejecución, garantizando la coherencia en la firma de Samara.app y los symlinks de habilidades utilizando el script `sync-organism`.","fr":"Permet aux agents de détecter et de corriger les écarts entre le référentiel et le système en cours d''exécution, en garantissant la cohérence dans la signature de Samara.app et les symlinks de compétences en utilisant le script `sync-organism`.","de":"Ermächtigt Agents, Abweichungen zwischen dem Repo und dem laufenden System zu erkennen und zu korrigieren, um Konsistenz bei der Signierung von Samara.app und Skills-Symlinks unter Verwendung des `sync-organism`-Skripts sicherzustellen.","pt":"Habilita os agentes a detectar e corrigir a divergência entre o repositório e o sistema em execução, garantindo a consistência na assinatura do Samara.app e symlinks de habilidades usando o script `sync-organism`.","ru":"Наделяет агентов возможностью обнаруживать и исправлять расхождение между репозиторием и работающей системой, обеспечивая последовательность в подписи Samara.app и ссылках навыков с помощью скрипта `sync-organism`.","ar":"تمكّن الوكلاء من الكشف وتصحيح الانحراف بين مستودع النظام و تشغيله، وضمان التناسق في توقيع Samara.app وروابط المهارات باستخدام سكريبت `sync-organism`."},"useCases":{"en":["Checking for inconsistencies between the repo and running system","Fixing drift in Samara.app signing and skills symlinks","Validating Team ID and skills properties"],"zh":["检查仓库与运行系统之间的不一致性","修复 Samara.app 签名和技能软链接中的偏差","验证团队 ID 和技能属性"],"ja":["レポジトリと実行中のシステムの間の不一致を確認する","Samara.app の署名とスキルのシンボリックリンクのズレを修正する","チーム ID とスキルのプロパティを検証する"],"ko":["저장소와 실행 중인 시스템 간의 불일치 확인","Samara.app 서명 및 스킬 심볼릭 링크의 드리프트 수정","팀 ID 및 스킬 속성 검증"],"es":["Comprobación de incoherencias entre el repositorio y el sistema en ejecución","Corrección de desviaciones en la firma de Samara.app y los symlinks de habilidades","Validación del ID de equipo y las propiedades de habilidades"],"fr":["Vérification des incohérences entre le référentiel et le système en cours d''exécution","Correction des écarts dans la signature de Samara.app et les symlinks de compétences","Validation de l''ID d''équipe et des propriétés de compétences"],"de":["Überprüfung von Inkonsistenzen zwischen dem Repo und dem laufenden System","Korrektur von Abweichungen in der Signierung von Samara.app und Skills-Symlinks","Validierung der Team-ID und der Skill-Eigenschaften"],"pt":["Verificar inconsistências entre o repositório e o sistema em execução","Corrigir a divergência na assinatura do Samara.app e symlinks de habilidades","Validar ID da Equipe e propriedades de habilidades"],"ru":["Проверять несоответствия между репозиторием и работающей системой","Исправлять расхождение в подписи Samara.app и ссылках навыков","Проверять ID команды и свойства навыков"],"ar":["فحص عدم التطابق بين مستودع النظام و تشغيله","تصحيح الانحراف في توقيع Samara.app وروابط المهارات","التحقق من معرف الفريق وخصائص المهارات"]},"limitations":{"en":["Requires access to `~/Developer/samara-main/` and `~/.claude-mind/` directories","Mac-based systems only","Dependent on `sync-organism` script functionality"],"zh":["需要访问 `~/Developer/samara-main/` 和 `~/.claude-mind/` 目录","仅限 Mac 基础系统","依赖于 `sync-organism` 脚本的功能"],"ja":["`~/Developer/samara-main/` と `~/.claude-mind/` ディレクトリへのアクセスが必要","Mac ベースのシステムのみ","`sync-organism` スクリプトの機能に依存"],"ko":["`~/Developer/samara-main/` 및 `~/.claude-mind/` 디렉토리에 대한 액세스가 필요","Mac 기반 시스템만","`sync-organism` 스크립트의 기능에 의존"],"es":["Requiere acceso a los directorios `~/Developer/samara-main/` y `~/.claude-mind/`","Sistemas basados en Mac solamente","Dependiente de la funcionalidad del script `sync-organism`"],"fr":["Nécessite un accès aux répertoires `~/Developer/samara-main/` et `~/.claude-mind/`","Systèmes basés sur Mac uniquement","Dépendant de la fonctionnalité du script `sync-organism`"],"de":["Erfordert Zugriff auf die Verzeichnisse `~/Developer/samara-main/` und `~/.claude-mind/`","Nur Mac-basierte Systeme","Abhängig von der Funktionalität des `sync-organism`-Skripts"],"pt":["Requer acesso aos diretórios `~/Developer/samara-main/` e `~/.claude-mind/`","Sistemas baseados em Mac apenas","Dependente da funcionalidade do script `sync-organism`"],"ru":["Требует доступа к директориям `~/Developer/samara-main/` и `~/.claude-mind/`","Только системы на базе Mac","Зависит от функциональности скрипта `sync-organism`"],"ar":["يتطلب الوصول إلى الدلائل `~/Developer/samara-main/` و `~/.claude-mind/`","نظم مک فقط","يعتمد على وظيفة سكريبت `sync-organism`"]},"version":4},"contentHash":"4197f9610839e4d1224ff7df6998c04f4d778cf81e2568ea8886e6785b4463a9","qualityScore":51}');
