INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('claudeaceae/samara-main/sync', 'sync', 'claudeaceae', 'samara-main', 'community', 'sync claudeaceae samara-main community The sync skill bootstraps a persistent body, memory, and agency for Claude on a Mac, ensuring consistency between the repo and running system. It benefits developers working with AI agents. Sync 技术通过运行 `sync-organism` 脚本来检测 Claude 的运行系统和仓库之间的差异 Sync 技術は `sync-organism` スクリプトを実行して Claude の実行システムとリポジトリの差異を検出します Sync 기술은 `sync-organism` 스크립트를 실행하여 Claude의 실행 시스템과 저장소의 차이를 감지합니다 Sync es una habilidad que permite a los desarrolladores configurar un cuerpo y memoria persistente para Claude en Mac Sync est une compétence qui permet aux développeurs de configurer un corps et une mémoire persistante pour Claude sur Mac Sync ist eine Fähigkeit, die es Entwicklern ermöglicht, einen persistenten Körper und Speicher für Claude auf Mac zu konfigurieren O sync é uma ferramenta que verifica e corrige a divergência entre o repositório e o sistema em execução, garantindo a consistência do agente de IA. Синхронизация - это инструмент, который проверяет и исправляет расхождения между репозиторием и запущенной системой, обеспечивая согласованность ИИ агентов. Sync هو أداة تتحقق من الانحراف بين المستودع والنظام التشغيلي، وتصححه لضمان توافق وكلاء الذكاء الاصطناعي. how to use sync sync setup guide sync alternative sync vs bootstrap sync install mac what is sync skill sync benefits for developers sync and Claude AI sync repository consistency Sync 技术 Claude AI AIエージェント Bootstrap Specification Samara.app Skills Symlinks Team ID G4XVD3J52J Runs the `sync-organism` script to detect differences between the repo, running organism, and built app Checks for correct Team ID (G4XVD3J52J) in Samara.app signing Verifies skills symlinks for all skills properties Utilizes the `~/Developer/samara-main/` repository and `~/.claude-mind/` running organism Optionally fixes drift between the repository and running system sync is a bootstrap specification for maintaining consistency between a repository and a running system on a Mac, enabling Claude''s persistent body, memory, and agency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rockcodelabs/kw-app/kamal-deployment', 'community', 'rockcodelabs', 'kw-app', 'rockcodelabs/kw-app', 'kamal-deployment', 6, 3, 51, '2026-01-28T13:58:03Z', '2026-03-06T06:52:17.783Z', 'e16f5f46b321a80cf9a8c321b21b9cb1502319711abcb32ad5fb7f314b83cf8d', '{"id":"rockcodelabs/kw-app/kamal-deployment","name":"kamal-deployment","description":{"en":"kamal-deployment is an app for the Krakow alpine club that uses Kamal for zero-downtime deployments. It benefits developers by automating migrations and restarts.","zh":"kamal-deployment是一款使用Kamal实现零宕机部署的工具，支持Docker和SSH","ja":"Kamalを使用したゼロダウンタイムデプロイメントツールで、DockerとSSHをサポート","ko":"Kamal을 사용한 무정지 배포 도구로 Docker와 SSH를 지원합니다","es":"kamal-deployment es una aplicación para el club alpino de Krakow que utiliza Kamal para despliegues sin tiempo de inactividad en Raspberry Pi 4 y VPS","fr":"kamal-deployment est une application pour le club alpin de Krakow qui utilise Kamal pour des déploiements sans interruption sur Raspberry Pi 4 et VPS","de":"kamal-deployment ist eine Anwendung für den Krakauer Alpenverein, die Kamal für Zero-Downtime-Deploiements auf Raspberry Pi 4 und VPS verwendet","pt":"O Kamal Deployment é uma aplicação para clubes de montanhismo que utiliza Kamal para implantações sem downtime. Ele oferece recursos como restarts rolantes e migrações automatizadas.","ru":"ИИ Агент Kamal Deployment - это приложение для альпийских клубов, использующее Kamal для установки без простоя. Он предлагает такие функции, как рулонные перезагрузки и автоматические миграции","ar":"وكل Kamal Deployment هو تطبيق لأندية الجبال يستخدم Kamal لتنصيب بدون توقف. يقدم ميزات مثل إعادة تشغيل لولبي وتحويل آلي"},"seo":{"title":{"en":"kamal-deployment: Zero-Downtime Deployment Setup Guide | ...","zh":"kamal-deployment_SETUP指南：零宕机部署","ja":"kamal-deployment セットアップガイド：Zero Downtime Deployment","ko":"kamal-deployment 설정 가이드: 무정지 배포","es":"Guía de configuración de kamal-deployment para despliegue...","fr":"Guide de mise en place de kamal-deployment pour des déplo...","de":"Einrichtungsleitfaden für kamal-deployment mit Zero-Downt...","pt":"Guia de Configuração do Kamal Deployment para Aplicativos...","ru":"Настройка ИИ Агента Kamal Deployment для Альпийского Клуба","ar":"دليل إعداد Kamal Deployment لأندية الجبال"},"description":{"en":"Discover how kamal-deployment streamlines app deployment for the Krakow alpine club. Learn how to set up zero-downtime deployments with Ruby and SSH.","zh":"了解kamal-deployment的技术细节，实现零宕机部署，使用Kamal、Docker和SSH","ja":"Kamal、Docker、SSHを使用したゼロダウンタイムデプロイメントの技術的詳細を学ぶ","ko":"Kamal, Docker, SSH를 사용한 무정지 배포의 기술적 세부 사항을 알아보세요","es":"Aprende a configurar kamal-deployment para despliegues sin tiempo de inactividad en Raspberry Pi 4 y VPS con características como reinicios en secuencia y mi...","fr":"Découvrez comment configurer kamal-deployment pour des déploiements sans interruption sur Raspberry Pi 4 et VPS avec des fonctionnalités comme les redémarrag...","de":"Erfahren Sie, wie Sie kamal-deployment für Zero-Downtime-Deploiements auf Raspberry Pi 4 und VPS mit Funktionen wie Rolling-Restarts und automatisierten Migr...","pt":"Aprenda a configurar o Kamal Deployment para aplicativos de clube de montanhismo com zero-downtime e implantação automatizada","ru":"Узнайте, как настроить ИИ Агент Kamal Deployment для альпийского клуба с нулевым временем простоя и автоматической установкой","ar":"تعرف على كيفية إعداد Kamal Deployment لأندية الجبال مع عدم توقف الصفر وتثبيت آلي"},"definition":{"en":"kamal-deployment is a deployment tool that utilizes Kamal for zero-downtime deployments to staging and production environments.","zh":"kamal-deployment是一款AI工具，用于实现Web应用的零宕机部署","ja":"kamal-deploymentは、Webアプリケーションのゼロダウンタイムデプロイメントを実現するAIエージェント","ko":"kamal-deployment는 웹 애플리케이션의 무정지 배포를实现하는 AI 도구","es":"kamal-deployment es un agente de inteligencia artificial para despliegues sin tiempo de inactividad que utiliza Kamal y tecnologías como Docker y SSH","fr":"kamal-deployment est un agent d''intelligence artificielle pour des déploiements sans interruption qui utilise Kamal et des technologies comme Docker et SSH","de":"kamal-deployment ist ein KI-Agent für Zero-Downtime-Deploiements, der Kamal und Technologien wie Docker und SSH verwendet","pt":"O Kamal Deployment é um agente de implantação de software que permite implantações sem downtime para aplicativos de clube de montanhismo","ru":"ИИ Агент Kamal Deployment - это агент установки программного обеспечения, позволяющий устанавливать без простоя для приложений альпийского клуба","ar":"وكل Kamal Deployment هو وكل إعداد برامج يسمح بتنصيب بدون توقف لتطبيقات أندية الجبال"},"features":{"en":["Rolling restarts using Kamal for zero-downtime deployments","Automated migrations before deployment using Ruby","Docker-based deployment for efficient containerization","SSH-based remote execution for secure deployment","Supports deployment to Raspberry Pi 4 (ARM64) and VPS (x86_64) environments"],"zh":["使用Kamal实现零宕机部署","支持Docker容器化部署","使用SSH进行远程执行","自动化迁移和回滚","支持Raspberry Pi 4和VPS部署"],"ja":["Kamalを使用したゼロダウンタイムデプロイメント","Dockerコンテナ化デプロイメントをサポート","SSHを使用したリモート実行","自動化されたマイグレーションとロールバック","Raspberry Pi 4とVPSのデプロイメントをサポート"],"ko":["Kamal을 사용한 무정지 배포","Docker 컨테이너화 배포를 지원","SSH를 사용한 원격 실행","자동화된 마이그레이션과 롤백","Raspberry Pi 4와 VPS 배포를 지원"],"es":["Despliegues sin tiempo de inactividad con reinicios en secuencia","Migraciones automatizadas antes de la implementación","Implementación basada en Docker","Ejecución remota basada en SSH","Compatibilidad con Raspberry Pi 4 y VPS"],"fr":["Déploiements sans interruption avec redémarrages en roulement","Migrations automatisées avant la mise en production","Déploiement basé sur Docker","Exécution à distance basée sur SSH","Compatibilité avec Raspberry Pi 4 et VPS"],"de":["Zero-Downtime-Deploiements mit Rolling-Restarts","Automatisierte Migrationen vor der Implementierung","Docker-basierte Implementierung","SSH-basierte Remote-Ausführung","Kompatibilität mit Raspberry Pi 4 und VPS"],"pt":["Implantação baseada em Docker","Execução remota baseada em SSH","Restarts rolantes para zero-downtime","Migrações automatizadas antes da implantação","Suporte a Ruby 3.2.2 via chruby","Implantação em Raspberry Pi 4 e VPS"],"ru":["Установка на основе Docker","Удаленная установка на основе SSH","Рулонные перезагрузки для нулевого времени простоя","Автоматические миграции перед установкой","Поддержка Ruby 3.2.2 через chruby","Установка на Raspberry Pi 4 и VPS"],"ar":["تنصيب يستند إلى Docker","تنفيذ بعيد يستند إلى SSH","إعادة تشغيل لولبي لعدم توقف الصفر","تحويل آلي قبل التنصيب","دعم Ruby 3.2.2 من خلال chruby","تنصيب على Raspberry Pi 4 و VPS"]},"keywords":{"en":["how to use kamal-deployment","kamal-deployment setup guide","kamal-deployment vs Capistrano","zero-downtime deployment with Kamal","Ruby deployment tools","SSH-based deployment","kamal-deployment install","kamal-deployment alternative","Kamal deployment tutorial"],"zh":["kamal-deployment","零宕机部署","Kamal","Docker","SSH","AI工具","Web应用部署","自动化部署"],"ja":["kamal-deployment","ゼロダウンタイムデプロイメント","Kamal","Docker","SSH","AIエージェント","Webアプリケーションデプロイメント","自動化デプロイメント"],"ko":["kamal-deployment","무정지 배포","Kamal","Docker","SSH","AI 도구","웹 애플리케이션 배포","자동화 배포"],"es":["kamal-deployment","despliegues sin tiempo de inactividad","Kamal","Docker","SSH","Raspberry Pi 4","VPS","agente de inteligencia artificial","despliegue de aplicaciones","implementación de software"],"fr":["kamal-deployment","déploiements sans interruption","Kamal","Docker","SSH","Raspberry Pi 4","VPS","agent d''intelligence artificielle","déploiement d''applications","mise en production de logiciels"],"de":["kamal-deployment","Zero-Downtime-Deploiements","Kamal","Docker","SSH","Raspberry Pi 4","VPS","KI-Agent","Anwendungs-Deploiement","Software-Implementierung"],"pt":["Kamal Deployment","Implantação de software","Zero-downtime","Docker","SSH","Ruby 3.2.2","chruby","Raspberry Pi 4","VPS","Desenvolvimento de aplicativos"],"ru":["ИИ Агент Kamal Deployment","Установка программного обеспечения","Нулевое время простоя","Docker","SSH","Ruby 3.2.2","chruby","Raspberry Pi 4","VPS","Разработка приложений"],"ar":["وكل Kamal Deployment","تنصيب برامج","عدم توقف الصفر","Docker","SSH","Ruby 3.2.2","chruby","Raspberry Pi 4","VPS","تطوير التطبيقات"]}},"owner":"rockcodelabs","repo":"kw-app","repoPath":"rockcodelabs/kw-app","stars":6,"forks":3,"updatedAt":"2026-01-28T13:58:03Z","topics":[],"category":"community","skillMd":{"name":"kamal-deployment","description":"Zero-downtime deployment with Kamal for kw-app (staging on Raspberry Pi ARM64, production on VPS x86_64). Covers deployment workflows, console access, and troubleshooting.","bodyPreview":"# Kamal Deployment (kw-app)\n\n## Overview\n\nkw-app uses Kamal for zero-downtime deployments to:\n- **Staging**: Raspberry Pi 4 (ARM64, ~4GB RAM)\n- **Production**: VPS (x86_64)\n\n**Key Features:**\n- Rolling restarts (zero downtime)\n- Automated migrations before deploy\n- Docker-based deployment\n- SSH-based remote execution\n\n## Prerequisites\n\n**Local Machine Requirements:**\n- Ruby 3.2.2 (via chruby) - **NOT Docker!**\n- Kamal gem installed globally or in bundle\n- SSH keys configured for deployment serve","body":"# Kamal Deployment (kw-app)\n\n## Overview\n\nkw-app uses Kamal for zero-downtime deployments to:\n- **Staging**: Raspberry Pi 4 (ARM64, ~4GB RAM)\n- **Production**: VPS (x86_64)\n\n**Key Features:**\n- Rolling restarts (zero downtime)\n- Automated migrations before deploy\n- Docker-based deployment\n- SSH-based remote execution\n\n## Prerequisites\n\n**Local Machine Requirements:**\n- Ruby 3.2.2 (via chruby) - **NOT Docker!**\n- Kamal gem installed globally or in bundle\n- SSH keys configured for deployment servers\n\n## Architecture\n\n### Deployment Flow\n\n```\nLocal Machine (chruby 3.2.2)\n    ↓\nRun: kamal deploy -d staging/production\n    ↓\n1. Build Docker image (ARM64 or x86_64)\n2. Push to registry\n3. SSH to target server\n4. Run migrations (if needed)\n5. Pull new image\n6. Rolling restart (zero downtime)\n7. Health checks\n```\n\n### Why Native Ruby for Kamal?\n\n- Kamal runs on **host machine**, not in Docker\n- Needs native Ruby 3.2.2 (via chruby)\n- Docker is used ONLY for the app container being deployed\n\n## Configuration Files\n\n```\nconfig/\n├── deploy.yml               # Base config (not used directly)\n├── deploy.staging.yml       # Staging (Raspberry Pi)\n└── deploy.production.yml    # Production (VPS)\n```\n\n### Key Settings\n\n**Staging (deploy.staging.yml):**\n- Server: Raspberry Pi 4\n- Architecture: ARM64\n- Memory: ~4GB (use batches for large operations)\n- Branch: `develop`\n\n**Production (deploy.production.yml):**\n- Server: VPS\n- Architecture: x86_64\n- Branch: `main`\n\n## Common Commands\n\n### Deployment Commands\n\n**All Kamal commands run with native Ruby (chruby):**\n\n```bash\n# Deploy to staging\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal deploy -d staging''\n\n# Deploy to production\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal deploy -d production''\n\n# Deploy specific branch\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal deploy -d staging --version=feature-branch''\n\n# Check deployment status\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app details -d staging''\n\n# View logs\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app logs -d staging''\n\n# Rollback to previous version\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal rollback -d production''\n```\n\n### Console Access\n\n**Staging Console:**\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app exec -d staging -i --reuse \"bin/rails console\"''\n```\n\n**Production Console:**\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app exec -d production -i --reuse \"bin/rails console\"''\n```\n\n**Flag Meanings:**\n- `-d staging/production` - Destination environment\n- `-i` / `--interactive` - Keep terminal interactive (required for console)\n- `--reuse` - Reuse existing SSH connection (no registry auth needed)\n\n### One-off Commands\n\n**Run rake task:**\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app exec -d staging --reuse \"bin/rails db:migrate:status\"''\n```\n\n**Run Rails runner:**\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app exec -d staging --reuse \"bin/rails runner \\\"puts User.count\\\"\"''\n```\n\n## Deployment Workflow\n\n### 1. Pre-Deployment Checklist\n\n```\nBefore deploying:\n- [ ] All tests passing locally\n- [ ] Migrations reviewed and tested\n- [ ] Environment variables updated in credentials\n- [ ] Staging tested (for production deploys)\n- [ ] Backup taken (for production)\n```\n\n### 2. Standard Deployment\n\n```bash\n# 1. Check current status\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app details -d staging''\n\n# 2. Deploy\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal deploy -d staging''\n\n# 3. Verify deployment\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app logs -d staging''\n\n# 4. Smoke test via console\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app exec -d staging -i --reuse \"bin/rails console\"''\n```\n\n### 3. Migration Deployment\n\n**Kamal runs migrations automatically before deploying new containers.**\n\nIf migration fails, deployment stops (zero-downtime preserved).\n\n**Manual migration (if needed):**\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app exec -d staging --reuse \"bin/rails db:migrate\"''\n```\n\n### 4. Emergency Rollback\n\n```bash\n# Rollback to previous version\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal rollback -d production''\n\n# Check status\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app details -d production''\n```\n\n## Troubleshooting\n\n### Issue: Deployment Hangs\n\n**Symptoms:** Kamal stuck on \"Waiting for health check\"\n\n**Solutions:**\n\n1. Check app logs:\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app logs -d staging''\n```\n\n2. Check container status:\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app details -d staging''\n```\n\n3. SSH to server and check Docker:\n```bash\nssh staging-server\ndocker ps\ndocker logs <container-id>\n```\n\n### Issue: \"Registry Authentication Failed\"\n\n**Cause:** Trying to use `--reuse` without an active connection.\n\n**Solutions:**\n\n1. Remove `--reuse` for first connection:\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app exec -d staging -i \"bin/rails console\"''\n```\n\n2. Or authenticate first:\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal registry login -d staging''\n```\n\n### Issue: Out of Memory (Staging Pi)\n\n**Symptoms:** Deployment succeeds but app crashes on Raspberry Pi.\n\n**Cause:** Pi has only ~4GB RAM.\n\n**Solutions:**\n\n1. Reduce Sidekiq concurrency in staging\n2. Use database batches for large operations\n3. Deploy during low-traffic times\n4. Consider upgrading Pi memory\n\n### Issue: \"Wrong Ruby Version\"\n\n**Symptoms:** \n```\nYour Ruby version is 2.6.10, but your Gemfile specified 3.2.2\n```\n\n**Cause:** Running Kamal without chruby.\n\n**Solution:** Always wrap in `zsh -c ''source ~/.zshrc && chruby 3.2.2 && ...''`\n\n### Issue: Migrations Fail During Deployment\n\n**Symptoms:** Deployment stops with migration error.\n\n**Solution:**\n\n1. Check migration on local:\n```bash\ndocker-compose exec -T app bundle exec rake db:migrate\n```\n\n2. Fix migration and redeploy\n3. OR manually run on server:\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app exec -d staging --reuse \"bin/rails db:migrate\"''\n```\n\n## CI/CD Integration\n\n### GitHub Actions (Automated)\n\n**Staging deploys automatically on push to `develop`:**\n```yaml\nname: Deploy to Staging\non:\n  push:\n    branches: [develop]\njobs:\n  deploy:\n    runs-on: self-hosted  # Runs on Pi\n    steps:\n      - uses: actions/checkout@v2\n      - name: Deploy\n        run: bundle exec kamal deploy -d staging\n```\n\n**Production deploys on push to `main`:**\n```yaml\nname: Deploy to Production\non:\n  push:\n    branches: [main]\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v2\n      - name: Deploy\n        run: bundle exec kamal deploy -d production\n```\n\n## Security Best Practices\n\n### ✅ Always Do\n\n- Use SSH keys (never passwords)\n- Store secrets in Rails encrypted credentials\n- Use `--reuse` flag to avoid exposing registry credentials\n- Review migrations before production deploy\n- Test on staging first\n- Keep Kamal gem updated\n\n### ⚠️ Ask First\n\n- Modifying `deploy.*.yml` files\n- Changing server SSH configurations\n- Deploying to production outside of CI/CD\n- Running destructive rake tasks on production\n\n### 🚫 Never Do\n\n- Commit `master.key` files\n- Hardcode passwords in deploy configs\n- Deploy directly to production without staging test\n- Skip migrations testing\n- Force deploy without health checks\n\n## Monitoring\n\n### Post-Deployment Verification\n\n```bash\n# 1. Check app is running\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app details -d production''\n\n# 2. Check logs for errors\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app logs -d production --tail 100''\n\n# 3. Test critical paths (console)\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal app exec -d production -i --reuse \"bin/rails console\"''\n> User.count\n> # Test other critical models\n\n# 4. Check Sidekiq\n# Visit: https://your-domain.com/sidekiq\n```\n\n### Monitoring Endpoints\n\n- **Sidekiq Web UI**: `https://domain.com/sidekiq`\n- **Health Check**: `https://domain.com/health` (if configured)\n- **App Logs**: Via Kamal `app logs` command\n\n## Quick Reference\n\n### Command Pattern\n\n**ALL Kamal commands:**\n```bash\nzsh -c ''source ~/.zshrc && chruby 3.2.2 && bundle exec kamal <command> -d <env> [flags]''\n```\n\n### Common Operations\n\n| Task | Command |\n|------|---------|\n| Deploy | `kamal deploy -d staging` |\n| Rollback | `kamal rollback -d staging` |\n| Console | `kamal app exec -d staging -i --reuse \"bin/rails console\"` |\n| Run rake task | `kamal app exec -d staging --reuse \"bin/rails <task>\"` |\n| View logs | `kamal app logs -d staging` |\n| Check status | `kamal app details -d staging` |\n\n### Key Flags\n\n- `-d <env>` - Destination (staging/production)\n- `-i` / `--interactive` - Interactive mode (console)\n- `--reuse` - Reuse SSH connection\n- `--version=<branch>` - Deploy specific branch\n\n## Additional Resources\n\n- **Kamal Docs**: https://kamal-deploy.org/\n- **kw-app Ansible Setup**: `ansible/README.md`\n- **Server Provisioning**: `ansible/playbooks/`\n- **Deploy Configs**: `config/deploy.*.yml`\n\n---\n\n**Version**: 2.0  \n**Last Updated**: 2024-01  \n**Maintained By**: kw-app team"},"lastSynced":"2026-03-06T06:52:17.783Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring automated zero-downtime deployments with Ruby and Kamal integration.","zh":"适用于需要自动零停机时间部署的DevOps代理，支持Ruby和Kamal集成。","ja":"RubyおよびKamalの統合を必要とする自動ゼロダウンタイムデプロイを必要とするDevOpsエージェントに最適。","ko":"Ruby 및 Kamal 통합을 필요로 하는 자동 제로 다운타임 배포가 필요한 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren implementaciones automatizadas con cero tiempo de inactividad con integración de Ruby y Kamal.","fr":"Idéal pour les agents DevOps nécessitant des déploiements automatiques avec zéro temps d''arrêt et une intégration Ruby et Kamal.","de":"Ideal für DevOps-Agents, die automatisierte Bereitstellungen mit null Ausfallzeit und Ruby- und Kamal-Integration erfordern.","pt":"Ideal para agentes DevOps que requerem implantações automatizadas sem tempo de inatividade com integração Ruby e Kamal.","ru":"Идеально подходит для агентов DevOps, требующих автоматизированной развертки без простоев с интеграцией Ruby и Kamal.","ar":"مثالي لعميل DevOps الذين يحتاجون إلى عمليات نشر آلي بدون توقف مع تكامل Ruby و Kamal."},"recommendation":{"en":"Empowers agents to automate migrations and restarts using Kamal, facilitating Docker-based deployments and SSH-based remote execution for efficient staging and production environments on Raspberry Pi 4 and VPS.","zh":"赋予代理人使用Kamal自动化迁移和重启的能力，支持Docker-based部署和SSH-based远程执行，能够高效地进行分阶段和生产环境的部署在Raspberry Pi 4和VPS上。","ja":"Kamalを使用してエージェントが移行と再起動を自動化できるようにし、DockerベースのデプロイとSSHベースのリモート実行をサポートし、Raspberry Pi 4とVPS上でのステージングとプロダクション環境を効率的に行えるようにします。","ko":"에이전트가 Kamal을 사용하여 마이그레이션 및 재시작을 자동화할 수 있도록 하며 Docker 기반 배포 및 SSH 기반 원격 실행을 지원하여 Raspberry Pi 4 및 VPS에서 효율적으로 스테이징 및 프로덕션 환경을 배포할 수 있습니다.","es":"Habilita a los agentes a automatizar migraciones y reinicios utilizando Kamal, lo que facilita los despliegues basados en Docker y la ejecución remota basada en SSH para entornos de ensayo y producción eficientes en Raspberry Pi 4 y VPS.","fr":"Permet aux agents d''automatiser les migrations et les redémarrages à l''aide de Kamal, facilitant ainsi les déploiements basés sur Docker et l''exécution à distance basée sur SSH pour des environnements de préproduction et de production efficaces sur Raspberry Pi 4 et VPS.","de":"Ermächtigt Agents, Migrationen und Neustarts mit Kamal zu automatisieren, wodurch Docker-basierte Bereitstellungen und SSH-basierte Remote-Ausführung für effiziente Staging- und Produktionsumgebungen auf Raspberry Pi 4 und VPS erleichtert werden.","pt":"Habilita os agentes a automatizar migrações e reinicializações usando Kamal, facilitando implantações baseadas em Docker e execução remota baseada em SSH para ambientes de preparo e produção eficientes no Raspberry Pi 4 e VPS.","ru":"Позволяет агентам автоматизировать миграции и перезапуски с помощью Kamal, облегчая развертку на основе Docker и удаленную выполнение на основе SSH для эффективных сред подготовки и производства на Raspberry Pi 4 и VPS.","ar":"يتمكن العملاء من تسهيل عمليات النشر والتحديثات باستخدام Kamal، مما يسهل عمليات النشر المستندة إلى Docker والتنفيذ عن بعد بالاعتماد على SSH لبيئات الإعداد والإنتاج الفعالة على Raspberry Pi 4 و VPS."},"useCases":{"en":["Automating rolling restarts for zero-downtime deployments","Deploying applications on Raspberry Pi 4 and VPS using Docker","Performing automated migrations before deployment"],"zh":["自动执行滚动重启以实现零停机时间部署","使用Docker在Raspberry Pi 4和VPS上部署应用程序","部署前自动执行迁移"],"ja":["ゼロダウンタイムデプロイのためのローリング再起動の自動化","Dockerを使用してRaspberry Pi 4とVPSにアプリケーションをデプロイする","デプロイ前の自動移行の実行"],"ko":["제로 다운타임 배포를 위한 롤링 재시작 자동화","Docker를 사용하여 Raspberry Pi 4 및 VPS에 애플리케이션 배포","배포 전 자동 마이그레이션 수행"],"es":["Automatizar reinicios en rol para implementaciones con cero tiempo de inactividad","Implementar aplicaciones en Raspberry Pi 4 y VPS mediante Docker","Realizar migraciones automatizadas antes de la implementación"],"fr":["Automatiser les redémarrages en roulement pour des déploiements avec zéro temps d''arrêt","Déployer des applications sur Raspberry Pi 4 et VPS à l''aide de Docker","Effectuer des migrations automatisées avant le déploiement"],"de":["Automatisierung von Rollbacks für Bereitstellungen mit null Ausfallzeit","Bereitstellung von Anwendungen auf Raspberry Pi 4 und VPS mithilfe von Docker","Durchführung automatisierter Migrationen vor der Bereitstellung"],"pt":["Automatizar reinicializações em rotação para implantações sem tempo de inatividade","Implantar aplicações no Raspberry Pi 4 e VPS usando Docker","Realizar migrações automatizadas antes da implantação"],"ru":["Автоматизировать перезапуски в ротации для развертки без простоев","Развертывать приложения на Raspberry Pi 4 и VPS с помощью Docker","Выполнять автоматические миграции до развертки"],"ar":["تحسين عمليات إعادة التشغيل الدوري لنشرات بدون توقف","نشر التطبيقات على Raspberry Pi 4 و VPS باستخدام Docker","إجراء عمليات نقل آلي قبل النشر"]},"limitations":{"en":["Requires Ruby 3.2.2 installation","Needs Kamal gem installed globally or in bundle","SSH keys must be configured for deployment server"],"zh":["需要安装Ruby 3.2.2","需要全局或捆绑安装Kamal gem","需要为部署服务器配置SSH密钥"],"ja":["Ruby 3.2.2のインストールが必要","Kamal gemをグローバルまたはバンドルにインストールする必要がある","デプロイサーバー用のSSH鍵を設定する必要がある"],"ko":["Ruby 3.2.2 설치 필요","전역 또는 번들에 Kamal gem 설치 필요","배포 서버에 대한 SSH 키 구성 필요"],"es":["Requiere instalación de Ruby 3.2.2","Necesita la gema Kamal instalada de forma global o en bundle","Las claves SSH deben estar configuradas para el servidor de implementación"],"fr":["Nécessite l''installation de Ruby 3.2.2","Nécessite la gemme Kamal installée de manière globale ou dans un bundle","Les clés SSH doivent être configurées pour le serveur de déploiement"],"de":["Benötigt Ruby 3.2.2-Installation","Benötigt Kamal-Gem, die global oder im Bundle installiert ist","SSH-Schlüssel müssen für den Bereitstellungs-Server konfiguriert sein"],"pt":["Requer instalação do Ruby 3.2.2","Precisa da gem Kamal instalada globalmente ou em bundle","As chaves SSH devem ser configuradas para o servidor de implantação"],"ru":["Требуется установка Ruby 3.2.2","Необходимо глобальное или пакетное установка Kamal","Ключи SSH должны быть настроены для сервера развертки"],"ar":["يتطلب تثبيت Ruby 3.2.2","يحتاج إلى تثبيت Kamal عالمي أو في حزمة","يجب تكوين مفاتيح SSH للخادم النشر"]},"version":4},"contentHash":"e16f5f46b321a80cf9a8c321b21b9cb1502319711abcb32ad5fb7f314b83cf8d","qualityScore":51}');
