INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('abeldotam/bmad-viewer/webapp-testing', 'webapp-testing', 'abeldotam', 'bmad-viewer', 'community', 'webapp-testing abeldotam bmad-viewer community The webapp-testing skill enables developers to test and debug local web applications using Playwright automation, covering frontend functionality, UI behavior, and more Web应用测试技能提供了使用Playwright自动化测试和调试本地Web应用的功能，包括验证UI行为和交互 Webアプリケーションテストスキルは、Playwright自動化を使用してローカルWebアプリケーションをテストおよびデバッグする機能を提供する 웹애플리케이션 테스트 스킬은 Playwright 자동화를 사용하여 로컬 웹애플리케이션을 테스트 및 디버깅하는 기능을 제공 La habilidad de pruebas de aplicaciones web permite probar y depurar aplicaciones web locales con Playwright. Automatiza la verificación de la interfaz de usuario y la depuración de problemas La compétence de test d''applications web permet de tester et de déboguer des applications web locales avec Playwright. Elle automatise la vérification de l''interface utilisateur et la débogage des problèmes Die Fähigkeit zum Testen von Webanwendungen ermöglicht das Testen und Debuggen lokaler Webanwendungen mit Playwright. Sie automatisiert die Überprüfung der Benutzeroberfläche und die Fehlersuche O webapp-testing é uma habilidade que permite testar e depurar aplicativos web locais usando automação Playwright. ИИ Агенты для Web Application Testing - это навык, который позволяет проводить комплексное тестирование и отладку локальных веб-приложений с помощью автоматизации Playwright. webapp-testing هو مهارة تتيح اختبار وتحديد الأخطاء في التطبيقات الويب المحلية باستخدام автоматизация Playwright. how to use webapp-testing webapp-testing setup guide webapp-testing vs Selenium Playwright automation tutorial web application testing best practices webapp-testing install for AI agents Web应用测试 Playwright自动化 前端功能测试 UI行为验证 截图捕获 浏览器控制台日志检查 表单提交验证 响应式设计检查 AIエージェント Test frontend functionality in a real browser using Playwright Verify UI behavior and interactions for web applications Debug web application issues and capture screenshots for documentation Inspect browser console logs for error analysis Validate form submissions and user flows for seamless user experience webapp-testing is a skill that enables comprehensive testing and debugging of local web applications using Playwright automation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NguyenSiTrung/CLIConfigEditUI/conductor', 'community', 'NguyenSiTrung', 'CLIConfigEditUI', 'NguyenSiTrung/CLIConfigEditUI', 'conductor', 6, 3, 51, '2026-02-17T13:44:11Z', '2026-03-06T06:53:50.309Z', 'cd560070d1c13ef4cf529df11725a7b0475860181b07a6b80ac01e1b57ed5eeb', '{"id":"NguyenSiTrung/CLIConfigEditUI/conductor","name":"conductor","description":{"en":"Conductor enables context-driven development for AI agents by establishing project context and organizing work into tracks. It benefits developers by streamlining their workflow.","zh":"Conductor 实现上下文驱动开发，通过建立项目上下文、组织工作和创建规格，提高开发效率","ja":"Conductor はコンテキスト駆動開発を実現し、プロジェクトのコンテキストを確立し、作業を整理し、仕様を生成して開発効率を高める","ko":"Conductor 는 컨텍스트 드리븐 개발을 구현하여 프로젝트 컨텍스트를 설정하고 작업을 조직하고 사양을 생성하여 개발 효율성을 높임","es":"Conductor es una herramienta de desarrollo que permite establecer el contexto del proyecto y organizar el trabajo en tareas paralelas","fr":"Conductor est un outil de développement qui permet d''établir le contexte du projet et d''organiser les tâches en parallèle","de":"Conductor ist ein Entwicklungstool, das es ermöglicht, den Projektkontext zu erstellen und die Arbeit in parallele Aufgaben zu organisieren","pt":"Conductor é uma ferramenta de desenvolvimento de software que permite a criação de specs e planos de implementação com TDD e execução paralela de tarefas","ru":"Conductor - это инструмент для разработки программного обеспечения, который позволяет создавать спецификации и планы реализации с помощью TDD и параллельного выполнения задач","ar":"Conductor هو أداة لتنمية البرمجيات التي تمكن من إنشاء مواصفات وخطط تنفيذ مع ممارسات TDD وتنفيذ متوازي للمهام"},"seo":{"title":{"en":"Conductor: Context-Driven Development Setup Guide | AI Ag...","zh":"Conductor 设置指南：实现上下文驱动开发","ja":"Conductor 導入ガイド：コンテキスト駆動開発の実現","ko":"Conductor 설정 가이드: 컨텍스트 드리븐 개발 구현","es":"Conductor: Guía de configuración para desarrollo dirigido...","fr":"Conductor: Guide de mise en place pour le développement p...","de":"Conductor: Einrichtungsleitfaden für kontextgetriebene En...","pt":"Conductor: Guia de Configuração para Desenvolvimento de S...","ru":"Conductor: Настройка для контекстно-ориентированного разв...","ar":"Conductor: دليل إعداد لتنمية البرمجيات مع أدوات الذكاء ال..."},"description":{"en":"Unlock efficient development with Conductor. Learn how to establish project context, organize work, and execute with TDD practices. Get started now!","zh":"了解 Conductor 的优势，实现上下文驱动开发，提高开发效率，使用 TDD 实践和进度跟踪","ja":"Conductor の利点を学び、コンテキスト駆動開発を実現し、開発効率を高め、TDD プラクティスと進度追跡を使用","ko":"Conductor 의 장점을 알아보고 컨텍스트 드리븐 개발을 구현하여 개발 효율성을 높이고 TDD 실천과 진행 상황 추적을 사용","es":"Aprende a utilizar Conductor para establecer el contexto del proyecto, organizar el trabajo y ejecutar tareas de forma paralela con subagentes","fr":"Découvrez comment utiliser Conductor pour établir le contexte du projet, organiser les tâches et exécuter des tâches en parallèle avec des sous-agents","de":"Erfahren Sie, wie Sie Conductor verwenden, um den Projektkontext zu erstellen, die Arbeit zu organisieren und Aufgaben parallel mit Subagenten auszuführen","pt":"Aprenda a configurar o Conductor para desenvolvimento de software eficaz com TDD e execução paralela de tarefas","ru":"Узнайте, как настроить Conductor для эффективного развития программного обеспечения с помощью TDD и параллельного выполнения задач с ИИ Агентами","ar":"تعلم كيفية ضبط Conductor لتنمية البرمجيات الفعالة مع ممارسات TDD وتنفيذ متوازي للمهام مع أدوات الذكاء الاصطناعي"},"definition":{"en":"Conductor is a context-driven development tool that enables AI agents to measure twice and code once, supporting parallel execution of independent tasks.","zh":"Conductor 是一种上下文驱动开发工具，帮助开发者建立项目上下文、组织工作和创建规格","ja":"Conductor はコンテキスト駆動開発ツールであり、開発者がプロジェクトのコンテキストを確立し、作業を整理し、仕様を生成するのに役立ちます","ko":"Conductor 는 컨텍스트 드리븐 개발 도구로 개발자가 프로젝트 컨텍스트를 설정하고 작업을 조직하고 사양을 생성하는 데 도움","es":"Conductor es una herramienta de desarrollo dirigido por contexto que permite a los desarrolladores organizar y ejecutar tareas de forma eficiente","fr":"Conductor est un outil de développement piloté par le contexte qui permet aux développeurs d''organiser et d''exécuter des tâches de manière efficace","de":"Conductor ist ein Tool für kontextgetriebene Entwicklung, das es Entwicklern ermöglicht, Aufgaben zu organisieren und effizient auszuführen","pt":"Conductor é uma ferramenta de desenvolvimento de software que permite a criação de specs e planos de implementação","ru":"Conductor - это инструмент для разработки программного обеспечения, который позволяет создавать спецификации и планы реализации","ar":"Conductor هو أداة لتنمية البرمجيات التي تمكن من إنشاء مواصفات وخطط تنفيذ"},"features":{"en":["Establishes project context including product vision, tech stack, and workflow","Organizes work into tracks for features, bugs, and improvements","Creates specs and phased implementation plans","Executes with Test-Driven Development (TDD) practices and progress tracking","Supports parallel execution of independent tasks using sub-agents"],"zh":["建立项目上下文","组织工作为特性、bug 和改进","创建规格和分阶段的实施计划","使用 TDD 实践和进度跟踪","并行执行独立任务"],"ja":["プロジェクトのコンテキストを確立","作業を特性、バグ、改善として整理","仕様と段階的な実施計画を生成","TDD プラクティスと進度追跡を使用","独立したタスクの並行実行"],"ko":["프로젝트 컨텍스트 설정","작업을 특성, 버그, 개선으로 조직","사양과 단계적 구현 계획 생성","TDD 실천과 진행 상황 추적 사용","독립적인 태스크의 병렬 실행"],"es":["Establecimiento de contexto del proyecto","Organización del trabajo en tareas paralelas","Creación de especificaciones y planes de implementación","Ejecución de tareas con prácticas de TDD","Ejecución paralela de tareas independientes con subagentes"],"fr":["Établissement du contexte du projet","Organisation des tâches en parallèle","Création de spécifications et de plans de mise en œuvre","Exécution de tâches avec des pratiques TDD","Exécution parallèle de tâches indépendantes avec des sous-agents"],"de":["Erstellung des Projektkontexts","Organisation der Arbeit in parallele Aufgaben","Erstellung von Spezifikationen und Implementierungsplänen","Ausführung von Aufgaben mit TDD-Praktiken","Parallele Ausführung unabhängiger Aufgaben mit Subagenten"],"pt":["Criação de specs e planos de implementação","Execução paralela de tarefas independentes","Suporte a TDD (Test-Driven Development)","Organização do trabalho em ''trilhas'' (recursos, bugs, melhorias)","Estabelecimento de contexto de projeto (visão do produto, pilha de tecnologia, fluxo de trabalho)"],"ru":["Создание спецификаций и планов реализации","Параллельное выполнение независимых задач","Поддержка TDD (Test-Driven Development)","Организация работы в ''треках'' (функции, ошибки, улучшения)","Установка контекста проекта (видение продукта, технологический стек, рабочий процесс)"],"ar":["إنشاء مواصفات وخطط تنفيذ","تنفيذ متوازي للمهام المستقلة","دعم TDD (التطوير الموجه بالاختبار)","تنظيم العمل في ''مسارات'' (ميزات، أخطاء، تحسينات)","تحديد سياق المشروع (رؤية المنتج، حزمة التكنولوجيا، تدفق العمل)"]},"keywords":{"en":["how to use conductor","conductor alternative","conductor setup guide","what is conductor","conductor vs jira","conductor install","conductor context-driven development","conductor tdd practices","conductor parallel execution"],"zh":["Conductor","上下文驱动开发","TDD","进度跟踪","并行执行","项目管理","软件开发","AI开发工具","AIエージェント"],"ja":["Conductor","コンテキスト駆動開発","TDD","進度追跡","並行実行","プロジェクト管理","ソフトウェア開発","AI開発ツール","AIエージェント"],"ko":["Conductor","컨텍스트 드리븐 개발","TDD","진행 상황 추적","병렬 실행","프로젝트 관리","소프트웨어 개발","AI 개발 도구","AI 에이전트"],"es":["Conductor","desarrollo dirigido por contexto","herramientas de desarrollo","TDD","subagentes","desarrollo de software","ingeniería de software","Agente de IA","herramientas de Agente de IA"],"fr":["Conductor","développement piloté par le contexte","outils de développement","TDD","sous-agents","développement de logiciels","ingénierie de logiciels","Agent d''IA","outils d''Agent d''IA"],"de":["Conductor","kontextgetriebene Entwicklung","Entwicklungstools","TDD","Subagenten","Softwareentwicklung","Softwareingenieurwesen","KI-Agent","KI-Agent-Tools"],"pt":["Conductor","desenvolvimento de software","TDD","execução paralela","specs","planos de implementação","ferramentas de desenvolvimento","desenvolvimento ágil","gerenciamento de projetos"],"ru":["Conductor","разработка программного обеспечения","TDD","параллельное выполнение","спецификации","планы реализации","инструменты разработки","гибкая разработка","управление проектами","ИИ Агенты"],"ar":["Conductor","تنمية البرمجيات","TDD","تنفيذ متوازي","مواصفات","خطط تنفيذ","أدوات التطوير","تنمية البرمجيات المتنقلة","إدارة المشاريع","أدوات الذكاء الاصطناعي"]}},"owner":"NguyenSiTrung","repo":"CLIConfigEditUI","repoPath":"NguyenSiTrung/CLIConfigEditUI","stars":6,"forks":3,"updatedAt":"2026-02-17T13:44:11Z","topics":[],"category":"community","skillMd":{"name":"conductor","description":"|","bodyPreview":"# Conductor: Context-Driven Development\n\nMeasure twice, code once.\n\n## Overview\n\nConductor enables context-driven development by:\n1. Establishing project context (product vision, tech stack, workflow)\n2. Organizing work into \"tracks\" (features, bugs, improvements)\n3. Creating specs and phased implementation plans\n4. Executing with TDD practices and progress tracking\n5. **Parallel execution** of independent tasks using sub-agents\n\n## Parallel Execution (New Feature)\n\nConductor now supports parall","body":"# Conductor: Context-Driven Development\n\nMeasure twice, code once.\n\n## Overview\n\nConductor enables context-driven development by:\n1. Establishing project context (product vision, tech stack, workflow)\n2. Organizing work into \"tracks\" (features, bugs, improvements)\n3. Creating specs and phased implementation plans\n4. Executing with TDD practices and progress tracking\n5. **Parallel execution** of independent tasks using sub-agents\n\n## Parallel Execution (New Feature)\n\nConductor now supports parallel task execution for eligible phases:\n\n### How It Works\n- During `/conductor-newtrack`, tasks are analyzed for parallelization potential\n- Tasks with no file conflicts and no dependencies can run in parallel\n- Parallel phases use `<!-- execution: parallel -->` annotation\n- Each task has `<!-- files: ... -->` for exclusive file ownership\n- Dependencies use `<!-- depends: ... -->` annotation\n\n### Plan.md Format for Parallel Phases\n```markdown\n## Phase 1: Core Setup\n<!-- execution: parallel -->\n\n- [ ] Task 1: Create auth module\n  <!-- files: src/auth/index.ts, src/auth/index.test.ts -->\n  \n- [ ] Task 2: Create config module\n  <!-- files: src/config/index.ts -->\n  \n- [ ] Task 3: Create utilities\n  <!-- files: src/utils/index.ts -->\n  <!-- depends: task1 -->\n```\n\n### Execution Flow\n1. **Coordinator** parses parallel annotations\n2. Detects file conflicts (fails safe if found)\n3. Spawns sub-agents via `Task()` for independent tasks\n4. Monitors `parallel_state.json` for completion\n5. Aggregates results and updates plan.md\n\n### When to Use Parallel Execution\n- ✅ Tasks modifying different files\n- ✅ Independent components (auth, config, utils)\n- ✅ Multiple test file creation\n- ❌ Tasks with shared state\n- ❌ Tasks with sequential dependencies\n\n## Context Loading\n\nWhen this skill activates, load these files to understand the project:\n1. `conductor/product.md` - Product vision and goals\n2. `conductor/tech-stack.md` - Technology constraints\n3. `conductor/workflow.md` - Development methodology (TDD, commits)\n4. `conductor/tracks.md` - Current work status\n\n**Important**: Conductor commits locally but never pushes. Users decide when to push to remote.\n\nFor active tracks, also load:\n- `conductor/tracks/<track_id>/spec.md`\n- `conductor/tracks/<track_id>/plan.md`\n\n## Beads Integration\n\nBeads integration is **always attempted** for persistent task memory. If `bd` CLI is unavailable or fails, the user can choose to continue without it.\n\n### Detection (MUST check before using bd commands)\n\nBefore using ANY `bd` command, you MUST verify:\n1. `bd` CLI is installed: `which bd` returns a path\n2. `conductor/beads.json` exists AND has `\"enabled\": true`\n\n```bash\n# Check availability - run this before any bd command\nif which bd > /dev/null 2>&1 && [ -f conductor/beads.json ]; then\n  BEADS_ENABLED=$(cat conductor/beads.json | grep -o ''\"enabled\"[[:space:]]*:[[:space:]]*true'' || echo \"\")\n  if [ -n \"$BEADS_ENABLED\" ]; then\n    # Beads is available and enabled - use bd commands\n  fi\nfi\n```\n\n### If Beads is NOT available:\n- **DO NOT** run any `bd` commands\n- Use only plan.md markers for task tracking\n- All conductor commands work normally without Beads\n\n### If Beads IS available:\n- Tracks become Beads epics\n- Tasks sync to Beads for persistent memory\n- Use `bd ready` instead of manual task selection\n- Notes survive context compaction\n\n## Proactive Behaviors\n\n1. **On new session**: Check for in-progress tracks, offer to resume\n2. **On task completion**: Suggest next task or phase verification\n3. **On blocked detection**: Alert user and suggest alternatives\n4. **On all tasks complete**: Congratulate and offer archive/cleanup\n5. **On stale context detected**: If setup >2 days old or significant codebase changes detected, suggest `/conductor-refresh`\n6. **On Beads available**: If `bd` CLI detected during setup, offer integration\n\n## Intent Mapping\n\n| User Intent | Command |\n|-------------|---------|\n| \"Set up this project\" | `/conductor-setup` |\n| \"Create a new feature\" | `/conductor-newtrack [desc]` |\n| \"Start working\" / \"Implement\" | `/conductor-implement [id]` |\n| \"What''s the status?\" | `/conductor-status` |\n| \"Undo that\" / \"Revert\" | `/conductor-revert` |\n| \"Check for issues\" | `/conductor-validate` |\n| \"This is blocked\" | `/conductor-block` |\n| \"Skip this task\" | `/conductor-skip` |\n| \"This needs revision\" / \"Spec is wrong\" | `/conductor-revise` |\n| \"Save context\" / \"Handoff\" / \"Transfer to next section\" | `/conductor-handoff` |\n| \"Archive completed\" | `/conductor-archive` |\n| \"Export summary\" | `/conductor-export` |\n| \"Docs are outdated\" / \"Sync with codebase\" | `/conductor-refresh` |\n\n## References\n\n- **Detailed workflows**: [references/workflows.md](references/workflows.md) - Step-by-step command execution\n- **Directory structure**: [references/structure.md](references/structure.md) - File layout and status markers\n- **Beads integration**: [references/beads-integration.md](references/beads-integration.md)\n"},"lastSynced":"2026-03-06T06:53:50.309Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined workflow and context-driven development capabilities.","zh":"非常适合需要简化工作流和上下文驱动开发能力的开发代理。","ja":"開発エージェントがストリームライン化されたワークフローとコンテキスト駆動の開発機能を必要とする場合に最適です。","ko":"개발 에이전트가 스트림 라인화된 워크 플로우와 컨텍스트 驅動 개발 능력을 필요로 하는 경우에 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan un flujo de trabajo optimizado y capacidades de desarrollo impulsadas por contexto.","fr":"Parfait pour les agents de développement ayant besoin d''un workflow rationalisé et de capacités de développement pilotées par le contexte.","de":"Perfekt für Entwicklungsmittel, die einen optimierten Arbeitsablauf und kontextgetriebene Entwicklungsfähigkeiten benötigen.","pt":"Perfeito para Development Agents que necessitam de um fluxo de trabalho simplificado e capacidades de desenvolvimento orientadas por contexto.","ru":"Идеально подходит для Development Agents, которым необходим оптимизированный рабочий процесс и возможности контекстно-ориентированной разработки.","ar":"مثالي لوكلاء التطوير (Development Agents) الذين يحتاجون إلى سير عمل مبسط وقدرات تطوير قائمة على السياق."},"recommendation":{"en":"Empowers agents to establish project context, organize work into tracks, and execute with Test-Driven Development practices, utilizing parallel execution of independent tasks using sub-agents and supporting phased implementation plans.","zh":"赋予代理建立项目上下文、组织工作到跟踪中，并执行使用子代理的独立任务并行执行和支持分阶段实施计划的测试驱动开发实践。","ja":"エージェントがプロジェクトコンテキストを確立し、作業をトラックに組織し、サブエージェントを使用した独立タスクの並行実行と段階的な実装プランのサポートを使用したテスト駆動開発の実践を実行することを可能にします。","ko":"에이전트가 프로젝트 컨텍스트를 설정하고 작업을 트랙으로 구성하며 서브 에이전트를 사용한 독립적인 태스크의 병렬 실행과 단계적인 구현 계획을 지원하는 테스트 주도 개발 관행을 실행할 수 있도록 합니다.","es":"Habilita a los agentes a establecer el contexto del proyecto, organizar el trabajo en pistas y ejecutar con prácticas de desarrollo dirigido por pruebas, utilizando la ejecución paralela de tareas independientes mediante subagentes y apoyando planes de implementación por fases.","fr":"Permet aux agents d''établir le contexte du projet, d''organiser le travail en pistes et d''exécuter avec des pratiques de développement piloté par les tests, en utilisant l''exécution parallèle de tâches indépendantes à l''aide de sous-agents et en soutenant les plans de mise en œuvre par phases.","de":"Ermächtigt die Agenten, den Projektzusammenhang herzustellen, die Arbeit in Spuren zu organisieren und mit testgetriebenen Entwicklungsmethoden auszuführen, indem sie die parallele Ausführung von unabhängigen Aufgaben mithilfe von Subagenten nutzen und Phasenimplementierungspläne unterstützen.","pt":"Capacita os agentes a estabelecer o contexto do projeto, organizar o trabalho em trilhas e executar com práticas de Test-Driven Development, utilizando a execução paralela de tarefas independentes por meio de sub-agents e suportando planos de implementação faseados.","ru":"Позволяет агентам устанавливать контекст проекта, организовывать работу по направлениям (трекам) и выполнять ее с использованием практик Test-Driven Development, используя параллельное выполнение независимых задач с помощью sub-agents и поддерживая поэтапные планы реализации.","ar":"يمكن الوكلاء من إنشاء سياق المشروع، وتنظيم العمل في مسارات، والتنفيذ باستخدام ممارسات التطوير القائم على الاختبار (Test-Driven Development)، باستخدام التنفيذ المتوازي للمهام المستقلة عبر وكلاء فرعيين (sub-agents) ودعم خطط التنفيذ المرحلية."},"useCases":{"en":["Establishing project context for AI agent development","Organizing work into features, bugs, and improvements tracks","Executing parallel execution of independent tasks","Creating specs and phased implementation plans"],"zh":["为AI代理开发建立项目上下文","将工作组织到功能、错误和改进跟踪中","执行独立任务的并行执行","创建规格和分阶段实施计划"],"ja":["AIエージェント開発のプロジェクトコンテキストを確立する","作業を機能、バグ、改善トラックに組織する","独立タスクの並行実行を実行する","仕様と段階的な実装プランを作成する"],"ko":["AI 에이전트 개발을 위한 프로젝트 컨텍스트를 설정하는 것","작업을 기능, 버그 및 개선 트랙으로 구성하는 것","독립적인 태스크의 병렬 실행을 실행하는 것","사양 및 단계적인 구현 계획을 만드는 것"],"es":["Establecer el contexto del proyecto para el desarrollo de agentes de inteligencia artificial","Organizar el trabajo en pistas de características, errores y mejoras","Ejecutar la ejecución paralela de tareas independientes","Crear especificaciones y planes de implementación por fases"],"fr":["Établir le contexte du projet pour le développement d''agents d''intelligence artificielle","Organiser le travail en pistes de fonctionnalités, de bogues et d''améliorations","Exécuter l''exécution parallèle de tâches indépendantes","Créer des spécifications et des plans de mise en œuvre par phases"],"de":["Herstellen des Projektzusammenhangs für die Entwicklung von KI-Agents","Organisieren der Arbeit in Spuren für Funktionen, Fehler und Verbesserungen","Ausführen der parallelen Ausführung von unabhängigen Aufgaben","Erstellen von Spezifikationen und Phasenimplementierungsplänen"],"pt":["Estabelecer o contexto do projeto para o desenvolvimento de AI agent","Organizar o trabalho em trilhas de funcionalidades, bugs e melhorias","Executar a execução paralela de tarefas independentes","Criar especificações e planos de implementação faseados"],"ru":["Установление контекста проекта для разработки AI agent","Организация работы по направлениям (трекам): функции, ошибки и улучшения","Выполнение параллельного выполнения независимых задач","Создание спецификаций и поэтапных планов реализации"],"ar":["إنشاء سياق المشروع لتطوير وكيل الذكاء الاصطناعي (AI agent development)","تنظيم العمل في مسارات الميزات والأخطاء والتحسينات","تنفيذ المهام المستقلة بالتوازي","إنشاء المواصفات وخطط التنفيذ المرحلية"]},"limitations":{"en":["Requires project context and track organization setup","Dependent on sub-agents for parallel execution"],"zh":["需要项目上下文和跟踪组织设置","依赖于子代理进行并行执行"],"ja":["プロジェクトコンテキストとトラック組織の設定が必要","並行実行にはサブエージェントに依存する"],"ko":["프로젝트 컨텍스트 및 트랙 구성 설정이 필요함","병렬 실행에는 서브 에이전트에 의존함"],"es":["Requiere la configuración del contexto del proyecto y la organización de pistas","Depende de subagentes para la ejecución paralela"],"fr":["Nécessite la configuration du contexte du projet et l''organisation des pistes","Dépend de sous-agents pour l''exécution parallèle"],"de":["Benötigt die Konfiguration des Projektzusammenhangs und der Spurenorganisation","Hängt von Subagenten für die parallele Ausführung ab"],"pt":["Requer a configuração do contexto do projeto e organização das trilhas","Dependente de sub-agents para execução paralela"],"ru":["Требует настройки контекста проекта и организации треков","Зависит от sub-agents для параллельного выполнения"],"ar":["يتطلب إعداد سياق المشروع وتنظيم المسارات","يعتمد على الوكلاء الفرعيين (sub-agents) للتنفيذ المتوازي"]},"version":4},"contentHash":"cd560070d1c13ef4cf529df11725a7b0475860181b07a6b80ac01e1b57ed5eeb","qualityScore":51}');
