INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NguyenSiTrung/CLIConfigEditUI/conductor', 'conductor', 'NguyenSiTrung', 'CLIConfigEditUI', 'community', 'conductor NguyenSiTrung CLIConfigEditUI community Conductor enables context-driven development for AI agents by establishing project context and organizing work into tracks. It benefits developers by streamlining their workflow. Conductor 实现上下文驱动开发，通过建立项目上下文、组织工作和创建规格，提高开发效率 Conductor はコンテキスト駆動開発を実現し、プロジェクトのコンテキストを確立し、作業を整理し、仕様を生成して開発効率を高める Conductor 는 컨텍스트 드리븐 개발을 구현하여 프로젝트 컨텍스트를 설정하고 작업을 조직하고 사양을 생성하여 개발 효율성을 높임 Conductor es una herramienta de desarrollo que permite establecer el contexto del proyecto y organizar el trabajo en tareas paralelas Conductor est un outil de développement qui permet d''établir le contexte du projet et d''organiser les tâches en parallèle Conductor ist ein Entwicklungstool, das es ermöglicht, den Projektkontext zu erstellen und die Arbeit in parallele Aufgaben zu organisieren Conductor é uma ferramenta de desenvolvimento de software que permite a criação de specs e planos de implementação com TDD e execução paralela de tarefas Conductor - это инструмент для разработки программного обеспечения, который позволяет создавать спецификации и планы реализации с помощью TDD и параллельного выполнения задач Conductor هو أداة لتنمية البرمجيات التي تمكن من إنشاء مواصفات وخطط تنفيذ مع ممارسات TDD وتنفيذ متوازي للمهام how to use conductor conductor alternative conductor setup guide what is conductor conductor vs jira conductor install conductor context-driven development conductor tdd practices conductor parallel execution Conductor 上下文驱动开发 TDD 进度跟踪 并行执行 项目管理 软件开发 AI开发工具 AIエージェント Establishes project context including product vision, tech stack, and workflow Organizes work into tracks for features, bugs, and improvements Creates specs and phased implementation plans Executes with Test-Driven Development (TDD) practices and progress tracking Supports parallel execution of independent tasks using sub-agents Conductor is a context-driven development tool that enables AI agents to measure twice and code once, supporting parallel execution of independent tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('troydai/gwt/gwt', 'community', 'troydai', 'gwt', 'troydai/gwt', 'gwt', 5, 0, 51, '2026-02-05T13:53:20Z', '2026-03-06T06:55:10.773Z', '15b976ffdf382f6e894dbf24d25d42034cb1841ae6a39fc27a84915b8edbcf69', '{"id":"troydai/gwt/gwt","name":"gwt","description":{"en":"gwt is a Git worktree management tool that simplifies working with multiple branches. It provides a streamlined workflow for developers using Git.","zh":"GWT是一种Git工作树管理工具，简化了多分支开发。使用GWT代替原始的Git worktree命令","ja":"GWTはGitワークツリー管理ツールで、マルチブランチ開発を簡素化。生のGit worktreeコマンドよりもGWTを使用","ko":"GWT는 Git 작업 트리 관리 도구로 다중 분기 개발을 간소화한다. 원시 Git worktree 명령어 대신 GWT를 사용","es":"GWT es un CLI de administración de Git worktree que simplifica el trabajo con múltiples ramas. Utiliza comandos como ''gwt sw'' para cambiar entre ramas","fr":"GWT est un outil de gestion de Git worktree qui simplifie le travail avec plusieurs branches. Utilisez des commandes comme ''gwt sw'' pour basculer entre les branches","de":"GWT ist ein Git Worktree-Management-Tool, das die Arbeit mit mehreren Zweigen vereinfacht. Verwenden Sie Befehle wie ''gwt sw'', um zwischen Zweigen zu wechseln","pt":"O GWT é uma ferramenta de gerenciamento de worktree do Git que simplifica o trabalho com múltiplos branches simultaneamente","ru":"GWT - это инструмент управления worktree Git, который упрощает работу с несколькими ветками одновременно","ar":"GWT هو أداة لإدارة worktrees لمستودع Git التي تسهل العمل مع عدة فروع في نفس الوقت"},"seo":{"title":{"en":"gwt: Git Worktree Management Setup Guide | AI Agent Skill","zh":"GWT 工作树管理工具设置指南","ja":"GWT ワークツリー管理CLIベストプラクティス","ko":"GWT 작업 트리 관리 도구 설정 가이드","es":"Guía de Configuración de GWT: Administración de Git Worktree","fr":"Guide de Configuration de GWT: Outil de Gestion de Git Wo...","de":"GWT-Setup-Leitfaden: Git Worktree-Management-Tool","pt":"Guia de Configuração do GWT: Ferramenta de Gerenciamento ...","ru":"ИИ Агент GWT: Руководство по Настройке Инструмента Управл...","ar":"دليل إعداد أداة إدارة Worktree لمستودع Git GWT"},"description":{"en":"Streamline your Git workflow with gwt, a Git worktree management CLI. Learn how to switch between branches and create new ones with ease. Get started now!","zh":"使用GWT工作树管理工具简化Git多分支开发，提高工作效率","ja":"GWTワークツリー管理CLIでGitのマルチブランチ開発を効率化","ko":"GWT 작업 트리 관리 도구로 Git 다중 분기 개발을 간소화","es":"Aprende a utilizar GWT, un CLI de administración de Git worktree para simplificar tu flujo de trabajo con múltiples ramas","fr":"Découvrez GWT, un outil de gestion de Git worktree pour simplifier votre workflow avec plusieurs branches","de":"Erfahren Sie, wie Sie GWT verwenden, ein Git Worktree-Management-Tool, um Ihren Arbeitsablauf mit mehreren Zweigen zu vereinfachen","pt":"Aprenda a usar o GWT, uma ferramenta de linha de comando para gerenciar worktrees do Git de forma eficiente","ru":"Узнайте, как использовать GWT, инструмент командной строки для управления worktree Git","ar":"تعرف على كيفية استخدام أداة GWT لادارة worktrees لمستودع Git بفعالية"},"definition":{"en":"gwt is a Git worktree management CLI that simplifies working with multiple branches simultaneously.","zh":"GWT是Git工作树管理工具的简称，用于简化Git多分支开发","ja":"GWTはGitワークツリー管理CLIの略称で、Gitのマルチブランチ開発を効率化する","ko":"GWT는 Git 작업 트리 관리 도구의 약자로 Git 다중 분기 개발을 간소화한다","es":"GWT es un herramienta de línea de comandos para administrar Git worktree, que permite trabajar con múltiples ramas de forma eficiente","fr":"GWT est un outil de ligne de commande pour gérer les Git worktree, qui permet de travailler avec plusieurs branches de manière efficace","de":"GWT ist ein Kommandozeilen-Tool für die Verwaltung von Git Worktree, das die Arbeit mit mehreren Zweigen effizient ermöglicht","pt":"O GWT é uma ferramenta de linha de comando para gerenciar worktrees do Git","ru":"GWT - это инструмент командной строки для управления worktree Git","ar":"GWT هو أداة سطر أوامر لادارة worktrees لمستودع Git"},"features":{"en":["Switch to existing branch and create worktree if needed using `gwt sw <branch>`","Create new branch and switch to it using `gwt sw -b <branch>`","Switch to main/master branch using `gwt sw -m`","Use `gwt` instead of raw `git worktree` commands for a streamlined workflow"],"zh":["支持多分支开发","简化Git worktree命令","支持创建新分支","支持切换到主分支","支持切换到已存在的分支","提供流程化的工作流"],"ja":["マルチブランチ開発をサポート","Git worktreeコマンドを簡素化","新しいブランチの作成をサポート","メインブランチへの切り替えをサポート","既存のブランチへの切り替えをサポート","ワークフローを流程化"],"ko":["다중 분기 개발 지원","Git worktree 명령어 간소화","새로운 분기 생성 지원","메인 분기 전환 지원","既存 분기 전환 지원","작업 흐름을 간소화"],"es":["Cambio entre ramas con ''gwt sw''","Creación de nuevas ramas con ''gwt sw -b''","Cambio a la rama principal con ''gwt sw -m''","Administración de múltiples ramas simultáneamente","Simplificación del flujo de trabajo con Git worktree"],"fr":["Basculer entre les branches avec ''gwt sw''","Créer de nouvelles branches avec ''gwt sw -b''","Basculer vers la branche principale avec ''gwt sw -m''","Gestion de plusieurs branches simultanément","Simplification du workflow avec Git worktree"],"de":["Wechseln zwischen Zweigen mit ''gwt sw''","Erstellen neuer Zweige mit ''gwt sw -b''","Wechseln zur Hauptzweig mit ''gwt sw -m''","Verwaltung von mehreren Zweigen gleichzeitig","Vereinfachung des Arbeitsablaufs mit Git Worktree"],"pt":["Comutação entre branches existentes","Criação de novos branches e comutação para eles","Comutação para o branch principal","Uso de comandos personalizados para gerenciar worktrees"],"ru":["Переключение между существующими ветками","Создание новых веток и переключение на них","Переключение на основную ветку","Использование пользовательских команд для управления worktree"],"ar":["التحويل بين الفروع الموجودة","إنشاء فروع جديدة والتحويل إليها","التحويل إلى الفرع الرئيسي","استخدام أوامر مخصصة لإدارة worktrees"]},"keywords":{"en":["how to use gwt","gwt alternative","gwt vs git worktree","gwt install","gwt setup guide","git worktree management"],"zh":["GWT","Git工作树管理","多分支开发","Git worktree","工作流简化","AI工具","代码管理"],"ja":["GWT","Gitワークツリー管理","マルチブランチ開発","Git worktree","ワークフロー簡素化","AIエージェント","コード管理"],"ko":["GWT","Git 작업 트리 관리","다중 분기 개발","Git worktree","작업 흐름 간소화","AI 에이전트","코드 관리"],"es":["GWT","Git worktree","administración de ramas","CLI de Git","herramientas de desarrollo","gestión de código","desarrollo de software","Herramientas de AI para desarrolladores","Agentes de IA para programadores"],"fr":["GWT","Git worktree","gestion de branches","CLI de Git","outils de développement","gestion de code","développement de logiciels","Outils d''IA pour les développeurs","Agents d''IA pour les programmeurs"],"de":["GWT","Git Worktree","Zweigverwaltung","Git-Kommandozeilen-Tool","Entwicklungstools","Code-Verwaltung","Software-Entwicklung","AI-Tools für Entwickler","KI-Agents für Programmierer"],"pt":["gwt","git worktree","gerenciamento de worktree","ferramenta de linha de comando","comutação entre branches","criação de branches","git workflow"],"ru":["gwt","git worktree","управление worktree","инструмент командной строки","переключение между ветками","создание веток","git workflow"],"ar":["gwt","git worktree","ادارة worktrees","أداة سطر أوامر","التحويل بين الفروع","إنشاء فروع","git workflow"]}},"owner":"troydai","repo":"gwt","repoPath":"troydai/gwt","stars":5,"forks":0,"updatedAt":"2026-02-05T13:53:20Z","topics":[],"category":"community","skillMd":{"name":"gwt","description":"Manage git worktrees using gwt for branch-based workflow. Use when switching branches, creating worktrees, listing worktrees, or cleaning up after merging PRs.","bodyPreview":"# GWT Worktree Management Skill\n\nYou have access to `gwt`, a Git worktree management tool that simplifies working with multiple branches simultaneously. Use gwt instead of raw `git worktree` commands for a streamlined workflow.\n\n## Available Commands\n\n### Switch to a Branch Worktree\n```bash\ngwt sw <branch>           # Switch to existing branch (creates worktree if needed)\ngwt sw -b <branch>        # Create new branch and switch to it\ngwt sw -m                 # Switch to main/master branch\ngwt s","body":"# GWT Worktree Management Skill\n\nYou have access to `gwt`, a Git worktree management tool that simplifies working with multiple branches simultaneously. Use gwt instead of raw `git worktree` commands for a streamlined workflow.\n\n## Available Commands\n\n### Switch to a Branch Worktree\n```bash\ngwt sw <branch>           # Switch to existing branch (creates worktree if needed)\ngwt sw -b <branch>        # Create new branch and switch to it\ngwt sw -m                 # Switch to main/master branch\ngwt sw <branch> --remote <remote>  # Switch to branch from specific remote\n```\n\n### List Worktrees\n```bash\ngwt ls                    # List all worktrees (truncated branch names)\ngwt ls --full             # List with full branch names\n```\n\n### Remove Worktrees\n```bash\ngwt rm <branch>           # Remove worktree for branch (prompts for confirmation)\ngwt rm <branch> -y        # Remove without confirmation\ngwt rm <branch> -b        # Remove worktree and delete the branch\ngwt rm <branch> -B        # Remove worktree and force-delete branch\ngwt rm --this             # Remove current worktree (switches to home first)\n```\n\n### Navigation\n```bash\ngwt home                  # Return to the main repository worktree\ngwt current               # Show current branch and worktree path (alias: gwt c)\n```\n\n## Workflow Patterns\n\n### Starting Work on a Feature\n1. Use `gwt sw -b feature/name` to create a new branch and worktree\n2. Work on the feature in the isolated worktree\n3. The original repository remains on its branch\n\n### Switching Between Tasks\n1. Use `gwt sw other-branch` to switch to another worktree\n2. No need to stash changes - each worktree is independent\n3. Use `gwt ls` to see all available worktrees\n\n### Cleaning Up After PR Merge\n1. Use `gwt home` to return to main repository\n2. Use `gwt rm feature/name -b` to remove worktree and delete merged branch\n3. Or use `gwt rm --this -b` if still in the feature worktree\n\n### Checking Current Location\nUse `gwt current` to see which branch and worktree you''re in.\n\n## Key Benefits\n\n- **Automatic directory switching**: gwt changes your shell''s working directory automatically\n- **Centralized storage**: Worktrees are stored in `~/.gwt_store`, keeping repos clean\n- **Just-in-time creation**: Worktrees are created automatically when switching to new branches\n- **Smart remote lookup**: Automatically finds and tracks remote branches\n\n## When to Use gwt\n\n- Switching between branches for code review or testing\n- Working on multiple features in parallel\n- Isolating experimental changes without affecting main work\n- Quick context switching without stashing changes\n"},"lastSynced":"2026-03-06T06:55:10.773Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined Git branch management and worktree creation.","zh":"适合需要简化Git分支管理和工作树创建的开发代理。","ja":"開発エージェントがGitブランチ管理とワークツリーの作成を簡素化する必要がある場合に適しています。","ko":"개발 에이전트가 Git 브랜치 관리와 워크트리 생성을 간소화해야 하는 경우 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de ramas de Git y creación de worktree simplificada.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de branches Git et de création de worktree simplifiée.","de":"Perfekt für Entwicklungssagenten, die eine vereinfachte Git-Zweigverwaltung und Worktree-Erstellung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gerenciamento de branch do Git e criação de worktree simplificados.","ru":"Идеально подходит для агентов разработки, которым необходим упрощенный менеджмент веток Git и создание рабочих деревьев.","ar":"مثالي لعميل التطوير الذي يحتاج إلى إدارة متسلسلة لفرع الجيت وإنشاء شجرة العمل"},"recommendation":{"en":"Empowers agents to efficiently manage multiple Git branches using `gwt` commands, simplifying workflow with features like automatic worktree creation and branch switching via `git worktree` protocol.","zh":"赋予代理高效管理多个Git分支的能力，使用`gwt`命令简化工作流程，具有自动工作树创建和通过`git worktree`协议的分支切换等功能。","ja":"`gwt`コマンドを使用して複数のGitブランチを効率的に管理し、自動ワークツリー作成や`git worktree`プロトコルによるブランチ切り替えなどの機能でワークフローを簡素化します。","ko":"`gwt` 명령을 사용하여 여러 Git 브랜치를 효율적으로 관리하고, 자동 워크트리 생성 및 `git worktree` 프로토콜을 통한 브랜치 전환 등의 기능으로 워크플ロー를 간소화합니다.","es":"Habilita a los agentes a gestionar de forma eficiente múltiples ramas de Git utilizando comandos `gwt`, simplificando el flujo de trabajo con características como la creación automática de worktree y el cambio de rama a través del protocolo `git worktree`.","fr":"Permet aux agents de gérer efficacement plusieurs branches Git à l''aide de commandes `gwt`, simplifiant le flux de travail avec des fonctionnalités telles que la création automatique de worktree et le commutation de branche via le protocole `git worktree`.","de":"Ermöglicht es Agenten, mehrere Git-Zweige mithilfe von `gwt`-Befehlen effizient zu verwalten, wodurch der Arbeitsablauf durch Funktionen wie die automatische Erstellung von Worktrees und den Wechsel zwischen Zweigen über das `git worktree`-Protokoll vereinfacht wird.","pt":"Habilita os agentes a gerenciar de forma eficiente várias branches do Git usando comandos `gwt`, simplificando o fluxo de trabalho com recursos como criação automática de worktree e alternância de branch via protocolo `git worktree`.","ru":"Позволяет агентам эффективно управлять несколькими ветками Git с помощью команд `gwt`, упрощая рабочий процесс с функциями, такими как автоматическое создание рабочего дерева и переключение веток через протокол `git worktree`.","ar":"تمكين الوكلاء من إدارة متسلسلة لفرع الجيت بفعالية باستخدام أوامر `gwt`، وبتبسيط تدفق العمل بميزات مثل إنشاء شجرة العمل التلقائي وتغيير الفرع عبر بروتوكول `git worktree`"},"useCases":{"en":["Switching to existing branches with `gwt sw`","Creating new branches and switching to them using `gwt sw -b`","Debugging branch-specific issues with isolated worktrees"],"zh":["使用`gwt sw`切换到现有分支","使用`gwt sw -b`创建新分支并切换到它们","使用隔离的工作树调试特定于分支的问题"],"ja":["`gwt sw`を使用して既存のブランチに切り替える","`gwt sw -b`を使用して新しいブランチを作成し、それに切り替える","分離されたワークツリーを使用してブランチ固有の問題をデバッグする"],"ko":["`gwt sw`를 사용하여 기존 브랜치로 전환하기","`gwt sw -b`를 사용하여 새로운 브랜치를 생성하고 전환하기","분리된 워크트리를 사용하여 브랜치별 문제를 디버깅하기"],"es":["Cambiar a ramas existentes con `gwt sw`","Crear nuevas ramas y cambiar a ellas utilizando `gwt sw -b`","Depurar problemas específicos de rama con worktrees aislados"],"fr":["Basculer vers des branches existantes avec `gwt sw`","Créer de nouvelles branches et basculer vers elles en utilisant `gwt sw -b`","Déboguer des problèmes spécifiques à la branche avec des worktrees isolés"],"de":["Zu bestehenden Zweigen wechseln mit `gwt sw`","Neue Zweige erstellen und zu ihnen wechseln mit `gwt sw -b`","Zweig-spezifische Probleme mit isolierten Worktrees debuggen"],"pt":["Alternar para branches existentes com `gwt sw`","Criar novas branches e alternar para elas usando `gwt sw -b`","Depurar problemas específicos de branch com worktrees isolados"],"ru":["Переключаться на существующие ветки с помощью `gwt sw`","Создавать новые ветки и переключаться на них с помощью `gwt sw -b`","Отладка проблем, связанных с ветками, с использованием изолированных рабочих деревьев"],"ar":["التحويل إلى الفروع الموجودة باستخدام `gwt sw`","إنشاء فروع جديدة والتحويل إليها باستخدام `gwt sw -b`","تصحيح الأخطاء المتعلقة بفرع معين باستخدام أشجار العمل المعزولة"]},"limitations":{"en":["Requires Git installation","Limited to Git worktree management"],"zh":["需要Git安装","仅限Git工作树管理"],"ja":["Gitのインストールが必要","Gitワークツリーマネージメントのみ"],"ko":["Git 설치가 필요함","Git 워크트리 관리에만限함"],"es":["Requiere instalación de Git","Limitado a la gestión de worktree de Git"],"fr":["Nécessite l''installation de Git","Limité à la gestion des worktrees Git"],"de":["Benötigt Git-Installation","Begrenzt auf Git-Worktree-Verwaltung"],"pt":["Requer instalação do Git","Limitado ao gerenciamento de worktree do Git"],"ru":["Требует установку Git","Ограничен менеджментом рабочих деревьев Git"],"ar":["يتطلب تثبيت الجيت","محدود بإدارة شجرة العمل للجيت"]},"version":4},"contentHash":"15b976ffdf382f6e894dbf24d25d42034cb1841ae6a39fc27a84915b8edbcf69","qualityScore":51}');
