INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('troydai/gwt/gwt', 'gwt', 'troydai', 'gwt', 'community', 'gwt troydai gwt community gwt is a Git worktree management tool that simplifies working with multiple branches. It provides a streamlined workflow for developers using Git. GWT是一种Git工作树管理工具，简化了多分支开发。使用GWT代替原始的Git worktree命令 GWTはGitワークツリー管理ツールで、マルチブランチ開発を簡素化。生のGit worktreeコマンドよりもGWTを使用 GWT는 Git 작업 트리 관리 도구로 다중 분기 개발을 간소화한다. 원시 Git worktree 명령어 대신 GWT를 사용 GWT es un CLI de administración de Git worktree que simplifica el trabajo con múltiples ramas. Utiliza comandos como ''gwt sw'' para cambiar entre ramas GWT est un outil de gestion de Git worktree qui simplifie le travail avec plusieurs branches. Utilisez des commandes comme ''gwt sw'' pour basculer entre les branches GWT ist ein Git Worktree-Management-Tool, das die Arbeit mit mehreren Zweigen vereinfacht. Verwenden Sie Befehle wie ''gwt sw'', um zwischen Zweigen zu wechseln O GWT é uma ferramenta de gerenciamento de worktree do Git que simplifica o trabalho com múltiplos branches simultaneamente GWT - это инструмент управления worktree Git, который упрощает работу с несколькими ветками одновременно GWT هو أداة لإدارة worktrees لمستودع Git التي تسهل العمل مع عدة فروع في نفس الوقت how to use gwt gwt alternative gwt vs git worktree gwt install gwt setup guide git worktree management GWT Git工作树管理 多分支开发 Git worktree 工作流简化 AI工具 代码管理 Switch to existing branch and create worktree if needed using `gwt sw <branch>` Create new branch and switch to it using `gwt sw -b <branch>` Switch to main/master branch using `gwt sw -m` Use `gwt` instead of raw `git worktree` commands for a streamlined workflow gwt is a Git worktree management CLI that simplifies working with multiple branches simultaneously.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('agairola/securing-ralph-loop/self-check', 'community', 'agairola', 'securing-ralph-loop', 'agairola/securing-ralph-loop', 'self-check', 4, 0, 51, '2026-02-09T08:27:39Z', '2026-03-06T06:57:55.369Z', '5419b3c4096f82b15c8468403629089ebf07c64d1516daa4efc86b809d054ebd', '{"id":"agairola/securing-ralph-loop/self-check","name":"self-check","description":{"en":"The self-check skill performs comprehensive validation on staged changes, combining code quality checks with security validation to ensure code quality and security standards are met. This benefits developers by catching issues before they are committed.","zh":"自检技能通过语法错误检查、linting检查、类型错误检查和测试覆盖率检查来验证代码质量和安全标准","ja":"自己チェック機能は、コード品質とセキュリティを確保するために、構文エラーのチェック、lintingのチェック、タイプエラーのチェック、テストカバレッジのチェックを行う","ko":"자체 검사 기능은 코드 품질과 보안을 확인하기 위해 구문 오류 확인, linting 확인, 유형 오류 확인 및 테스트 커버리지 확인을 수행한다","es":"Self-check es una herramienta que valida tus cambios de código antes de comprometer, asegurando la calidad y seguridad de tu proyecto mediante la verificación de errores de sintaxis, problemas de linting y seguridad","fr":"Self-check est un outil qui valide vos modifications de code avant de les committer, garantissant la qualité et la sécurité de votre projet en vérifiant les erreurs de syntaxe, les problèmes de linting et la sécurité","de":"Self-check ist ein Tool, das Ihre Code-Änderungen vor dem Commit überprüft, um die Qualität und Sicherheit Ihres Projekts zu gewährleisten, indem es Syntaxfehler, Linting-Probleme und Sicherheitsrisiken überprüft","pt":"O self-check executa uma verificação abrangente em alterações para detectar problemas de qualidade e segurança","ru":"Self-check выполняет комплексную проверку изменений для обнаружения проблем качества и безопасности","ar":"Self-Check يؤدي فحصا شاملا للتحقق من وجود مشاكل في جودة وأمان الكود"},"seo":{"title":{"en":"self-check: Pre-Commit Validation Setup Guide | AI Agent ...","zh":"AI工具自检设置指南 - 代码质量和安全标准","ja":"AIエージェントの自己チェックベストプラクティス - コード品質とセキュリティ","ko":"AI 에이전트 자체 검사 설정 가이드 - 코드 품질 및 보안","es":"Guía de configuración de self-check: Validación de código...","fr":"Mise en place de self-check : Vérification de code et de ...","de":"Einrichtungsleitfaden für self-check: Code- und Sicherhei...","pt":"Guia de Configuração do Self-Check para Desenvolvedores","ru":"ИИ Агенты: Настройка Self-Check для Безопасности Код","ar":"إعداد Self-Check للأمان الرقمي: دليل المطورين"},"description":{"en":"Catch code quality and security issues before committing with self-check. Learn how to integrate this AI agent skill into your workflow and ensure compliance...","zh":"了解如何使用自检技能来验证代码质量和安全标准，提高代码提交质量","ja":"AIエージェントの自己チェック機能を使用してコード品質とセキュリティを確保する方法","ko":"코드 품질 및 보안을 확인하는 자체 검사 기능을 사용하여 코드 제출 품질을 높이는 방법","es":"Aprende a utilizar self-check para validar tus cambios de código antes de comprometer, asegurando la calidad y seguridad de tu proyecto","fr":"Découvrez comment utiliser self-check pour valider vos modifications de code avant de les committer, garantissant la qualité et la sécurité de votre projet","de":"Erfahren Sie, wie Sie self-check verwenden, um Ihre Code-Änderungen vor dem Commit zu überprüfen und die Qualität und Sicherheit Ihres Projekts zu gewährleisten","pt":"Aprenda a configurar o self-check para garantir a qualidade e segurança do código antes do commit","ru":"Узнайте, как настроить self-check для обеспечения качества и безопасности кода перед коммитом","ar":"تعرف على كيفية إعداد Self-Check لضمان جودة وأمان الكود قبل الإلتزام"},"definition":{"en":"self-check is a pre-commit validation skill that scans staged changes for code quality and security issues, including syntax errors, linting issues, and type errors","zh":"自检是AI工具的一种功能，用于在提交代码之前验证代码质量和安全标准","ja":"自己チェックは、AIエージェントの機能の一つで、コードをコミットする前にコード品質とセキュリティを確認する","ko":"자체 검사는 AI 에이전트의 기능 중 하나로 코드를 제출하기 전에 코드 품질 및 보안을 확인한다","es":"S