INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('agairola/securing-ralph-loop/self-check', 'self-check', 'agairola', 'securing-ralph-loop', 'community', 'self-check agairola securing-ralph-loop community The self-check skill performs comprehensive validation on staged changes, combining code quality checks with security validation to ensure code quality and security standards are met. This benefits developers by catching issues before they are committed. 自检技能通过语法错误检查、linting检查、类型错误检查和测试覆盖率检查来验证代码质量和安全标准 自己チェック機能は、コード品質とセキュリティを確保するために、構文エラーのチェック、lintingのチェック、タイプエラーのチェック、テストカバレッジのチェックを行う 자체 검사 기능은 코드 품질과 보안을 확인하기 위해 구문 오류 확인, linting 확인, 유형 오류 확인 및 테스트 커버리지 확인을 수행한다 Self-check es una herramienta que valida tus cambios de código antes de comprometer, asegurando la calidad y seguridad de tu proyecto mediante la verificación de errores de sintaxis, problemas de linting y seguridad Self-check est un outil qui valide vos modifications de code avant de les committer, garantissant la qualité et la sécurité de votre projet en vérifiant les erreurs de syntaxe, les problèmes de linting et la sécurité Self-check ist ein Tool, das Ihre Code-Änderungen vor dem Commit überprüft, um die Qualität und Sicherheit Ihres Projekts zu gewährleisten, indem es Syntaxfehler, Linting-Probleme und Sicherheitsrisiken überprüft O self-check executa uma verificação abrangente em alterações para detectar problemas de qualidade e segurança Self-check выполняет комплексную проверку изменений для обнаружения проблем качества и безопасности Self-Check يؤدي فحصا شاملا للتحقق من وجود مشاكل في جودة وأمان الكود how to use self-check self-check setup guide pre-commit validation tools code quality checking security validation for developers self-check alternative self-check vs git hooks self-check install integrating self-check into CI/CD pipelines AI工具自检 代码质量检查 安全标准验证 语法错误检查 linting检查 类型错误检查 测试覆盖率检查 代码提交质量提高 Validates code quality by checking for syntax errors in changed files 