INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aram-devdocs/GoudEngine/integration-testing', 'integration-testing', 'aram-devdocs', 'GoudEngine', 'community', 'integration-testing aram-devdocs GoudEngine community Integration-testing skill provides patterns and conventions for writing tests in GoudEngine, covering GL context management and SDK wrappers. Benefits developers working with Rust and C/C#. GoudEngine的集成测试涵盖跨模块交互、GL上下文管理和FFI边界测试 GoudEngineの統合テストは、クロスモジュールの相互作用、GLコンテキストの管理、FFI境界のテストをカバー GoudEngine의 통합 테스트는 크로스 모듈 상호 작용, GL 컨텍스트 관리, FFI 경계 테스트를 다룹니다 Patrones y convenciones para escribir pruebas de integración en GoudEngine, cubriendo interacciones entre módulos, gestión de contexto GL y pruebas de fronteras FFI Patterns et conventions pour écrire des tests d''intégration dans GoudEngine, couvrant les interactions entre modules, la gestion du contexte GL et les tests de frontières FFI Muster und Konventionen für das Schreiben von Integrationstests in GoudEngine, einschließlich Modul-Interaktionen, GL-Kontextverwaltung und FFI-Grenztests O teste de integração é crucial para garantir a interoperabilidade entre módulos no mecanismo de jogo OpenGL construído com Rust. Тестирование интеграции имеет важное значение для обеспечения взаимодействия между модулями в игровом движке OpenGL, построенном на Rust. اختبار التكامل ضروري لضمان التوافق بين الوحدات في محرك الألعاب OpenGL المبني على Rust. how to use integration-testing in GoudEngine integration-testing vs unit testing integration-testing setup guide for OpenGL Game Engine what is integration-testing in software development integration-testing alternative for Rust projects integration-testing install for C/C# developers GoudEngine testing patterns FFI boundary testing best practices GL context management in integration testing 集成测试 GoudEngine Rust OpenGL FFI C/C# SDK 游戏引擎 AIエージェント 集成测试框架 Covers cross-module interactions in GoudEngine Manages GL context for reliable testing Tests FFI boundaries end-to-end Validates SDK wrappers against the Rust core Organizes tests using a modular structure in src/ directory Supports writing tests in Rust using the #[cfg(test)] module Integration-testing is a software testing technique for verifying interactions between multiple modules in a system, such as GoudEngine''s OpenGL Game Engine.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gaebalai/claude-code-orchestrator/context-loader', 'community', 'gaebalai', 'claude-code-orchestrator', 'gaebalai/claude-code-orchestrator', 'context-loader', 2, 1, 51, '2026-02-28T13:11:20Z', '2026-03-06T13:08:13.298Z', '35e1bb3bae4f542b0d3607f9a3145047d8ef429e846b1f36e69c65ff00c6b464', '{"id":"gaebalai/claude-code-orchestrator/context-loader","name":"context-loader","description":{"en":"The context-loader skill loads shared project context from the .claude/ directory, ensuring Codex CLI has the same knowledge as Claude Code, benefiting AI agent developers.","zh":"Context Loader 是一个用于加载共享项目上下文的技能，确保 Codex CLI 与 Claude Code 具有相同的知识","ja":"Context Loader は、共有プロジェクトコンテキストを読み込み、Codex CLI と Claude Code が同じ知識を持つことを保証するスキルです","ko":"Context Loader는 공유 프로젝트 컨텍스트를 로드하여 Codex CLI와 Claude Code가 동일한 지식을 갖도록 하는 기술입니다","es":"Context Loader es un entorno de desarrollo de AI que carga el contexto del proyecto desde el directorio `.claude/` para garantizar la coherencia en Codex CLI","fr":"Context Loader est un environnement de développement d''IA qui charge le contexte du projet depuis le répertoire `.claude/` pour assurer la cohérence dans Codex CLI","de":"Context Loader ist eine künstliche Intelligenz-Entwicklungsumgebung, die den Projekt-Kontext aus dem Verzeichnis `.claude/` lädt, um die Konsistenz in Codex CLI zu gewährleisten","pt":"O Context Loader é uma habilidade que carrega o contexto do projeto compartilhado a partir do diretório `.claude/` para garantir que o Codex CLI tenha o mesmo conhecimento que o Claude Code","ru":"Context Loader - это навык, который загружает общий контекст проекта из директории `.claude/`, чтобы обеспечить совместимость знаний между Codex CLI и Claude Code","ar":"محمل السياق هو مهارة تقوم بتحميل السياق المشترك للمشروع من الدليل `.claude/` لضمان توافق المعرفة بين Codex CLI و Claude Code"},"seo":{"title":{"en":"context-loader: Setup Guide for AI Agents | AI Agent Skill","zh":"Context Loader 技术指南：AI开发环境设置","ja":"Context Loader セットアップガイド：AIエージェント開発環境","ko":"Context Loader 설정 가이드: AI 에이전트 개발 환경","es":"Configuración de Context Loader: Guía de inicio para ento...","fr":"Configurer Context Loader: Guide de démarrage pour les en...","de":"Context Loader Einrichtung: Setup-Anleitung für künstlich...","pt":"Guia de Configuração do Context Loader para Ferramentas d...","ru":"Настройка ИИ Агентов: Context Loader Руководство","ar":"دليل إعداد محمل السياق لادوات الذكاء الاصطناعي"},"description":{"en":"Discover how to load shared project context with context-loader. Learn to activate it at the beginning of every task for seamless Codex CLI integration.","zh":"了解 Context Loader 技术细节，实现 AI 开发环境的高效设置和项目上下文加载","ja":"Context Loader の技術詳細を学び、AI エージェント開発環境の設定を最適化する","ko":"Context Loader 기술을 통해 효율적인 AI 에이전트 개발 환경 설정과 프로젝트 컨텍스트 로딩을 실현하세요","es":"Aprende a configurar Context Loader para cargar el contexto del proyecto y garantizar que Codex CLI tenga los mismos conocimientos que Claude Code","fr":"Découvrez comment configurer Context Loader pour charger le contexte du projet et assurer que Codex CLI ait les mêmes connaissances que Claude Code","de":"Erfahren Sie, wie Sie Context Loader einrichten, um den Projekt-Kontext zu laden und sicherzustellen, dass Codex CLI dieselben Kenntnisse wie Claude Code hat","pt":"Aprenda a configurar o Context Loader para garantir que o Codex CLI tenha o mesmo conhecimento que o Claude Code em ambientes de desenvolvimento de IA multia...","ru":"Узнайте, как настроить Context Loader, чтобы обеспечить совместимость знаний между Codex CLI и Claude Code в среде разработки ИИ с несколькими агентами","ar":"تعرف على كيفية إعداد محمل السياق لضمان توافق المعرفة بين Codex CLI و Claude Code في بيئة تطوير الذكاء الاصطناعي متعددة الوكلاء"},"definition":{"en":"context-loader is a multi-agent AI development environment skill that loads project context to synchronize knowledge between Codex CLI and Claude Code.","zh":"Context Loader 是一个 AI 开发环境技能，用于加载共享项目上下文","ja":"Context Loader は、共有プロジェクトコンテキストを読み込む AI エージェント開発環境スキルです","ko":"Context Loader는 공유 프로젝트 컨텍스트를 로드하는 AI 에이전트 개발 환경 기술입니다","es":"Context Loader es una habilidad que carga el contexto del proyecto para garantizar la coherencia en la línea de comandos de Codex","fr":"Context Loader est une compétence qui charge le contexte du projet pour assurer la cohérence dans la ligne de commande de Codex","de":"Context Loader ist eine Fähigkeit, die den Projekt-Kontext lädt, um die Konsistenz in der Codex-Kommandozeile zu gewährleisten","pt":"O Context Loader é uma habilidade de carregamento de contexto que garante a consistência da conhecimento entre o Codex CLI e o Claude Code","ru":"Context Loader - это навык загрузки контекста, обеспечивающий согласованность знаний между Codex CLI и Claude Code","ar":"محمل السياق هو مهارة لتحميل السياق التي تضمن الاتساق في المعرفة بين Codex CLI و Claude Code"},"features":{"en":["Loads coding rules from .claude/rules/ directory","Reads files such as coding-principles.md and dev-environment.md","Ensures Codex CLI has the same knowledge as Claude Code","Activates at the beginning of every task for seamless integration","Supports files like uv, ruff, ty, and pytest requirements","Loads project context from .claude/ directory"],"zh":["加载 `.claude/` 目录中的共享项目上下文","读取 `.claude/rules/` 目录中的编码规则","支持 Codex CLI 和 Claude Code 知识一致性","实现开发环境的高效设置","支持多种开发工具，如 uv、ruff、ty、pytest"],"ja":["`.claude/` ディレクトリ内の共有プロジェクトコンテキストを読み込み","`.claude/rules/` ディレクトリ内のコーディングルールを読み取り","Codex CLI と Claude Code の知識の一貫性をサポート","開発環境の効率的な設定を実現","uv、ruff、ty、pytest などの開発ツールをサポート"],"ko":["`.claude/` 디렉토리 내의 공유 프로젝트 컨텍스트 로딩","`.claude/rules/` 디렉토리 내의 코딩 규칙 읽기","Codex CLI와 Claude Code의 지식 일관성 지원","개발 환경의 효율적인 설정을 구현","uv, ruff, ty, pytest 등의 개발 도구 지원"],"es":["Carga de reglas de codificación desde `.claude/rules/`","Soporte para principios de codificación como simplicidad y responsabilidad única","Compatibilidad con entornos de desarrollo como uv, ruff y ty","Integración con herramientas de testing como pytest","Carga de contexto de proyecto para garantizar la coherencia en Codex CLI","Compatibilidad con la línea de comandos de Codex"],"fr":["Chargement des règles de codage depuis `.claude/rules/`","Prise en charge des principes de codage tels que la simplicité et la responsabilité unique","Compatibilité avec les environnements de développement tels que uv, ruff et ty","Intégration avec les outils de testing tels que pytest","Chargement du contexte de projet pour assurer la cohérence dans Codex CLI","Compatibilité avec la ligne de commande de Codex"],"de":["Laden von Codierregeln aus `.claude/rules/`","Unterstützung für Codierprinzipien wie Einfachheit und einzelne Verantwortung","Kompatibilität mit Entwicklungsumgebungen wie uv, ruff und ty","Integrierung mit Testtools wie pytest","Laden des Projekt-Kontexts, um die Konsistenz in Codex CLI zu gewährleisten","Kompatibilität mit der Codex-Kommandozeile"],"pt":["Carregamento de regras de codificação a partir do diretório `.claude/rules/`","Compatibilidade com o Codex CLI e o Claude Code","Suporte a ambientes de desenvolvimento de IA multiagente","Leitura de arquivos em formato Markdown","Integração com o diretório `.claude/`"],"ru":["Загрузка правил кодирования из директории `.claude/rules/`","Совместимость с Codex CLI и Claude Code","Поддержка среды разработки ИИ с несколькими агентами","Чтение файлов в формате Markdown","Интеграция с директорией `.claude/`"],"ar":["تحميل قواعد التشفير من الدليل `.claude/rules/`","التوافق مع Codex CLI و Claude Code","دعم بيئة تطوير الذكاء الاصطناعي متعددة الوكلاء","قراءة الملفات بصيغة Markdown","التكامل مع الدليل `.claude/`"]},"keywords":{"en":["how to use context-loader","what is context-loader","context-loader alternative","context-loader vs Claude Code","context-loader install","context-loader setup guide","Codex CLI integration","multi-agent AI development environment"],"zh":["Context Loader","AI 开发环境","共享项目上下文","Codex CLI","Claude Code","开发环境设置","AI 技术","开发工具"],"ja":["Context Loader","AI エージェント開発環境","共有プロジェクトコンテキスト","Codex CLI","Claude Code","開発環境設定","AI 技術","開発ツール","AIエージェント"],"ko":["Context Loader","AI 에이전트 개발 환경","공유 프로젝트 컨텍스트","Codex CLI","Claude Code","개발 환경 설정","AI 기술","개발 도구","AI 에이전트"],"es":["context loader","entorno de desarrollo de AI","carga de contexto de proyecto","reglas de codificación","principios de codificación","compatibilidad con Codex CLI","herramientas de testing","desarrollo de software","AI Agents","Herramientas de IA"],"fr":["context loader","environnement de développement d''IA","chargement du contexte de projet","règles de codage","principes de codage","compatibilité avec Codex CLI","outils de testing","développement de logiciels","Agents d''IA","Outils d''IA"],"de":["context loader","künstliche Intelligenz-Entwicklungsumgebung","Laden des Projekt-Kontexts","Codierregeln","Codierprinzipien","Kompatibilität mit Codex CLI","Testtools","Software-Entwicklung","künstliche Intelligenz-Tools","KI-Entwicklung"],"pt":["Context Loader","Ferramentas de IA","Desenvolvimento de IA","Codex CLI","Claude Code","Regras de codificação","Ambientes de desenvolvimento de IA","Integração com diretórios"],"ru":["Context Loader","ИИ Агенты","Разработка ИИ","Codex CLI","Claude Code","Правила кодирования","Среды разработки ИИ","Интеграция с директориями"],"ar":["محمل السياق","أدوات الذكاء الاصطناعي","تطوير الذكاء الاصطناعي","Codex CLI","Claude Code","قواعد التشفير","بيئات تطوير الذكاء الاصطناعي","التكامل مع الدلائل"]}},"owner":"gaebalai","repo":"claude-code-orchestrator","repoPath":"gaebalai/claude-code-orchestrator","stars":2,"forks":1,"updatedAt":"2026-02-28T13:11:20Z","topics":[],"category":"community","skillMd":{"name":"context-loader","description":"ALWAYS activate this skill at the start of every task. Load project context from .claude/ directory including coding rules, design decisions, and documentation before executing any task.","bodyPreview":"# Context Loader Skill\n\n## Purpose\n\nLoad shared project context from `.claude/` directory to ensure Codex CLI has the same knowledge as Claude Code.\n\n## When to Activate\n\n**ALWAYS** - This skill must run at the beginning of every task to load project context.\n\n## Workflow\n\n### Step 1: Load Coding Rules\n\nRead all files in `.claude/rules/`:\n\n```\n.claude/rules/\n├── coding-principles.md   # Simplicity, single responsibility, early return\n├── dev-environment.md     # uv, ruff, ty, pytest requirements","body":"# Context Loader Skill\n\n## Purpose\n\nLoad shared project context from `.claude/` directory to ensure Codex CLI has the same knowledge as Claude Code.\n\n## When to Activate\n\n**ALWAYS** - This skill must run at the beginning of every task to load project context.\n\n## Workflow\n\n### Step 1: Load Coding Rules\n\nRead all files in `.claude/rules/`:\n\n```\n.claude/rules/\n├── coding-principles.md   # Simplicity, single responsibility, early return\n├── dev-environment.md     # uv, ruff, ty, pytest requirements\n├── language.md            # Think in English, respond in Korean\n├── security.md            # Secrets, validation, SQLi/XSS prevention\n├── testing.md             # TDD, AAA pattern, 80% coverage\n└── codex-delegation.md    # (skip - not relevant for Codex itself)\n```\n\n### Step 2: Load Design Documentation\n\nRead `.claude/docs/DESIGN.md` for:\n- Architecture decisions\n- Implementation patterns\n- Library choices and constraints\n- TODO items and open questions\n\n### Step 3: Check Library Documentation\n\nIf the task involves specific libraries, read relevant files from:\n```\n.claude/docs/libraries/\n```\n\n### Step 4: Execute Task\n\nWith the loaded context, execute the requested task following:\n- Coding principles from rules\n- Design decisions from DESIGN.md\n- Library constraints from docs\n\n## Key Rules to Remember\n\nAfter loading, always follow these principles:\n\n1. **Simplicity first** - Choose readable code over complex\n2. **Single responsibility** - One function/class does one thing\n3. **Type hints required** - All functions need annotations\n4. **Use uv** - Never use pip directly\n5. **Security** - No hardcoded secrets, validate input, parameterize SQL\n\n## Language Protocol\n\n- **Thinking/Reasoning**: English\n- **Code**: English (variables, functions, comments)\n- **User communication**: Korean (when reporting back through Claude Code)\n\n## Output\n\nAfter loading context, briefly confirm:\n- Rules loaded\n- Design document status\n- Ready to execute task\n"},"lastSynced":"2026-03-06T13:08:13.298Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agent Developers needing synchronized project knowledge across Codex CLI and Claude Code","zh":"适合需要在 Codex CLI 和 Claude Code 中同步项目知识的 AI Agent 开发者","ja":"Codex CLI と Claude Code でプロジェクトの知識を同期する必要がある AI エージェント開発者に最適","ko":"Codex CLI와 Claude Code에서 프로젝트 지식을 동기화해야 하는 AI 에이전트 개발자를 위한 최적의 솔루션","es":"Perfecto para desarrolladores de Agentes de IA que necesitan conocimiento de proyecto sincronizado en Codex CLI y Claude Code","fr":"Idéal pour les développeurs d''agents IA ayant besoin de connaissances de projet synchronisées sur Codex CLI et Claude Code","de":"Perfekt für AI-Agent-Entwickler, die synchrones Projektwissen über Codex CLI und Claude Code benötigen","pt":"Perfeito para desenvolvedores de Agentes de IA que precisam de conhecimento de projeto sincronizado em Codex CLI e Claude Code","ru":"Идеально для разработчиков агентов ИИ, которым необходим синхронизированный знание проекта в Codex CLI и Claude Code","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يحتاجون إلى معرفة مشروع متزامنة عبر Codex CLI و Claude Code"},"recommendation":{"en":"Empowers agents to leverage shared project context from the .claude/ directory, ensuring consistency with Claude Code by loading coding rules and environment requirements","zh":"赋予代理人从 .claude/ 目录加载项目上下文的能力，确保与 Claude Code 兼容，并通过加载编码规则和环境要求实现一致性","ja":".claude/ ディレクトリからプロジェクトコンテキストを読み込むことで、Claude Code との一貫性を保ち、コーディングルールと環境要件を読み込むことでエージェントに力を与える","ko":"에이전트가 .claude/ 디렉토리에서 프로젝트 컨텍스트를 로드하여 Claude Code와의 일관성을 보장하고, 코딩 규칙 및 환경 요구 사항을 로드하여 일관성을 제공","es":"Habilita a los agentes a aprovechar el contexto de proyecto compartido desde el directorio .claude/, garantizando la coherencia con Claude Code al cargar reglas de codificación y requisitos de entorno","fr":"Permet aux agents d''utiliser le contexte de projet partagé à partir du répertoire .claude/, en garantissant la cohérence avec Claude Code en chargeant les règles de codage et les exigences d''environnement","de":"Ermächtigt Agenten, den gemeinsamen Projektkontext aus dem .claude/-Verzeichnis zu nutzen, um die Konsistenz mit Claude Code durch Laden von Codierregeln und Umgebungsanforderungen sicherzustellen","pt":"Habilita os agentes a aproveitarem o contexto de projeto compartilhado a partir do diretório .claude/, garantindo a consistência com o Claude Code carregando regras de codificação e requisitos de ambiente","ru":"Наделяет агентов возможностью использовать общий контекст проекта из директории .claude/, обеспечивая согласованность с Claude Code путем загрузки правил кодирования и требований окружения","ar":"يمكن للوكلاء الاستفادة من السياق المشترك للمشروع من دليل .claude/، ضمانًا للاتساق مع Claude Code عن طريق تحميل قواعد البرمجة ومتطلبات البيئة"},"useCases":{"en":["Initializing project context for Codex CLI","Synchronizing coding principles across AI agents","Loading development environment requirements for task execution"],"zh":["为 Codex CLI 初始化项目上下文","在 AI 代理人之间同步编码原则","为任务执行加载开发环境要求"],"ja":["Codex CLI のプロジェクトコンテキストの初期化","AI エージェント間のコーディング原則の同期","タスク実行のための開発環境要件の読み込み"],"ko":["Codex CLI를 위한 프로젝트 컨텍스트 초기화","AI 에이전트 간 코딩 원칙 동기화","태스크 실행을 위한 개발 환경 요구 사항 로드"],"es":["Inicializar el contexto del proyecto para Codex CLI","Sincronizar los principios de codificación entre los agentes de IA","Cargar los requisitos del entorno de desarrollo para la ejecución de tareas"],"fr":["Initialiser le contexte du projet pour Codex CLI","Synchroniser les principes de codage entre les agents IA","Charger les exigences d''environnement de développement pour l''exécution de tâches"],"de":["Initialisieren des Projektkontexts für Codex CLI","Synchronisieren der Codierprinzipien zwischen den AI-Agenten","Laden der Entwicklungsumgebungsanforderungen für die Aufgabenausführung"],"pt":["Inicializar contexto de projeto para Codex CLI","Sincronizar princípios de codificação em agentes de IA","Carregar requisitos de ambiente de desenvolvimento para execução de tarefas"],"ru":["Инициализировать контекст проекта для Codex CLI","Синхронизировать принципы кодирования в агентах ИИ","Загрузить требования окружения разработки для выполнения задач"],"ar":["ت.Initialize سياق المشروع ل Codex CLI","تزامن مبادئ البرمجة عبر وكلاء الذكاء الاصطناعي","تحميل متطلبات بيئة التطوير لتنفيذ المهام"]},"limitations":{"en":["Requires access to .claude/ directory","Dependent on Codex CLI and Claude Code compatibility"],"zh":[".claude/ 目录的访问权限","依赖于 Codex CLI 和 Claude Code 的兼容性"],"ja":[".claude/ ディレクトリへのアクセス","Codex CLI と Claude Code の互換性への依存"],"ko":[".claude/ 디렉토리 접근 권한","Codex CLI와 Claude Code의 호환성에 대한 의존"],"es":["Requiere acceso al directorio .claude/","Depende de la compatibilidad de Codex CLI y Claude Code"],"fr":["Nécessite un accès au répertoire .claude/","Dépend de la compatibilité de Codex CLI et Claude Code"],"de":["Erfordert Zugriff auf das .claude/-Verzeichnis","Hängt von der Kompatibilität von Codex CLI und Claude Code ab"],"pt":["Requer acesso ao diretório .claude/","Dependente da compatibilidade entre Codex CLI e Claude Code"],"ru":["Требует доступа к директории .claude/","Зависит от совместимости между Codex CLI и Claude Code"],"ar":["يتطلب الوصول إلى دليل .claude/","يعتمد على التوافق بين Codex CLI و Claude Code"]},"version":4},"contentHash":"35e1bb3bae4f542b0d3607f9a3145047d8ef429e846b1f36e69c65ff00c6b464","qualityScore":51}');
