INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gaebalai/claude-code-orchestrator/context-loader', 'context-loader', 'gaebalai', 'claude-code-orchestrator', 'community', 'context-loader gaebalai claude-code-orchestrator community The context-loader skill loads shared project context from the .claude/ directory, ensuring Codex CLI has the same knowledge as Claude Code, benefiting AI agent developers. Context Loader 是一个用于加载共享项目上下文的技能，确保 Codex CLI 与 Claude Code 具有相同的知识 Context Loader は、共有プロジェクトコンテキストを読み込み、Codex CLI と Claude Code が同じ知識を持つことを保証するスキルです Context Loader는 공유 프로젝트 컨텍스트를 로드하여 Codex CLI와 Claude Code가 동일한 지식을 갖도록 하는 기술입니다 Context Loader es un entorno de desarrollo de AI que carga el contexto del proyecto desde el directorio `.claude/` para garantizar la coherencia en Codex CLI Context Loader est un environnement de développement d''IA qui charge le contexte du projet depuis le répertoire `.claude/` pour assurer la cohérence dans Codex CLI Context Loader ist eine künstliche Intelligenz-Entwicklungsumgebung, die den Projekt-Kontext aus dem Verzeichnis `.claude/` lädt, um die Konsistenz in Codex CLI zu gewährleisten O Context Loader é uma habilidade que carrega o contexto do projeto compartilhado a partir do diretório `.claude/` para garantir que o Codex CLI tenha o mesmo conhecimento que o Claude Code Context Loader - это навык, который загружает общий контекст проекта из директории `.claude/`, чтобы обеспечить совместимость знаний между Codex CLI и Claude Code محمل السياق هو مهارة تقوم بتحميل السياق المشترك للمشروع من الدليل `.claude/` لضمان توافق المعرفة بين Codex CLI و Claude Code how to use context-loader what is context-loader context-loader alternative context-loader vs Claude Code context-loader install context-loader setup guide Codex CLI integration multi-agent AI development environment Context Loader AI 开发环境 共享项目上下文 Codex CLI Claude Code 开发环境设置 AI 技术 开发工具 Loads coding rules from .claude/rules/ directory Reads files such as coding-principles.md and dev-environment.md Ensures Codex CLI has the same knowledge as Claude Code Activates at the beginning of every task for seamless integration Supports files like uv, ruff, ty, and pytest requirements Loads project context from .claude/ directory context-loader is a multi-agent AI development environment skill that loads project context to synchronize knowledge between Codex CLI and Claude Code.');
