INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('monkey1sai/openai-cli/caching-cdn-strategy-planner', 'caching-cdn-strategy-planner', 'monkey1sai', 'openai-cli', 'community', 'caching-cdn-strategy-planner monkey1sai openai-cli community The caching-cdn-strategy-planner skill helps developers design effective caching at all layers, from client to database. It provides a framework for configuring CDN strategies using CloudFront. Caching & CDN 策略规划工具帮助您设计有效的缓存层，包括客户端、CDN（边缘）和服务器缓存。使用 gemini cli、codex cli 和 claude cli 进行个人环境设置 キャッシング & CDN 戦略プランナーは、クライアント、CDN（エッジ）、サーバーキャッシュの各層で有効なキャッシングを設計するのに役立ちます。gemini cli、codex cli、claude cli を使用して個人環境設定を実施 캐싱 & CDN 전략 계획 도구는 클라이언트, CDN(에지), 서버 캐시의 각 계층에서 효과적인 캐싱을 설계하는 데 도움을 줍니다. gemini cli, codex cli, claude cli를 사용하여 개인 환경 설정을 수행 El planificador de estrategia de caché y CDN permite diseñar una caché efectiva en todas las capas, desde el cliente hasta la base de datos. Le planificateur de stratégie de mise en cache et de CDN permet de concevoir une mise en cache efficace à tous les niveaux, du client à la base de données. Der Caching- und CDN-Strategie-Planer ermöglicht das Entwerfen einer effektiven Caching-Strategie auf allen Ebenen, vom Client bis zur Datenbank. O Caching & CDN Strategy Planner é uma ferramenta que ajuda a configurar uma estratégia de cache eficaz em todas as camadas, incluindo Client, CDN, Server Cache e Database. ИИ Агент Caching & CDN Strategy Planner - это инструмент, который помогает настроить эффективную стратегию кэширования на всех уровнях, включая Client, CDN, Server Cache и Database. مخطط استراتيجية ذاكرة التخزين المؤقت و CDN هو أداة تساعد في تكوين استراتيجية ذاكرة التخزين المؤقت الفعالة على جميع المستويات ، بما في ذلك العميل و CDN و ذاكرة التخزين المؤقت للخادم و قاعدة البيانات. how to use caching-cdn-strategy-planner caching-cdn-strategy-planner setup guide CloudFront configuration tutorial caching-cdn-strategy-planner vs Cloudflare caching-cdn-strategy-planner install CDN strategy optimization techniques what is caching-cdn-strategy-planner caching-cdn-strategy-planner alternative caching-cdn-strategy-planner documentation Caching & CDN 缓存层设计 CDN 配置 CloudFront gemini cli codex cli claude cli AI エージェント Configures CloudFront distributions with custom headers and origins Supports HTTPS redirection using ViewerProtocolPolicy Designs caching layers from client to database Utilizes TypeScript for CDN configuration Integrates with environment variables for secure secret storage Defines default cache behavior for optimized performance caching-cdn-strategy-planner is a skill that enables the design of effective caching strategies at multiple layers, including client, CDN, server cache, and database.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Not-Sarthak/copium/tapestry', 'community', 'Not-Sarthak', 'copium', 'Not-Sarthak/copium', 'tapestry', 1, 0, 51, '2026-02-28T04:36:11Z', '2026-03-06T07:14:03.002Z', '0bb4acfa0c2ad92f33c490db326cd2edcea618ddf0a8b6c0250719344444b2f0', '{"id":"Not-Sarthak/copium/tapestry","name":"tapestry","description":{"en":"Tapestry enables social trading app developers to predict and profit together, leveraging React Native and Expo Router. It benefits developers building social features for mobile apps like Copium.","zh":"Tapestry 是一个预测和利润工具，用于构建社交交易应用程序，如 Copium，集成了 React Native 和 Expo","ja":"Tapestry は、Copium のようなソーシャルトレーディングアプリを構築するために、React Native と Expo で統合される予測と利益ツールです","ko":"Tapestry는 Copium과 같은 社交 거래 애플리케이션을 구축하기 위한 React Native와 Expo에서 통합되는 예측 및 수익 도구입니다","es":"Tapestry es una herramienta para predecir y ganar juntos en aplicaciones de trading social como Copium","fr":"Tapestry est un outil pour prédire et gagner ensemble dans les applications de trading social comme Copium","de":"Tapestry ist ein Tool, um gemeinsam vorherzusagen und zu gewinnen in sozialen Trading-Apps wie Copium","pt":"O Tapestry é uma ferramenta de gráficos sociais para aplicações React Native, permitindo a previsão e lucro conjunto","ru":"Tapestry - это инструмент социальных графов для React Native-приложений, позволяющий предсказывать и получать прибыль вместе","ar":"Tapestry هو أداة للرسوم البيانية الاجتماعية لتطبيقات React Native، مما يسمح بالتنبؤ والربح المشترك"},"seo":{"title":{"en":"Tapestry: Social Graph Integration Setup Guide | AI Agent...","zh":"Tapestry 集成指南：预测和利润工具","ja":"Tapestry のセットアップガイド：AIエージェントによる予測と利益","ko":"Tapestry 설정 가이드: 예측 및 수익 도구","es":"Guía de configuración de Tapestry para React Native","fr":"Guide d''intégration de Tapestry pour les applications mob...","de":"Tapestry-Setup-Anleitung für React Native-Entwickler","pt":"Guia de Configuração do Tapestry para Desenvolvedores","ru":"Настройка Tapestry: Руководство для Разработчиков ИИ Агентов","ar":"دليل إعداد Tapestry لمنصة التداول الاجتماعي"},"description":{"en":"Unlock predictable profits with Tapestry''s social graph integration for React Native apps - learn how to get started today!","zh":"了解 Tapestry 的技术细节和集成方法，用于构建社交交易应用程序，如 Copium","ja":"Tapestry の技術的詳細と統合方法を学び、Copium のようなソーシャルトレーディングアプリを構築する","ko":"Tapestry의 기술 세부 정보와 통합 방법을 알아보고 Copium 같은 사회 거래 애플리케이션을 구축하세요","es":"Aprende a integrar Tapestry en tu aplicación móvil React Native con Expo Router y Privy para OAuth","fr":"Découvrez comment intégrer Tapestry dans votre application mobile React Native avec Expo Router et Privy pour OAuth","de":"Erfahren Sie, wie Sie Tapestry in Ihre React Native-App mit Expo Router und Privy für OAuth integrieren","pt":"Aprenda a integrar o Tapestry na sua aplicação React Native com Expo Router e Privy Auth","ru":"Интегрируйте Tapestry в свое React Native-приложение с Expo Router и аутентификацией Privy","ar":"تعلم كيفية دمج Tapestry في تطبيقك الخاص بالتداول الاجتماعي مع React Native و Expo Router"},"definition":{"en":"Tapestry is a social graph integration technology for building social trading apps, utilizing Privy and Mobile Wallet Adapter for secure authentication.","zh":"Tapestry 是一个用于构建社交交易应用程序的预测和利润工具","ja":"Tapestry は、ソーシャルトレーディングアプリを構築するための予測と利益ツールです","ko":"Tapestry는 社交 거래 애플리케이션을 구축하기 위한 예측 및 수익 도구입니다","es":"Tapestry es una herramienta de gráficos sociales para aplicaciones móviles","fr":"Tapestry est un outil de graphiques sociaux pour applications mobiles","de":"Tapestry ist ein Tool für soziale Graphen in mobilen Anwendungen","pt":"O que é Tapestry? Uma ferramenta de gráficos sociais para aplicações React Native","ru":"Что такое Tapestry? Инструмент социальных графов для React Native-приложений","ar":"ما هو Tapestry؟ أداة للرسوم البيانية الاجتماعية لتطبيقات React Native"},"features":{"en":["Integrates with React Native and Expo Router for seamless file-based routing","Utilizes Privy for OAuth and embedded Solana wallet authentication","Supports Mobile Wallet Adapter (MWA) for secure wallet management","Provides a wallet hook via `useUnifiedWallet()` from `@/hooks/use-wallet`","Enables social graph integration for predictive trading apps like Copium","Compatible with Polymarket for robust market data and analytics"],"zh":["React Native 和 Expo 集成","Privy 和 Mobile Wallet Adapter 身份验证","useUnifiedWallet() 钩子提供 wallet 功能","支持 file-based routing","集成了 Polymarket"],"ja":["React Native と Expo の統合","Privy と Mobile Wallet Adapter の認証","useUnifiedWallet() フックによるウォレット機能","ファイルベースのルーティングのサポート","Polymarket との統合"],"ko":["React Native와 Expo 통합","Privy와 Mobile Wallet Adapter 인증","useUnifiedWallet() 훅으로 제공되는 지갑 기능","파일 기반 라우팅 지원","Polymarket와의 통합"],"es":["Integración con React Native y Expo Router","Autenticación con Privy y OAuth","Soporte para wallets móviles con Mobile Wallet Adapter (MWA)","Uso de hooks de wallet como useUnifiedWallet()","Compatibilidad con Solana wallet"],"fr":["Intégration avec React Native et Expo Router","Authentification avec Privy et OAuth","Support pour les wallets mobiles avec Mobile Wallet Adapter (MWA)","Utilisation de hooks de wallet tels que useUnifiedWallet()","Compatibilité avec le portefeuille Solana"],"de":["Integration mit React Native und Expo Router","Authentifizierung mit Privy und OAuth","Unterstützung für mobile Wallets mit Mobile Wallet Adapter (MWA)","Verwendung von Wallet-Hooks wie useUnifiedWallet()","Kompatibilität mit Solana-Wallet"],"pt":["Integração com React Native e Expo Router","Suporte à autenticação com Privy e Mobile Wallet Adapter","Uso do hook useUnifiedWallet() para gerenciar carteiras","Compatibilidade com o estado de conexão e logout","Integração com a wallet do Solana"],"ru":["Интеграция с React Native и Expo Router","Поддержка аутентификации с Privy и Mobile Wallet Adapter","Использование хука useUnifiedWallet() для управления кошельками","Совместимость со статусом подключения и выхода","Интеграция с кошельком Solana"],"ar":["التكامل مع React Native و Expo Router","دعم التأشير مع Privy و Mobile Wallet Adapter","استخدام Hook useUnifiedWallet() لإدارة المحفظة","التوافق مع حالة الاتصال و الخروج","التكامل مع محفظة Solana"]},"keywords":{"en":["how to use tapestry","tapestry social graph integration","react native tapestry setup","tapestry vs polymarket","tapestry install guide","what is tapestry","tapestry alternative","tapestry for social trading apps","tapestry and expo router","tapestry predictive trading"],"zh":["Tapestry 集成","React Native 社交交易","Expo 社交应用","Privy 身份验证","Mobile Wallet Adapter","useUnifiedWallet() 钩子","Polymarket 集成"],"ja":["Tapestry 統合","React Native ソーシャルトレーディング","Expo ソーシャルアプリ","Privy 認証","Mobile Wallet Adapter","useUnifiedWallet() フック","Polymarket 統合"],"ko":["Tapestry 설정","React Native 社交 거래","Expo 社交 애플리케이션","Privy 인증","Mobile Wallet Adapter","useUnifiedWallet() 훅","Polymarket 설정"],"es":["Tapestry React Native","Integración de gráficos sociales","Aplicaciones de trading social","Privy OAuth","Mobile Wallet Adapter","Solana wallet","Desarrollo de aplicaciones móviles","Herramientas de AI para trading"],"fr":["Tapestry React Native","Intégration de graphiques sociaux","Applications de trading social","Privy OAuth","Mobile Wallet Adapter","Solana portefeuille","Développement d''applications mobiles","Outils d''IA pour le trading"],"de":["Tapestry React Native","Integration von sozialen Graphen","Soziale Trading-Anwendungen","Privy OAuth","Mobile Wallet Adapter","Solana-Wallet","Entwicklung von mobilen Anwendungen","AI-Tools für Trading"],"pt":["Tapestry","React Native","Expo Router","Privy Auth","Mobile Wallet Adapter","useUnifiedWallet","Solana wallet","desenvolvimento de aplicações móveis","gráficos sociais"],"ru":["Tapestry","React Native","Expo Router","Privy Auth","Mobile Wallet Adapter","useUnifiedWallet","Solana кошелек","разработка мобильных приложений","ИИ Агенты","социальные графы"],"ar":["Tapestry","React Native","Expo Router","Privy Auth","Mobile Wallet Adapter","useUnifiedWallet","محفظة Solana","تطوير التطبيقات الموبايل","الرسوم البيانية الاجتماعية","أدوات الذكاء الاصطناعي"]}},"owner":"Not-Sarthak","repo":"copium","repoPath":"Not-Sarthak/copium","stars":1,"forks":0,"updatedAt":"2026-02-28T04:36:11Z","topics":[],"category":"community","skillMd":{"name":"tapestry","description":"Social graph protocol integration for Copium app using Tapestry API. Use when building social features - profiles, follows, content/posts, comments, likes, activity feeds, identity resolution, or trades. Covers all 41 Tapestry API endpoints.","bodyPreview":"# Tapestry Social Graph Integration\n\nYou are building social features for a React Native (Expo) mobile app called **Copium** - a social trading app using Tapestry and Polymarket.\n\n## Project Context\n\n- **Framework**: React Native with Expo Router (file-based routing)\n- **Auth**: Privy (OAuth + embedded Solana wallet) + Mobile Wallet Adapter (MWA)\n- **Wallet hook**: `useUnifiedWallet()` from `@/hooks/use-wallet` provides `address`, `walletType`, `provider`, `isConnected`, `logout`\n- **State**: Re","body":"# Tapestry Social Graph Integration\n\nYou are building social features for a React Native (Expo) mobile app called **Copium** - a social trading app using Tapestry and Polymarket.\n\n## Project Context\n\n- **Framework**: React Native with Expo Router (file-based routing)\n- **Auth**: Privy (OAuth + embedded Solana wallet) + Mobile Wallet Adapter (MWA)\n- **Wallet hook**: `useUnifiedWallet()` from `@/hooks/use-wallet` provides `address`, `walletType`, `provider`, `isConnected`, `logout`\n- **State**: React Query (`@tanstack/react-query`) for server state\n- **Styling**: StyleSheet with `#0a0a0a` bg, `#232323` borders, `PlusJakartaSans` font\n- **API Key**: `process.env.TAPESTRY_API_KEY` (server-side only, stored in `.env.local`)\n- **Base URL**: `https://api.usetapestry.dev/api/v1`\n\n## API Authentication\n\nAll endpoints require `apiKey` as a query parameter:\n```\nGET /profiles/{id}?apiKey=YOUR_API_KEY\n```\n\nThe API key is in `.env.local` as `TAPESTRY_API_KEY`. Since this is a React Native app (no server-side routes), call the Tapestry API directly from a utility module, keeping the API key secure via `process.env.TAPESTRY_API_KEY` (bundled at build time but not exposed to web).\n\n## Execution Methods (for write operations)\n\n| Method | Speed | Use When |\n|--------|-------|----------|\n| `FAST_UNCONFIRMED` | <1s | Default. Returns after graph DB write, on-chain tx in background |\n| `QUICK_SIGNATURE` | ~5s | Need tx signature but don''t need confirmation |\n| `CONFIRMED_AND_PARSED` | ~15s | Need full on-chain confirmation |\n\n## API Client Pattern\n\nCreate API calls in `lib/tapestry/` directory. Use this pattern:\n\n```typescript\n// lib/tapestry/client.ts\nconst TAPESTRY_BASE = ''https://api.usetapestry.dev/api/v1'';\nconst API_KEY = process.env.TAPESTRY_API_KEY!;\n\nexport async function tapestryFetch<T>(\n  endpoint: string,\n  options?: { method?: string; body?: any; params?: Record<string, string> }\n): Promise<T> {\n  const { method = ''GET'', body, params = {} } = options ?? {};\n  const url = new URL(`${TAPESTRY_BASE}${endpoint}`);\n  url.searchParams.set(''apiKey'', API_KEY);\n  Object.entries(params).forEach(([k, v]) => v && url.searchParams.set(k, v));\n\n  const res = await fetch(url.toString(), {\n    method,\n    headers: body ? { ''Content-Type'': ''application/json'' } : undefined,\n    body: body ? JSON.stringify(body) : undefined,\n  });\n\n  if (!res.ok) {\n    const err = await res.json().catch(() => ({}));\n    throw new Error(err.error || `Tapestry API error: ${res.status}`);\n  }\n  return res.json();\n}\n```\n\n## React Hook Pattern\n\n```typescript\n// hooks/use-tapestry-profile.ts\nimport { useQuery, useMutation, useQueryClient } from ''@tanstack/react-query'';\nimport { tapestryFetch } from ''@/lib/tapestry/client'';\n\nexport function useTapestryProfile(username: string) {\n  return useQuery({\n    queryKey: [''tapestry-profile'', username],\n    queryFn: () => tapestryFetch<ProfileResponse>(`/profiles/${username}`),\n    enabled: !!username,\n  });\n}\n```\n\n## All Endpoints Reference\n\nFor detailed endpoint specs, see [reference.md](reference.md).\n\n### Quick Endpoint Map\n\n**Profiles**\n- `GET /profiles/` - List/search profiles (by wallet, phone, twitter, email)\n- `POST /profiles/findOrCreate` - Find or create profile\n- `GET /profiles/{id}` - Get profile by ID or username\n- `PUT /profiles/{id}` - Update profile\n- `GET /profiles/{id}/followers` - Get followers\n- `GET /profiles/{id}/following` - Get following\n- `GET /profiles/{id}/followers/global` - Cross-namespace followers\n- `GET /profiles/{id}/following/global` - Cross-namespace following\n- `GET /profiles/{id}/following-who-follow` - Mutual connections\n- `GET /profiles/{id}/wallets` - Get linked wallets\n- `PATCH /profiles/{id}/wallets` - Link wallets\n- `DELETE /profiles/{id}/wallets` - Unlink wallets\n- `PATCH /profiles/{id}/contacts` - Link contacts\n- `DELETE /profiles/{id}/contacts` - Unlink contacts\n- `POST /profiles/{id}/notification` - Send notification\n- `GET /profiles/{id}/referrals` - Get referral tree\n- `GET /profiles/{id}/suggested-profiles` - Suggested follows\n- `GET /profiles/suggested/{identifier}` - Suggestions by wallet/contact\n- `GET /profiles/suggested/{identifier}/global` - Cross-namespace suggestions\n- `GET /profiles/token-owners/{tokenAddress}` - Token holder profiles\n- `GET /search/profiles` - Search profiles by text\n\n**Social Graph (Followers)**\n- `POST /followers/add` - Follow `{ startId, endId }`\n- `POST /followers/remove` - Unfollow `{ startId, endId }`\n- `GET /followers/state` - Check follow state `?startId=&endId=`\n\n**Content (Posts)**\n- `GET /contents/` - List content (with filters, ordering, pagination)\n- `GET /contents/aggregation` - Aggregate content properties\n- `POST /contents/batch/read` - Batch get by IDs (max 20)\n- `POST /contents/findOrCreate` - Create content `{ id, profileId, properties: [{key,value}] }`\n- `GET /contents/{id}` - Get content details\n- `PUT /contents/{id}` - Update content properties\n- `DELETE /contents/{id}` - Delete content\n\n**Comments**\n- `GET /comments/` - List comments `?contentId=&profileId=&targetProfileId=`\n- `POST /comments/` - Create comment `{ profileId, text, contentId?, commentId?, targetProfileId? }`\n- `POST /comments/batch/read` - Batch get (max 20)\n- `GET /comments/{id}` - Get comment with replies\n- `PUT /comments/{id}` - Update comment\n- `DELETE /comments/{id}` - Delete comment\n- `GET /comments/{id}/replies` - Get replies\n\n**Likes**\n- `GET /likes/{nodeId}` - Get profiles who liked a node\n- `POST /likes/{nodeId}` - Like `{ startId }`\n- `DELETE /likes/{nodeId}` - Unlike `{ startId }`\n\n**Activity Feeds**\n- `GET /activity/feed` - User activity feed `?username=`\n- `GET /activity/global` - Global activity feed\n- `GET /activity/swap` - Swap activity from followed wallets `?username=&tokenAddress=`\n\n**Identities**\n- `GET /identities/{id}` - Resolve wallets/contacts from ID\n- `GET /identities/{id}/profiles` - Find profiles across namespaces\n\n**Trades**\n- `POST /trades/` - Log a trade\n- `GET /trades/all-trades` - Get all trades in time period\n- `GET /trades/fetch-transaction-history` - Wallet tx history\n\n**Wallets**\n- `POST /wallets/{address}/connect` - Connect two wallets\n- `GET /wallets/{address}/socialCounts` - Social counts by wallet\n\n## Key Integration Points for Copium\n\n### 1. Profile Creation (on signup/login)\nAfter wallet connection + X login, call `findOrCreate`:\n```typescript\nawait tapestryFetch(''/profiles/findOrCreate'', {\n  method: ''POST'',\n  body: {\n    username: twitterHandle, // from Privy OAuth\n    walletAddress: address,  // from useUnifiedWallet\n    blockchain: ''SOLANA'',\n    image: twitterProfileImage,\n    bio: twitterBio,\n    contact: { id: twitterHandle, type: ''TWITTER'' },\n  },\n});\n```\n\n### 2. Follow/Unfollow\n```typescript\nawait tapestryFetch(''/followers/add'', {\n  method: ''POST'',\n  body: { startId: myProfileId, endId: targetProfileId },\n});\n```\n\n### 3. Create a Post (Content)\n```typescript\nawait tapestryFetch(''/contents/findOrCreate'', {\n  method: ''POST'',\n  body: {\n    id: `post-${Date.now()}`,\n    profileId: myProfileId,\n    properties: [\n      { key: ''text'', value: ''My post content'' },\n      { key: ''type'', value: ''trade_call'' },\n    ],\n  },\n});\n```\n\n### 4. Like Content\n```typescript\nawait tapestryFetch(`/likes/${contentId}`, {\n  method: ''POST'',\n  body: { startId: myProfileId },\n});\n```\n\n### 5. Comment on Content\n```typescript\nawait tapestryFetch(''/comments/'', {\n  method: ''POST'',\n  body: {\n    profileId: myProfileId,\n    contentId: contentId,\n    text: ''Great trade!'',\n  },\n});\n```\n\n### 6. Activity Feed\n```typescript\nconst feed = await tapestryFetch(''/activity/feed'', {\n  params: { username: myUsername },\n});\n```\n\n### 7. Search Users\n```typescript\nconst results = await tapestryFetch(''/search/profiles'', {\n  params: { query: searchText },\n});\n```\n\n### 8. Polymarket Integration Pattern\nStore Polymarket-related data as content properties:\n```typescript\nawait tapestryFetch(''/contents/findOrCreate'', {\n  method: ''POST'',\n  body: {\n    id: `prediction-${marketId}-${profileId}`,\n    profileId: myProfileId,\n    properties: [\n      { key: ''type'', value: ''prediction'' },\n      { key: ''marketId'', value: polymarketConditionId },\n      { key: ''position'', value: ''YES'' },\n      { key: ''amount'', value: 50 },\n      { key: ''odds'', value: 0.65 },\n    ],\n  },\n});\n```\n\n## Response Types\n\n```typescript\ninterface TapestryProfile {\n  id: string;\n  namespace: string;\n  created_at: number;\n  username: string;\n  bio: string | null;\n  image: string | null;\n}\n\ninterface ProfileResponse {\n  profile: TapestryProfile;\n  walletAddress: string;\n  socialCounts: { followers: number; following: number };\n  namespace: { name: string | null; readableName: string | null };\n}\n\ninterface ContentResponse {\n  id: string;\n  created_at: number;\n  properties: Record<string, any>;\n}\n\ninterface CommentResponse {\n  comment: { id: string; created_at: number; text: string };\n  author: TapestryProfile;\n  socialCounts: { likeCount: number };\n  requestingProfileSocialInfo?: { hasLiked: boolean };\n}\n\ninterface ActivityItem {\n  type: ''following'' | ''new_content'' | ''like'' | ''comment'' | ''new_follower'';\n  actor_id: string;\n  actor_username: string;\n  target_id?: string;\n  target_username?: string;\n  timestamp: number;\n  activity: string;\n}\n\ninterface PaginatedResponse<T> {\n  page: number;\n  pageSize: number;\n  totalCount: number;\n  data?: T[];\n  profiles?: T[];\n  activities?: T[];\n}\n```\n\n## File Structure Convention\n\n```\nlib/tapestry/\n  client.ts          # Base fetch wrapper\n  profiles.ts        # Profile API functions\n  social.ts          # Follow/unfollow/like functions\n  content.ts         # Content/posts CRUD\n  comments.ts        # Comments CRUD\n  activity.ts        # Activity feed functions\n  types.ts           # TypeScript interfaces\n\nhooks/\n  use-tapestry-profile.ts\n  use-tapestry-feed.ts\n  use-tapestry-social.ts\n  use-tapestry-content.ts\n```\n\nWhen implementing features with `$ARGUMENTS`, refer to [reference.md](reference.md) for full endpoint details.\n"},"lastSynced":"2026-03-06T07:14:03.002Z","agentAnalysis":{"suitability":{"en":"Perfect for Social Trading Agents needing advanced React Native integration with Expo Router for mobile app development.","zh":"非常适合需要高级React Native集成的Expo Router用于移动应用开发的社交交易代理。","ja":"React NativeとExpo Routerの高度な統合が必要なソーシャルトレーディングエージェントに最適。","ko":"React Native와 Expo Router의 고급 통합이 필요한 소셜 트레이딩 에이전트에게 최적입니다.","es":"Perfecto para Agentes de Trading Social que necesitan una integración avanzada de React Native con Expo Router para el desarrollo de aplicaciones móviles.","fr":"Parfait pour les agents de trading social nécessitant une intégration avancée de React Native avec Expo Router pour le développement d''applications mobiles.","de":"Perfekt für Social Trading Agenten, die eine erweiterte React Native-Integration mit Expo Router für die Entwicklung mobiler Apps benötigen.","pt":"Perfeito para Agentes de Negociação Social que precisam de integração avançada do React Native com o Expo Router para desenvolvimento de aplicativos móveis.","ru":"Идеально подходит для социальных торговых агентов, которым требуется продвинутая интеграция React Native с Expo Router для разработки мобильных приложений.","ar":"مثالي لوسائل التداول الاجتماعي التي تحتاج إلى دمج متقدم من React Native مع Expo Router لتطوير التطبيقات المحمولة."},"recommendation":{"en":"Empowers agents to predict and profit together by leveraging Tapestry''s social graph integration, utilizing React Native and Expo Router for seamless mobile app development, and integrating with Privy and Mobile Wallet Adapter for secure authentication and wallet management.","zh":"通过利用Tapestry的社交图集成，使用React Native和Expo Router实现无缝的移动应用开发，并与Privy和Mobile Wallet Adapter集成以实现安全的认证和钱包管理，赋予代理预测和共同获利的能力。","ja":"Tapestryのソーシャルグラフ統合を利用し、React NativeとExpo Routerを使用してシームレスなモバイルアプリ開発を行い、PrivyとMobile Wallet Adapterを統合して安全な認証とウォレット管理を行うことで、エージェントが予測して共同で利益を得ることができる。","ko":"Tapestry의 소셜 그래프 통합을 활용하고 React Native와 Expo Router를 사용하여 무결점의 모바일 앱 개발을 수행하며 Privy와 Mobile Wallet Adapter와 통합하여 안전한 인증 및 월レット 관리를 통해 에이전트가 예측하고 공동으로 이익을 얻을 수 있도록 합니다.","es":"Habilita a los agentes a predecir y obtener beneficios juntos aprovechando la integración de gráficos sociales de Tapestry, utilizando React Native y Expo Router para un desarrollo de aplicaciones móviles sin problemas, e integrándose con Privy y Mobile Wallet Adapter para una autenticación y gestión de billetera seguras.","fr":"Permet aux agents de prédire et de profiter ensemble en exploitant l''intégration du graphique social de Tapestry, en utilisant React Native et Expo Router pour un développement d''applications mobiles sans accroc, et en s''intégrant avec Privy et Mobile Wallet Adapter pour une authentification et une gestion de portefeuille sécurisées.","de":"Ermöglicht es den Agenten, gemeinsam zu prognostizieren und zu profitieren, indem sie die soziale Graph-Integration von Tapestry nutzen, React Native und Expo Router für eine nahtlose Entwicklung mobiler Apps verwenden und sich mit Privy und Mobile Wallet Adapter für eine sichere Authentifizierung und Wallet-Verwaltung integrieren.","pt":"Habilita os agentes a prever e lucrar juntos, aproveitando a integração do grafo social da Tapestry, utilizando React Native e Expo Router para desenvolvimento de aplicativos móveis sem problemas, e integrando com Privy e Mobile Wallet Adapter para autenticação e gestão de carteira seguras.","ru":"Наделяет агентов возможностью предсказывать и получать прибыль вместе, используя интеграцию социального графа Tapestry, React Native и Expo Router для бесшовного разработки мобильных приложений, а также интегрируя с Privy и Mobile Wallet Adapter для безопасной аутентификации и управления кошельком.","ar":"تمكين الوكلاء من التنبؤ والربح معًا من خلال الاستفادة من دمج الرسم البياني الاجتماعي Tapestry، واستخدام React Native و Expo Router من أجل تطوير تطبيقات محمولة دون مشاكل، ودمجها مع Privy و Mobile Wallet Adapter لأغراض التحقق والتحكم في الحساب الآمنين."},"useCases":{"en":["Building social features for mobile trading apps like Copium","Integrating Tapestry with Polymarket for social trading functionality","Implementing file-based routing with Expo Router for efficient navigation"],"zh":["为移动交易应用程序（如Copium）构建社交功能","将Tapestry与Polymarket集成以实现社交交易功能","使用Expo Router实现基于文件的路由以进行高效导航"],"ja":["モバイルトレーディングアプリ（例：Copium）向けのソーシャル機能の構築","TapestryとPolymarketの統合によるソーシャルトレーディング機能の実現","Expo Routerを使用したファイルベースのルーティングによる効率的なナビゲーションの実現"],"ko":["모바일 트레이딩 앱(Copium 등) 용 소셜 기능 구축","Tapestry와 Polymarket의 통합을 통한 소셜 트레이딩 기능 구현","Expo Router를 사용한 파일 기반 라우팅을 통한 효율적인 탐색 구현"],"es":["Construir características sociales para aplicaciones de trading móviles como Copium","Integrar Tapestry con Polymarket para funcionalidad de trading social","Implementar enrutamiento basado en archivos con Expo Router para una navegación eficiente"],"fr":["Construire des fonctionnalités sociales pour les applications de trading mobile comme Copium","Intégrer Tapestry avec Polymarket pour la fonctionnalité de trading social","Mettre en œuvre un routage basé sur des fichiers avec Expo Router pour une navigation efficace"],"de":["Soziale Funktionen für mobile Trading-Apps wie Copium erstellen","Tapestry mit Polymarket für soziale Trading-Funktionalität integrieren","Dateibasiertes Routing mit Expo Router für eine effiziente Navigation implementieren"],"pt":["Construir recursos sociais para aplicativos de negociação móveis como o Copium","Integrar a Tapestry com o Polymarket para funcionalidade de negociação social","Implementar roteamento baseado em arquivos com Expo Router para navegação eficiente"],"ru":["Построение социальных функций для мобильных торговых приложений, таких как Copium","Интеграция Tapestry с Polymarket для социальной торговой функциональности","Реализация маршрутизации на основе файлов с помощью Expo Router для эффективной навигации"],"ar":["بناء الميزات الاجتماعية لتطبيقات التداول المحمول مثل Copium","دمج Tapestry مع Polymarket من أجل وظائف التداول الاجتماعي","تنفيذ التوجيه المبني على الملفات مع Expo Router من أجل الملاحة الفعالة"]},"limitations":{"en":["Requires React Native and Expo Router setup","Limited to mobile app development","Dependent on Privy and Mobile Wallet Adapter for authentication and wallet management"],"zh":["需要React Native和Expo Router的设置","仅限移动应用开发","依赖Privy和Mobile Wallet Adapter进行认证和钱包管理"],"ja":["React NativeとExpo Routerの設定が必要","モバイルアプリ開発に限定される","認証とウォレット管理のためにPrivyとMobile Wallet Adapterに依存する"],"ko":["React Native와 Expo Router 설정이 필요","모바일 앱 개발에만 제한됨","인증 및 월レット 관리를 위해 Privy와 Mobile Wallet Adapter에 의존"],"es":["Requiere configuración de React Native y Expo Router","Limitado al desarrollo de aplicaciones móviles","Dependiente de Privy y Mobile Wallet Adapter para la autenticación y la gestión de billetera"],"fr":["Nécessite une configuration de React Native et Expo Router","Limité au développement d''applications mobiles","Dépend de Privy et Mobile Wallet Adapter pour l''authentification et la gestion de portefeuille"],"de":["Benötigt eine Einrichtung von React Native und Expo Router","Begrenzt auf die Entwicklung mobiler Apps","Abhängig von Privy und Mobile Wallet Adapter für Authentifizierung und Wallet-Verwaltung"],"pt":["Requer configuração do React Native e do Expo Router","Limitado ao desenvolvimento de aplicativos móveis","Dependente do Privy e do Mobile Wallet Adapter para autenticação e gestão de carteira"],"ru":["Требует настройки React Native и Expo Router","Ограничен разработкой мобильных приложений","Зависит от Privy и Mobile Wallet Adapter для аутентификации и управления кошельком"],"ar":["يتطلب إعداد React Native و Expo Router","محدود بتطوير التطبيقات المحمولة","يعتمد على Privy و Mobile Wallet Adapter من أجل التحقق والتحكم في الحساب"]},"version":4},"contentHash":"0bb4acfa0c2ad92f33c490db326cd2edcea618ddf0a8b6c0250719344444b2f0","qualityScore":51}');
