INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Not-Sarthak/copium/tapestry', 'tapestry', 'Not-Sarthak', 'copium', 'community', 'tapestry Not-Sarthak copium community Tapestry enables social trading app developers to predict and profit together, leveraging React Native and Expo Router. It benefits developers building social features for mobile apps like Copium. Tapestry 是一个预测和利润工具，用于构建社交交易应用程序，如 Copium，集成了 React Native 和 Expo Tapestry は、Copium のようなソーシャルトレーディングアプリを構築するために、React Native と Expo で統合される予測と利益ツールです Tapestry는 Copium과 같은 社交 거래 애플리케이션을 구축하기 위한 React Native와 Expo에서 통합되는 예측 및 수익 도구입니다 Tapestry es una herramienta para predecir y ganar juntos en aplicaciones de trading social como Copium Tapestry est un outil pour prédire et gagner ensemble dans les applications de trading social comme Copium Tapestry ist ein Tool, um gemeinsam vorherzusagen und zu gewinnen in sozialen Trading-Apps wie Copium O Tapestry é uma ferramenta de gráficos sociais para aplicações React Native, permitindo a previsão e lucro conjunto Tapestry - это инструмент социальных графов для React Native-приложений, позволяющий предсказывать и получать прибыль вместе Tapestry هو أداة للرسوم البيانية الاجتماعية لتطبيقات React Native، مما يسمح بالتنبؤ والربح المشترك how to use tapestry tapestry social graph integration react native tapestry setup tapestry vs polymarket tapestry install guide what is tapestry tapestry alternative tapestry for social trading apps tapestry and expo router tapestry predictive trading Tapestry 集成 React Native 社交交易 Expo 社交应用 Privy 身份验证 Mobile Wallet Adapter useUnifiedWallet() 钩子 Polymarket 集成 Integrates with React Native and Expo Router for seamless file-based routing Utilizes Privy for OAuth and embedded Solana wallet authentication Supports Mobile Wallet Adapter (MWA) for secure wallet management Provides a wallet hook via `useUnifiedWallet()` from `@/hooks/use-wallet` Enables social graph integration for predictive trading apps like Copium Compatible with Polymarket for robust market data and analytics Tapestry is a social graph integration technology for building social trading apps, utilizing Privy and Mobile Wallet Adapter for secure authentication.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mattycraig/nuxt-theme-builder/nuxt-seo', 'community', 'mattycraig', 'nuxt-theme-builder', 'mattycraig/nuxt-theme-builder', 'nuxt-seo', 1, 0, 51, '2026-02-28T23:25:57Z', '2026-03-06T07:15:32.484Z', '254b902fbdd467b08ff7c2556f02dec2afc99fcd47583e02d1f31f9c30e8fbb3', '{"id":"mattycraig/nuxt-theme-builder/nuxt-seo","name":"nuxt-seo","description":{"en":"The nuxt-seo skill enables developers to design and preview Nuxt UI semantic palettes and configure SEO settings for their sites, including site URL, name, and indexability.","zh":"Nuxt SEO 是一个用于设计和预览 Nuxt UI 语义调色板、中性比例、半径、字体和浅色/深色模式令牌覆盖的工具","ja":"Nuxt SEO は、Nuxt UI のシマンティック パレット、ニュートラル スケール、半径、フォント、ライト/ダーク モード トークン オーバーライドを設計およびプレビューするツールです","ko":"Nuxt SEO는 Nuxt UI의 시맨틱 팔레트, 중성 스케일, 반지름, 글꼴 및 라이트/다크 모드 토큰 오버라이드를 설계 및 미리 보는 도구입니다","es":"nuxt-seo es una herramienta para diseñar y previsualizar paletas semánticas de Nuxt UI, incluyendo escalas neutrales, radio, fuentes y anulaciones de tokens de modo claro/oscuro","fr":"nuxt-seo est un outil pour concevoir et prévisualiser les palettes sémantiques de Nuxt UI, y compris les échelles neutres, le rayon, les polices et les annulations de tokens de mode clair/sombre","de":"nuxt-seo ist ein Tool zum Entwerfen und Vorschauen semantischer Paletten von Nuxt UI, einschließlich neutraler Skalen, Radius, Schriftarten und Aufhebungen von Token für Hell-/Dunkelmodus","pt":"O Nuxt SEO é uma ferramenta poderosa para melhorar a visibilidade dos seus projetos de Ferramentas de IA. Configure recursos como SEO configuration e JSON-LD.","ru":"Nuxt SEO - это мощный инструмент для улучшения видимости ваших проектов ИИ Агентов. Настройте функции như SEO конфигурация и JSON-LD.","ar":"Nuxt SEO هو أداة قوية لتحسين ظهور مشاريعك من الأدوات الذكية. إعداد ميزات مثل تكوين SEO و JSON-LD."},"seo":{"title":{"en":"nuxt-seo: Setup Guide for AI Agents | AI Agent Skill","zh":"Nuxt SEO Setup Guide - AIエージェント","ja":"Nuxt SEO 設定ガイド - AIエージェント","ko":"Nuxt SEO 설정 가이드 - AI 에이전트","es":"Guía de configuración de nuxt-seo para optimización de mo...","fr":"Guide de configuration de nuxt-seo pour l''optimisation de...","de":"Einrichtungsleitfaden für nuxt-seo zur Suchmaschinenoptim...","pt":"Guia de Configuração do Nuxt SEO para Ferramentas de IA","ru":"Настройка Nuxt SEO для ИИ Агентов","ar":"دليل إعداد Nuxt SEO للأدوات الذكية"},"description":{"en":"Discover how to configure nuxt-seo for optimal site indexing and SEO configuration. Learn to generate robots.txt, sitemap.xml, and dynamic OG images with thi...","zh":"使用 Nuxt SEO 实现 SEO 配置、robots.txt 和 sitemap.xml 生成、动态 OG 图像生成等功能","ja":"Nuxt SEO を使用して SEO 設定、robots.txt と sitemap.xml の生成、動的な OG 画像の生成などを実現","ko":"Nuxt SEO를 사용하여 SEO 설정, robots.txt 및 sitemap.xml 생성, 동적 OG 이미지 생성 등을 구현","es":"Aprende a configurar nuxt-seo para mejorar el posicionamiento de tu sitio web en los resultados de búsqueda con nuestra guía paso a paso","fr":"Découvrez comment configurer nuxt-seo pour améliorer le référencement de votre site web dans les résultats de recherche avec notre guide étape par étape","de":"Erfahren Sie, wie Sie nuxt-seo konfigurieren, um die Positionierung Ihrer Website in den Suchmaschinenergebnissen zu verbessern, mit unserem Schritt-für-Schr...","pt":"Aprenda a configurar o Nuxt SEO para melhorar a visibilidade dos seus projetos de Ferramentas de IA com recursos como SEO configuration e JSON-LD","ru":"Узнайте, как настроить Nuxt SEO для улучшения видимости ваших проектов ИИ Агентов с помощью функций như SEO конфигурация и JSON-LD","ar":"تعرف على كيفية إعداد Nuxt SEO لتحسين ظهور مشاريعك من الأدوات الذكية باستخدام ميزات مثل تكوين SEO و JSON-LD"},"definition":{"en":"nuxt-seo is a module for Nuxt.js that allows developers to configure and generate SEO-related files and settings, such as robots.txt and sitemap.xml.","zh":"Nuxt SEO 是一个用于优化 Nuxt 应用的 SEO 的工具","ja":"Nuxt SEO は、Nuxt アプ