INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thewebbeckons/eif-website/nuxt-seo', 'nuxt-seo', 'thewebbeckons', 'eif-website', 'community', 'nuxt-seo thewebbeckons eif-website community The nuxt-seo skill helps developers configure and optimize SEO settings for Nuxt.js applications, including site URL, name, and indexability. It benefits developers working with Nuxt.js. Nuxt SEO是一个用于优化Nuxt.js网站的模块，提供SEO配置、robots.txt和sitemap.xml生成等功能 Nuxt SEOはNuxt.jsのウェブサイトを最適化するためのモジュールです。SEO設定、robots.txt、sitemap.xmlの生成などを提供します Nuxt SEO는 Nuxt.js 웹사이트를 최적화하는 모듈입니다. SEO 구성, robots.txt 및 sitemap.xml 생성 등을 제공합니다 nuxt-seo es un módulo para configurar la optimización de motores de búsqueda en aplicaciones Nuxt.js nuxt-seo est un module pour configurer l''optimisation des moteurs de recherche dans les applications Nuxt.js nuxt-seo ist ein Modul zur Konfiguration der Suchmaschinenoptimierung in Nuxt.js-Anwendungen O Nuxt SEO é uma ferramenta para melhorar a otimização do site para mecanismos de busca. Configure recursos como SEO, robots.txt e sitemap.xml. Nuxt SEO - это инструмент для улучшения оптимизации сайта для поисковых систем. Настройте функции seperti SEO, robots.txt и sitemap.xml для ИИ Агентов. Nuxt SEO هو أداة لتحسين تحسين موقعك لآلات البحث. أعد تعيين ميزات مثل SEO و robots.txt و sitemap.xml لأدوات الذكاء الاصطناعي. how to use nuxt-seo nuxt-seo setup guide nuxt-seo vs prismicio nuxt-seo install nuxt-seo configuration what is nuxt-seo nuxt-seo alternative nuxt-seo optimization nuxt-seo tutorial nuxt-seo best practices Nuxt SEO Nuxt.js SEO 网站优化 搜索引擎排名 AIエージェント SEO配置 robots.txt sitemap.xml Generates robots.txt and sitemap.xml files for improved search engine crawling Supports dynamic OG image generation for enhanced social media sharing Provides JSON-LD structured data using schema.org for better search engine understanding Automates breadcrumbs and canonical URLs for improved site navigation and SEO Configures site URL, name, and indexability for optimal search engine indexing nuxt-seo is a module for Nuxt.js that provides SEO configuration and optimization capabilities, including robots.txt and sitemap.xml generation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ForkingAwesome/copium/tapestry', 'community', 'ForkingAwesome', 'copium', 'ForkingAwesome/copium', 'tapestry', 1, 0, 51, '2026-03-06T05:51:06Z', '2026-03-06T13:11:39.230Z', '0bb4acfa0c2ad92f33c490db326cd2edcea618ddf0a8b6c0250719344444b2f0', '{"id":"ForkingAwesome/copium/tapestry","name":"tapestry","description":{"en":"Tapestry enables social trading app development with React Native and Expo Router. It benefits developers building social features for mobile apps like Copium.","zh":"Tapestry是一种社会图谱集成技术，用于构建社交特性。它与React Native和Polymarket集成，实现预测和利润的共享","ja":"Tapestryはソーシャルグラフの統合技術で、ソーシャル特性を構築するために使用されます。React NativeとPolymarketを使用して予測と利益を共有する","ko":"Tapestry는 소셜 그래프 통합 기술로, 소셜 특성을 구축하는 데 사용됩니다. React Native와 Polymarket를 사용하여 예측 및 이익을 공유합니다","es":"Tapestry es una herramienta para predecir y ganar juntos en aplicaciones de trading social, como Copium, utilizando React Native y Expo Router.","fr":"Tapestry est un outil pour prédire et gagner ensemble dans les applications de trading social, comme Copium, en utilisant React Native et Expo Router.","de":"Tapestry ist ein Tool für soziale Trading-Apps wie Copium, um gemeinsam zu prognostizieren und zu gewinnen, mit React Native und Expo Router.","pt":"O Tapestry é uma ferramenta de integração social para aplicativos móveis, permitindo a previsão e lucro conjunto.","ru":"Tapestry — инструмент социальной интеграции для мобильных приложений, позволяющий предсказывать и получать прибыль вместе","ar":"Tapestry هو أداة تكامل اجتماعي لتطبيقات الجوال، تمكن من التنبؤ والربح المشترك"},"seo":{"title":{"en":"Tapestry: Social Graph Integration Setup Guide | AI Agent...","zh":"Tapestry集成指南：使用React Native构建社交特性","ja":"Tapestryのセットアップガイド：React NativeとPolymarketを使用したソーシャルトレーディ...","ko":"Tapestry 설정 가이드: React Native와 Polymarket를 사용한 소셜 트레이딩 앱","es":"Guía de configuración de Tapestry para aplicaciones móvil...","fr":"Guide d''intégration de Tapestry pour les applications de ...","de":"Einrichtungsleitfaden für Tapestry in sozialen Trading-Apps","pt":"Guia de Configuração do Tapestry para Aplicativos Móveis","ru":"Настройка Tapestry для Мобильных Приложений: ИИ Агенты","ar":"دليل إعداد Tapestry لأدوات المواقع الإلكترونية الذكية"},"description":{"en":"Unlock the power of social trading with Tapestry! Learn how to integrate social features into your React Native app and start profiting together","zh":"了解Tapestry如何与React Native和Polymarket集成，构建社交特性并实现预测和利润的共享","ja":"TapestryとReact Native、Polymarketを使用してソーシャルトレーディングアプリを構築し、予測と利益を共有する","ko":"Tapestry와 React Native, Polymarket를 사용하여 소셜 트레이딩 앱을 구축하고 예측 및 이익을 공유하는 방법","es":"Aprende a integrar Tapestry en tu aplicación móvil de trading social con React Native y Expo Router","fr":"Découvrez comment intégrer Tapestry dans votre application de trading social mobile avec React Native et Expo Router","de":"Erfahren Sie, wie Sie Tapestry in Ihre soziale Trading-App mit React Native und Expo Router integrieren","pt":"Aprenda a integrar o Tapestry em aplicativos móveis React Native com Expo Router e Privy para autenticação","ru":"Изучите возможности Tapestry для мобильных приложений с React Native, Expo Router и аутентификацией от Privy","ar":"اكتشف كيفية دمج Tapestry في تطبيقات الجوال باستخدام React Native و Expo Router و Privy للتحقق"},"definition":{"en":"Tapestry is a social graph integration tool for building social trading apps with React Native, Expo, and Polymarket","zh":"Tapestry是一种社会图谱集成技术，用于构建社交特性和实现预测和利润的共享","ja":"Tapestryはソーシャルグラフの統合技術で、ソーシャル特性を構築し、予測と利益を共有する","ko":"Tapestry는 소셜 그래프 통합 기술로, 소셜 특성을 구축하고 예측 및 이익을 공유하는 데 사용됩니다","es":"Tapestry es una tecnología de gráficos sociales para aplicaciones móviles de trading","fr":"Tapestry est une technologie de graphiques sociaux pour les applications mobiles de trading","de":"Tapestry ist eine soziale Grafiktechnologie für mobile Trading-Anwendungen","pt":"O que é Tapestry? Uma ferramenta de integração social para aplicativos móveis","ru":"Что такое Tapestry? Инструмент социальной интеграции для мобильных приложений","ar":"ما هو Tapestry؟ أداة تكامل اجتماعي لتطبيقات الجوال"},"features":{"en":["Integrates with React Native and Expo Router for file-based routing","Supports Privy Auth with OAuth and embedded Solana wallet","Utilizes Mobile Wallet Adapter (MWA) for secure transactions","Provides a wallet hook via `useUnifiedWallet()` from `@/hooks/use-wallet`","Enables social feature development with Polymarket"],"zh":["支持React Native和Expo Router","集成Privy和Mobile Wallet Adapter（MWA）","使用useUnifiedWallet()提供address、walletType、provider、isConnected和logout","支持Polymarket和社会图谱集成","实现预测和利润的共享"],"ja":["React NativeとExpo Routerのサポート","PrivyとMobile Wallet Adapter（MWA）の統合","useUnifiedWallet()を使用してaddress、walletType、provider、isConnected、logoutを提供","Polymarketとソーシャルグラフの統合","予測と利益の共有の実現"],"ko":["React Native와 Expo Router 지원","Privy와 Mobile Wallet Adapter（MWA）的 통합","useUnifiedWallet()를 사용하여 address、walletType、provider、isConnected、logout를 제공","Polymarket와 소셜 그래프의 통합","예측 및 이익의 공유의 구현"],"es":["Integración con React Native y Expo Router","Compatibilidad con Privy (OAuth + billetera Solana integrada) y Mobile Wallet Adapter (MWA)","Uso de hooks de billetera como `useUnifiedWallet()`","Soporte para autenticación y gestión de estado","Integración con Polymarket para funcionalidades de trading social","Gráficos sociales para predecir y ganar juntos"],"fr":["Intégration avec React Native et Expo Router","Compatibilité avec Privy (OAuth + portefeuille Solana intégré) et Mobile Wallet Adapter (MWA)","Utilisation de hooks de portefeuille tels que `useUnifiedWallet()`","Prise en charge de l''authentification et de la gestion d''état","Intégration avec Polymarket pour des fonctionnalités de trading social","Graphiques sociaux pour prédire et gagner ensemble"],"de":["Integration mit React Native und Expo Router","Kompatibilität mit Privy (OAuth + integrierter Solana-Wallet) und Mobile Wallet Adapter (MWA)","Verwendung von Wallet-Hooks wie `useUnifiedWallet()`","Unterstützung für Authentifizierung und Statusverwaltung","Integration mit Polymarket für soziale Trading-Funktionen","Soziale Grafiken für gemeinsame Prognosen und Gewinne"],"pt":["Integração com React Native e Expo Router","Autenticação com Privy e Mobile Wallet Adapter (MWA)","Uso do hook useUnifiedWallet() para gerenciar carteiras","Suporte a state e roteamento baseado em arquivos","Integração com Polymarket para previsão e lucro conjunto"],"ru":["Интеграция с React Native и Expo Router","Аутентификация с помощью Privy и Mobile Wallet Adapter (MWA)","Использование хука useUnifiedWallet() для управления кошельками","Поддержка состояния и маршрутизации на основе файлов","Интеграция с Polymarket для предсказания и получения прибыли вместе"],"ar":["التكامل مع React Native و Expo Router","التحقق باستخدام Privy و Mobile Wallet Adapter (MWA)","استخدام Hook useUnifiedWallet() لإدارة المحافظ","دعم الحالة و التوجيه المبني على الملفات","التكامل مع Polymarket للتنبؤ والربح المشترك"]},"keywords":{"en":["how to use tapestry","tapestry social graph integration","react native tapestry","tapestry alternative","tapestry setup guide","polymarket tapestry"],"zh":["Tapestry","React Native","Expo Router","Privy","Mobile Wallet Adapter","Polymarket","社会图谱集成","预测和利润的共享","AIエージェント","AI工具"],"ja":["Tapestry","React Native","Expo Router","Privy","Mobile Wallet Adapter","Polymarket","ソーシャルグラフの統合","予測と利益の共有","AIエージェント","AIツール"],"ko":["Tapestry","React Native","Expo Router","Privy","Mobile Wallet Adapter","Polymarket","소셜 그래프 통합","예측 및 이익의 공유","AI 에이전트","AI 툴"],"es":["Tapestry","aplicaciones móviles de trading social","React Native","Expo Router","Privy","Solana","Polymarket","gráficos sociales","predicción de trading","ganancias sociales"],"fr":["Tapestry","applications mobiles de trading social","React Native","Expo Router","Privy","Solana","Polymarket","graphiques sociaux","prédiction de trading","gains sociaux"],"de":["Tapestry","mobile Trading-Anwendungen","React Native","Expo Router","Privy","Solana","Polymarket","soziale Grafiken","Trading-Prognose","soziale Gewinne","AI-Tools","KI-Agents"],"pt":["Tapestry","React Native","Expo Router","Privy","Mobile Wallet Adapter","useUnifiedWallet","integração social","aplicativos móveis","autenticação"],"ru":["Tapestry","React Native","Expo Router","Privy","Mobile Wallet Adapter","useUnifiedWallet","социальная интеграция","мобильные приложения","аутентификация","ИИ Агенты"],"ar":["Tapestry","React Native","Expo Router","Privy","Mobile Wallet Adapter","useUnifiedWallet","التكامل الاجتماعي","تطبيقات الجوال","التحقق","أدوات الذكاء الاصطناعي"]}},"owner":"ForkingAwesome","repo":"copium","repoPath":"ForkingAwesome/copium","stars":1,"forks":0,"updatedAt":"2026-03-06T05:51:06Z","topics":[],"category":"community","skillMd":{"name":"tapestry","description":"Social graph protocol integration for Copium app using Tapestry API. Use when building social features - profiles, follows, content/posts, comments, likes, activity feeds, identity resolution, or trades. Covers all 41 Tapestry API endpoints.","bodyPreview":"# Tapestry Social Graph Integration\n\nYou are building social features for a React Native (Expo) mobile app called **Copium** - a social trading app using Tapestry and Polymarket.\n\n## Project Context\n\n- **Framework**: React Native with Expo Router (file-based routing)\n- **Auth**: Privy (OAuth + embedded Solana wallet) + Mobile Wallet Adapter (MWA)\n- **Wallet hook**: `useUnifiedWallet()` from `@/hooks/use-wallet` provides `address`, `walletType`, `provider`, `isConnected`, `logout`\n- **State**: Re","body":"# Tapestry Social Graph Integration\n\nYou are building social features for a React Native (Expo) mobile app called **Copium** - a social trading app using Tapestry and Polymarket.\n\n## Project Context\n\n- **Framework**: React Native with Expo Router (file-based routing)\n- **Auth**: Privy (OAuth + embedded Solana wallet) + Mobile Wallet Adapter (MWA)\n- **Wallet hook**: `useUnifiedWallet()` from `@/hooks/use-wallet` provides `address`, `walletType`, `provider`, `isConnected`, `logout`\n- **State**: React Query (`@tanstack/react-query`) for server state\n- **Styling**: StyleSheet with `#0a0a0a` bg, `#232323` borders, `PlusJakartaSans` font\n- **API Key**: `process.env.TAPESTRY_API_KEY` (server-side only, stored in `.env.local`)\n- **Base URL**: `https://api.usetapestry.dev/api/v1`\n\n## API Authentication\n\nAll endpoints require `apiKey` as a query parameter:\n```\nGET /profiles/{id}?apiKey=YOUR_API_KEY\n```\n\nThe API key is in `.env.local` as `TAPESTRY_API_KEY`. Since this is a React Native app (no server-side routes), call the Tapestry API directly from a utility module, keeping the API key secure via `process.env.TAPESTRY_API_KEY` (bundled at build time but not exposed to web).\n\n## Execution Methods (for write operations)\n\n| Method | Speed | Use When |\n|--------|-------|----------|\n| `FAST_UNCONFIRMED` | <1s | Default. Returns after graph DB write, on-chain tx in background |\n| `QUICK_SIGNATURE` | ~5s | Need tx signature but don''t need confirmation |\n| `CONFIRMED_AND_PARSED` | ~15s | Need full on-chain confirmation |\n\n## API Client Pattern\n\nCreate API calls in `lib/tapestry/` directory. Use this pattern:\n\n```typescript\n// lib/tapestry/client.ts\nconst TAPESTRY_BASE = ''https://api.usetapestry.dev/api/v1'';\nconst API_KEY = process.env.TAPESTRY_API_KEY!;\n\nexport async function tapestryFetch<T>(\n  endpoint: string,\n  options?: { method?: string; body?: any; params?: Record<string, string> }\n): Promise<T> {\n  const { method = ''GET'', body, params = {} } = options ?? {};\n  const url = new URL(`${TAPESTRY_BASE}${endpoint}`);\n  url.searchParams.set(''apiKey'', API_KEY);\n  Object.entries(params).forEach(([k, v]) => v && url.searchParams.set(k, v));\n\n  const res = await fetch(url.toString(), {\n    method,\n    headers: body ? { ''Content-Type'': ''application/json'' } : undefined,\n    body: body ? JSON.stringify(body) : undefined,\n  });\n\n  if (!res.ok) {\n    const err = await res.json().catch(() => ({}));\n    throw new Error(err.error || `Tapestry API error: ${res.status}`);\n  }\n  return res.json();\n}\n```\n\n## React Hook Pattern\n\n```typescript\n// hooks/use-tapestry-profile.ts\nimport { useQuery, useMutation, useQueryClient } from ''@tanstack/react-query'';\nimport { tapestryFetch } from ''@/lib/tapestry/client'';\n\nexport function useTapestryProfile(username: string) {\n  return useQuery({\n    queryKey: [''tapestry-profile'', username],\n    queryFn: () => tapestryFetch<ProfileResponse>(`/profiles/${username}`),\n    enabled: !!username,\n  });\n}\n```\n\n## All Endpoints Reference\n\nFor detailed endpoint specs, see [reference.md](reference.md).\n\n### Quick Endpoint Map\n\n**Profiles**\n- `GET /profiles/` - List/search profiles (by wallet, phone, twitter, email)\n- `POST /profiles/findOrCreate` - Find or create profile\n- `GET /profiles/{id}` - Get profile by ID or username\n- `PUT /profiles/{id}` - Update profile\n- `GET /profiles/{id}/followers` - Get followers\n- `GET /profiles/{id}/following` - Get following\n- `GET /profiles/{id}/followers/global` - Cross-namespace followers\n- `GET /profiles/{id}/following/global` - Cross-namespace following\n- `GET /profiles/{id}/following-who-follow` - Mutual connections\n- `GET /profiles/{id}/wallets` - Get linked wallets\n- `PATCH /profiles/{id}/wallets` - Link wallets\n- `DELETE /profiles/{id}/wallets` - Unlink wallets\n- `PATCH /profiles/{id}/contacts` - Link contacts\n- `DELETE /profiles/{id}/contacts` - Unlink contacts\n- `POST /profiles/{id}/notification` - Send notification\n- `GET /profiles/{id}/referrals` - Get referral tree\n- `GET /profiles/{id}/suggested-profiles` - Suggested follows\n- `GET /profiles/suggested/{identifier}` - Suggestions by wallet/contact\n- `GET /profiles/suggested/{identifier}/global` - Cross-namespace suggestions\n- `GET /profiles/token-owners/{tokenAddress}` - Token holder profiles\n- `GET /search/profiles` - Search profiles by text\n\n**Social Graph (Followers)**\n- `POST /followers/add` - Follow `{ startId, endId }`\n- `POST /followers/remove` - Unfollow `{ startId, endId }`\n- `GET /followers/state` - Check follow state `?startId=&endId=`\n\n**Content (Posts)**\n- `GET /contents/` - List content (with filters, ordering, pagination)\n- `GET /contents/aggregation` - Aggregate content properties\n- `POST /contents/batch/read` - Batch get by IDs (max 20)\n- `POST /contents/findOrCreate` - Create content `{ id, profileId, properties: [{key,value}] }`\n- `GET /contents/{id}` - Get content details\n- `PUT /contents/{id}` - Update content properties\n- `DELETE /contents/{id}` - Delete content\n\n**Comments**\n- `GET /comments/` - List comments `?contentId=&profileId=&targetProfileId=`\n- `POST /comments/` - Create comment `{ profileId, text, contentId?, commentId?, targetProfileId? }`\n- `POST /comments/batch/read` - Batch get (max 20)\n- `GET /comments/{id}` - Get comment with replies\n- `PUT /comments/{id}` - Update comment\n- `DELETE /comments/{id}` - Delete comment\n- `GET /comments/{id}/replies` - Get replies\n\n**Likes**\n- `GET /likes/{nodeId}` - Get profiles who liked a node\n- `POST /likes/{nodeId}` - Like `{ startId }`\n- `DELETE /likes/{nodeId}` - Unlike `{ startId }`\n\n**Activity Feeds**\n- `GET /activity/feed` - User activity feed `?username=`\n- `GET /activity/global` - Global activity feed\n- `GET /activity/swap` - Swap activity from followed wallets `?username=&tokenAddress=`\n\n**Identities**\n- `GET /identities/{id}` - Resolve wallets/contacts from ID\n- `GET /identities/{id}/profiles` - Find profiles across namespaces\n\n**Trades**\n- `POST /trades/` - Log a trade\n- `GET /trades/all-trades` - Get all trades in time period\n- `GET /trades/fetch-transaction-history` - Wallet tx history\n\n**Wallets**\n- `POST /wallets/{address}/connect` - Connect two wallets\n- `GET /wallets/{address}/socialCounts` - Social counts by wallet\n\n## Key Integration Points for Copium\n\n### 1. Profile Creation (on signup/login)\nAfter wallet connection + X login, call `findOrCreate`:\n```typescript\nawait tapestryFetch(''/profiles/findOrCreate'', {\n  method: ''POST'',\n  body: {\n    username: twitterHandle, // from Privy OAuth\n    walletAddress: address,  // from useUnifiedWallet\n    blockchain: ''SOLANA'',\n    image: twitterProfileImage,\n    bio: twitterBio,\n    contact: { id: twitterHandle, type: ''TWITTER'' },\n  },\n});\n```\n\n### 2. Follow/Unfollow\n```typescript\nawait tapestryFetch(''/followers/add'', {\n  method: ''POST'',\n  body: { startId: myProfileId, endId: targetProfileId },\n});\n```\n\n### 3. Create a Post (Content)\n```typescript\nawait tapestryFetch(''/contents/findOrCreate'', {\n  method: ''POST'',\n  body: {\n    id: `post-${Date.now()}`,\n    profileId: myProfileId,\n    properties: [\n      { key: ''text'', value: ''My post content'' },\n      { key: ''type'', value: ''trade_call'' },\n    ],\n  },\n});\n```\n\n### 4. Like Content\n```typescript\nawait tapestryFetch(`/likes/${contentId}`, {\n  method: ''POST'',\n  body: { startId: myProfileId },\n});\n```\n\n### 5. Comment on Content\n```typescript\nawait tapestryFetch(''/comments/'', {\n  method: ''POST'',\n  body: {\n    profileId: myProfileId,\n    contentId: contentId,\n    text: ''Great trade!'',\n  },\n});\n```\n\n### 6. Activity Feed\n```typescript\nconst feed = await tapestryFetch(''/activity/feed'', {\n  params: { username: myUsername },\n});\n```\n\n### 7. Search Users\n```typescript\nconst results = await tapestryFetch(''/search/profiles'', {\n  params: { query: searchText },\n});\n```\n\n### 8. Polymarket Integration Pattern\nStore Polymarket-related data as content properties:\n```typescript\nawait tapestryFetch(''/contents/findOrCreate'', {\n  method: ''POST'',\n  body: {\n    id: `prediction-${marketId}-${profileId}`,\n    profileId: myProfileId,\n    properties: [\n      { key: ''type'', value: ''prediction'' },\n      { key: ''marketId'', value: polymarketConditionId },\n      { key: ''position'', value: ''YES'' },\n      { key: ''amount'', value: 50 },\n      { key: ''odds'', value: 0.65 },\n    ],\n  },\n});\n```\n\n## Response Types\n\n```typescript\ninterface TapestryProfile {\n  id: string;\n  namespace: string;\n  created_at: number;\n  username: string;\n  bio: string | null;\n  image: string | null;\n}\n\ninterface ProfileResponse {\n  profile: TapestryProfile;\n  walletAddress: string;\n  socialCounts: { followers: number; following: number };\n  namespace: { name: string | null; readableName: string | null };\n}\n\ninterface ContentResponse {\n  id: string;\n  created_at: number;\n  properties: Record<string, any>;\n}\n\ninterface CommentResponse {\n  comment: { id: string; created_at: number; text: string };\n  author: TapestryProfile;\n  socialCounts: { likeCount: number };\n  requestingProfileSocialInfo?: { hasLiked: boolean };\n}\n\ninterface ActivityItem {\n  type: ''following'' | ''new_content'' | ''like'' | ''comment'' | ''new_follower'';\n  actor_id: string;\n  actor_username: string;\n  target_id?: string;\n  target_username?: string;\n  timestamp: number;\n  activity: string;\n}\n\ninterface PaginatedResponse<T> {\n  page: number;\n  pageSize: number;\n  totalCount: number;\n  data?: T[];\n  profiles?: T[];\n  activities?: T[];\n}\n```\n\n## File Structure Convention\n\n```\nlib/tapestry/\n  client.ts          # Base fetch wrapper\n  profiles.ts        # Profile API functions\n  social.ts          # Follow/unfollow/like functions\n  content.ts         # Content/posts CRUD\n  comments.ts        # Comments CRUD\n  activity.ts        # Activity feed functions\n  types.ts           # TypeScript interfaces\n\nhooks/\n  use-tapestry-profile.ts\n  use-tapestry-feed.ts\n  use-tapestry-social.ts\n  use-tapestry-content.ts\n```\n\nWhen implementing features with `$ARGUMENTS`, refer to [reference.md](reference.md) for full endpoint details.\n"},"lastSynced":"2026-03-06T13:11:39.230Z","agentAnalysis":{"suitability":{"en":"Ideal for Mobile App Agents focused on social feature development with React Native and Expo Router","zh":"适用于专注于使用 React Native 和 Expo Router 开发社交功能的移动应用代理","ja":"React Native と Expo Router を使用したソーシャル機能開発に焦点を当てたモバイル アプリ エージェントに適しています","ko":"React Native 및 Expo Router를 사용하여 소셜 기능 개발에 중점을 둔 모바일 앱 에이전트에 적합합니다","es":"Ideal para Agentes de Aplicaciones Móviles centrados en el desarrollo de características sociales con React Native y Expo Router","fr":"Idéal pour les Agents d''Applications Mobiles axés sur le développement de fonctionnalités sociales avec React Native et Expo Router","de":"Ideal für Mobile App-Agents, die auf die Entwicklung von sozialen Funktionen mit React Native und Expo Router ausgerichtet sind","pt":"Ideal para Agentes de Aplicativos Móveis focados no desenvolvimento de recursos sociais com React Native e Expo Router","ru":"Идеально подходит для агентов мобильных приложений, ориентированных на разработку социальных функций с React Native и Expo Router","ar":"مثالي لعميل تطبيقات الجوال الذين يركزون على تطوير الميزات الاجتماعية مع React Native و Expo Router"},"recommendation":{"en":"Empowers agents to build social trading apps with Tapestry, integrating social graphs and leveraging Privy for OAuth and Solana wallet management, while utilizing Expo Router for file-based routing and Mobile Wallet Adapter (MWA) for seamless wallet interactions","zh":"赋予代理构建集成社会图表和利用 Privy 进行 OAuth 和 Solana 钱包管理的社交交易应用的能力，同时使用 Expo Router 进行基于文件的路由和 Mobile Wallet Adapter (MWA) 进行无缝的钱包交互","ja":"エージェントが、Tapestry を使用してソーシャル グラフを統合し、Privy を使用して OAuth と Solana ウォレット管理を行い、Expo Router を使用してファイルベースのルーティングを行い、Mobile Wallet Adapter (MWA) を使用してシームレスなウォレットのやり取りを行うソーシャル トレーディング アプリを構築する能力を提供する","ko":"에이전트가 Tapestry를 사용하여 소셜 그래프를 통합하고 Privy를 사용하여 OAuth 및 Solana 월レット 관리를 수행하며 Expo Router를 사용하여 파일 기반 라우팅을 수행하고 Mobile Wallet Adapter(MWA)를 사용하여 무차별적인 월レット 상호 작용을 수행하는 소셜 트레이딩 앱을 구축할 수 있는 능력을 제공합니다","es":"Habilita a los agentes a crear aplicaciones de trading social con Tapestry, integrando gráficos sociales y aprovechando Privy para OAuth y gestión de la billetera Solana, mientras utiliza Expo Router para enrutamiento basado en archivos y Mobile Wallet Adapter (MWA) para interacciones de billetera sin problemas","fr":"Permet aux agents de créer des applications de trading social avec Tapestry, en intégrant des graphiques sociaux et en exploitant Privy pour OAuth et la gestion du portefeuille Solana, tout en utilisant Expo Router pour le routage basé sur les fichiers et Mobile Wallet Adapter (MWA) pour des interactions de portefeuille sans problème","de":"Ermöglicht es Agenten, soziale Trading-Apps mit Tapestry zu erstellen, indem soziale Grafiken integriert und Privy für OAuth und Solana-Wallet-Verwaltung genutzt wird, während Expo Router für dateibasiertes Routing und Mobile Wallet Adapter (MWA) für nahtlose Wallet-Interaktionen verwendet wird","pt":"Habilita os agentes a construir aplicativos de negociação social com Tapestry, integrando gráficos sociais e aproveitando Privy para OAuth e gerenciamento de carteira Solana, ao mesmo tempo em que utiliza Expo Router para roteamento baseado em arquivos e Mobile Wallet Adapter (MWA) para interações de carteira sem problemas","ru":"Наделяет агентов возможностью создавать социальные торговые приложения с помощью Tapestry, интегрируя социальные графики и используя Privy для OAuth и управления кошельком Solana, а также использует Expo Router для маршрутизации на основе файлов и Mobile Wallet Adapter (MWA) для бесшовного взаимодействия с кошельком","ar":"يمنح الوكلاء khảية بناء تطبيقات التداول الاجتماعي مع Tapestry، وتكامل الرسوم البيانية الاجتماعية وتفعيل Privy لOAuth وإدارة المحفظة Solana، وفي الوقت نفسه استخدام Expo Router للتعيين القائم على الملفات و Mobile Wallet Adapter (MWA) للتفاعلات السلسة للمحفظة"},"useCases":{"en":["Developing social features for mobile apps like Copium","Integrating Tapestry with Polymarket for social trading functionality","Implementing authentication with Privy and wallet management using Mobile Wallet Adapter (MWA)"],"zh":["为移动应用程序（如 Copium）开发社交功能","将 Tapestry 与 Polymarket 集成以实现社交交易功能","使用 Privy 和 Mobile Wallet Adapter (MWA) 实现身份验证和钱包管理"],"ja":["Copium のようなモバイル アプリケーション用のソーシャル機能を開発する","Tapestry を Polymarket と統合してソーシャル トレーディング機能を実現する","Privy と Mobile Wallet Adapter (MWA) を使用して認証とウォレット管理を実装する"],"ko":["Copium과 같은 모바일 애플리케이션을 위한 소셜 기능 개발","Tapestry를 Polymarket와 통합하여 소셜 트레이딩 기능을 구현하는 것","Privy 및 Mobile Wallet Adapter(MWA)를 사용하여 인증 및 월렛 관리를 구현하는 것"],"es":["Desarrollar características sociales para aplicaciones móviles como Copium","Integrar Tapestry con Polymarket para funcionalidad de trading social","Implementar autenticación con Privy y gestión de billetera con Mobile Wallet Adapter (MWA)"],"fr":["Développer des fonctionnalités sociales pour des applications mobiles comme Copium","Intégrer Tapestry avec Polymarket pour la fonctionnalité de trading social","Mettre en œuvre l''authentification avec Privy et la gestion du portefeuille avec Mobile Wallet Adapter (MWA)"],"de":["Soziale Funktionen für mobile Apps wie Copium entwickeln","Tapestry mit Polymarket für soziale Trading-Funktionalität integrieren","Authentifizierung mit Privy und Wallet-Verwaltung mit Mobile Wallet Adapter (MWA) implementieren"],"pt":["Desenvolver recursos sociais para aplicativos móveis como Copium","Integrar Tapestry com Polymarket para funcionalidade de negociação social","Implementar autenticação com Privy e gerenciamento de carteira usando Mobile Wallet Adapter (MWA)"],"ru":["Разработка социальных функций для мобильных приложений, таких как Copium","Интеграция Tapestry с Polymarket для социальной торговой функциональности","Реализация аутентификации с помощью Privy и управления кошельком с помощью Mobile Wallet Adapter (MWA)"],"ar":["تطوير الميزات الاجتماعية لتطبيقات الجوال مثل Copium","تكامل Tapestry مع Polymarket للوظائف الاجتماعية للتداول","تنفيذ المصادقة مع Privy وإدارة المحفظة باستخدام Mobile Wallet Adapter (MWA)"]},"limitations":{"en":["Requires React Native and Expo Router setup","Dependent on Privy for authentication and Solana wallet integration","Limited to mobile app development"],"zh":["需要 React Native 和 Expo Router 设置","依赖 Privy 进行身份验证和 Solana 钱包集成","仅限移动应用程序开发"],"ja":["React Native と Expo Router の設定が必要","Privy への依存による認証と Solana ウォレット統合","モバイル アプリケーション開発のみ"],"ko":["React Native 및 Expo Router 설정이 필요합니다","Privy에 의존하여 인증 및 Solana 월렛 통합을 수행","모바일 애플리케이션 개발만 해당"],"es":["Requiere configuración de React Native y Expo Router","Depende de Privy para la autenticación y la integración de la billetera Solana","Limitado al desarrollo de aplicaciones móviles"],"fr":["Nécessite la configuration de React Native et Expo Router","Dépend de Privy pour l''authentification et l''intégration du portefeuille Solana","Limité au développement d''applications mobiles"],"de":["Benötigt React Native- und Expo Router-Setup","Hängt von Privy für Authentifizierung und Solana-Wallet-Integration ab","Begrenzt auf die Entwicklung von Mobile Apps"],"pt":["Requer configuração do React Native e Expo Router","Depende de Privy para autenticação e integração da carteira Solana","Limitado ao desenvolvimento de aplicativos móveis"],"ru":["Требует настройки React Native и Expo Router","Зависит от Privy для аутентификации и интеграции кошелька Solana","Ограничен разработкой мобильных приложений"],"ar":["يتطلب إعداد React Native و Expo Router","يعتمد على Privy للمصادقة وتكامل المحفظة Solana","محدود بتطوير تطبيقات الجوال"]},"version":4},"contentHash":"0bb4acfa0c2ad92f33c490db326cd2edcea618ddf0a8b6c0250719344444b2f0","qualityScore":51}');
