INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ForkingAwesome/copium/tapestry', 'tapestry', 'ForkingAwesome', 'copium', 'community', 'tapestry ForkingAwesome copium community Tapestry enables social trading app development with React Native and Expo Router. It benefits developers building social features for mobile apps like Copium. Tapestry是一种社会图谱集成技术，用于构建社交特性。它与React Native和Polymarket集成，实现预测和利润的共享 Tapestryはソーシャルグラフの統合技術で、ソーシャル特性を構築するために使用されます。React NativeとPolymarketを使用して予測と利益を共有する Tapestry는 소셜 그래프 통합 기술로, 소셜 특성을 구축하는 데 사용됩니다. React Native와 Polymarket를 사용하여 예측 및 이익을 공유합니다 Tapestry es una herramienta para predecir y ganar juntos en aplicaciones de trading social, como Copium, utilizando React Native y Expo Router. Tapestry est un outil pour prédire et gagner ensemble dans les applications de trading social, comme Copium, en utilisant React Native et Expo Router. Tapestry ist ein Tool für soziale Trading-Apps wie Copium, um gemeinsam zu prognostizieren und zu gewinnen, mit React Native und Expo Router. O Tapestry é uma ferramenta de integração social para aplicativos móveis, permitindo a previsão e lucro conjunto. Tapestry — инструмент социальной интеграции для мобильных приложений, позволяющий предсказывать и получать прибыль вместе Tapestry هو أداة تكامل اجتماعي لتطبيقات الجوال، تمكن من التنبؤ والربح المشترك how to use tapestry tapestry social graph integration react native tapestry tapestry alternative tapestry setup guide polymarket tapestry Tapestry React Native Expo Router Privy Mobile Wallet Adapter Polymarket 社会图谱集成 预测和利润的共享 AIエージェント AI工具 Integrates with React Native and Expo Router for file-based routing Supports Privy Auth with OAuth and embedded Solana wallet Utilizes Mobile Wallet Adapter (MWA) for secure transactions Provides a wallet hook via `useUnifiedWallet()` from `@/hooks/use-wallet` Enables social feature development with Polymarket Tapestry is a social graph integration tool for building social trading apps with React Native, Expo, and Polymarket');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OmuNaman/blog-automation/research-topic', 'community', 'OmuNaman', 'blog-automation', 'OmuNaman/blog-automation', 'research-topic', 0, 0, 51, '2026-02-22T15:25:34Z', '2026-03-07T03:39:57.843Z', 'aaa4dc3f0d2e022c6ec72ec2e41eea70d62b6960f49cc28ee6fff5e3a9f19be7', '{"id":"OmuNaman/blog-automation/research-topic","name":"research-topic","description":{"en":"The research-topic skill generates deeply pedagogical technical blog posts using automated pipelines. It benefits developers and technical writers by providing high-quality content","zh":"使用AIエージェント创建深度技术博客文章，包含原创研究论文、官方文档和技术博客文章等","ja":"AIエージェントを使用して、原著研究論文、公式ドキュメント、技術ブログ記事などを含む深い技術ブログ記事を作成します","ko":"AI 에이전트를 사용하여 원본 연구 논문, 공식 문서 및 기술 블로그 게시물 등을 포함한 깊은 기술 블로그 게시물 생성","es":"La habilidad de investigación automatiza la creación de artículos técnicos con 25-35 diagramas de PaperBanana, utilizando fuentes de alta calidad como arXiv y GitHub","fr":"La compétence de recherche automatise la création d''articles techniques avec 25-35 diagrammes PaperBanana, en utilisant des sources de haute qualité telles que arXiv et GitHub","de":"Die Forschungsfähigkeit automatisiert die Erstellung von technischen Artikeln mit 25-35 PaperBanana-Diagrammen, unter Verwendung von hochwertigen Quellen wie arXiv und GitHub","pt":"O research-topic é uma habilidade que cria artigos técnicos profundos com 25-35 diagramas PaperBanana por artigo, utilizando uma pipeline automatizada","ru":"Исследование-тема - это навык, который создает глубокие технические статьи с 25-35 диаграммами PaperBanana на статью, используя автоматизированную pipeline и ИИ Агенты","ar":"برنامج research-topic هو مهارة تُنشئ مقالات تقنية متعمقة مع 25-35 رسمًا PaperBanana لكل مقال، باستخدام خط أنابيب آلي"},"seo":{"title":{"en":"research-topic: Automated Technical Blog Post Generation ...","zh":"AIエージェント研究主题设置指南","ja":"AIエージェントを使用した研究トピックの最適化","ko":"AI 에이전트를 활용한 연구 주제 설정 가이드","es":"Guía de configuración para el tema de investigación con P...","fr":"Guide de démarrage pour le sujet de recherche avec PaperB...","de":"Einrichtungsleitfaden für das Forschungsthema mit PaperBa...","pt":"Guia de Configuração do research-topic: Crie Artigos Técn...","ru":"Настройка исследования-темы: Создание технических статей ...","ar":"دليل الإعداد لبرنامج research-topic: إنشاء مقالات تقنية م..."},"description":{"en":"Discover how research-topic AI skill automates technical blog posts with 25-35 PaperBanana diagrams. Learn how to leverage Claude Code skills for in-depth re...","zh":"利用AIエージェント创建深度技术博客文章，包含25-35个PaperBanana图表，每篇文章都经过深入研究","ja":"AIエージェントを使用して、PaperBanana図25-35個を含む深い技術ブログ記事を作成します","ko":"AI 에이전트를 사용하여 PaperBanana 다이어그램 25-35개가 포함된 깊은 기술 블로그 게시물 생성","es":"Aprende a crear artículos técnicos profundos con diagramas de PaperBanana utilizando nuestra herramienta de investigación automatizada","fr":"Découvrez comment créer des articles techniques approfondis avec des diagrammes PaperBanana à l''aide de notre outil de recherche automatisé","de":"Erfahren Sie, wie Sie tiefe technische Artikel mit PaperBanana-Diagrammen erstellen können, indem Sie unsere automatisierte Forschungsfunktion verwenden","pt":"Aprenda a configurar o research-topic para criar artigos técnicos profundos com diagramas PaperBanana e melhore sua experiência de desenvolvimento","ru":"Узнайте, как настроить исследование-тему для создания глубоких технических статей с диаграммами PaperBanana и ИИ Агентами","ar":"تعرف على كيفية إعداد برنامج research-topic لإنشاء مقالات تقنية متعمقة مع رسومات PaperBanana"},"definition":{"en":"research-topic is an AI agent skill that automates the creation of technical blog posts with detailed diagrams and references","zh":"研究主题AIエージェント是一种自动化的技术博客文章创建工具，使用Claude Code技能","ja":"研究トピックAIエージェントは、Claude Codeスキルを使用する自動化された技術ブログ記事作成ツールです","ko":"연구 주제 AI 에이전트는 Claude Code 스킬을 사용하는 자동화된 기술 블로그 게시물 생성 도구입니