INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OmuNaman/blog-automation/research-topic', 'research-topic', 'OmuNaman', 'blog-automation', 'community', 'research-topic OmuNaman blog-automation community The research-topic skill generates deeply pedagogical technical blog posts using automated pipelines. It benefits developers and technical writers by providing high-quality content 使用AIエージェント创建深度技术博客文章，包含原创研究论文、官方文档和技术博客文章等 AIエージェントを使用して、原著研究論文、公式ドキュメント、技術ブログ記事などを含む深い技術ブログ記事を作成します AI 에이전트를 사용하여 원본 연구 논문, 공식 문서 및 기술 블로그 게시물 등을 포함한 깊은 기술 블로그 게시물 생성 La habilidad de investigación automatiza la creación de artículos técnicos con 25-35 diagramas de PaperBanana, utilizando fuentes de alta calidad como arXiv y GitHub La compétence de recherche automatise la création d''articles techniques avec 25-35 diagrammes PaperBanana, en utilisant des sources de haute qualité telles que arXiv et GitHub Die Forschungsfähigkeit automatisiert die Erstellung von technischen Artikeln mit 25-35 PaperBanana-Diagrammen, unter Verwendung von hochwertigen Quellen wie arXiv und GitHub O research-topic é uma habilidade que cria artigos técnicos profundos com 25-35 diagramas PaperBanana por artigo, utilizando uma pipeline automatizada Исследование-тема - это навык, который создает глубокие технические статьи с 25-35 диаграммами PaperBanana на статью, используя автоматизированную pipeline и ИИ Агенты برنامج research-topic هو مهارة تُنشئ مقالات تقنية متعمقة مع 25-35 رسمًا PaperBanana لكل مقال، باستخدام خط أنابيب آلي how to use research-topic what is research-topic research-topic alternative research-topic vs Claude Code research-topic install guide research-topic setup for AI agents automated technical blog post generation PaperBanana diagram creation AIエージェント 研究主题 技术博客文章 PaperBanana图表 Claude Code 自动化创建 原创研究论文 官方文档 GitHub实现 Conducts broad searches across arXiv, conference proceedings, and official documentation Performs deep reads of promising sources, including video transcripts and GitHub implementations Generates technical blog posts with 25-35 PaperBanana diagrams per article Utilizes Claude Code skills for automated pipeline creation References high-quality sources, including original research papers and well-written technical blog posts research-topic is an AI agent skill that automates the creation of technical blog posts with detailed diagrams and references');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('BIGSHOL/ijw-Calander/generate-import-modal', 'community', 'BIGSHOL', 'ijw-Calander', 'BIGSHOL/ijw-Calander', 'generate-import-modal', 0, 0, 51, '2026-03-06T05:59:19Z', '2026-03-07T03:40:52.104Z', '76c03fbacabe5912a54f1a276ce81e8876abe6513169a411a2027a56af789b4c', '{"id":"BIGSHOL/ijw-Calander/generate-import-modal","name":"generate-import-modal","description":{"en":"The generate-import-modal skill automates the creation of Excel import modals, generating modal components, parser functions, and TypeScript interfaces. It benefits developers by simplifying the import process.","zh":"generate-import-modal 是一个自动创建 Excel 导入模态的工具，支持 useExcelImport 钩子和 xlsx 解析","ja":"generate-import-modal は Excel インポートモーダルを自動生成するツールで、useExcelImport フックと xlsx 解析をサポート","ko":"generate-import-modal은 Excel 가져오기 모달을 자동 생성하는 도구로 useExcelImport 훅과 xlsx 파싱을 지원","es":"El skill generate-import-modal permite generar automáticamente un modal de importación de Excel personalizado según el patrón estándar del proyecto","fr":"Le skill generate-import-modal permet de générer automatiquement un modal d''importation Excel personnalisé selon le modèle standard du projet","de":"Der Skill generate-import-modal ermöglicht die automatische Generierung eines benutzerdefinierten Excel-Import-Modals nach dem Projektstandardmuster","pt":"O generate-import-modal é uma ferramenta que gera modais de importação de Excel personalizados com React e TypeScript, incluindo hooks e parsers.","ru":"generate-import-modal - это инструмент, который генерирует индивидуальные модали импорта Excel с использованием React и TypeScript, включая хуки и парсеры.","ar":"generate-import-modal هو أداة ت generar نماذج استيراد Excel مخصصة باستخدام React و TypeScript، بما في ذلك hooks و parsers."},"seo":{"title":{"en":"generate-import-modal: Automated Excel Import Modal Gener...","zh":"generate-import-modal Setup Guide - AI工具","ja":"generate-import-modal セットアップガイド - AIエージェント","ko":"generate-import-modal 설정 가이드 - AI 에이전트","es":"Generador de modal de importación de Excel: Guía de confi...","fr":"Générateur de modal d''importation Excel: Meilleures prati...","de":"Excel-Import-Modal-Generator: Einrichtungsanleitung","pt":"Guia de Configuração do generate-import-modal para Ferram...","ru":"Настройка generate-import-modal для ИИ Агентов","ar":"دليل إعداد generate-import-modal لأدوات الذكاء الاصطناعي"},"description":{"en":"Streamline your workflow with generate-import-modal, a skill that automates Excel import modal creation. Learn how to set it up and integrate it with your pr...","zh":"使用 generate-import-modal 自动创建 Excel 导入模态，支持 useExcelImport 钩子、xlsx 解析和 TypeScript 类型定义","ja":"generate-import-modal を使用して Excel インポートモーダルを自動生成し、useExcelImport フック、xlsx 解析、TypeScript 型定義をサポート","ko":"generate-import-modal을 사용하여 Excel 가져오기 모달을 자동 생성하고 useExcelImport 훅, xlsx 파싱, TypeScript 인터페이스를 지원","es":"Descubre cómo generar un modal de importación de Excel personalizado con el skill generate-import-modal y mejorar la experiencia del usuario","fr":"Découvrez comment générer un modal d''importation Excel sur mesure avec le skill generate-import-modal et améliorer l''expérience utilisateur","de":"Erfahren Sie, wie Sie ein benutzerdefiniertes Excel-Import-Modal mit dem Skill generate-import-modal erstellen und die Benutzererfahrung verbessern","pt":"Aprenda a configurar o generate-import-modal para criar modais de importação de Excel personalizados com React e TypeScript","ru":"Узнайте, как настроить generate-import-modal для создания индивидуальных модалей импорта Excel с использованием React и TypeScript","ar":"تعرف على كيفية إعداد generate-import-modal لإنشاء نماذج استيراد Excel مخصصة باستخدام React و TypeScript"},"definition":{"en":"generate-import-modal is a skill that automatically generates Excel import modals based on project standards, including modal components, parser functions, and TypeScript interfaces.","zh":"generate-import-modal 是一个用于自动创建 Excel 导入模态的 AI 工具","ja":"generate-import-modal は Excel インポートモーダルを自動生成する AI エージェント","ko":"generate-import-modal은 Excel 가져오기 모달을 자동 생성하는 AI 에이전트","es":"El generate-import-modal es un skill que genera automáticamente un modal de importación de Excel según el patrón estándar del proyecto","fr":"Le generate-import-modal est un skill qui génère automatiquement un modal d''importation Excel selon le modèle standard du projet","de":"Der generate-import-modal ist ein Skill, der automatisch ein Excel-Import-Modal nach dem Projektstandardmuster generiert","pt":"O generate-import-modal é uma ferramenta de código aberto que gera modais de importação de Excel personalizados","ru":"generate-import-modal - это открытый инструмент, который генерирует индивидуальные модали импорта Excel","ar":"generate-import-modal هو أداة مفتوحة المصدر لإنشاء نماذج استيراد Excel مخصصة"},"features":{"en":["Generates modal components using the useExcelImport hook","Creates parser functions for xlsx field mapping and normalization","Defines TypeScript interfaces for parsed rows","Provides guidance on integrating with parent components","Supports refactoring existing import modals to use the useExcelImport hook"],"zh":["支持 useExcelImport 钩子","自动创建 Excel 导入模态","支持 xlsx 解析","支持 TypeScript 类型定义","提供父组件联动指导","支持模态打开/关闭和 onImport 回调"],"ja":["useExcelImport フックをサポート","Excel インポートモーダルを自動生成","xlsx 解析をサポート","TypeScript 型定義をサポート","親コンポーネント連動ガイドを提供","モーダルを開く/閉じると onImport コールバックをサポート"],"ko":["useExcelImport 훅 지원","Excel 가져오기 모달 자동 생성","xlsx 파싱 지원","TypeScript 인터페이스 지원","부모 컴포넌트 연동 안내 제공","모달 열기/닫기 및 onImport 콜백 지원"],"es":["Generación automática de un modal de importación de Excel personalizado","Uso de la biblioteca xlsx para el mapeo y la normalización de campos","Definición de tipos para los datos parseados utilizando TypeScript","Integración con el componente padre para la apertura y cierre del modal","Compatibilidad con el hook useExcelImport para la gestión de estados y la ejecución de la importación"],"fr":["Génération automatique d''un modal d''importation Excel personnalisé","Utilisation de la bibliothèque xlsx pour le mappage et la normalisation des champs","Définition de types pour les données parsées à l''aide de TypeScript","Intégration avec le composant parent pour l''ouverture et la fermeture du modal","Compatibilité avec le hook useExcelImport pour la gestion des états et l''exécution de l''importation"],"de":["Automatische Generierung eines benutzerdefinierten Excel-Import-Modals","Verwendung der Bibliothek xlsx für das Mapping und die Normalisierung von Feldern","Definition von Typen für die geparsten Daten mittels TypeScript","Integration mit dem Elternkomponenten für die Öffnung und Schließung des Modals","Kompatibilität mit dem Hook useExcelImport für die Zustandsverwaltung und die Ausführung der Importierung"],"pt":["Geração de modais de importação de Excel personalizados com React","Criação de hooks personalizados para gerenciar o estado de importação","Suporte a parsers para normalizar dados de planilhas","Integração com TypeScript para definição de tipos de dados","Guia de integração com componentes pai para abrir e fechar modais"],"ru":["Генерация индивидуальных модалей импорта Excel с использованием React","Создание кастомных хуков для управления состоянием импорта","Поддержка парсеров для нормализации данных таблиц","Интеграция с TypeScript для определения типов данных","Руководство по интеграции с родительскими компонентами для открытия и закрытия модалей"],"ar":["إنشاء نماذج استيراد Excel مخصصة باستخدام React","إنشاء hooks مخصصة لإدارة حالة الاستيراد","دعم parsers لتنسيق بيانات الجداول","التكامل مع TypeScript لتحديد أنواع البيانات","دليل تكامل مع مكونات الأبوين لفتح وإغلاق النماذج"]},"keywords":{"en":["how to use generate-import-modal","generate-import-modal setup guide","automated Excel import modal generation","useExcelImport hook tutorial","generate-import-modal vs manual implementation","what is generate-import-modal","generate-import-modal install","Excel import modal best practices"],"zh":["generate-import-modal","AI 工具","Excel 导入模态","useExcelImport 钩子","xlsx 解析","TypeScript 类型定义","自动创建模态","父组件联动指导"],"ja":["generate-import-modal","AI エージェント","Excel インポートモーダル","useExcelImport フック","xlsx 解析","TypeScript 型定義","モーダル自動生成","親コンポーネント連動ガイド"],"ko":["generate-import-modal","AI 에이전트","Excel 가져오기 모달","useExcelImport 훅","xlsx 파싱","TypeScript 인터페이스","모달 자동 생성","부모 컴포넌트 연동 안내"],"es":["generate-import-modal","modal de importación de Excel","skill de importación de Excel","uso de xlsx","TypeScript para datos parseados","integración con componente padre","hook useExcelImport","herramientas de AI para desarrolladores","Agentes de IA para desarrolladores"],"fr":["generate-import-modal","modal d''importation Excel","skill d''importation Excel","utilisation de xlsx","TypeScript pour données parsées","intégration avec composant parent","hook useExcelImport","outils d''IA pour développeurs","Agents d''IA pour développeurs"],"de":["generate-import-modal","Excel-Import-Modal","Skill für Excel-Import","Verwendung von xlsx","TypeScript für geparste Daten","Integration mit Elternkomponente","Hook useExcelImport","AI-Tools für Entwickler","KI-Agents für Entwickler"],"pt":["generate-import-modal","Ferramentas de IA","React","TypeScript","Importação de Excel","Modais personalizados","Hooks personalizados","Parsers de dados"],"ru":["generate-import-modal","ИИ Агенты","React","TypeScript","Импорт Excel","Индивидуальные модали","Кастомные хуки","Парсеры данных"],"ar":["generate-import-modal","أدوات الذكاء الاصطناعي","React","TypeScript","استيراد Excel","نماذج مخصصة","hooks مخصصة","parsers بيانات"]}},"owner":"BIGSHOL","repo":"ijw-Calander","repoPath":"BIGSHOL/ijw-Calander","stars":0,"forks":0,"updatedAt":"2026-03-06T05:59:19Z","topics":[],"category":"community","skillMd":{"name":"generate-import-modal","description":"Excel 가져오기 모달의 보일러플레이트를 자동 생성합니다. useExcelImport 훅 기반. 새 가져오기 기능 추가 시 사용.","bodyPreview":"## Purpose\n\n새로운 Excel 가져오기 모달을 프로젝트 표준 패턴에 맞춰 자동 생성합니다:\n\n1. **모달 컴포넌트 생성** — `useExcelImport` 훅을 사용하는 가져오기 모달\n2. **파서 함수 생성** — xlsx 필드 매핑 및 정규화 로직\n3. **타입 정의** — 파싱된 행의 TypeScript 인터페이스\n4. **부모 컴포넌트 연동 안내** — 모달 열기/닫기 및 onImport 콜백 연결\n\n## When to Run\n\n- 새 도메인에 Excel 가져오기 기능을 추가할 때\n- 기존 가져오기 모달을 `useExcelImport` 훅 기반으로 리팩토링할 때\n\n## Related Files\n\n| File | Purpose |\n|------|---------|\n| `hooks/useExcelImport.ts` | Excel 가져오기 공통 훅 (파일 읽기, 상태 관리, 가져오기 실행) |\n| `components/Textbooks/TextbookImportModa","body":"## Purpose\n\n새로운 Excel 가져오기 모달을 프로젝트 표준 패턴에 맞춰 자동 생성합니다:\n\n1. **모달 컴포넌트 생성** — `useExcelImport` 훅을 사용하는 가져오기 모달\n2. **파서 함수 생성** — xlsx 필드 매핑 및 정규화 로직\n3. **타입 정의** — 파싱된 행의 TypeScript 인터페이스\n4. **부모 컴포넌트 연동 안내** — 모달 열기/닫기 및 onImport 콜백 연결\n\n## When to Run\n\n- 새 도메인에 Excel 가져오기 기능을 추가할 때\n- 기존 가져오기 모달을 `useExcelImport` 훅 기반으로 리팩토링할 때\n\n## Related Files\n\n| File | Purpose |\n|------|---------|\n| `hooks/useExcelImport.ts` | Excel 가져오기 공통 훅 (파일 읽기, 상태 관리, 가져오기 실행) |\n| `components/Textbooks/TextbookImportModal.tsx` | 참조 구현: 교재 수납 가져오기 |\n| `components/Billing/BillingImportModal.tsx` | 참조 구현: 수납 데이터 가져오기 |\n| `components/StudentManagement/StudentMigrationModal.tsx` | 참조 구현: 학생 마이그레이션 |\n| `utils/studentMatching.ts` | 학생 매칭 유틸 (가져오기 시 학생 DB 매칭이 필요한 경우 사용) |\n\n## Workflow\n\n### Step 1: 사용자 입력 수집\n\n`AskUserQuestion`을 사용하여 다음을 확인합니다:\n\n1. **도메인 이름** (예: `attendance`, `homework`, `shuttle`)\n2. **Excel 필드 매핑** — 어떤 열을 읽을지 (예: 이름, 학년, 학교, 점수)\n3. **필터 조건** (선택) — 특정 행만 가져올지 (예: 구분 === ''교재'')\n4. **학생 매칭 필요 여부** — `studentMatching.ts` 연동 필요 여부\n5. **소속 탭** — 이 모달이 열리는 탭 컴포넌트 이름\n\n### Step 2: 타입 정의 생성\n\n파싱된 행의 인터페이스를 모달 파일 상단에 정의합니다:\n\n```typescript\nexport interface <PascalCase>ImportRow {\n  // 사용자가 지정한 필드들\n  studentName: string;\n  grade: string;\n  // ...\n  // 학생 매칭이 필요한 경우:\n  matched: boolean;\n  studentId?: string;\n}\n```\n\n### Step 3: 모달 컴포넌트 생성\n\n**파일:** `components/<PascalCase>/<PascalCase>ImportModal.tsx`\n\n**프로젝트 표준 구조:**\n\n```tsx\nimport React, { useMemo } from ''react'';\nimport { X, Upload, FileSpreadsheet, Loader2, AlertCircle, Check, RotateCcw, Eye } from ''lucide-react'';\nimport { useExcelImport } from ''../../hooks/useExcelImport'';\n\n// 1. 타입 정의\nexport interface <PascalCase>ImportRow {\n  // ...fields\n}\n\n// 2. Props 정의\ninterface <PascalCase>ImportModalProps {\n  isOpen: boolean;\n  onClose: () => void;\n  onImport: (rows: <PascalCase>ImportRow[]) => Promise<{ added: number; skipped: number }>;\n  // 학생 매칭이 필요한 경우:\n  // studentIds?: Set<string>;\n}\n\n// 3. 파서 함수 (또는 컴포넌트 내부 useCallback)\nfunction parse<PascalCase>Rows(rows: Record<string, any>[]): <PascalCase>ImportRow[] {\n  return rows\n    // .filter(row => ...)  // 필터 조건이 있는 경우\n    .map(row => ({\n      // 필드 매핑\n    }));\n}\n\n// 4. 컴포넌트\nexport const <PascalCase>ImportModal: React.FC<<PascalCase>ImportModalProps> = ({\n  isOpen,\n  onClose,\n  onImport,\n}) => {\n  const {\n    fileInputRef,\n    parsedData,\n    fileName,\n    isImporting,\n    importResult,\n    handleFileChange,\n    handleImport,\n    handleReset,\n    openFileDialog,\n    isParsed,\n    isComplete,\n  } = useExcelImport({\n    parser: parse<PascalCase>Rows,\n    onImport,\n  });\n\n  // 통계 요약 (useMemo)\n  const summary = useMemo(() => {\n    if (!isParsed) return null;\n    return {\n      totalRecords: parsedData.length,\n      // ... 도메인별 통계\n    };\n  }, [parsedData, isParsed]);\n\n  if (!isOpen) return null;\n\n  return (\n    <div className=\"fixed inset-0 bg-black/50 flex items-start justify-center pt-[8vh] z-[100]\" onClick={onClose}>\n      <div className=\"bg-white rounded-sm w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden\" onClick={e => e.stopPropagation()}>\n        {/* Header */}\n        <div className=\"flex items-center justify-between px-3 py-2 border-b border-gray-200\">\n          <h2 className=\"text-sm font-bold text-primary flex items-center gap-2\">\n            <FileSpreadsheet size={18} className=\"text-emerald-600\" />\n            <도메인명> 데이터 가져오기\n          </h2>\n          <button onClick={onClose} className=\"p-1 rounded-sm hover:bg-gray-100 text-gray-400 hover:text-gray-600\">\n            <X size={18} />\n          </button>\n        </div>\n\n        {/* Body */}\n        <div className=\"flex-1 overflow-auto p-6 space-y-2\">\n          {/* 파일 업로드 섹션 */}\n          <div className=\"bg-white border border-gray-200 overflow-hidden\">\n            <div className=\"flex items-center gap-1 px-2 py-1.5 bg-gray-50 border-b border-gray-200\">\n              <Upload className=\"w-3 h-3 text-primary\" />\n              <h3 className=\"text-primary font-bold text-xs\">파일 업로드</h3>\n            </div>\n            <div className=\"p-3\">\n              <input ref={fileInputRef} type=\"file\" accept=\".xlsx,.xls\" onChange={handleFileChange} className=\"hidden\" />\n              <div className=\"flex items-center gap-3\">\n                <button\n                  onClick={openFileDialog}\n                  className=\"flex items-center gap-2 px-4 py-2 border-2 border-dashed border-gray-300 rounded-sm hover:border-emerald-500 hover:bg-emerald-50 transition-colors text-sm\"\n                >\n                  <FileSpreadsheet className=\"w-4 h-4\" />\n                  Excel 파일 선택\n                </button>\n                {fileName && <span className=\"text-sm text-gray-600 font-medium\">{fileName}</span>}\n              </div>\n            </div>\n          </div>\n\n          {/* 데이터 미리보기 섹션 */}\n          {summary && (\n            <div className=\"bg-white border border-gray-200 overflow-hidden\">\n              <div className=\"flex items-center gap-1 px-2 py-1.5 bg-gray-50 border-b border-gray-200\">\n                <Eye className=\"w-3 h-3 text-primary\" />\n                <h3 className=\"text-primary font-bold text-xs\">데이터 미리보기</h3>\n              </div>\n              <div className=\"p-3 space-y-3\">\n                {/* 통계 카드 */}\n                <div className=\"grid grid-cols-2 md:grid-cols-3 gap-2 text-sm\">\n                  {/* ... 도메인별 통계 카드 */}\n                </div>\n\n                {/* 미리보기 테이블 */}\n                <div className=\"border border-gray-200 rounded-sm overflow-hidden\">\n                  <div className=\"bg-gray-50 px-2 py-1 border-b border-gray-200\">\n                    <h4 className=\"text-xs font-medium text-gray-600\">처음 15건 미리보기</h4>\n                  </div>\n                  <div className=\"overflow-x-auto\">\n                    <table className=\"w-full text-xs\">\n                      <thead className=\"bg-gray-50 border-b border-gray-200\">\n                        <tr>{/* 도메인별 컬럼 헤더 */}</tr>\n                      </thead>\n                      <tbody className=\"divide-y divide-gray-100 bg-white\">\n                        {parsedData.slice(0, 15).map((row, i) => (\n                          <tr key={i} className=\"hover:bg-gray-50\">\n                            {/* 도메인별 컬럼 데이터 */}\n                          </tr>\n                        ))}\n                      </tbody>\n                    </table>\n                  </div>\n                  {parsedData.length > 15 && (\n                    <div className=\"bg-gray-50 px-2 py-1 border-t border-gray-200\">\n                      <p className=\"text-xxs text-gray-400 text-center\">... 외 {parsedData.length - 15}건 더 있음</p>\n                    </div>\n                  )}\n                </div>\n              </div>\n            </div>\n          )}\n\n          {/* 결과 섹션 */}\n          {importResult && (\n            <div className=\"bg-white border border-gray-200 overflow-hidden\">\n              <div className=\"flex items-center gap-1 px-2 py-1.5 bg-gray-50 border-b border-gray-200\">\n                {importResult.success\n                  ? <Check className=\"w-3 h-3 text-emerald-600\" />\n                  : <AlertCircle className=\"w-3 h-3 text-red-600\" />}\n                <h3 className={`font-bold text-xs ${importResult.success ? ''text-emerald-700'' : ''text-red-700''}`}>\n                  {importResult.success ? ''가져오기 완료'' : ''가져오기 실패''}\n                </h3>\n              </div>\n              <div className={`p-3 ${importResult.success ? ''bg-emerald-50'' : ''bg-red-50''}`}>\n                {importResult.success ? (\n                  <div className=\"flex items-center gap-2\">\n                    <Check className=\"w-5 h-5 text-emerald-600 shrink-0\" />\n                    <div className=\"text-sm text-emerald-700 font-medium\">\n                      {importResult.added.toLocaleString()}건 추가 완료\n                      {importResult.skipped > 0 && (\n                        <span className=\"text-gray-500 font-normal ml-1\">(중복 {importResult.skipped.toLocaleString()}건 건너뜀)</span>\n                      )}\n                    </div>\n                  </div>\n                ) : (\n                  <div className=\"flex items-start gap-2\">\n                    <AlertCircle className=\"w-5 h-5 text-red-600 shrink-0 mt-0.5\" />\n                    <span className=\"text-sm text-red-700 font-medium\">데이터 가져오기에 실패했습니다.</span>\n                  </div>\n                )}\n              </div>\n            </div>\n          )}\n        </div>\n\n        {/* Footer */}\n        <div className=\"flex gap-3 px-6 py-4 border-t bg-gray-50\">\n          {isComplete ? (\n            <>\n              <button onClick={handleReset} className=\"flex-1 flex items-center justify-center gap-2 px-4 py-2 border border-gray-300 rounded-sm hover:bg-gray-100 text-sm font-medium\">\n                <RotateCcw className=\"w-4 h-4\" /> 다른 파일 가져오기\n              </button>\n              <button onClick={onClose} className=\"flex-1 px-4 py-2 bg-emerald-600 text-white rounded-sm hover:bg-emerald-700 text-sm font-medium\">닫기</button>\n            </>\n          ) : (\n            <>\n              <button onClick={onClose} className=\"flex-1 px-4 py-2 border border-gray-300 rounded-sm hover:bg-gray-100 text-sm font-medium\">취소</button>\n              <button\n                onClick={handleImport}\n                disabled={!isParsed || isImporting}\n                className=\"flex-1 flex items-center justify-center gap-2 px-4 py-2 bg-emerald-600 text-white rounded-sm hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed text-sm font-medium\"\n              >\n                {isImporting ? (\n                  <><Loader2 className=\"w-4 h-4 animate-spin\" /> 가져오는 중...</>\n                ) : (\n                  <><Upload className=\"w-4 h-4\" /> {isParsed ? `${parsedData.length.toLocaleString()}건 가져오기` : ''가져오기''}</>\n                )}\n              </button>\n            </>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n};\n```\n\n### Step 4: barrel export 업데이트\n\n해당 도메인의 `index.ts`에 export를 추가합니다:\n\n```typescript\nexport { <PascalCase>ImportModal } from ''./<PascalCase>ImportModal'';\n```\n\n### Step 5: 부모 컴포넌트 연동 안내\n\n가져오기 모달을 호출하는 부모 컴포넌트에서:\n\n```tsx\n// 1. state 추가\nconst [isImportOpen, setIsImportOpen] = useState(false);\n\n// 2. onImport 콜백 (훅에서 mutation 함수를 가져와 사용)\nconst handleImport = async (rows: <PascalCase>ImportRow[]) => {\n  // Firebase batch write or mutation\n  const batch = writeBatch(db);\n  // ... batch.set/update\n  await batch.commit();\n  return { added: rows.length, skipped: 0 };\n};\n\n// 3. 버튼 추가\n<button onClick={() => setIsImportOpen(true)}>\n  xlsx 가져오기\n</button>\n\n// 4. 모달 렌더\n<<PascalCase>ImportModal\n  isOpen={isImportOpen}\n  onClose={() => setIsImportOpen(false)}\n  onImport={handleImport}\n/>\n```\n\n### Step 6: 검증\n\n1. 컴포넌트 파일 존재 확인\n2. `useExcelImport` import 확인\n3. barrel export 존재 확인\n4. TypeScript 타입 오류 없는지 확인\n\n## Output Format\n\n```markdown\n## 가져오기 모달 생성 완료\n\n| 항목 | 상태 | 파일 |\n|------|------|------|\n| 타입 정의 | 생성됨 | `components/<Name>/<Name>ImportModal.tsx` (상단) |\n| 모달 컴포넌트 | 생성됨 | `components/<Name>/<Name>ImportModal.tsx` |\n| barrel export | 업데이트 | `components/<Name>/index.ts` |\n| useExcelImport | 연동됨 | `hooks/useExcelImport.ts` |\n\n필드 매핑:\n- `이름` → studentName (string)\n- `학년` → grade (string)\n- ...\n\n다음 단계:\n1. 부모 컴포넌트에서 모달 열기/닫기 state 추가\n2. `onImport` 콜백에서 Firebase batch write 구현\n3. 통계 카드와 미리보기 테이블의 컬럼을 도메인에 맞게 커스터마이즈\n```\n\n## Design Decisions\n\n### useExcelImport 훅 사용 이유\n\n프로젝트에 이미 7개의 가져오기 모달이 존재하며, 모두 동일한 상태 관리 패턴을 반복합니다:\n- `fileInputRef`, `parsedData`, `fileName`, `isImporting`, `importResult` state\n- `handleFileChange` (xlsx 파싱), `handleImport`, `handleReset` 핸들러\n\n`useExcelImport` 훅은 이 공통 로직을 캡슐화하여:\n- 새 모달 작성 시 코드량 60% 감소\n- 상태 관리 버그 방지 (검증된 패턴 재사용)\n- 일관된 UX (파일 선택 → 미리보기 → 가져오기 → 결과)\n\n### 모달 UI 표준\n\n모든 가져오기 모달은 동일한 4섹션 구조를 따릅니다:\n1. **헤더** — FileSpreadsheet 아이콘 + 도메인명 + 닫기 버튼\n2. **파일 업로드** — 점선 border 버튼 + hidden input\n3. **미리보기** — 통계 카드(grid) + 테이블(처음 15건)\n4. **푸터** — 완료 전: 취소/가져오기 | 완료 후: 다른 파일/닫기\n\n색상 체계: emerald(성공), red(실패), gray(기본), blue(통계)\n\n## Exceptions\n\n다음은 **문제가 아닙니다**:\n\n1. **통계 카드/테이블 컬럼이 TODO** — 도메인별 커스터마이즈가 필요한 부분이므로 생성 후 수동 조정\n2. **onImport에 Firebase 로직이 없는 것** — 가져오기 모달은 UI만 담당하고, 저장 로직은 부모/훅에서 구현\n3. **학생 매칭 미포함** — 학생 매칭이 필요한 경우에만 `studentIds` prop과 `studentMatching.ts` 유틸 연동\n"},"lastSynced":"2026-03-07T03:40:52.104Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing automated Excel import modal generation with TypeScript and React hooks.","zh":"非常适合需要使用TypeScript和React hooks自动生成Excel导入模态的前端代理","ja":"TypeScriptとReact hooksを使用してExcelインポートモーダルを自動生成する必要があるフロントエンドエージェントに最適","ko":"TypeScript와 React hooks를 사용하여 Excel 가져오기 모달을 자동 생성해야 하는 프론트엔드 에이전트에 적합","es":"Perfecto para agentes Frontend que necesitan generación automática de modal de importación de Excel con TypeScript y ganchos de React.","fr":"Parfait pour les agents Frontend ayant besoin d''une génération automatisée de modale d''importation Excel avec TypeScript et crochets React.","de":"Perfekt für Frontend-Agenten, die eine automatisierte Excel-Import-Modal-Generierung mit TypeScript und React-Hooks benötigen.","pt":"Perfeito para Agentes Frontend que precisam de geração automática de modal de importação do Excel com TypeScript e React hooks.","ru":"Идеально для агентов Frontend, которым необходима автоматизированная генерация модального окна импорта Excel с помощью TypeScript и React hooks.","ar":"مثالي لعميل واجهة المستخدم الذي يحتاج إلى генера автоматية لحوار استيراد إكسل مع TypeScript و React hooks."},"recommendation":{"en":"Empowers agents to create standardized Excel import modals with automatically generated modal components, parser functions, and TypeScript interfaces, streamlining the import process with `useExcelImport` hooks and xlsx field mapping.","zh":"赋予代理创建标准化Excel导入模态的能力，自动生成模态组件、解析函数和TypeScript接口，利用`useExcelImport` hooks和xlsx字段映射简化导入过程","ja":"`useExcelImport` hooksとxlsxフィールドマッピングを使用してインポートプロセスを簡素化する、標準化されたExcelインポートモーダルを作成するエージェントの能力を可能にし、モーダルコンポーネント、パーサー関数、およびTypeScriptインターフェイスを自動生成する","ko":"`useExcelImport` hooks와 xlsx 필드 매핑을 사용하여 가져오기 프로세스를 간소화하는 표준화된 Excel 가져오기 모달을 만들 수 있는 에이전트의 능력을 가능하게 하며, 모달 컴포넌트, 파서 함수 및 TypeScript 인터페이스를 자동 생성","es":"Habilita a los agentes a crear modales de importación de Excel estandarizados con componentes de modal generados automáticamente, funciones de parser y interfaces de TypeScript, lo que agiliza el proceso de importación con ganchos `useExcelImport` y mapeo de campos xlsx.","fr":"Permet aux agents de créer des modales d''importation Excel standardisées avec des composants de modale générés automatiquement, des fonctions d''analyse et des interfaces TypeScript, ce qui rationalise le processus d''importation avec des crochets `useExcelImport` et un mappage de champs xlsx.","de":"Ermächtigt Agenten, standardisierte Excel-Import-Modals mit automatisch generierten Modal-Komponenten, Parser-Funktionen und TypeScript-Schnittstellen zu erstellen, wodurch der Importprozess mit `useExcelImport`-Hooks und xlsx-Feldzuordnung rationalisiert wird.","pt":"Habilita os agentes a criar modais de importação do Excel padronizados com componentes de modal gerados automaticamente, funções de análise e interfaces do TypeScript, simplificando o processo de importação com ganchos `useExcelImport` e mapeamento de campos xlsx.","ru":"Наделяет агентов возможностью создавать стандартизированные модальные окна импорта Excel с автоматически сгенерированными компонентами модального окна, функциями парсера и интерфейсами TypeScript, упрощая процесс импорта с помощью крючков `useExcelImport` и сопоставления полей xlsx.","ar":"يمكّن العميل من إنشاء حوارات مستوردة إكسل معيارية مع مكونات الحوار التلقائي وتوابع التحليل وواجهات برمجة TypeScript، وبذلك يبسط عملية الاستيراد باستخدام مشابك `useExcelImport` وتوافق حقول xlsx."},"useCases":{"en":["Automating Excel import modal creation for new domains","Refactoring existing import modals to use `useExcelImport` hooks","Generating TypeScript interfaces for parsed Excel data","Integrating import modals with parent components for seamless import functionality"],"zh":["为新域自动创建Excel导入模态","使用`useExcelImport` hooks重构现有的导入模态","为解析的Excel数据生成TypeScript接口","将导入模态集成到父组件以实现无缝的导入功能"],"ja":["新しいドメインのExcelインポートモーダルの自動生成","`useExcelImport` hooksを使用して既存のインポートモーダルをリファクタリングする","解析されたExcelデータのTypeScriptインターフェイスの生成","インポートモーダルを親コンポーネントに統合してシームレスなインポート機能を実現する"],"ko":["새로운 도메인에 대한 Excel 가져오기 모달 자동 생성","`useExcelImport` hooks를 사용하여 기존의 가져오기 모달을 리팩토링","파싱된 Excel 데이터에 대한 TypeScript 인터페이스 생성","가져오기 모달을 부모 컴포넌트와 통합하여 무결점의 가져오기 기능을 구현"],"es":["Automatización de la creación de modales de importación de Excel para nuevos dominios","Reestructuración de modales de importación existentes para utilizar ganchos `useExcelImport`","Generación de interfaces de TypeScript para datos de Excel analizados","Integración de modales de importación con componentes principales para una funcionalidad de importación sin problemas"],"fr":["Automatisation de la création de modales d''importation Excel pour de nouveaux domaines","Réorganisation de modales d''importation existants pour utiliser des crochets `useExcelImport`","Génération d''interfaces TypeScript pour des données Excel analysées","Intégration de modales d''importation avec des composants parents pour une fonctionnalité d''importation transparente"],"de":["Automatisierung der Erstellung von Excel-Import-Modals für neue Domains","Umstrukturierung bestehender Import-Modals zur Verwendung von `useExcelImport`-Hooks","Generierung von TypeScript-Schnittstellen für analysierte Excel-Daten","Integration von Import-Modals mit übergeordneten Komponenten für eine nahtlose Importfunktion"],"pt":["Automatizar a criação de modais de importação do Excel para novos domínios","Reestruturar modais de importação existentes para usar ganchos `useExcelImport`","Gerar interfaces do TypeScript para dados do Excel analisados","Integrar modais de importação com componentes pai para funcionalidade de importação sem interrupção"],"ru":["Автоматизировать создание модальных окон импорта Excel для новых доменов","Перестроить существующие модальные окна импорта для использования крючков `useExcelImport`","Сгенерировать интерфейсы TypeScript для проанализированных данных Excel","Интегрировать модальные окна импорта с родительскими компонентами для бесперебойной функциональности импорта"],"ar":["تؤتمة إنشاء حوارات استيراد إكسل لأسماء المجالات الجديدة","إعادة هيكلة حوارات الاستيراد الحالية لاستخدام مشابك `useExcelImport`","توليد واجهات برمجة TypeScript للبيانات المُحَلَّلة من إكسل","دمج حوارات الاستيراد مع المكونات الأساسية لتوفر وظيفة استيراد دون انقطاع"]},"limitations":{"en":["Requires React and TypeScript project setup","Limited to Excel import functionality","Dependent on `hooks/useExcelImport.ts` and related component files"],"zh":["需要React和TypeScript项目设置","仅限Excel导入功能","依赖于`hooks/useExcelImport.ts`和相关的组件文件"],"ja":["ReactとTypeScriptプロジェクトの設定が必要","Excelインポート機能のみ","`hooks/useExcelImport.ts`および関連するコンポーネントファイルに依存"],"ko":["React와 TypeScript 프로젝트 설정이 필요","Excel 가져오기 기능만","`hooks/useExcelImport.ts` 및 관련 컴포넌트 파일에 의존"],"es":["Requiere configuración de proyecto React y TypeScript","Limitado a la funcionalidad de importación de Excel","Dependiente de `hooks/useExcelImport.ts` y archivos de componentes relacionados"],"fr":["Nécessite une configuration de projet React et TypeScript","Limité à la fonctionnalité d''importation Excel","Dépendant de `hooks/useExcelImport.ts` et des fichiers de composants associés"],"de":["Erfordert React- und TypeScript-Projektsetup","Begrenzt auf Excel-Importfunktion","Abhängig von `hooks/useExcelImport.ts` und verwandten Komponentendateien"],"pt":["Exige configuração do projeto React e TypeScript","Limitado à funcionalidade de importação do Excel","Dependente de `hooks/useExcelImport.ts` e arquivos de componentes relacionados"],"ru":["Требует настройки проекта React и TypeScript","Ограничен функциональностью импорта Excel","Зависит от `hooks/useExcelImport.ts` и связанных с ним файлов компонентов"],"ar":["يتطلب إعداد مشروع React و TypeScript","محدود بوظيفة استيراد إكسل","يعتمد على `hooks/useExcelImport.ts` وملفات المكونات المرتبطة"]},"version":4},"contentHash":"76c03fbacabe5912a54f1a276ce81e8876abe6513169a411a2027a56af789b4c","qualityScore":51}');
