INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BIGSHOL/ijw-Calander/generate-import-modal', 'generate-import-modal', 'BIGSHOL', 'ijw-Calander', 'community', 'generate-import-modal BIGSHOL ijw-Calander community The generate-import-modal skill automates the creation of Excel import modals, generating modal components, parser functions, and TypeScript interfaces. It benefits developers by simplifying the import process. generate-import-modal 是一个自动创建 Excel 导入模态的工具，支持 useExcelImport 钩子和 xlsx 解析 generate-import-modal は Excel インポートモーダルを自動生成するツールで、useExcelImport フックと xlsx 解析をサポート generate-import-modal은 Excel 가져오기 모달을 자동 생성하는 도구로 useExcelImport 훅과 xlsx 파싱을 지원 El skill generate-import-modal permite generar automáticamente un modal de importación de Excel personalizado según el patrón estándar del proyecto Le skill generate-import-modal permet de générer automatiquement un modal d''importation Excel personnalisé selon le modèle standard du projet Der Skill generate-import-modal ermöglicht die automatische Generierung eines benutzerdefinierten Excel-Import-Modals nach dem Projektstandardmuster O generate-import-modal é uma ferramenta que gera modais de importação de Excel personalizados com React e TypeScript, incluindo hooks e parsers. generate-import-modal - это инструмент, который генерирует индивидуальные модали импорта Excel с использованием React и TypeScript, включая хуки и парсеры. generate-import-modal هو أداة ت generar نماذج استيراد Excel مخصصة باستخدام React و TypeScript، بما في ذلك hooks و parsers. how to use generate-import-modal generate-import-modal setup guide automated Excel import modal generation useExcelImport hook tutorial generate-import-modal vs manual implementation what is generate-import-modal generate-import-modal install Excel import modal best practices generate-import-modal AI 工具 Excel 导入模态 useExcelImport 钩子 xlsx 解析 TypeScript 类型定义 自动创建模态 父组件联动指导 Generates modal components using the useExcelImport hook Creates parser functions for xlsx field mapping and normalization Defines TypeScript interfaces for parsed rows Provides guidance on integrating with parent components Supports refactoring existing import modals to use the useExcelImport hook generate-import-modal is a skill that automatically generates Excel import modals based on project standards, including modal components, parser functions, and TypeScript interfaces.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MarioPasc/MenGrowth/preprocess-debug', 'community', 'MarioPasc', 'MenGrowth', 'MarioPasc/MenGrowth', 'preprocess-debug', 0, 0, 51, '2026-03-06T12:05:55Z', '2026-03-07T03:44:53.385Z', 'd75a5720c3679d33a6edd06689e84165c39ec4e7397dce2f43236718ec9c742a', '{"id":"MarioPasc/MenGrowth/preprocess-debug","name":"preprocess-debug","description":{"en":"The preprocess-debug skill predicts the probability of growth for meningioma intracranial tumors using AI and aids in diagnosing preprocessing failures. It benefits developers and researchers working with medical imaging data.","zh":"预处理调试是一种使用AI预测脑膜瘤生长概率，并诊断预处理失败原因的技术","ja":"前処理デバッグは、AIエージェントを使用して髄膜腫の成長確率を予測し、前処理の失敗原因を診断する技術です","ko":"전처리 디버깅은 AI를 사용하여 뇌종양의 성장 확률을 예측하고 전처리 실패 원인을 진단하는 기술입니다","es":"Preprocess-debug es una habilidad que ayuda a diagnosticar errores de preprocesamiento en la predicción de la probabilidad de crecimiento de tumores intracraneales","fr":"Preprocess-debug est une compétence qui aide à diagnostiquer les erreurs de prétraitement dans la prédiction de la probabilité de croissance des tumeurs intracraniennes","de":"Preprocess-debug ist eine Fähigkeit, die dabei hilft, Fehler bei der Vorbearbeitung bei der Vorhersage der Wachstumswahrscheinlichkeit von intrakraniellen Tumoren zu diagnostizieren","pt":"O preprocess-debug é uma ferramenta de IA para diagnosticar falhas de pré-processamento em análises de tumores cerebrais. Aprenda a configurá-lo para melhorar a precisão do seu modelo","ru":"Preprocess-debug - это инструмент ИИ для диагностики сбоев предобработки в анализе интракраниальных опухолей. Узнайте, как настроить его для улучшения точности вашей модели","ar":"مرشح المعالجة المسبقة هو أداة ذكاء اصطناعي لتشخيص أعطال المعالجة المسبقة في تحليل الأورام الدماغية. تعرف على إعدادها لتحسين دقة نموذجك"},"seo":{"title":{"en":"preprocess-debug: Diagnostic Workflow Setup Guide | AI Ag...","zh":"预处理调试指南：预处理失败诊断","ja":"AIエージェントを使用した前処理デバッグセットアップガイド","ko":"전처리 디버깅 가이드: 전처리 실패 진단","es":"Guía de configuración de preprocess-debug para diagnóstic...","fr":"Guide de configuration de preprocess-debug pour le diagno...","de":"Konfigurationsleitfaden für preprocess-debug zur Fehlersu...","pt":"Guia de Configuração do Preprocess-Debug para Análise de ...","ru":"Настройка Preprocess-Debug для анализа_intrakraniálních о...","ar":"إعداد مرشح المعالجة المسبقة للتشخيص الدقيق للأورام الدماغ..."},"description":{"en":"Troubleshoot preprocessing failures with preprocess-debug. Identify issues and optimize your workflow. Learn how to use it now!","zh":"利用AI预测脑膜瘤生长概率，并诊断预处理失败原因","ja":"AIエージェントを使用して髄膜腫の成長確率を予測し、前処理の失敗原因を診断します","ko":"AI를 사용하여 뇌종양의 성장 확률을 예측하고 전처리 실패 원인을 진단합니다","es":"Aprende a diagnosticar errores de preprocesamiento con preprocess-debug y mejora la calidad de tus datos con herramientas de AI","fr":"Découvrez comment diagnostiquer les erreurs de prétraitement avec preprocess-debug et améliorer la qualité de vos données avec des outils d''IA","de":"Erfahren Sie, wie Sie Fehler bei der Vorbearbeitung mit preprocess-debug diagnostizieren und die Datenqualität mit KI-Tools verbessern","pt":"Aprenda a configurar o preprocess-debug para diagnosticar falhas de pré-processamento em análises de tumores cerebrais com IA. Melhore a precisão do seu modelo","ru":"Узнайте, как настроить preprocess-debug для диагностики сбоев предобработки в анализе интракраниальных опухолей с помощью ИИ Агентов. Улучшите точность вашей...","ar":"تعرف على إعداد مرشح المعالجة المسبقة لتشخيص أعطال المعالجة المسبقة في تحليل الأورام الدماغية باستخدام أدوات الذكاء الاصطناعي. تحسين دقة نموذجك"},"definition":{"en":"preprocess-debug is a diagnostic tool that identifies preprocessing failures in medical imaging data, specifically for meningioma intracranial tumors.","zh":"预处理调试是一种使用AI技术诊断预处理失败原因的方法","ja":"前処理デバッグは、AIエージェントを使用して前処理の失敗原因を診断する方法です","ko":"전처리 디버깅은 AI를 사용하여 전처리 실패 원인을 진단하는 방법입니다","es":"Preprocess-debug es una herramienta de AI que diagnostica errores de preprocesamiento en la visualización de datos médicos","fr":"Preprocess-debug est un outil d''IA qui diagnostique les erreurs de prétraitement dans la visualisation de données médicales","de":"Preprocess-debug ist ein KI-Tool, das Fehler bei der Vorbearbeitung in der Visualisierung von medizinischen Daten diagnostiziert","pt":"O preprocess-debug é uma técnica de diagnóstico de falhas de pré-processamento em análises de tumores cerebrais com IA","ru":"Preprocess-debug - это метод диагностики сбоев предобработки в анализе интракраниальных опухолей с помощью ИИ","ar":"مرشح المعالجة المسبقة هو تقنية تشخيصية لأعطال المعالجة المسبقة في تحليل الأورام الدماغية باستخدام الذكاء الاصطناعي"},"features":{"en":["Identifies the failing step in the preprocessing pipeline","Checks the visualization directory for last PNG output using ls command","Diagnoses preprocessing quality issues or crashes","Investigates skull stripping and intensity normalization problems","Supports diagnostic workflow for patient data analysis"],"zh":["预处理失败诊断","前処理质量问题调查","注册输出检查","颅骨剥离检查","强度归一化检查"],"ja":["前処理失敗の診断","前処理品質の問題調査","登録出力の確認","頭骨除去の確認","強度正規化の確認"],"ko":["전처리 실패 진단","전처리 품질 문제 조사","등록 출력 확인","뼈剥離 확인","강도 정규화 확인"],"es":["Identificación del paso que falla en el proceso de preprocesamiento","Diagnóstico de errores de registro y normalización de intensidad","Análisis de la calidad de los datos de visualización","Uso de la línea de comandos (CLI) para la depuración","Integración con herramientas de visualización de datos médicos"],"fr":["Identification de l''étape qui échoue dans le processus de prétraitement","Diagnostic des erreurs d''enregistrement et de normalisation d''intensité","Analyse de la qualité des données de visualisation","Utilisation de la ligne de commande (CLI) pour le débogage","Intégration avec des outils de visualisation de données médicales"],"de":["Identifizierung des fehlerhaften Schritts im Vorbearbeitungsprozess","Fehlerdiagnose bei der Registrierung und Intensitätsnormalisierung","Analyse der Datenqualität bei der Visualisierung","Verwendung der Kommandozeile (CLI) für die Fehlersuche","Integration mit Tools für die Visualisierung von medizinischen Daten"],"pt":["Identificação do passo de falha no pré-processamento","Análise de registros de pré-processamento","Diagnóstico de problemas de pré-processamento","Otimização do pré-processamento para melhorar a precisão do modelo","Integração com ferramentas de visualização para análise de resultados"],"ru":["Определение шага сбоя в предобработке","Анализ журналов предобработки","Диагностика проблем предобработки","Оптимизация предобработки для улучшения точности модели","Интеграция с инструментами визуализации для анализа результатов"],"ar":["تحديد خطوة الفشل في المعالجة المسبقة","تحليل سجلات المعالجة المسبقة","تشخيص مشاكل المعالجة المسبقة","تحسين المعالجة المسبقة لتحسين دقة النموذج","التكامل مع أدوات التصور لتحليل النتائج"]},"keywords":{"en":["how to use preprocess-debug","preprocess-debug alternative","preprocess-debug setup guide","what is preprocess-debug","preprocess-debug vs other diagnostic tools","preprocess-debug install","preprocess-debug for medical imaging","preprocess-debug tutorial","preprocess-debug troubleshooting"],"zh":["预处理调试","AI预测","脑膜瘤生长概率","前処理失败诊断","注册输出检查","颅骨剥离检查","强度归一化检查"],"ja":["AIエージェント","前処理デバッグ","髄膜腫の成長確率","前処理失敗の診断","登録出力の確認","頭骨除去の確認","強度正規化の確認"],"ko":["AI","전처리 디버깅","뇌종양 성장 확률","전처리 실패 진단","등록 출력 확인","뼈剥離 확인","강도 정규화 확인"],"es":["preprocess-debug","herramientas de AI","diagnóstico de errores de preprocesamiento","visualización de datos médicos","CLI","registrierung","intensitätsnormalisierung","calidad de datos"],"fr":["preprocess-debug","outils d''IA","diagnostic des erreurs de prétraitement","visualisation de données médicales","CLI","enregistrement","normalisation d''intensité","qualité des données"],"de":["preprocess-debug","KI-Tools","Fehlersuche bei der Vorbearbeitung","Visualisierung von medizinischen Daten","CLI","Registrierung","Intensitätsnormalisierung","Datenqualität"],"pt":["preprocess-debug","análise de tumores cerebrais","IA para saúde","ferramentas de IA","pré-processamento de dados","diagnóstico de falhas","otimização do pré-processamento"],"ru":["preprocess-debug","анализ интракраниальных опухолей","ИИ для здравоохранения","инструменты ИИ","предобработка данных","диагностика сбоев","оптимизация предобработки"],"ar":["مرشح المعالجة المسبقة","تحليل الأورام الدماغية","الذكاء الاصطناعي للرعاية الصحية","أدوات الذكاء الاصطناعي","معالجة البيانات المسبقة","تشخيص الأعطال","تحسين المعالجة المسبقة"]}},"owner":"MarioPasc","repo":"MenGrowth","repoPath":"MarioPasc/MenGrowth","stars":0,"forks":0,"updatedAt":"2026-03-06T12:05:55Z","topics":[],"category":"community","skillMd":{"name":"preprocess-debug","description":"Debug preprocessing pipeline failures. Guides through reading checkpoint files, checking step artifacts, interpreting QC metrics, examining visualization PNGs, and identifying which step failed and why. Use when a preprocessing run produces unexpected results, crashes, or generates poor-quality outputs.","bodyPreview":"# Preprocess Debug — Preprocessing Failure Diagnosis\n\n## When to Use\n\n- \"Why did preprocessing fail for patient X?\"\n- \"The registration output looks wrong\"\n- \"Skull stripping removed too much / too little\"\n- \"Intensity normalization produced weird values\"\n- \"Which step is causing the problem?\"\n- Any preprocessing quality issue or crash investigation\n\n## Diagnostic Workflow\n\n### Step 1: Identify the failing step\n\nCheck the visualization directory for which step produced the last PNG:\n\n```bash\nls","body":"# Preprocess Debug — Preprocessing Failure Diagnosis\n\n## When to Use\n\n- \"Why did preprocessing fail for patient X?\"\n- \"The registration output looks wrong\"\n- \"Skull stripping removed too much / too little\"\n- \"Intensity normalization produced weird values\"\n- \"Which step is causing the problem?\"\n- Any preprocessing quality issue or crash investigation\n\n## Diagnostic Workflow\n\n### Step 1: Identify the failing step\n\nCheck the visualization directory for which step produced the last PNG:\n\n```bash\nls -la {viz_root}/MenGrowth-XXXX/MenGrowth-XXXX-YYY/\n# step1_data_harmonization_t1c.png  ← exists\n# step2_bias_field_correction_t1c.png  ← exists\n# step3_resampling_t1c.png  ← MISSING → Step 3 failed\n```\n\nCheck logs for error messages (look for `ERROR` or `RuntimeError`).\n\n### Step 2: Check step artifacts\n\nEach step may produce artifacts in `{artifacts}/MenGrowth-XXXX/MenGrowth-XXXX-YYY/`:\n\n| Artifact | Produced by | What to check |\n|----------|-------------|---------------|\n| `t1c_bias_field.nii.gz` | Bias field correction | Should be smooth, low-frequency field |\n| `t1c_brain_mask.nii.gz` | Skull stripping | Load in viewer — verify mask covers brain + tumor |\n| `*.h5`, `*.mat` transforms | Registration | Verify transforms exist and are non-zero |\n\n### Step 3: Examine visualization PNGs\n\nEach step''s PNG shows before/after comparison. Look for:\n\n| Step | What to check in visualization |\n|------|-------------------------------|\n| Data harmonization | Orientation correct? Background removed? |\n| Bias field correction | Intensity gradients reduced? |\n| Resampling | Resolution changed? No aliasing artifacts? |\n| Cubic padding | Volume centered? Correct padding extent? |\n| Registration | Modalities aligned? Atlas overlay reasonable? |\n| Skull stripping | Mask boundary at brain surface? Tumor included? |\n| Intensity normalization | Histogram shifted to expected range? |\n| Longitudinal registration | Timepoints aligned? No excessive deformation? |\n\n### Step 4: Check specific failure patterns\n\n#### Registration failures\n- **\"No reference modality found\"**: Check that `reference_modality_priority` matches available modalities\n- **Poor alignment**: Try `engine: \"antspyx\"` instead of `\"nipype\"` (or vice versa)\n- **Divergence**: Check if `use_center_of_mass_init: true` is set\n- **ANTs crash**: Look for `ITK ERROR` in logs; check if input volumes have valid affine matrices\n- **Quality warning**: If correlation dissimilarity > `quality_warning_threshold`, registration may have failed\n\n#### Skull stripping failures\n- **Over-stripping (tumor removed)**: HD-BET is more robust to pathology than SynthStrip; try `method: \"hdbet\"` with `hdbet_mode: \"accurate\"`\n- **Under-stripping (skull remaining)**: Increase SynthStrip `border` parameter or switch methods\n- **GPU OOM**: Set `hdbet_device: \"cpu\"` or `synthstrip_device: \"cpu\"`\n\n#### Intensity normalization failures\n- **All zeros output**: Check that brain mask exists and covers tissue\n- **Extreme values**: Use `clip_range: [-5.0, 5.0]` for z-score\n- **NaN values**: Input may contain NaN — check with `nib.load(path).get_fdata()` for NaN/Inf\n- **Wrong mask source**: Check logs for \"Using brain mask from:\" vs \"using nonzero voxels as fallback\"\n\n#### Data harmonization failures\n- **Wrong orientation**: Check `reorient_to` matches expected convention (RAS vs LPS)\n- **Background not removed**: Try `method: \"otsu_foreground\"` instead of default\n- **NRRD parse error**: Check if input file is valid NRRD with `nrrd.read(path)`\n\n#### Resampling failures\n- **ECLARE environment not found**: Verify `conda_environment_eclare` matches installed env\n- **GPU OOM with ECLARE**: Reduce `batch_size` or switch to `method: \"bspline\"`\n- **Extreme anisotropy**: Use `method: \"composite\"` for volumes with > 5mm slice thickness\n\n### Step 5: Check the temp-file mechanism\n\nIf a step crashes mid-write, a `.tmp.nii.gz` file may be left behind:\n\n```bash\nfind {output_root} -name \"*.tmp*\"\n```\n\nThese should be deleted before re-running.\n\n## Key Debugging Code Locations\n\n| Issue | File to read |\n|-------|-------------|\n| Step handler logic | `mengrowth/preprocessing/src/steps/{step_name}.py` |\n| Brain mask resolution | Search for `brain_mask` in the step handler |\n| Registration quality metrics | `mengrowth/preprocessing/src/registration/diagnostic_parser.py` |\n| Checkpoint state | `mengrowth/preprocessing/src/checkpoint.py` |\n| QC metrics interpretation | `mengrowth/preprocessing/src/config.py` → `QCMetricsConfig` |\n| Step execution order | YAML config `steps:` list |\n| Config validation errors | `mengrowth/preprocessing/src/config.py` → `__post_init__()` methods |\n\n## Quick Config Fixes\n\n| Problem | Config change |\n|---------|--------------|\n| Step taking too long | Increase `shrink_factor`, reduce iterations |\n| Registration not converging | Switch `engine`, adjust `sampling_percentage`, add transform stages |\n| Mask too aggressive | Adjust `fill_value`, `border`, or switch skull stripping method |\n| Step crashing on GPU | Set device to `\"cpu\"` in step config |\n| Want to skip a step | Remove from `steps:` list or set `method: null` in step config |\n| Need to re-run from step N | Remove all outputs from step N onward, or use checkpoint resume |\n"},"lastSynced":"2026-03-07T03:44:53.385Z","agentAnalysis":{"suitability":{"en":"Ideal for Medical Imaging Agents requiring advanced preprocessing failure diagnosis and tumor growth prediction capabilities.","zh":"适合需要高级预处理故障诊断和肿瘤生长预测能力的医疗影像代理。","ja":"医療用画像エージェントに高度な前処理障害診断および腫瘍増殖予測機能を必要とする場合に最適です。","ko":"고급 전처리 실패 진단 및 종양 성장 예측 기능이 필요한 의료 영상 에이전트에 적합합니다.","es":"Ideal para agentes de imagen médica que requieren capacidades de diagnóstico de fallos de preprocesamiento avanzadas y predicción de crecimiento de tumores.","fr":"Idéal pour les agents d''imagerie médicale nécessitant des capacités de diagnostic de défaillance de prétraitement avancées et de prédiction de croissance tumorale.","de":"Ideal für medizinische Bildgebungsmittel, die erweiterte Fähigkeiten zur Fehlerdiagnose bei der Vorverarbeitung und zur Vorhersage des Tumorwachstums erfordern.","pt":"Ideal para Agentes de Imagem Médica que exigem capacidades avançadas de diagnóstico de falha de pré-processamento e previsão de crescimento de tumor.","ru":"Идеально для Медицинских Изображений Агентов, требующих расширенных возможностей диагностики неисправностей предобработки и прогнозирования роста опухоли.","ar":"مثالي للوكلاء الصوريين الطبيين الذين يحتاجون إلى قدرات متقدمة لتشخيص فشل المعالجة المسبقة وتوقعات نمو الأورام."},"recommendation":{"en":"Empowers agents to diagnose preprocessing failures using AI, predict meningioma intracranial tumor growth, and analyze medical imaging data with steps like skull stripping and intensity normalization.","zh":"赋予代理使用AI诊断前处理故障、预测硬脑膜瘤颅内肿瘤生长，并通过诸如颅骨剥离和强度归一化等步骤分析医疗影像数据的能力。","ja":"エージェントにAIを使用して前処理の障害を診断し、硬膜瘤の頭内腫瘤の増殖を予測し、頭骨の剥離や強度の正規化などのステップで医療画像データを分析する機能を付与します。","ko":"에이전트가 AI를 사용하여 전처리 실패를 진단하고 경막종의 두개 내 종양 성장을 예측하며, 두개골 제거 및 강도 정규화 등의 단계로 의료 영상 데이터를 분석할 수 있는 기능을 제공합니다.","es":"Habilita a los agentes a diagnosticar fallos de preprocesamiento utilizando IA, predecir el crecimiento de tumores meningioma intracraneales y analizar datos de imagen médica con pasos como la eliminación del cráneo y la normalización de intensidad.","fr":"Permet aux agents de diagnostiquer les défaillances de prétraitement à l''aide de l''IA, de prédire la croissance des tumeurs méningiomes intracrâniennes et d''analyser les données d''imagerie médicale avec des étapes comme le décapage du crâne et la normalisation d''intensité.","de":"Ermöglicht es den Agenten, Fehler bei der Vorverarbeitung mithilfe von KI zu diagnostizieren, das Wachstum von Meningeom-Tumoren im Schädel vorherzusagen und medizinische Bilddaten mit Schritten wie Schädelentfernung und Intensitätsnormalisierung zu analysieren.","pt":"Habilita agentes a diagnosticar falhas de pré-processamento usando IA, prever o crescimento de tumores intracranianos meningioma, e analisar dados de imagem médica com etapas como remoção do crânio e normalização de intensidade.","ru":"Наделяет агентов возможностью диагностировать неисправности предобработки с помощью ИИ, прогнозировать рост внутричерепных опухолей менингиома и анализировать медицинские изображения с шагами, такими как удаление черепа и нормализация интенсивности.","ar":"يمكّن الوكلاء من تشخيص فشل المعالجة المسبقة باستخدام الذكاء الاصطناعي، وتوقعات نمو الأورام المخية المنيجية، وتحليل البيانات الصورية الطبية بخطوات مثل إزالة الجمجمة وتنظيم شدة الإشعاع."},"useCases":{"en":["Debugging preprocessing failures in medical imaging pipelines","Investigating registration output issues in tumor analysis","Identifying quality issues in skull stripping and intensity normalization","Analyzing crash reports for preprocessing steps","Determining the probability of growth for meningioma intracranial tumors"],"zh":["调试医疗影像管道中的前处理故障","调查肿瘤分析中的注册输出问题","确定颅骨剥离和强度归一化中的质量问题","分析前处理步骤的崩溃报告","确定硬脑膜瘤颅内肿瘤生长的概率"],"ja":["医療画像パイプラインの前処理障害のデバッグ","腫瘍解析の登録出力の問題の調査","頭骨の剥離と強度の正規化の品質の問題の特定","前処理ステップのクラッシュレポートの分析","硬膜瘤頭内腫瘤の増殖の確率の決定"],"ko":["의료 영상 파이프라인에서 전처리 실패를 디버깅하는 것","종양 분석에서 등록 출력 문제를 조사하는 것","두개골 제거 및 강도 정규화에서 품질 문제를 식별하는 것","전처리 단계의 크래시 보고서를 분석하는 것","경막종 두개 내 종양의 성장 확률을 결정하는 것"],"es":["Depuración de fallos de preprocesamiento en tuberías de imagen médica","Investigación de problemas de salida de registro en análisis de tumores","Identificación de problemas de calidad en la eliminación del cráneo y la normalización de intensidad","Análisis de informes de errores para pasos de preprocesamiento","Determinación de la probabilidad de crecimiento para tumores meningioma intracraneales"],"fr":["Débogage des défaillances de prétraitement dans les pipelines d''imagerie médicale","Enquête sur les problèmes de sortie d''enregistrement dans l''analyse des tumeurs","Identification des problèmes de qualité dans le décapage du crâne et la normalisation d''intensité","Analyse des rapports d''erreur pour les étapes de prétraitement","Détermination de la probabilité de croissance pour les tumeurs méningiomes intracrâniennes"],"de":["Fehlerbehebung bei der Vorverarbeitung in medizinischen Bildverarbeitungspipelines","Untersuchung von Ausgabeproblemen bei der Tumoranalyse","Identifizierung von Qualitätsproblemen bei der Schädelentfernung und Intensitätsnormalisierung","Analyse von Fehlerberichten für Vorverarbeitungsschritte","Bestimmung der Wahrscheinlichkeit des Wachstums für Meningeom-Tumoren im Schädel"],"pt":["Depuração de falhas de pré-processamento em pipelines de imagem médica","Investigação de problemas de saída de registro em análise de tumor","Identificação de problemas de qualidade em remoção do crânio e normalização de intensidade","Análise de relatórios de falha para etapas de pré-processamento","Determinação da probabilidade de crescimento de tumores intracranianos meningioma"],"ru":["Отладка неисправностей предобработки в конвейерах медицинских изображений","Расследование проблем вывода регистрации в анализе опухоли","Определение проблем качества при удалении черепа и нормализации интенсивности","Анализ отчетов об ошибках для шагов предобработки","Определение вероятности роста внутричерепных опухолей менингиома"],"ar":["تصحيح الأخطاء في المعالجة المسبقة للخطوط أنابيب الصور الطبية","تحقيق مشاكل الإخراج المسجل في تحليل الأورام","تحديد مشاكل الجودة في إزالة الجمجمة وتنظيم شدة الإشعاع","تحليل تقارير الأعطال لخطوات المعالجة المسبقة","تحديد احتمال نمو الأورام المخية المنيجية"]},"limitations":{"en":["Requires access to medical imaging data","Limited to preprocessing failure diagnosis and tumor growth prediction","May require additional computational resources for AI-driven analysis"],"zh":["需要访问医疗影像数据","仅限于前处理故障诊断和肿瘤生长预测","可能需要额外的计算资源用于AI驱动的分析"],"ja":["医療画像データへのアクセスが必要","前処理障害診断および腫瘤増殖予測に限定される","AI駆動の解析に追加の計算リソースが必要になる可能性がある"],"ko":["의료 영상 데이터에 대한 접근이 필요함","전처리 실패 진단 및 종양 성장 예측에만 제한됨","AI 주도 분석에 추가 컴퓨팅 리소스가 필요할 수 있음"],"es":["Requiere acceso a datos de imagen médica","Limitado al diagnóstico de fallos de preprocesamiento y predicción de crecimiento de tumores","Puede requerir recursos computacionales adicionales para análisis impulsado por IA"],"fr":["Nécessite un accès aux données d''imagerie médicale","Limité au diagnostic des défaillances de prétraitement et à la prédiction de croissance tumorale","Peut nécessiter des ressources de calcul supplémentaires pour l''analyse impulsée par l''IA"],"de":["Benötigt Zugriff auf medizinische Bilddaten","Begrenzt auf Fehlerdiagnose bei der Vorverarbeitung und Vorhersage des Tumorwachstums","Kann zusätzliche Rechenressourcen für die KI-gesteuerte Analyse erfordern"],"pt":["Exige acesso a dados de imagem médica","Limitado ao diagnóstico de falha de pré-processamento e previsão de crescimento de tumor","Pode exigir recursos computacionais adicionais para análise impulsionada por IA"],"ru":["Требует доступа к медицинским изображениям","Ограничен диагностикой неисправностей предобработки и прогнозированием роста опухоли","Может требовать дополнительных вычислительных ресурсов для анализа, управляемого ИИ"],"ar":["يتطلب الوصول إلى بيانات الصور الطبية","محدود بتشخيص فشل المعالجة المسبقة وتوقعات نمو الأورام","يمكن أن يتطلب موارد حاسوبية إضافية للتحليل الذي يعتمد على الذكاء الاصطناعي"]},"version":4},"contentHash":"d75a5720c3679d33a6edd06689e84165c39ec4e7397dce2f43236718ec9c742a","qualityScore":51}');
