INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MarioPasc/MenGrowth/preprocess-debug', 'preprocess-debug', 'MarioPasc', 'MenGrowth', 'community', 'preprocess-debug MarioPasc MenGrowth community The preprocess-debug skill predicts the probability of growth for meningioma intracranial tumors using AI and aids in diagnosing preprocessing failures. It benefits developers and researchers working with medical imaging data. 预处理调试是一种使用AI预测脑膜瘤生长概率，并诊断预处理失败原因的技术 前処理デバッグは、AIエージェントを使用して髄膜腫の成長確率を予測し、前処理の失敗原因を診断する技術です 전처리 디버깅은 AI를 사용하여 뇌종양의 성장 확률을 예측하고 전처리 실패 원인을 진단하는 기술입니다 Preprocess-debug es una habilidad que ayuda a diagnosticar errores de preprocesamiento en la predicción de la probabilidad de crecimiento de tumores intracraneales Preprocess-debug est une compétence qui aide à diagnostiquer les erreurs de prétraitement dans la prédiction de la probabilité de croissance des tumeurs intracraniennes Preprocess-debug ist eine Fähigkeit, die dabei hilft, Fehler bei der Vorbearbeitung bei der Vorhersage der Wachstumswahrscheinlichkeit von intrakraniellen Tumoren zu diagnostizieren O preprocess-debug é uma ferramenta de IA para diagnosticar falhas de pré-processamento em análises de tumores cerebrais. Aprenda a configurá-lo para melhorar a precisão do seu modelo Preprocess-debug - это инструмент ИИ для диагностики сбоев предобработки в анализе интракраниальных опухолей. Узнайте, как настроить его для улучшения точности вашей модели مرشح المعالجة المسبقة هو أداة ذكاء اصطناعي لتشخيص أعطال المعالجة المسبقة في تحليل الأورام الدماغية. تعرف على إعدادها لتحسين دقة نموذجك how to use preprocess-debug preprocess-debug alternative preprocess-debug setup guide what is preprocess-debug preprocess-debug vs other diagnostic tools preprocess-debug install preprocess-debug for medical imaging preprocess-debug tutorial preprocess-debug troubleshooting 预处理调试 AI预测 脑膜瘤生长概率 前処理失败诊断 注册输出检查 颅骨剥离检查 强度归一化检查 Identifies the failing step in the preprocessing pipeline Checks the visualization directory for last PNG output using ls command Diagnoses preprocessing quality issues or crashes Investigates skull stripping and intensity normalization problems Supports diagnostic workflow for patient data analysis preprocess-debug is a diagnostic tool that identifies preprocessing failures in medical imaging data, specifically for meningioma intracranial tumors.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ContentsUS/Agentic-AI-Paji/gogogo', 'community', 'ContentsUS', 'Agentic-AI-Paji', 'ContentsUS/Agentic-AI-Paji', 'gogogo', 0, 0, 51, '2026-02-27T09:14:35Z', '2026-03-07T03:45:33.813Z', '266f381481f13f601b74def419bf1acc3549fa1a67bbe713cda15a363450b298', '{"id":"ContentsUS/Agentic-AI-Paji/gogogo","name":"gogogo","description":{"en":"gogogo is a skill that executes implementation plans following a detailed plan from the most recent issue. It benefits developers who need to automate their workflow.","zh":"GOGOGO 是一个执行计划的 AI 代理，通过 gh 命令行工具实现自动化流程","ja":"GOGOGO は計画を実施する AI エージェントで、gh コマンドラインツールを使用して自動化プロセスを実現します","ko":"GOGOGO는 계획을 실행하는 AI 도구로 gh 명령줄 도구를 사용하여 자동화 프로세스를 구현합니다","es":"gogogo es una herramienta de Agentic Ai que ejecuta planes de implementación de características y solución de problemas de manera automatizada","fr":"gogogo est un outil d''Agentic Ai qui exécute des plans de mise en œuvre de fonctionnalités et de résolution de problèmes de manière automatisée","de":"gogogo ist ein Tool von Agentic Ai, das Implementierungspläne für Funktionen und Problemlösungen automatisiert ausführt","pt":"O Gogogo é uma habilidade que executa planos de implementação passo a passo com a Agentic Ai. Ele utiliza comandos do GitHub para encontrar a issue mais recente com a label ''plan:'' e executar a implementação.","ru":"Gogogo - это навык, который выполняет планы реализации шаг за шагом с ИИ Агентами. Он использует команды GitHub для поиска последнего вопроса с меткой ''plan:'' и выполнения реализации.","ar":"Gogogo هو مهارة تقوم بتنفيذ خطط التنفيذ بخطوات مع أدوات الذكاء الاصطناعي. يستخدم أوامر GitHub لإيجاد القضية الأحدث مع العلامة ''plan:'' وتنفيذ التنفيذ."},"seo":{"title":{"en":"gogogo: Execute Planned Implementation Setup Guide | AI A...","zh":"GOGOGO 设置指南 - 实现计划执行","ja":"GOGOGO Setup Guide - AIエージェントによる計画実施","ko":"GOGOGO 설정 가이드 - 계획 실행을 위한 AI 도구","es":"Guía de configuración de gogogo para implementación de pl...","fr":"Guide d''installation de gogogo pour l''exécution de plans","de":"Einrichtungsleitfaden für gogogo zur Planumsetzung","pt":"Guia de Configuração do Gogogo - Implementação de Planos ...","ru":"Настройка Gogogo - Реализация Планов с ИИ Агентами","ar":"دليل إعداد Gogogo - تنفيذ الخطط مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to use gogogo to execute implementation plans step-by-step. Learn to automate your workflow with gh issue commands and JSON outputs.","zh":"了解 GOGOGO 的技术细节，实现计划执行和自动化流程","ja":"GOGOGO を使用して計画を実施し、自動化プロセスを実現する方法を学ぶ","ko":"GOGOGO 설정을 통해 계획 실행과 자동화 프로세스를 구현하는 방법을 알아보세요","es":"Aprende a utilizar gogogo para ejecutar planes de implementación de características y solucionar problemas de manera eficiente","fr":"Découvrez comment utiliser gogogo pour exécuter des plans de mise en œuvre de fonctionnalités et résoudre des problèmes de manière efficace","de":"Erfahren Sie, wie Sie gogogo verwenden können, um Implementierungspläne für Funktionen und Problemlösungen effizient auszuführen","pt":"Aprenda a configurar o Gogogo para executar planos de implementação passo a passo com a Agentic Ai","ru":"Узнайте, как настроить Gogogo для реализации планов шаг за шагом с ИИ Агентами","ar":"تعرف على كيفية إعداد Gogogo لتنفيذ خطط التنفيذ بخطوات مع أدوات الذكاء الاصطناعي"},"definition":{"en":"gogogo is an AI agent skill that automates the execution of planned implementations using gh issue commands and JSON outputs.","zh":"GOGOGO 是一个通过 gh 命令行工具执行计划的 AI 代理","ja":"GOGOGO は gh コマンドラインツールを使用して計画を実施する AI エージェントです","ko":"GOGOGO는 gh 명령줄 도구를 사용하여 계획을 실행하는 AI 도구입니다","es":"gogogo es un agente de inteligencia artificial que ejecuta planes de implementación","fr":"gogogo est un agent d''intelligence artificielle qui exécute des plans de mise en œuvre","de":"gogogo ist ein künstlicher Intelligenz-Agent, der Implementierungspläne ausführt","pt":"O Gogogo é uma habilidade de Agentic Ai que executa planos de implementação passo a passo","ru":"Gogogo - это навык ИИ Агентов, который выполняет планы реализации шаг за шагом","ar":"Gogogo هو مهارة من أدوات الذكاء الاصطناعي التي تنفذ خطط التنفيذ بخطوات"},"features":{"en":["Executes implementation plans step-by-step using gh issue commands","Finds the most recent plan issue using `gh issue list` with `--label plan` and `--state open`","Handles JSON outputs from `gh issue list` commands","Automates workflow by following a detailed plan from the most recent issue","Supports `nnn` plan creation and `gogogo` execution commands"],"zh":["使用 gh 命令行工具执行计划","自动化流程实现","支持计划issue的查找和执行","实现计划的 step-by-step 执行","与 nnn 计划工具集成"],"ja":["gh コマンドラインツールを使用して計画を実施","自動化プロセスの実現","計画 issue の検索と実施をサポート","計画の step-by-step 実施を実現","nnn 計画ツールとの統合"],"ko":["gh 명령줄 도구를 사용하여 계획을 실행","자동화 프로세스의 구현","계획 issue의 검색과 실행을 지원","계획의 step-by-step 실행을 구현","nnn 계획 도구와의 통합"],"es":["Ejecuta planes de implementación de características de manera automatizada","Utiliza la línea de comandos de GitHub para encontrar problemas de planificación","Soporta la creación de planes con la herramienta nnn","Permite la implementación de planes de manera secuencial","Integra con herramientas de desarrollo como CLI y GitHub"],"fr":["Exécute des plans de mise en œuvre de fonctionnalités de manière automatisée","Utilise la ligne de commande de GitHub pour trouver des problèmes de planification","Prend en charge la création de plans avec l''outil nnn","Permet la mise en œuvre de plans de manière séquentielle","Intègre avec des outils de développement tels que CLI et GitHub"],"de":["Führt Implementierungspläne für Funktionen automatisiert aus","Verwendet die GitHub-Kommandozeile, um Planungsprobleme zu finden","Unterstützt die Erstellung von Plänen mit dem Tool nnn","Ermöglicht die Ausführung von Plänen in sequenzieller Reihenfolge","Integriert mit Entwicklungstools wie CLI und GitHub"],"pt":["Executa planos de implementação passo a passo","Utiliza comandos do GitHub para encontrar a issue mais recente com a label ''plan:''","Executa a implementação com base no plano detalhado","Suporta a criação de planos com a habilidade ''nnn''","Notifica o usuário se não for encontrado um plano","Utiliza a CLI do GitHub para executar comandos"],"ru":["Выполняет планы реализации шаг за шагом","Использует команды GitHub для поиска последнего вопроса с меткой ''plan:''","Выполняет реализацию на основе детального плана","Поддерживает создание планов с помощью навыка ''nnn''","Уведомляет пользователя, если не найден план","Использует CLI GitHub для выполнения команд"],"ar":["تنفذ خطط التنفيذ بخطوات","يستخدم أوامر GitHub لإيجاد القضية الأحدث مع العلامة ''plan:''","تنفذ التنفيذ بناءً على الخطة المفصلة","يدعم إنشاء خطط مع مهارة ''nnn''","يُخطِر المستخدم إذا لم يُجد خطط","يستخدم واجهة سطر الأوامر GitHub للتشغيل"]},"keywords":{"en":["how to use gogogo","gogogo alternative","gogogo setup guide","what is gogogo","gogogo vs other AI agents","gogogo install","gh issue commands","JSON output automation"],"zh":["GOGOGO","AI 代理","自动化流程","gh 命令行工具","计划执行","AI 工具","自动化","计划 issue","step-by-step 执行"],"ja":["GOGOGO","AI エージェント","自動化プロセス","gh コマンドラインツール","計画実施","AI ツール","自動化","計画 issue","step-by-step 実施"],"ko":["GOGOGO","AI 도구","자동화 프로세스","gh 명령줄 도구","계획 실행","AI 에이전트","자동화","계획 issue","step-by-step 실행"],"es":["gogogo","agente de inteligencia artificial","herramienta de Agentic Ai","implementación de planes","automatización de tareas","desarrollo de software","herramientas de desarrollo","CLI","GitHub","planificación de proyectos"],"fr":["gogogo","agent d''intelligence artificielle","outil d''Agentic Ai","mise en œuvre de plans","automatisation de tâches","développement de logiciels","outils de développement","CLI","GitHub","planification de projets"],"de":["gogogo","künstlicher Intelligenz-Agent","Tool von Agentic Ai","Implementierung von Plänen","Automatisierung von Aufgaben","Software-Entwicklung","Entwicklungstools","CLI","GitHub","Projektplanung"],"pt":["Gogogo","Agentic Ai","Implementação de planos","GitHub","CLI","Desenvolvimento de software","Automatização de processos","Ferramentas de desenvolvimento","Tecnologias de desenvolvimento"],"ru":["Gogogo","ИИ Агенты","Реализация планов","GitHub","CLI","Разработка программного обеспечения","Автоматизация процессов","Инструменты разработки","Технологии разработки"],"ar":["Gogogo","أدوات الذكاء الاصطناعي","تنفيذ الخطط","GitHub","واجهة سطر الأوامر","تطوير البرمجيات","أتمتة العمليات","أدوات التطوير","تكنولوجيا التطوير"]}},"owner":"ContentsUS","repo":"Agentic-AI-Paji","repoPath":"ContentsUS/Agentic-AI-Paji","stars":0,"forks":0,"updatedAt":"2026-02-27T09:14:35Z","topics":[],"category":"community","skillMd":{"name":"gogogo","description":"Execute the most recent plan issue step-by-step. Use when user types gogogo or when ready to implement a planned feature/fix. Follow the plan, make code changes, test, and create PR.","bodyPreview":"# GOGOGO - Execute Planned Implementation\n\n## Purpose\nExecute the implementation plan step-by-step, following the detailed plan from the most recent \"plan:\" issue.\n\n## When to Use\n- User explicitly types `gogogo`\n- After creating a plan with `nnn`\n- Ready to implement a planned feature or fix\n\n## Steps\n\n### 1. Find Implementation Issue\n\nFind the most recent plan issue:\n```bash\ngh issue list --label \"plan\" --state open --limit 1 --json number,title\n```\n\n**If no plan issue found:**\n- Tell user: \"N","body":"# GOGOGO - Execute Planned Implementation\n\n## Purpose\nExecute the implementation plan step-by-step, following the detailed plan from the most recent \"plan:\" issue.\n\n## When to Use\n- User explicitly types `gogogo`\n- After creating a plan with `nnn`\n- Ready to implement a planned feature or fix\n\n## Steps\n\n### 1. Find Implementation Issue\n\nFind the most recent plan issue:\n```bash\ngh issue list --label \"plan\" --state open --limit 1 --json number,title\n```\n\n**If no plan issue found:**\n- Tell user: \"No plan issue found. Create one with `nnn` first.\"\n- Stop execution\n\n**If plan issue found:**\n- Display: \"Found plan: #[number] - [title]\"\n- Load the plan details:\n```bash\ngh issue view [number]\n```\n\n### 2. Prepare Branch\n\n```bash\n# Check current branch\nCURRENT_BRANCH=$(git branch --show-current)\n\n# If on main, create feature branch\nif [ \"$CURRENT_BRANCH\" = \"main\" ]; then\n  BRANCH_NAME=\"feat/issue-[number]-[description]\"\n  git checkout -b $BRANCH_NAME\nfi\n\n# Ensure working directory is clean\ngit status\n```\n\n### 3. Execute Implementation\n\n**Follow the plan step-by-step:**\n\nFor each phase in the plan:\n1. **Announce Phase**: Tell user \"Starting Phase X: [phase name]\"\n2. **Read Required Files**: Use `Read` tool for files mentioned in the phase\n3. **Make Changes**: Use `Edit` or `Write` tools as needed\n4. **Verify Changes**: Check that changes compile/work\n5. **Update Checklist**: Comment on the issue to mark steps complete\n\n**Important:**\n- Follow the plan exactly - don''t add unplanned features\n- Keep changes focused and minimal\n- Test after each significant change\n- If you discover issues with the plan, ask user before deviating\n\n### 4. Test & Verify\n\nAfter implementation:\n```bash\n# Run build (if applicable)\n[build-command]\n\n# Run tests (if applicable)\n[test-command]\n\n# Manual verification\n# Test key scenarios mentioned in the plan\n```\n\n**If tests fail:**\n- Fix the issues\n- Re-run tests\n- Don''t proceed until tests pass\n\n### 5. Commit & Push\n\n```bash\n# Stage all changes\ngit add -A\n\n# Create descriptive commit\ngit commit -m \"$(cat <<''EOF''\nfeat: [Brief description from plan]\n\n- What: [Specific changes made]\n- Why: [Reason from plan]\n- Impact: [What this affects]\n\nImplements #[plan-issue-number]\nEOF\n)\"\n\n# Push to remote\ngit push -u origin $(git branch --show-current)\n```\n\n### 6. Create Pull Request\n\n```bash\ngh pr create --title \"feat: [Same as commit title]\" --body \"$(cat <<''EOF''\n## Summary\n[Brief overview of what was implemented]\n\n## Implementation Details\n- [Key change 1]\n- [Key change 2]\n- [Key change 3]\n\n## Testing\n- [x] Build successful\n- [x] Tests passing\n- [x] Manual testing completed\n\n## Related Issues\nImplements #[plan-issue-number]\n\n---\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\nEOF\n)\"\n```\n\n### 7. Update Plan Issue\n\nComment on the plan issue:\n```bash\ngh issue comment [plan-number] --body \"✅ Implementation complete!\n\n**PR Created:** #[pr-number]\n\n**What was done:**\n- [Summary of implementation]\n\n**Test Results:**\n- Build: ✅ Passing\n- Tests: ✅ All passing\n- Manual: ✅ Verified\n\nReady for review!\"\n```\n\n### 8. Report to User\n\nProvide a complete summary:\n```\n✅ Implementation Complete!\n\n**Plan Issue:** #[plan-number]\n**PR Created:** #[pr-number]\n**Branch:** [branch-name]\n\n**Changes:**\n- [file1]: [what changed]\n- [file2]: [what changed]\n\n**Tests:** ✅ All passing\n**Build:** ✅ Successful\n\n**Next steps:**\n1. Review the PR: [pr-url]\n2. Request review from team\n3. Merge when approved\n\n⚠️ **IMPORTANT:** Don''t merge until user explicitly approves!\n```\n\n## Important Notes\n- **Follow the Plan**: Don''t deviate without asking\n- **Test Everything**: Never skip testing\n- **Commit Often**: Make logical commits as you progress\n- **Safety First**: Follow all git safety rules (no --force)\n- **Never Merge**: Only create PR, wait for user approval\n- **Ask Questions**: If plan is unclear, ask user before proceeding\n- **Update Issue**: Keep the plan issue updated with progress\n\n## Error Handling\n\n**If build fails:**\n1. Read error messages carefully\n2. Fix the issues\n3. Re-run build\n4. Continue only when passing\n\n**If plan is incomplete:**\n1. Ask user for clarification\n2. Update plan issue with questions\n3. Wait for user response\n\n**If stuck:**\n1. Document what you tried\n2. Comment on plan issue with blockers\n3. Ask user for guidance\n\n## Success Criteria\n- ✅ All plan phases completed\n- ✅ All tests passing\n- ✅ Build successful\n- ✅ PR created (not merged)\n- ✅ Plan issue updated\n- ✅ User provided with clear summary\n"},"lastSynced":"2026-03-07T03:45:33.813Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated workflow execution following detailed implementation plans.","zh":"适用于需要自动执行工作流的开发代理，遵循详细的实现计划。","ja":"詳細な実装計画に従って自動化されたワークフロー実行が必要な開発エージェントに適しています。","ko":"세부적인 구현 계획을 따라 자동화된 워크플로우 실행이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan ejecución de flujo de trabajo automatizada siguiendo planes de implementación detallados.","fr":"Parfait pour les agents de développement ayant besoin d''une exécution de flux de travail automatisée suivant des plans de mise en œuvre détaillés.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Workflow-Ausführung nach detaillierten Implementierungsplänen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de execução de fluxo de trabalho automatizado seguindo planos de implementação detalhados.","ru":"Идеально подходит для агентов разработки, которым требуется автоматизированная реализация рабочих процессов в соответствии с подробными планами реализации.","ar":"مثالي لعمليات وكلاء التطوير التي تحتاج إلى تنفيذ تلقائي لتدفق العمل بعد خطط تنفيذ مفصلة."},"recommendation":{"en":"Empowers agents to execute step-by-step implementation plans using GitHub issues, leveraging `gh` commands for seamless project management and automation, specifically with `--label` and `--state` flags for targeted issue retrieval.","zh":"使代理能够使用GitHub问题执行一步步的实现计划，利用 `gh` 命令实现无缝的项目管理和自动化，特别是使用 `--label` 和 `--state` 标志来检索目标问题。","ja":"エージェントがGitHubの問題を使用してステップバイステップの実装計画を実行できるようにし、`gh` コマンドを使用してシームレスなプロジェクト管理と自動化を実現し、特に `--label` と `--state` フラグを使用して対象の問題を取得します。","ko":"에이전트가 GitHub 이슈를 사용하여 단계별 구현 계획을 실행할 수 있도록 하며, `gh` 명령을 사용하여无缝な 프로젝트 관리 및 자동화를 구현하며, 특히 `--label` 및 `--state` 플래그를 사용하여 대상 이슈를 검색합니다.","es":"Habilita a los agentes a ejecutar planes de implementación paso a paso utilizando problemas de GitHub, aprovechando los comandos `gh` para una gestión y automatización de proyectos sin problemas, específicamente con las banderas `--label` y `--state` para la recuperación de problemas dirigida.","fr":"Permet aux agents d''exécuter des plans de mise en œuvre étape par étape en utilisant des problèmes GitHub, en exploitant les commandes `gh` pour une gestion et une automation de projet sans rupture, spécifiquement avec les drapeaux `--label` et `--state` pour la récupération ciblée de problèmes.","de":"Ermächtigt Agenten, Schritt-für-Schritt-Implementierungspläne mithilfe von GitHub-Problemen auszuführen, indem sie die `gh`-Befehle für eine nahtlose Projektverwaltung und -automatisierung nutzen, insbesondere mit den Flags `--label` und `--state` für die gezielte Problemabfrage.","pt":"Permite que os agentes executem planos de implementação passo a passo usando problemas do GitHub, aproveitando comandos `gh` para gerenciamento de projeto e automação sem problemas, especificamente com flags `--label` e `--state` para recuperação direcionada de problemas.","ru":"Наделяет агентов возможностью реализовывать пошаговые планы реализации с использованием проблем GitHub, используя команды `gh` для беспрепятственного управления проектами и автоматизации, в частности с флагами `--label` и `--state` для целевой выборки проблем.","ar":"تمكن الوكلاء من تنفيذ خطط التنفيذ خطوة بخطوة باستخدام قضايا GitHub، واستخدام أوامر `gh` لإدارة المشروع والتنفيذ التلقائي دون مشاكل، خصيصًا مع أعلام `--label` و `--state` لاسترجاع القضايا المستهدفة."},"useCases":{"en":["Automating feature implementation workflows","Executing planned fixes with precision","Streamlining development processes using recent ''plan:'' issues"],"zh":["自动执行功能实现工作流","精确执行计划修复","使用最近的 ''plan:'' 问题来简化开发流程"],"ja":["機能実装ワークフローの自動化","計画修復の精密実行","最近の ''plan:'' 問題を使用して開発プロセスを合理化"],"ko":["기능 구현 워크플로우의 자동화","계획된 수정의 정밀한 실행","최근의 ''plan:'' 이슈를 사용하여 개발 프로세스를 간소화"],"es":["Automatización de flujos de trabajo de implementación de características","Ejecución de correcciones planificadas con precisión","Optimización de procesos de desarrollo mediante problemas recientes ''plan:''"],"fr":["Automatisation des flux de travail d''implémentation de fonctionnalités","Exécution de corrections planifiées avec précision","Optimisation des processus de développement à l''aide de problèmes récents ''plan:''"],"de":["Automatisierung von Implementierungs-Workflows für Funktionen","Ausführung geplanter Korrekturen mit Präzision","Optimierung von Entwicklungsprozessen unter Verwendung von aktuellen ''plan:''-Problemen"],"pt":["Automatizar fluxos de trabalho de implementação de recursos","Executar correções planejadas com precisão","Otimizar processos de desenvolvimento usando problemas recentes ''plan:''"],"ru":["Автоматизация рабочих процессов реализации функций","Выполнение запланированных исправлений с точностью","Оптимизация процессов разработки с использованием недавних проблем ''plan:''"],"ar":["توتير تدفقات العمل لتنفيذ الميزات","تنفيذ الإصلاحات المخطط لها بدقة","تسهيل عمليات التطوير باستخدام قضايا ''plan:'' الأخيرة"]},"limitations":{"en":["Requires GitHub issue access","Dependent on ''plan:'' labeled issues","Limited to open issues with the ''plan'' label"],"zh":["需要GitHub问题访问权限","依赖于 ''plan:'' 标记的问题","仅限于带有 ''plan'' 标签的打开问题"],"ja":["GitHub問題へのアクセスが必要","''plan:'' ラベルが付いた問題に依存","''plan'' ラベルが付いたオープン問題のみに限定"],"ko":["GitHub 이슈 액세스가 필요함","''plan:'' 레이블이 있는 문제에 의존","''plan'' 레이블이 있는 열린 이슈에만 محدود"],"es":["Requiere acceso a problemas de GitHub","Dependiente de problemas etiquetados con ''plan:''","Limitado a problemas abiertos con la etiqueta ''plan''"],"fr":["Nécessite un accès aux problèmes GitHub","Dépendant de problèmes étiquetés ''plan:''","Limité aux problèmes ouverts avec l''étiquette ''plan''"],"de":["Benötigt Zugriff auf GitHub-Probleme","Abhängig von mit ''plan:'' gekennzeichneten Problemen","Begrenzt auf offene Probleme mit dem Label ''plan''"],"pt":["Requer acesso a problemas do GitHub","Dependente de problemas com rótulo ''plan:''","Limitado a problemas abertos com o rótulo ''plan''"],"ru":["Требует доступа к проблемам GitHub","Зависит от проблем с меткой ''plan:''","Ограничен проблемами в открытом состоянии с меткой ''plan''"],"ar":["يتطلب الوصول إلى قضايا GitHub","يتوقف على قضايا ذات علامة ''plan:''","محدود بالقضايا المفتوحة بعلامة ''plan''"]},"version":4},"contentHash":"266f381481f13f601b74def419bf1acc3549fa1a67bbe713cda15a363450b298","qualityScore":51}');
