INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ContentsUS/Agentic-AI-Paji/gogogo', 'gogogo', 'ContentsUS', 'Agentic-AI-Paji', 'community', 'gogogo ContentsUS Agentic-AI-Paji community gogogo is a skill that executes implementation plans following a detailed plan from the most recent issue. It benefits developers who need to automate their workflow. GOGOGO 是一个执行计划的 AI 代理，通过 gh 命令行工具实现自动化流程 GOGOGO は計画を実施する AI エージェントで、gh コマンドラインツールを使用して自動化プロセスを実現します GOGOGO는 계획을 실행하는 AI 도구로 gh 명령줄 도구를 사용하여 자동화 프로세스를 구현합니다 gogogo es una herramienta de Agentic Ai que ejecuta planes de implementación de características y solución de problemas de manera automatizada gogogo est un outil d''Agentic Ai qui exécute des plans de mise en œuvre de fonctionnalités et de résolution de problèmes de manière automatisée gogogo ist ein Tool von Agentic Ai, das Implementierungspläne für Funktionen und Problemlösungen automatisiert ausführt O Gogogo é uma habilidade que executa planos de implementação passo a passo com a Agentic Ai. Ele utiliza comandos do GitHub para encontrar a issue mais recente com a label ''plan:'' e executar a implementação. Gogogo - это навык, который выполняет планы реализации шаг за шагом с ИИ Агентами. Он использует команды GitHub для поиска последнего вопроса с меткой ''plan:'' и выполнения реализации. Gogogo هو مهارة تقوم بتنفيذ خطط التنفيذ بخطوات مع أدوات الذكاء الاصطناعي. يستخدم أوامر GitHub لإيجاد القضية الأحدث مع العلامة ''plan:'' وتنفيذ التنفيذ. how to use gogogo gogogo alternative gogogo setup guide what is gogogo gogogo vs other AI agents gogogo install gh issue commands JSON output automation GOGOGO AI 代理 自动化流程 gh 命令行工具 计划执行 AI 工具 自动化 计划 issue step-by-step 执行 Executes implementation plans step-by-step using gh issue commands Finds the most recent plan issue using `gh issue list` with `--label plan` and `--state open` Handles JSON outputs from `gh issue list` commands Automates workflow by following a detailed plan from the most recent issue Supports `nnn` plan creation and `gogogo` execution commands gogogo is an AI agent skill that automates the execution of planned implementations using gh issue commands and JSON outputs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('thewoolleyman/tab-groups-windows-list/land', 'community', 'thewoolleyman', 'tab-groups-windows-list', 'thewoolleyman/tab-groups-windows-list', 'land', 0, 0, 51, '2026-03-06T12:59:22.224Z', '2026-03-06T14:09:47.085Z', '69511ebbb285b4b4fc3733f87e76559706835228e8d665c33377f24398e1cb59', '{"id":"thewoolleyman/tab-groups-windows-list/land","name":"land","description":{"en":"The land skill automates the git workflow, ensuring a clean and committed repo state. It benefits AI agents by streamlining their work sessions.","zh":"Land技能是基于Steve Yegge的''Landing the Plane''工作流程，确保代码仓库在工作会话结束时保持清洁和完整","ja":"Landスキルは、Steve Yeggeの''Landing the Plane''ワークフローに基づいており、作業セッションの終了時にコードリポジトリがクリーンで完了することを保証する","ko":"Land 스킬은 Steve Yegge의 ''Landing the Plane'' 워크플로우에 기반하여 코드 저장소가 작업 세션이 종료될 때 깨끗하고 완료되도록 보장합니다","es":"El agente ''land'' ayuda a dejar el repositorio en un estado limpio y comprometido con Git. Se basa en el flujo de trabajo ''Landing the Plane'' de Steve Yegge.","fr":"L''agent ''land'' aide à laisser le référentiel dans un état propre et validé avec Git. Il est basé sur le flux de travail ''Landing the Plane'' de Steve Yegge.","de":"Der Agent ''land'' hilft, das Repository in einem sauberen und committeten Zustand mit Git zu hinterlassen. Er basiert auf dem Workflow ''Landing the Plane'' von Steve Yegge.","pt":"O land é uma ferramenta para garantir que o repositório esteja em um estado limpo e atualizado, com commit e push bem-sucedidos.","ru":"Land - это инструмент для обеспечения чистого и актуального состояния репозитория, с успешным коммитом и пушем.","ar":"يعد land أداة لضمان أن يكون المستودع في حالة نظيفة و محدثة، مع التزام و دفع بنجاح."},"seo":{"title":{"en":"land: Git Workflow Automation for AI Agents | AI Agent Skill","zh":"Land技能设置指南 - Git推送和代码提交","ja":"Landスキル設定ガイド - Gitプッシュとコードコミット","ko":"Land 스킬 설정 가이드 - Git 푸시 및 코드 커밋","es":"Guía de configuración para ''land'' - Mejores prácticas par...","fr":"Guide de configuration pour ''land'' - Meilleures pratiques...","de":"Konfigurationsleitfaden für ''land'' - Best Practices für K...","pt":"Guia de Configuração do Land: Commit e Push com Sucesso","ru":"ИИ Агенты: Руководство по Настройке Land для Безопасного ...","ar":"دليل إعداد Land: التزام و دفع بنجاح"},"description":{"en":"Learn how to land the plane with git push automation and discover the best practices for wrapping up work sessions with a clean repo state","zh":"了解Land技能的技术细节，包括Git推送和代码提交，确保代码仓库的清洁和完整性","ja":"Landスキルの技術的詳細を学び、Gitプッシュとコードコミットを使用してコードリポジトリの整理と完了を保証する","ko":"Land 스킬의 기술적 세부 사항을 학습하고 Git 푸시 및 코드 커밋을 사용하여 코드 저장소의 정리와 완성을 보장합니다","es":"Aprende a utilizar ''land'' para dejar tu repositorio en un estado limpio y comprometido con Git. ¡Descubre cómo funciona este agente de AI!","fr":"Découvrez comment utiliser ''land'' pour laisser votre référentiel dans un état propre et validé avec Git. Apprenez-en plus sur cet outil d''IA !","de":"Erfahren Sie, wie Sie ''land'' verwenden, um Ihr Repository in einem sauberen und committeten Zustand mit Git zu hinterlassen. Entdecken Sie, wie dieser KI-Age...","pt":"Aprenda a utilizar o land para deixar o repositório em um estado limpo e atualizado, com dicas práticas para commit e push","ru":"Узнайте, как использовать land для безопасного коммита и пуша, и оставьте репозиторий в чистом состоянии","ar":"تعلم كيفية استخدام land لإجراء التزام و دفع بنجاح، مع نصائح عملية لتحديث المستودع"},"definition":{"en":"land is a git workflow automation process that ensures a clean, committed, and pushed repository state","zh":"Land技能是一种基于Git的代码提交和推送技术，确保代码仓库的清洁和完整性","ja":"Landスキルは、Gitに基づくコードコミットとプッシュ技術であり、コードリポジトリの整理と完了を保証する","ko":"Land 스킬은 Git 기반의 코드 커밋 및 푸시 기술로 코드 저장소의 정리와 완성을 보장합니다","es":"El agente ''land'' es una herramienta que ayuda a los desarrolladores a dejar su repositorio en un estado limpio y comprometido con Git.","fr":"L''agent ''land'' est un outil qui aide les développeurs à laisser leur référentiel dans un état propre et validé avec Git.","de":"Der Agent ''land'' ist ein Tool, das Entwicklern hilft, ihr Repository in einem sauberen und committeten Zustand mit Git zu hinterlassen.","pt":"O que é land? É uma ferramenta para garantir a limpeza e atualização do repositório.","ru":"Что такое land? Это инструмент для обеспечения чистоты и актуальности репозитория.","ar":"ما هو land؟ إنه أداة لضمان نظافة و تحديث المستودع."},"features":{"en":["Automates git workflow using git push command","Ensures a clean and committed repository state","Wraps up work sessions with a pushed repo state","Follows Steve Yegge''s ''Landing the Plane'' workflow","Integrates with Beads agent memory system","Pushes changes to the repository until git push succeeds"],"zh":["基于Steve Yegge的''Landing the Plane''工作流程","使用Git推送和代码提交技术","确保代码仓库的清洁和完整性","支持代码仓库的管理和维护","提高代码的可靠性和稳定性"],"ja":["Steve Yeggeの''Landing the Plane''ワークフローに基づく","Gitプッシュとコードコミット技術を使用","コードリポジトリの整理と完了を保証","コードリポジトリの管理とメンテナンスをサポート","コードの信頼性と安定性を向上"],"ko":["Steve Yegge의 ''Landing the Plane'' 워크플로우에 기반","Git 푸시 및 코드 커밋 기술을 사용","코드 저장소의 정리와 완성을 보장","코드 저장소의 관리와 유지 보수를 지원","코드의 신뢰성과 안정성을 향상"],"es":["Utiliza Git para dejar el repositorio en un estado limpio","Se basa en el flujo de trabajo ''Landing the Plane'' de Steve Yegge","Realiza un push automático para asegurar el estado del repositorio","Ayuda a evitar problemas con el estado del repositorio","Es compatible con la línea de comandos de Git"],"fr":["Utilise Git pour laisser le référentiel dans un état propre","Est basé sur le flux de travail ''Landing the Plane'' de Steve Yegge","Effectue un push automatique pour assurer l''état du référentiel","Aide à éviter les problèmes avec l''état du référentiel","Est compatible avec la ligne de commande de Git"],"de":["Verwendet Git, um das Repository in einem sauberen Zustand zu hinterlassen","Basiert auf dem Workflow ''Landing the Plane'' von Steve Yegge","Führt einen automatischen Push durch, um den Zustand des Repositorys zu sichern","Hilft, Probleme mit dem Zustand des Repositorys zu vermeiden","Ist kompatibel mit der Git-Kommandozeile"],"pt":["Commit e push automático","Verificação de estado do repositório","Integração com o GitHub","Suporte a comandos Git","Notificação de sucesso ou falha"],"ru":["Автоматический коммит и пуш","Проверка состояния репозитория","Интеграция с GitHub","Поддержка команд Git","Уведомление о успехе или провале"],"ar":["التزام و دفع آلي","فحص حالة المستودع","التكامل مع GitHub","دعم أوامر Git","إشعار بنجاح أو فشل"]},"keywords":{"en":["how to use land","what is land","land alternative","land vs git flow","land install","land setup guide","git workflow automation","AI agent workflow","repository management"],"zh":["Land技能","Git推送","代码提交","代码仓库管理","代码可靠性","AI工具","AIエージェント","代码完整性"],"ja":["Landスキル","Gitプッシュ","コードコミット","コードリポジトリ管理","コードの信頼性","AIエージェント","コードの完全性","開発ツール"],"ko":["Land 스킬","Git 푸시","코드 커밋","코드 저장소 관리","코드의 신뢰성","AI 에이전트","코드의 완전성","개발 도구"],"es":["agente de AI para Git","land agente","configuración de land","mejores prácticas para land","Git push automático","estado del repositorio","flujo de trabajo Landing the Plane","Steve Yegge","herramientas de desarrollo"],"fr":["agent d''IA pour Git","agent land","configuration de land","meilleures pratiques pour land","push Git automatique","état du référentiel","flux de travail Landing the Plane","Steve Yegge","outils de développement"],"de":["KI-Agent für Git","land-Agent","Konfiguration von land","Best Practices für land","automatischer Git-Push","Zustand des Repositorys","Workflow Landing the Plane","Steve Yegge","Entwicklungstools"],"pt":["land ai","commit e push","repositório git","ferramenta de desenvolvimento","integração com github","comandos git","notificação de sucesso"],"ru":["ИИ Агенты land","коммит и пуш","репозиторий git","инструмент разработки","интеграция с github","команды git","уведомление о успехе"],"ar":["وكلاء الذكاء الاصطناعي land","التزام و دفع","مستودع git","أداة تطوير","التكامل مع github","أوامر git","إشعار بنجاح"]}},"owner":"thewoolleyman","repo":"tab-groups-windows-list","repoPath":"thewoolleyman/tab-groups-windows-list","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.224Z","topics":[],"category":"community","skillMd":{"name":"land","description":"Land the plane: commit all changes, push, and confirm clean state","bodyPreview":"# Land the Plane\n\n> Based on Steve Yegge''s \"Landing the Plane\" workflow from the Beads agent memory system.\n> See: https://github.com/steveyegge/beads/blob/ff67b88/AGENT_INSTRUCTIONS.md#landing-the-plane\n\nYou are wrapping up a work session. Your job is to leave the repo in a clean, committed, pushed state with nothing left dangling.\n\n**The plane is NOT landed until `git push` succeeds.** Do not stop before pushing. Do not say \"ready to push when you are\" -- that is a failure. YOU must push.\n\n##","body":"# Land the Plane\n\n> Based on Steve Yegge''s \"Landing the Plane\" workflow from the Beads agent memory system.\n> See: https://github.com/steveyegge/beads/blob/ff67b88/AGENT_INSTRUCTIONS.md#landing-the-plane\n\nYou are wrapping up a work session. Your job is to leave the repo in a clean, committed, pushed state with nothing left dangling.\n\n**The plane is NOT landed until `git push` succeeds.** Do not stop before pushing. Do not say \"ready to push when you are\" -- that is a failure. YOU must push.\n\n## Steps\n\nFollow these steps IN ORDER. Do not skip any step. Do not ask for confirmation between steps -- just execute the full sequence and report the results at the end.\n\n### 1. Check for uncommitted work\n\nRun `git status` and `git diff --stat` to see what''s changed. If there are NO changes (working tree clean, nothing untracked), skip to step 7 and report \"Already clean -- nothing to land.\"\n\n### 2. Stage changes\n\nStage all modified and untracked files. Use `git add` with specific file paths -- do NOT use `git add -A` or `git add .`. Review the list and exclude:\n\n- `.env` files or anything that looks like secrets/credentials\n- Large binary files that shouldn''t be in git\n- Runtime/temp files (`.pid`, `.log`, `node_modules/`, etc.)\n\nIf you find files that should be excluded, mention them in your summary.\n\n### 3. Sync beads issue state\n\nRun `bd sync` to commit beads issue changes to git. This ensures any issue updates from this session (status changes, new issues, closed issues) are captured before the final push.\n\nIf `bd` is not installed or `.beads/` doesn''t exist, skip this step silently.\n\n### 4. Commit\n\nCreate a single commit with a clear, descriptive message summarizing ALL the work done in this session. Look at the diff and recent conversation context to write a meaningful message -- not a generic \"checkpoint\" or \"wip\".\n\nFormat:\n```\n<concise summary of what changed>\n\n<optional body with details if the change is non-trivial>\n\nCo-Authored-By: Claude Opus 4.5 <noreply@anthropic.com>\n```\n\n### 5. Push -- NON-NEGOTIABLE\n\nPull with rebase first, then push to the remote tracking branch:\n\n```\ngit pull --rebase\ngit push\n```\n\nIf the push fails, resolve the issue and retry. Do NOT force push. If it cannot be resolved, report the specific error.\n\n### 6. Clean up git state\n\n```\ngit stash list\n```\n\nIf there are stale stashes, note them in the summary (do not drop them without being asked).\n\n### 7. Confirm clean state\n\nRun `git status` one final time. Report:\n\n- The commit hash and message\n- The branch and remote\n- Whether the working tree is clean\n- Any files that were intentionally skipped\n\n### Output format\n\nReport a brief summary like:\n\n```\nLanded. <commit-hash> on <branch> -> <remote>\n  <one-line commit message>\n  <N> files changed\n  Working tree: clean\n```\n\nOr if there were issues:\n\n```\nPartial landing:\n  Committed: <hash>\n  Push: failed (behind remote -- pull needed)\n  Skipped: .env, build/output.bin\n  Stale stashes: 2 (run `git stash list` to review)\n```\n"},"lastSynced":"2026-03-06T14:09:47.085Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated git workflow management.","zh":"适合需要自动化git工作流管理的开发代理。","ja":"開発エージェントが自動化されたgitワークフローマネージメントを必要とする場合に適しています。","ko":"자동화된 git 워크플로우 관리가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de flujo de trabajo automatizada de git.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de workflow git automatisée.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte git-Workflow-Verwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de gerenciamento de workflow do git automatizado.","ru":"Идеально для агентов разработки, которым требуется автоматизированное управление рабочим процессом git.","ar":"مثالي للوكلاء النموزجيين الذين يحتاجون إلى إدارة تدفق العمل التلقائي لجيت."},"recommendation":{"en":"Empowers agents to maintain a clean and committed repository state using git push, ensuring seamless workflow sessions with protocols like HTTPS or SSH.","zh":"赋予代理维护干净和提交的存储库状态的能力，使用git push，确保与HTTPS或SSH等协议的无缝工作流会话。","ja":"エージェントがクリーンでコミットされたリポジトリ状態を維持する能力を付与し、git pushを使用してHTTPSまたはSSHなどのプロトコルを使用したシームレスなワークフローセッションを保証します。","ko":"에이전트가 깨끗하고 커밋된 저장소 상태를 유지할 수 있는 능력을 부여하며, git push를 사용하여 HTTPS 또는 SSH와 같은 프로토콜을 사용한 무정지 워크플로우 세션을 보장합니다.","es":"Habilita a los agentes a mantener un estado de repositorio limpio y comprometido utilizando git push, lo que garantiza sesiones de flujo de trabajo sin problemas con protocolos como HTTPS o SSH.","fr":"Permet aux agents de maintenir un état de référentiel propre et validé en utilisant git push, garantissant ainsi des sessions de workflow sans heurts avec des protocoles comme HTTPS ou SSH.","de":"Ermächtigt die Mittel, einen sauberen und übertragenen Repository-Zustand mit git push zu wahren, was wiederum eine reibungslose Arbeitsumgebung mit Protokollen wie HTTPS oder SSH gewährleistet.","pt":"Habilita os agentes a manter um estado de repositório limpo e comprometido usando git push, garantindo sessões de trabalho sem interrupções com protocolos como HTTPS ou SSH.","ru":"Наделяет агентов возможностью поддерживать чистое и зафиксированное состояние репозитория с помощью git push, обеспечивая бесперебойные рабочие сессии с протоколами như HTTPS или SSH.","ar":"يمنح الوكلاء القدرة على الحفاظ على حالة مستودع نظيف ومعتمد باستخدام git push، مما يضمن جلسات عمل بدون انقطاع مع بروتوكولات مثل HTTPS أو SSH."},"useCases":{"en":["Automating git workflow for clean repo states","Ensuring successful git push for committed changes","Streamlining work sessions with reliable repo management"],"zh":["自动化git工作流以保持干净的repo状态","确保成功的git push以提交更改","简化工作会话，具有可靠的repo管理"],"ja":["クリーンなリポジトリ状態を維持するためのgitワークフローの自動化","コミットされた変更のための成功したgit pushの確保","信頼性の高いリポジトリ管理を備えたワークフローセッションの簡素化"],"ko":["깨끗한 저장소 상태를 유지하기 위한 git 워크플로우 자동화","커밋된 변경 사항에 대한 성공적인 git push 보장","안정적인 저장소 관리를 통해 워크플로우 세션 간소화"],"es":["Automatizar el flujo de trabajo de git para estados de repositorio limpios","Garantizar un git push exitoso para cambios comprometidos","Optimizar las sesiones de trabajo con una gestión de repositorio confiable"],"fr":["Automatiser le workflow git pour des états de référentiel propres","Assurer un git push réussi pour les modifications validées","Optimiser les sessions de travail avec une gestion de référentiel fiable"],"de":["Automatisierung des git-Workflows für saubere Repository-Zustände","Sicherstellung eines erfolgreichen git push für übertragene Änderungen","Optimierung der Arbeitsumgebung mit zuverlässiger Repository-Verwaltung"],"pt":["Automatizar o fluxo de trabalho do git para estados de repositório limpos","Garantir um git push bem-sucedido para alterações comprometidas","Otimizar as sessões de trabalho com gerenciamento de repositório confiável"],"ru":["Автоматизировать рабочий процесс git для чистых состояний репозитория","Обеспечить успешный git push для зафиксированных изменений","Оптимизировать рабочие сессии с надежным управлением репозиторием"],"ar":["تutomatizar تدفق العمل لجيت لتحقيق حالة مستودع نظيف","تأكيد نجاح git push للتغييرات المعتمدة","تسهيل جلسات العمل مع إدارة مستودع موثوق بها"]},"limitations":{"en":["Requires git installation and configuration","Needs active repository access","Must successfully execute git push to land the plane"],"zh":["需要git安装和配置","需要活动仓库访问","必须成功执行git push以达到预期"],"ja":["gitのインストールと構成が必要","アクティブなリポジトリへのアクセスが必要","目的地に到達するためにgit pushを正常に実行する必要がある"],"ko":["git 설치 및 구성이 필요합니다.","활성 저장소 액세스가 필요합니다.","목표에 도달하려면 git push를 성공적으로 실행해야 합니다."],"es":["Requiere instalación y configuración de git","Necesita acceso activo al repositorio","Debe ejecutar con éxito git push para aterrizar"],"fr":["Nécessite l''installation et la configuration de git","A besoin d''un accès actif au référentiel","Doit exécuter avec succès git push pour atterrir"],"de":["Benötigt die Installation und Konfiguration von git","Benötigt aktiven Zugriff auf das Repository","Muss git push erfolgreich ausführen, um zu landen"],"pt":["Requer instalação e configuração do git","Necessita de acesso ativo ao repositório","Deve executar com sucesso o git push para concluir a tarefa"],"ru":["Требует установки и настройки git","Требует активного доступа к репозиторию","Должен успешно выполнить git push, чтобы завершить работу"],"ar":["يتطلب تثبيت وضبط جيت","يتطلب وصول نشط إلى المستودع","يجب أن ينفذ بنجاح git push لإنجاز المهمة"]},"version":4},"contentHash":"69511ebbb285b4b4fc3733f87e76559706835228e8d665c33377f24398e1cb59","qualityScore":51}');
