INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('thewoolleyman/tab-groups-windows-list/land', 'land', 'thewoolleyman', 'tab-groups-windows-list', 'community', 'land thewoolleyman tab-groups-windows-list community The land skill automates the git workflow, ensuring a clean and committed repo state. It benefits AI agents by streamlining their work sessions. Land技能是基于Steve Yegge的''Landing the Plane''工作流程，确保代码仓库在工作会话结束时保持清洁和完整 Landスキルは、Steve Yeggeの''Landing the Plane''ワークフローに基づいており、作業セッションの終了時にコードリポジトリがクリーンで完了することを保証する Land 스킬은 Steve Yegge의 ''Landing the Plane'' 워크플로우에 기반하여 코드 저장소가 작업 세션이 종료될 때 깨끗하고 완료되도록 보장합니다 El agente ''land'' ayuda a dejar el repositorio en un estado limpio y comprometido con Git. Se basa en el flujo de trabajo ''Landing the Plane'' de Steve Yegge. L''agent ''land'' aide à laisser le référentiel dans un état propre et validé avec Git. Il est basé sur le flux de travail ''Landing the Plane'' de Steve Yegge. Der Agent ''land'' hilft, das Repository in einem sauberen und committeten Zustand mit Git zu hinterlassen. Er basiert auf dem Workflow ''Landing the Plane'' von Steve Yegge. O land é uma ferramenta para garantir que o repositório esteja em um estado limpo e atualizado, com commit e push bem-sucedidos. Land - это инструмент для обеспечения чистого и актуального состояния репозитория, с успешным коммитом и пушем. يعد land أداة لضمان أن يكون المستودع في حالة نظيفة و محدثة، مع التزام و دفع بنجاح. how to use land what is land land alternative land vs git flow land install land setup guide git workflow automation AI agent workflow repository management Land技能 Git推送 代码提交 代码仓库管理 代码可靠性 AI工具 AIエージェント 代码完整性 Automates git workflow using git push command Ensures a clean and committed repository state Wraps up work sessions with a pushed repo state Follows Steve Yegge''s ''Landing the Plane'' workflow Integrates with Beads agent memory system Pushes changes to the repository until git push succeeds land is a git workflow automation process that ensures a clean, committed, and pushed repository state');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('StudioJinsei-Official/line-pj/nanobanana', 'community', 'StudioJinsei-Official', 'line-pj', 'StudioJinsei-Official/line-pj', 'nanobanana', 0, 1, 51, '2026-01-12T00:21:46Z', '2026-03-07T03:52:54.813Z', 'd70be522c08ed5bb12f90ea631f3dca4a9906241b2ba37f6bf7eb1cf2697f240', '{"id":"StudioJinsei-Official/line-pj/nanobanana","name":"nanobanana","description":{"en":"The nanobanana skill generates StudioJinsei''s brand visuals using Google Gemini API, benefiting developers and designers. It creates logos, characters, and site visuals with ease.","zh":"Nanobanana 画像生成技能使用 Google Gemini API 生成高品质图像，包括 logo 和网站视觉效果","ja":"Nanobanana 画像生成 Skill は Google Gemini API を使用して、高品質のロゴやサイトビジュアルを生成します","ko":"Nanobanana 이미지 생성 스킬은 Google Gemini API를 사용하여 높은 품질의 로고와 웹사이트 시각 효과를 생성합니다","es":"nanobanana es una habilidad de generación de imágenes que utiliza Google Gemini API para crear contenido visual de alta calidad. Soporta modelos como Gemini 3 Pro Image y Gemini 2.5 Flash Image","fr":"nanobanana est une compétence de génération d''images qui utilise Google Gemini API pour créer du contenu visuel de haute qualité. Elle prend en charge des modèles tels que Gemini 3 Pro Image et Gemini 2.5 Flash Image","de":"nanobanana ist eine Bildgenerierungs-Fähigkeit, die Google Gemini API verwendet, um hochwertigen visuellen Inhalt zu erstellen. Sie unterstützt Modelle wie Gemini 3 Pro Image und Gemini 2.5 Flash Image","pt":"O Nanobanana é uma habilidade de geração de imagens que utiliza a Google Gemini API para criar logotipos, visuais de site e mais. Aprenda a configurá-lo","ru":"Nanobanana - это навык генерации изображений, который использует Google Gemini API для создания логотипов, визуальных эффектов сайта и многое другое. Узнайте, как его настроить","ar":"Nanobanana هو مهارة لإنشاء الصور التي تستخدم Google Gemini API لإنشاء الشعارات وصور الموقع والكثير منها. تعلم كيفية إعداده"},"seo":{"title":{"en":"nanobanana: Google Gemini API Integration for AI Agents |...","zh":"Nanobanana 画像生成技能设置指南","ja":"Nanobanana 画像生成 Skill のベストプラクティス","ko":"Nanobanana 이미지 생성 스킬 설정 가이드","es":"nanobanana: Guía de configuración para generación de imág...","fr":"nanobanana: Guide de mise en place pour la génération d''i...","de":"nanobanana: Einrichtungsleitfaden für die Bildgenerierung...","pt":"Guia de Configuração do Nanobanana: Geração de Imagens co...","ru":"Настройка Nanobanana: Создание Изображений с Использовани...","ar":"دليل إعداد Nanobanana: генерація الصور باستخدام Google Ge..."},"description":{"en":"Discover how nanobanana leverages Google Gemini API for high-quality image generation. Get started with our setup guide and unlock AI-powered visuals","zh":"了解 Nanobanana 画像生成技能的技术细节和设置方法，实现高品质的图像生成","ja":"Nanobanana 画像生成 Skill の技術的特徴と設定方法を紹介します","ko":"Nanobanana 이미지 생성 스킬의 기술적 세부 사항과 설정 방법을 알아보세요","es":"Aprende a utilizar nanobanana para generar imágenes de alta calidad con Google Gemini API. Descubre los modelos de uso y las características clave de esta he...","fr":"Découvrez comment utiliser nanobanana pour générer des images de haute qualité avec Google Gemini API. Explorez les modèles d''utilisation et les fonctionnali...","de":"Erfahren Sie, wie Sie nanobanana verwenden können, um hochwertige Bilder mit Google Gemini API zu generieren. Entdecken Sie die Nutzungsmodelle und die wicht...","pt":"Aprenda a configurar o Nanobanana para gerar imagens de alta qualidade com a Google Gemini API. Descubra como utilizar o Gemini 3 Pro Image e o Gemini 2.5 Fl...","ru":"Узнайте, как настроить Nanobanana для генерации высококачественных изображений с помощью Google Gemini API. Откройте для себя возможности Gemini 3 Pro Image ...","ar":"تعلم كيفية إعداد Nanobanana ل生成 صور عالية الجودة باستخدام Google Gemini API. اكتشف كيفية استخدام Gemini 3 Pro Image و Gemini 2.5 Flash Image"},"definition":{"en":"nanobanana is a skill that utilizes Google Gemini API to generate high-quality images, such as logos and site visuals, for StudioJinsei''s brand","zh":"Nanobanana 画像生成技能是一种使用 Google Gemini API 生成图像的 AI 技术","ja":"Nanobanana 画像生成 Skill は、Google Gemini API を使用して画像を生成する AI エージェントの一種です","ko":"Nanobanana 이미지 생성 스킬은 Google Gemini API를 사용하여 이미지를 생성하는 AI 도구입니다","es":"nanobanana es una herramienta de AI que utiliza Google Gemini API para generar imágenes de alta calidad","fr":"nanobanana est un outil d''IA qui utilise Google Gemini API pour générer des images de haute qualité","de":"nanobanana ist ein AI-Tool, das Google Gemini API verwendet, um hochwertige Bilder zu generieren","pt":"O que é Nanobanana? É uma habilidade de geração de imagens que utiliza a Google Gemini API","ru":"Что такое Nanobanana? Это навык генерации изображений, который использует Google Gemini API","ar":"ما هي Nanobanana؟ هي مهارة لإنشاء الصور التي تستخدم Google Gemini API"},"features":{"en":["Utilizes Google Gemini API for image generation","Supports Gemini 3 Pro Image and Gemini 2.5 Flash Image models","Generates high-quality, high-resolution images with Gemini 3 Pro Image","Offers cost-effective image generation with Gemini 2.5 Flash Image","Requires Google API Key for authentication"],"zh":["使用 Google Gemini API 生成高品质图像","支持 Gemini 3 Pro Image 和 Gemini 2.5 Flash Image 两种模型","高品质图像生成，适合 logo 和网站视觉效果","低成本的图像生成选项，约 6 円/枚","支持 Google API Key 验证"],"ja":["Google Gemini API を使用して高品質の画像を生成","Gemini 3 Pro Image と Gemini 2.5 Flash Image の 2 つのモデルをサポート","高品質のロゴやサイトビジュアルを生成","低コストの画像生成オプション、約 6 円/枚","Google API Key 認証をサポート"],"ko":["Google Gemini API를 사용하여 높은 품질의 이미지를 생성","Gemini 3 Pro Image와 Gemini 2.5 Flash Image 두 가지 모델을 지원","높은 品質의 로고와 웹사이트 시각 효과를 생성","低コスト의 이미지 생성 옵션, 약 6 円/枚","Google API Key 인증을 지원"],"es":["Soporte para Google Gemini API","Generación de imágenes de alta calidad con Gemini 3 Pro Image","Opción de imágenes de baja costo con Gemini 2.5 Flash Image","Requisito de clave de API de Google (GOOGLE_API_KEY)","Compatibilidad con varios modelos de uso","Generación de logotipos y visuales de sitio web"],"fr":["Prise en charge de Google Gemini API","Génération d''images de haute qualité avec Gemini 3 Pro Image","Option d''images à faible coût avec Gemini 2.5 Flash Image","Exigence d''une clé d''API Google (GOOGLE_API_KEY)","Compatibilité avec plusieurs modèles d''utilisation","Génération de logos et de visuels de site web"],"de":["Unterstützung für Google Gemini API","Generierung von hochwertigen Bildern mit Gemini 3 Pro Image","Option für günstige Bilder mit Gemini 2.5 Flash Image","Anforderung an einen Google-API-Schlüssel (GOOGLE_API_KEY)","Kompatibilität mit verschiedenen Nutzungsmustern","Generierung von Logos und Website-Visuals"],"pt":["Geração de imagens de alta qualidade com Gemini 3 Pro Image","Geração de imagens rápidas e de baixo custo com Gemini 2.5 Flash Image","Utilização da Google Gemini API","Criação de logotipos e visuais de site personalizados","Suporte a diferentes formatos de imagem"],"ru":["Генерация высококачественных изображений с помощью Gemini 3 Pro Image","Генерация быстрых и недорогих изображений с помощью Gemini 2.5 Flash Image","Использование Google Gemini API","Создание индивидуальных логотипов и визуальных эффектов сайта","Поддержка различных форматов изображений"],"ar":["إنشاء صور عالية الجودة باستخدام Gemini 3 Pro Image","إنشاء صور سريعة و低 التكلفة باستخدام Gemini 2.5 Flash Image","استخدام Google Gemini API","إنشاء شعارات وصور موقع مخصصة","دعم صيغ صور مختلفة"]},"keywords":{"en":["how to use nanobanana","nanobanana setup guide","Google Gemini API integration","nanobanana alternative","nanobanana vs Google Cloud Vision","nanobanana install","StudioJinsei brand visuals","AI-powered image generation","Gemini 3 Pro Image model"],"zh":["Nanobanana 画像生成技能","Google Gemini API","AI 画像生成","图像生成技术","logo 生成","网站视觉效果","AI エージェント","画像生成工具"],"ja":["Nanobanana 画像生成 Skill","Google Gemini API","AI 画像生成","画像生成技術","ロゴ生成","サイトビジュアル","AI エージェント","画像生成ツール"],"ko":["Nanobanana 이미지 생성 스킬","Google Gemini API","AI 이미지 생성","이미지 생성 기술","로고 생성","웹사이트 시각 효과","AI 도구","이미지 생성 툴"],"es":["nanobanana","Google Gemini API","generación de imágenes","herramientas de AI","desarrollo de imágenes","Gemini 3 Pro Image","Gemini 2.5 Flash Image","clave de API de Google","AI para desarrolladores"],"fr":["nanobanana","Google Gemini API","génération d''images","outils d''IA","développement d''images","Gemini 3 Pro Image","Gemini 2.5 Flash Image","clé d''API Google","IA pour développeurs"],"de":["nanobanana","Google Gemini API","Bildgenerierung","AI-Tools","Bildentwicklung","Gemini 3 Pro Image","Gemini 2.5 Flash Image","Google-API-Schlüssel","KI für Entwickler"],"pt":["Nanobanana","Google Gemini API","Geração de imagens","Gemini 3 Pro Image","Gemini 2.5 Flash Image","Desenvolvimento de IA","Ferramentas de IA","Agente de IA"],"ru":["Nanobanana","Google Gemini API","Генерация изображений","Gemini 3 Pro Image","Gemini 2.5 Flash Image","Разработка ИИ","Инструменты ИИ","ИИ Агенты"],"ar":["Nanobanana","Google Gemini API","إنشاء الصور","Gemini 3 Pro Image","Gemini 2.5 Flash Image","تطوير الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","وكلاء الذكاء الاصطناعي"]}},"owner":"StudioJinsei-Official","repo":"line-pj","repoPath":"StudioJinsei-Official/line-pj","stars":0,"forks":1,"updatedAt":"2026-01-12T00:21:46Z","topics":[],"category":"community","skillMd":{"name":"nanobanana","description":"StudioJinsei用Nanobanana画像生成Skill。Google Gemini APIを使用してロゴ、コトネちゃん、サイトビジュアル等を生成します。","bodyPreview":"# StudioJinsei Nanobanana 画像生成 Skill\n\n## 概要\n\nStudioJinseiのブランドビジュアルを生成するためのNanobanana Skillです。\nGoogle Gemini APIを直接使用して、ロゴ、コトネちゃん、サイトビジュアル等を生成します。\n\n---\n\n## 📋 利用モデル\n\n| モデル名 | API名 | 特徴 | 料金目安 |\n|---------|-------|------|----------|\n| **Gemini 3 Pro Image** | gemini-3-pro-image-preview | 高品質・高解像度 | 約21-30円/枚 |\n| Gemini 2.5 Flash Image | gemini-2.5-flash-image | 高速・低コスト | 約6円/枚 |\n\n**推奨：** StudioJinseiのロゴやメインビジュアルは **Gemini 3 Pro Image** を使用\n\n---\n\n## 🔧 前提条件\n\n### 必須\n- Google API Key（`GOOGLE_API_KEY","body":"# StudioJinsei Nanobanana 画像生成 Skill\n\n## 概要\n\nStudioJinseiのブランドビジュアルを生成するためのNanobanana Skillです。\nGoogle Gemini APIを直接使用して、ロゴ、コトネちゃん、サイトビジュアル等を生成します。\n\n---\n\n## 📋 利用モデル\n\n| モデル名 | API名 | 特徴 | 料金目安 |\n|---------|-------|------|----------|\n| **Gemini 3 Pro Image** | gemini-3-pro-image-preview | 高品質・高解像度 | 約21-30円/枚 |\n| Gemini 2.5 Flash Image | gemini-2.5-flash-image | 高速・低コスト | 約6円/枚 |\n\n**推奨：** StudioJinseiのロゴやメインビジュアルは **Gemini 3 Pro Image** を使用\n\n---\n\n## 🔧 前提条件\n\n### 必須\n- Google API Key（`GOOGLE_API_KEY`）\n- Python 3.x\n- google-generativeai パッケージ\n\n### 環境変数\n```bash\nexport GOOGLE_API_KEY=\"AIzaSyBs2FQS6FYWwx9LKQdyywkBFTEXt5tK9Z8\"\n```\n\n---\n\n## ⚙️ セットアップ手順\n\n### 1. 環境変数を設定\n\n#### macOS/Linux（zsh）の場合\n```bash\n# ~/.zshrc を編集\nnano ~/.zshrc\n\n# 以下を追加\nexport GOOGLE_API_KEY=\"AIzaSyBs2FQS6FYWwx9LKQdyywkBFTEXt5tK9Z8\"\n\n# 設定を反映\nsource ~/.zshrc\n\n# 確認\necho $GOOGLE_API_KEY\n```\n\n### 2. Python パッケージをインストール\n\n```bash\npip install google-generativeai\n```\n\n---\n\n## 🚀 基本的な使い方\n\n### 画像生成スクリプト（簡易版）\n\n```python\nimport google.generativeai as genai\nimport os\nfrom pathlib import Path\n\n# API設定\ngenai.configure(api_key=os.environ[\"GOOGLE_API_KEY\"])\n\n# モデル選択\nmodel = genai.GenerativeModel(\"gemini-3-pro-image-preview\")  # または \"gemini-2.5-flash-image\"\n\n# プロンプト\nprompt = \"\"\"\n[ここにプロンプトを記述]\n\"\"\"\n\n# 画像生成\nresponse = model.generate_content(prompt)\n\n# 保存\noutput_path = Path(\"images/studiojinsei/output.png\")\noutput_path.parent.mkdir(parents=True, exist_ok=True)\n\nif response.candidates and response.candidates[0].content.parts:\n    image_data = response.candidates[0].content.parts[0].inline_data.data\n    output_path.write_bytes(image_data)\n    print(f\"画像を保存しました: {output_path}\")\n```\n\n---\n\n## 📝 プロンプトの作り方\n\n### 基本テンプレート\n\nすべてのプロンプトに以下を含める：\n\n```\n[StudioJinsei Brand Foundation]\n\nConcept: \"Making invisible thoughts visible and tangible\"\nTagline: \"考えが動きに変わるきっかけをつくるスタジオ\"\n\nVisual direction:\n- Simple yet warm (not cold)\n- Organized yet approachable (not rigid)\n- Sophisticated yet friendly (not intimidating)\n- Professional yet personal (not distant)\n\nColor palette: Soft mint green (#A8D5BA), dark teal (#1D4E4A), pale mint (#E8F5EE), white (#FFFFFF).\nMain: soft mint green (#A8D5BA), accent: dark teal (#1D4E4A).\n\nTypography: Modern sans-serif, Poppins or similar clean font style.\n\nDesign style:\n- Minimalist, Apple-inspired clean aesthetic\n- Plenty of white space, generous breathing room\n- Simple, uncluttered, focused layout\n- High quality, attention to detail\n\nAvoid:\n- Flashy, overly colorful, hyper-energetic styles\n- Spiritual, abstract, mystical vibes\n- Cold, corporate, distant aesthetics\n- Cheap, low-quality appearance\n\n---\n\n[ここに具体的な指示]\n```\n\n---\n\n## 🎯 生成パターン\n\n### パターン1：ロゴ生成\n\n**プロンプト例：**\n```\n[StudioJinsei Brand Foundation]\n...\n\nProfessional wordmark logo for \"StudioJinsei\".\nText-only design, no symbols or icons.\nTypography: Modern sans-serif, Poppins or similar clean font.\n\"Studio\" in light/thin weight, \"Jinsei\" in medium/semibold weight.\nColor scheme: Dark teal (#1D4E4A) for main text, soft mint green (#A8D5BA) subtle accent.\nMinimalist, sophisticated, professional yet approachable.\nClean letterforms with generous letter spacing.\nPlenty of white space around the text.\nHigh quality vector style.\n```\n\n**参照：** [brand-foundation.md](./brand-foundation.md)\n\n### パターン2：コトネちゃん生成\n\n**プロンプト例：**\n```\n[StudioJinsei Brand Foundation]\n...\n\nA soft, hand-drawn style illustration of Kotone-chan.\nYoung Japanese woman with dark long hair.\nMint green bucket hat with subtle leaf pattern.\nWhite elegant clothing.\nGentle, warm illustration style with soft lines.\nMuted, sophisticated color palette (soft mint #A8D5BA, dark teal #1D4E4A).\nCalm, professional, trustworthy expression with a gentle smile.\nMinimal background, plenty of white space.\nApple-inspired clean aesthetic.\nShe embodies \"making invisible thoughts visible\" concept.\n```\n\n**参照：** [kotone-character.md](./kotone-character.md)\n\n### パターン3：サイトビジュアル生成\n\n**プロンプト例：**\n```\n[StudioJinsei Brand Foundation]\n...\n\nWebsite hero section design for StudioJinsei.\nMain headline: \"考えが動きに変わるきっかけをつくるスタジオ\"\nSubheadline: \"見えない思いを、見える形に\"\nBackground: Soft mint green gradient (#E8F5EE to #FFFFFF).\nMinimalist hand-drawn style illustration of Kotone-chan (optional).\nPlenty of breathing room, clean and uncluttered.\nProfessional yet friendly, modern and sophisticated.\n```\n\n---\n\n## 📐 解像度設定\n\nGemini APIでは解像度を直接指定できませんが、プロンプトで要求できます：\n\n```\nGenerate a 1024x1024 square image.\nHigh resolution, suitable for professional use.\n```\n\nまたは\n\n```\nGenerate a 1920x1080 (16:9) landscape image.\n```\n\n---\n\n## 💰 料金目安\n\n### API料金\n| 解像度相当 | 1枚あたりの料金 |\n|----------|----------------|\n| 1K (1024x1024) | 約21円 |\n| 2K (2048x2048) | 約42円 |\n| 4K (4096x4096) | 約85円 |\n\n### 制作例\n**ロゴ制作：**\n- 3パターン生成 = 約63円\n- 最終版高解像度 = 約85円\n- **合計：約150円**\n\n---\n\n## 📋 チェックリスト\n\n生成時に必ず確認：\n\n- [ ] [brand-foundation.md](./brand-foundation.md) を参照したか\n- [ ] カラーパレット（#A8D5BA, #1D4E4A）が正しいか\n- [ ] 「シンプル、でも冷たくない」が表現されているか\n- [ ] 余白がたっぷりあるか\n- [ ] StudioJinseiの核心コンセプトが伝わるか\n- [ ] NGデザイン（キラキラ、スピリチュアル、冷たい、チープ）になっていないか\n\n---\n\n## 🖼️ 参照画像\n\n### 画像の場所\n\nこのディレクトリ（`nanobanana-base`）には参照画像が含まれています：\n\n```\nnanobanana-base/\n└── images/\n    └── reference/\n        ├── line-profile.jpg        # LINEプロフィール画像\n        └── officialprofile.PNG     # 公式プロフィール画像\n```\n\n### Claudeスキルでの使用\n\n新しいリポジトリでClaudeスキル（`.claude/skills/kotone-*`）を使用する場合：\n\n1. **スキルディレクトリに画像をコピー**\n   ```bash\n   mkdir -p .claude/skills/kotone-business/images\n   cp manuals/nanobanana/nanobanana-base/images/reference/* .claude/skills/kotone-business/images/\n   ```\n\n2. **SKILL.mdで参照**\n   ```markdown\n   ## 参照画像\n   \n   | 用途 | パス |\n   |------|------|\n   | LINEプロフィール画像 | `images/line-profile.jpg` |\n   | 公式プロフィール画像 | `images/officialprofile.PNG` |\n   ```\n\n詳細は [setup-guide.md](./setup-guide.md) の「Claudeスキルに参照画像を配置」セクションを参照してください。\n\n---\n\n## 🔗 関連資料\n\n- [ブランド共通デザイン土台](./brand-foundation.md)\n- [コトネちゃん設定](./kotone-character.md)\n- [セットアップガイド](./setup-guide.md)\n- [使い方ガイド](./usage-guide.md)\n- [README](./README.md)\n\n---\n\n## 🤖 AI向け：画像制作依頼時の自動セットアップ手順\n\nユーザーから「〇〇の画像を作りたい」という依頼があった場合、以下の手順を自動実行してください：\n\n### 1. プロジェクトディレクトリを作成\n\n```bash\n# 例：ロゴ制作の場合\nmkdir -p logo-generation\ncd logo-generation\n```\n\n### 2. nanobanana-baseをコピー\n\n```bash\n# 現在のリポジトリからコピー（既にクローン済みの場合）\ncp -r ../nanobanana-base .\n\n# または、リポジトリをクローンして取得\ngit clone https://github.com/StudioJinsei/opening-preparation temp\ncp -r temp/manuals/nanobanana/nanobanana-base .\nrm -rf temp\n```\n\n### 3. Claudeスキルを設定\n\n```bash\n# スキルディレクトリを作成\nmkdir -p .claude/skills/nanobanana\n\n# nanobanana-baseの内容をコピー（manuals内から）\ncp -r nanobanana-base/* .claude/skills/nanobanana/\n# または、リポジトリから直接取得\ngit clone https://github.com/StudioJinsei/opening-preparation temp\ncp -r temp/manuals/nanobanana/nanobanana-base/* .claude/skills/nanobanana/\nrm -rf temp\n\n# SKILL.mdのnameを確認（nanobananaになっているか）\n```\n\n### 4. 専用プロンプトファイルを作成\n\nプロジェクトディレクトリ内（`nanobanana-base`と同じディレクトリ）に、用途に応じた専用プロンプトファイルを作成：\n\n```bash\n# 例：ロゴ制作の場合\nnano logo_prompt.txt\n```\n\n**プロンプトファイルの構成：**\n1. `nanobanana-base/brand-foundation.md` の「Nanobanana用 共通プロンプト基盤」を参照\n2. 用途に応じた具体的な指示を追加\n3. ファイル名は用途に応じて（例：`logo_prompt.txt`, `kotone_prompt.txt`）\n\n### 5. 生成スクリプトを作成（必要に応じて）\n\n```python\n# 例：generate_logo.py\nimport google.generativeai as genai\nimport os\nfrom pathlib import Path\n\ngenai.configure(api_key=os.environ[\"GOOGLE_API_KEY\"])\nmodel = genai.GenerativeModel(\"gemini-3-pro-image-preview\")\n\n# ベースプロンプトを読み込む（nanobanana-baseはプロジェクトディレクトリ内にコピー済み）\nwith open(\"nanobanana-base/brand-foundation.md\", \"r\") as f:\n    base_content = f.read()\n# 共通プロンプト基盤を抽出（実装は省略）\n\n# 専用プロンプトを読み込む\nwith open(\"logo_prompt.txt\", \"r\") as f:\n    custom_prompt = f.read()\n\n# 結合して生成\nprompt = base_prompt + \"\\n\\n---\\n\\n\" + custom_prompt\nresponse = model.generate_content(prompt)\n# 保存処理...\n```\n\n### 6. README.mdを作成（推奨）\n\nプロジェクトディレクトリの説明と使い方を記載：\n\n```markdown\n# [プロジェクト名]\n\n## 構成\n- nanobanana-base/ - ベースディレクトリ\n- [プロンプトファイル名] - 専用プロンプト\n- [生成スクリプト名] - 生成スクリプト\n\n## 使い方\n[具体的な使い方]\n```\n\n### 重要なポイント\n\n- **専用プロンプトファイルは `nanobanana-base` と同じディレクトリ（プロジェクトディレクトリ内）に保存**\n- ベースプロンプトは `nanobanana-base/brand-foundation.md` から自動読み込み\n- 専用プロンプトには用途固有の指示のみを記述\n- プロジェクトディレクトリは独立して完結する構成にする\n\n---\n\n## 🎓 Tips\n\n### プロンプト作成のコツ\n1. 必ず共通プロンプト基盤を含める\n2. カラーコードを明記（#A8D5BA, #1D4E4A）\n3. 避けるべきものを明記（Avoid:）\n4. 具体的に、曖昧な表現を避ける\n\n### 品質管理\n1. 生成後は必ずチェックリスト確認\n2. プロンプトを保存してバージョン管理\n3. 複数パターン生成して比較\n\n---\n\n**最終更新：2025/12/20**\n"},"lastSynced":"2026-03-07T03:52:54.813Z","agentAnalysis":{"suitability":{"en":"Perfect for Creative Agents needing advanced brand visual generation capabilities using Google Gemini API.","zh":"非常适合需要使用Google Gemini API进行高级品牌视觉生成的创意代理","ja":"Google Gemini APIを使用して高度なブランド視覚生成機能を必要とするクリエイティブエージェントに最適","ko":"Google Gemini API를 사용하여 고급 브랜드 시각 생성 기능이 필요한 크리에이티브 에이전트에게 완벽","es":"Perfecto para agentes creativos que necesitan capacidades avanzadas de generación de visuales de marca utilizando Google Gemini API.","fr":"Idéal pour les agents créatifs ayant besoin de capacités avancées de génération de visuels de marque en utilisant Google Gemini API.","de":"Perfekt für kreative Agenten, die erweiterte Marken-Visualisierungsfunktionen mit Google Gemini API benötigen.","pt":"Perfeito para Agentes Criativos que precisam de capacidades avançadas de geração de visual de marca usando o Google Gemini API.","ru":"Идеально подходит для Креативных Агентов, которым необходимы продвинутые возможности генерации визуального бренда с использованием Google Gemini API.","ar":"مثالي لويبوتات الإبداعية التي تحتاج إلى إمكانيات متقدمة لإنشاء الصور المرئية للعلامة التجارية باستخدام Google Gemini API."},"recommendation":{"en":"Empowers agents to generate high-quality logos, characters, and site visuals using Gemini 3 Pro Image and Gemini 2.5 Flash Image models, leveraging Google API for direct integration and cost-effective solutions like approximately 21-30円/枚 for high-resolution images.","zh":"赋予代理商使用Gemini 3 Pro Image和Gemini 2.5 Flash Image模型生成高质量的标志、角色和网站视觉的能力，利用Google API进行直接集成和成本有效的解决方案，例如高分辨率图像大约21-30円/枚","ja":"Gemini 3 Pro ImageとGemini 2.5 Flash Imageモデルの使用により、エージェントが高品質のロゴ、キャラクター、サイト視覚を生成できるようにし、Google APIを使用して直接統合および費用対効果の高いソリューション（例：高解像度画像は約21-30円/枚）を実現","ko":"에이전트가 Gemini 3 Pro Image와 Gemini 2.5 Flash Image 모델을 사용하여 고품질의 로고, 캐릭터, 사이트 시각을 생성할 수 있도록 하며, Google API를 사용하여 직접 통합 및 비용 효과적인 솔루션(예: 고해상도 이미지 약 21-30円/枚)을 제공","es":"Permite a los agentes generar logotipos, personajes y visuales de sitios web de alta calidad utilizando los modelos Gemini 3 Pro Image y Gemini 2.5 Flash Image, aprovechando Google API para una integración directa y soluciones rentables como aproximadamente 21-30円/枚 para imágenes de alta resolución.","fr":"Permet aux agents de générer des logos, des personnages et des visuels de sites web de haute qualité en utilisant les modèles Gemini 3 Pro Image et Gemini 2.5 Flash Image, en exploitant Google API pour une intégration directe et des solutions rentables comme environ 21-30円/枚 pour les images haute résolution.","de":"Ermöglicht es Agenten, hochwertige Logos, Charaktere und Site-Visuals mit den Modellen Gemini 3 Pro Image und Gemini 2.5 Flash Image zu generieren, indem Google API für eine direkte Integration und kostengünstige Lösungen wie etwa 21-30円/枚 für hochauflösende Bilder genutzt wird.","pt":"Habilita os agentes a gerar logotipos, personagens e visuais de site de alta qualidade usando os modelos Gemini 3 Pro Image e Gemini 2.5 Flash Image, aproveitando o Google API para integração direta e soluções rentáveis, como aproximadamente 21-30円/枚 para imagens de alta resolução.","ru":"Наделяет агентов возможностью генерировать логотипы, персонажи и визуальные элементы сайта высокого качества с использованием моделей Gemini 3 Pro Image и Gemini 2.5 Flash Image, используя Google API для прямой интеграции и экономически эффективных решений, таких как примерно 21-30円/枚 для изображений высокого разрешения.","ar":"يُمنح الوكلاء القدرة على إنشاء شعارات و شخصيات وصور موقع ويب عالية الجودة باستخدام نماذج Gemini 3 Pro Image و Gemini 2.5 Flash Image، مستفيدة من Google API لتكامل مباشر وحلول اقتصادية، مثل ما يقرب من 21-30円/枚 لصور عالية الدقة."},"useCases":{"en":["Generating StudioJinsei brand visuals","Creating logos and characters with Google Gemini API","Automating site visual production with Gemini 3 Pro Image"],"zh":["为StudioJinsei生成品牌视觉","使用Google Gemini API创建标志和角色","使用Gemini 3 Pro Image自动化网站视觉生产"],"ja":["StudioJinseiのブランド視覚を生成","Google Gemini APIを使用してロゴとキャラクターを作成","Gemini 3 Pro Imageを使用してサイト視覚の生産を自動化"],"ko":["StudioJinsei 브랜드 시각 생성","Google Gemini API를 사용하여 로고와 캐릭터 생성","Gemini 3 Pro Image를 사용하여 사이트 시각 생산 자동화"],"es":["Generación de visuales de marca StudioJinsei","Creación de logotipos y personajes con Google Gemini API","Automatización de la producción de visuales de sitio con Gemini 3 Pro Image"],"fr":["Génération de visuels de marque StudioJinsei","Création de logos et de personnages avec Google Gemini API","Automatisation de la production de visuels de site avec Gemini 3 Pro Image"],"de":["Erzeugung von StudioJinsei-Markenvisuals","Erstellung von Logos und Charakteren mit Google Gemini API","Automatisierung der Site-Visual-Produktion mit Gemini 3 Pro Image"],"pt":["Geração de visuais de marca StudioJinsei","Criação de logotipos e personagens com o Google Gemini API","Automação da produção de visuais de site com Gemini 3 Pro Image"],"ru":["Генерация визуальных элементов бренда StudioJinsei","Создание логотипов и персонажей с использованием Google Gemini API","Автоматизация производства визуальных элементов сайта с помощью Gemini 3 Pro Image"],"ar":["إنشاء صور مرئية للعلامة التجارية StudioJinsei","إنشاء الشعارات والأشخاص باستخدام Google Gemini API","أتمتة إنتاج الصور المرئية للموقع باستخدام Gemini 3 Pro Image"]},"limitations":{"en":["Requires Google API Key","Dependent on Google Gemini API availability and pricing (e.g., approximately 6円/枚 for low-cost options)"],"zh":["需要Google API密钥","依赖Google Gemini API的可用性和定价（例如，低成本选项大约6円/枚）"],"ja":["Google APIキーが必要","Google Gemini APIの可用性と価格設定（例：低コストオプションは約6円/枚）に依存"],"ko":["Google API 키가 필요","Google Gemini API의 가용성과 가격 결정(예: 저비용 옵션은 약 6円/枚)에 의존"],"es":["Requiere Google API Key","Dependiente de la disponibilidad y el precio de Google Gemini API (por ejemplo, aproximadamente 6円/枚 para opciones de bajo costo)"],"fr":["Nécessite une clé Google API","Dépend de la disponibilité et du prix de Google Gemini API (par exemple, environ 6円/枚 pour les options à faible coût)"],"de":["Benötigt Google API-Schlüssel","Abhängig von der Verfügbarkeit und dem Preis von Google Gemini API (z. B. etwa 6円/枚 für günstige Optionen)"],"pt":["Requer uma Chave de API do Google","Dependente da disponibilidade e preços do Google Gemini API (por exemplo, aproximadamente 6円/枚 para opções de baixo custo)"],"ru":["Требуется Ключ API Google","Зависит от наличия и цен Google Gemini API (например, примерно 6円/枚 для бюджетных вариантов)"],"ar":["يتطلب مفتاح واجهة برمجة تطبيقات Google","يعتمد على توافر و أسعار Google Gemini API (على سبيل المثال ، ما يقرب من 6円/枚 للخيارات منخفضة التكلفة)"]},"version":4},"contentHash":"d70be522c08ed5bb12f90ea631f3dca4a9906241b2ba37f6bf7eb1cf2697f240","qualityScore":51}');
