INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('StudioJinsei-Official/line-pj/nanobanana', 'nanobanana', 'StudioJinsei-Official', 'line-pj', 'community', 'nanobanana StudioJinsei-Official line-pj community The nanobanana skill generates StudioJinsei''s brand visuals using Google Gemini API, benefiting developers and designers. It creates logos, characters, and site visuals with ease. Nanobanana 画像生成技能使用 Google Gemini API 生成高品质图像，包括 logo 和网站视觉效果 Nanobanana 画像生成 Skill は Google Gemini API を使用して、高品質のロゴやサイトビジュアルを生成します Nanobanana 이미지 생성 스킬은 Google Gemini API를 사용하여 높은 품질의 로고와 웹사이트 시각 효과를 생성합니다 nanobanana es una habilidad de generación de imágenes que utiliza Google Gemini API para crear contenido visual de alta calidad. Soporta modelos como Gemini 3 Pro Image y Gemini 2.5 Flash Image nanobanana est une compétence de génération d''images qui utilise Google Gemini API pour créer du contenu visuel de haute qualité. Elle prend en charge des modèles tels que Gemini 3 Pro Image et Gemini 2.5 Flash Image nanobanana ist eine Bildgenerierungs-Fähigkeit, die Google Gemini API verwendet, um hochwertigen visuellen Inhalt zu erstellen. Sie unterstützt Modelle wie Gemini 3 Pro Image und Gemini 2.5 Flash Image O Nanobanana é uma habilidade de geração de imagens que utiliza a Google Gemini API para criar logotipos, visuais de site e mais. Aprenda a configurá-lo Nanobanana - это навык генерации изображений, который использует Google Gemini API для создания логотипов, визуальных эффектов сайта и многое другое. Узнайте, как его настроить Nanobanana هو مهارة لإنشاء الصور التي تستخدم Google Gemini API لإنشاء الشعارات وصور الموقع والكثير منها. تعلم كيفية إعداده how to use nanobanana nanobanana setup guide Google Gemini API integration nanobanana alternative nanobanana vs Google Cloud Vision nanobanana install StudioJinsei brand visuals AI-powered image generation Gemini 3 Pro Image model Nanobanana 画像生成技能 Google Gemini API AI 画像生成 图像生成技术 logo 生成 网站视觉效果 AI エージェント 画像生成工具 Utilizes Google Gemini API for image generation Supports Gemini 3 Pro Image and Gemini 2.5 Flash Image models Generates high-quality, high-resolution images with Gemini 3 Pro Image Offers cost-effective image generation with Gemini 2.5 Flash Image Requires Google API Key for authentication nanobanana is a skill that utilizes Google Gemini API to generate high-quality images, such as logos and site visuals, for StudioJinsei''s brand');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('benjgrad/workout-ai/subagent-driven-development', 'community', 'benjgrad', 'workout-ai', 'benjgrad/workout-ai', 'subagent-driven-development', 0, 0, 51, '2026-02-23T03:54:12Z', '2026-03-07T04:07:39.514Z', 'cb483bee1ad1478e363f95493adf4ab349d1cfc9eeec173a5aff260a882169aa', '{"id":"benjgrad/workout-ai/subagent-driven-development","name":"subagent-driven-development","description":{"en":"Subagent-driven development executes plans by dispatching fresh subagents per task, with two-stage reviews for high-quality, fast iteration. This skill benefits developers working on independent tasks.","zh":"子代理驱动开发是一种通过分派新子代理执行任务并进行两阶段审查的开发方法，实现高质量和快速迭代","ja":"サブエージェント駆動開発は、タスクを新しいサブエージェントに割り当てて実行し、2段階のレビューを実施する開発手法であり、高品質と迅速なイテレーションを実現する","ko":"서브 에이전트 주도 개발은 새 서브 에이전트를 할당하여 작업을 실행하고 2단계 검토를 수행하는 개발 방법으로 고품질과 빠른 반복을 실현합니다","es":"Subagent-driven-development es una técnica que utiliza subagentes frescos por tarea con revisión de especificaciones y calidad para mejorar la calidad y velocidad de los proyectos","fr":"Subagent-driven-development est une technique qui utilise des sous-agents frais par tâche avec revue de spécifications et de qualité pour améliorer la qualité et la vitesse des projets","de":"Subagent-driven-development ist eine Technik, die frische Subagenten pro Aufgabe mit zweistufiger Überprüfung verwendet, um die Qualität und Geschwindigkeit von Projekten zu verbessern","pt":"O desenvolvimento dirigido por subagentes é uma abordagem que executa planos por meio da dispatch de subagentes frescos por tarefa, com revisão em duas etapas","ru":"Разработка на основе субагентов - это подход, который выполняет планы путем отправки новых субагентов на каждую задачу, с двухэтапным ревью","ar":"تطوير مدفوع بالوكيل الفرعي هو نهج ينفذ الخطط من خلال إرسال وكلاء فرعيين جدد لكل مهمة، مع مراجعة على مرحلتين"},"seo":{"title":{"en":"Subagent-Driven Development: Two-Stage Review Setup Guide...","zh":"子代理驱动开发设置指南","ja":"サブエージェント駆動開発ベストプラクティス","ko":"서브 에이전트 주도 개발 가이드","es":"Guía de configuración para subagent-driven-development co...","fr":"Guide de mise en place de subagent-driven-development ave...","de":"Einrichtungsleitfaden für subagent-driven-development mit...","pt":"Guia de Configuração de Desenvolvimento Dirigido por Suba...","ru":"Настройка инструментов ИИ Агентов: разработка на основе с...","ar":"دليل إعداد تطوير مدفوع بالوكيل الفرعي"},"description":{"en":"Discover how to execute plans with fresh subagents and two-stage reviews for spec compliance and code quality. Learn to implement subagent-driven development...","zh":"了解子代理驱动开发的核心原则和技术细节，实现高质量和快速迭代的开发流程","ja":"サブエージェント駆動開発のコアプリンシプルとテクニカル詳細を学び、高品質と迅速なイテレーションの開発プロセスを実現する","ko":"서브 에이전트 주도 개발의 핵심 원리와 기술 세부 사항을 학습하여 고품질과 빠른 반복의 개발 프로세스를 구현하십시오","es":"Aprende a implementar subagent-driven-development para mejorar la calidad y velocidad de tus proyectos con revisión de especificaciones y calidad","fr":"Découvrez comment mettre en place subagent-driven-development pour améliorer la qualité et la vitesse de vos projets avec revue de spécifications et de qualité","de":"Erfahren Sie, wie Sie subagent-driven-development einrichten, um die Qualität und Geschwindigkeit Ihrer Projekte mit zweistufiger Überprüfung zu verbessern","pt":"Aprenda a implementar o desenvolvimento dirigido por subagentes com revisão em duas etapas para melhorar a qualidade e a velocidade de iteração","ru":"Узнайте, как настроить разработку на основе субагентов с двухэтапным ревью для повышения качества и скорости итерации","ar":"تعرف على كيفية تنفيذ تطوير مدفوع بالوكيل الفرعي مع مراجعة على مرحلتين لتحسين الجودة وسرعة التكرار"},"definition":{"en":"Subagent-driven development is a methodology that executes plans by dispatching fresh subagents per task, with two-stage reviews for spec compliance and code quality.","zh":"子代理驱动开发是一种开发方法，通过分派新子代理执行任务并进行两阶段审查，实现高质量和快速迭代","ja":"サブエージェント駆動開発は、タスクを新しいサブエージェントに割り当てて実行し、2段階のレビューを実施する開発手法","ko":"서브 에이전트 주도 개발은 새 서브 에이전트를 할당하여 작업을 실행하고 2단계 검토를 수행하는 개발 방법","es":"Subagent-driven-development es una técnica de desarrollo que utiliza subagentes frescos por tarea con revisión de especificaciones y calidad","fr":"Subagent-driven-development est une technique de développement qui utilise des sous-agents frais par tâche avec revue de spécifications et de qualité","de":"Subagent-driven-development ist eine Entwicklungstechnik, die frische Subagenten pro Aufgabe mit zweistufiger Überprüfung verwendet","pt":"Desenvolvimento dirigido por subagentes é uma técnica de desenvolvimento que usa subagentes frescos por tarefa com revisão em duas etapas","ru":"Разработка на основе субагентов - это техника разработки, которая использует новых субагентов для каждой задачи с двухэтапным ревью","ar":"تطوير مدفوع بالوكيل الفرعي هو تقنية تطوير تستخدم وكلاء فرعيين جدد لكل مهمة مع مراجعة على مرحلتين"},"features":{"en":["Executes plans by dispatching fresh subagents per task","Two-stage review process for spec compliance and code quality","Supports independent tasks with fresh subagent allocation","Enables high-quality, fast iteration with two-stage review","Uses dot digraph for visualizing when to use subagent-driven development","Implements core principle of fresh subagent per task plus two-stage review"],"zh":["分派新子代理执行任务","两阶段审查：规范合规审查和代码质量审查","实现高质量和快速迭代的开发流程","适用于任务相对独立的开发项目","支持快速迭代和开发效率的提高"],"ja":["タスクを新しいサブエージェントに割り当てて実行","2段階のレビュー：仕様の準拠レビューとコードの品質レビュー","高品質と迅速なイテレーションの開発プロセスを実現","タスクが相対的に独立している開発プロジェクトに適する","迅速なイテレーションと開発効率の向上をサポート"],"ko":["새 서브 에이전트를 할당하여 작업을 실행","2단계 검토：규격 준수 검토와 코드 품질 검토","고품질과 빠른 반복의 개발 프로세스를 구현","작업이 상대적으로 독립적인 개발 프로젝트에 적합","빠른 반복과 개발 효율의 향상을 지원"],"es":["Utiliza subagentes frescos por tarea","Revisión de especificaciones y calidad en dos etapas","Mejora la calidad y velocidad de los proyectos","Permite la iteración rápida y la implementación de planes","Se integra con herramientas de desarrollo como CLI"],"fr":["Utilise des sous-agents frais par tâche","Revue de spécifications et de qualité en deux étapes","Améliore la qualité et la vitesse des projets","Permet l''itération rapide et la mise en œuvre de plans","S''intègre avec des outils de développement comme CLI"],"de":["Verwendet frische Subagenten pro Aufgabe","Zweistufige Überprüfung von Spezifikationen und Qualität","Verbessert die Qualität und Geschwindigkeit von Projekten","Ermöglicht die schnelle Iteration und die Implementierung von Plänen","Integriert sich mit Entwicklungstools wie CLI"],"pt":["Execução de planos por meio da dispatch de subagentes frescos por tarefa","Revisão em duas etapas: revisão de conformidade com especificações e revisão de qualidade de código","Melhoria da qualidade e da velocidade de iteração","Tarefas independentes para melhor gerenciamento de projetos","Integração com ferramentas de desenvolvimento para melhor eficiência"],"ru":["Выполнение планов путем отправки новых субагентов на каждую задачу","Двухэтапное ревью: ревью соответствия спецификациям и ревью качества кода","Повышение качества и скорости итерации","Независимые задачи для лучшего управления проектами","Интеграция с инструментами разработки для лучшей эффективности"],"ar":["تنفيذ الخطط من خلال إرسال وكلاء فرعيين جدد لكل مهمة","مراجعة على مرحلتين: مراجعة مطابقة للمواصفات ومراجعة جودة الكود","تحسين الجودة وسرعة التكرار","مهام مستقلة لتحسين إدارة المشاريع","التكامل مع أدوات التطوير لتحسين الفعالية"]},"keywords":{"en":["how to use subagent-driven development","what is subagent-driven development","subagent-driven development setup guide","subagent-driven development vs traditional development","subagent-driven development install","subagent-driven development two-stage review","subagent-driven development independent tasks","subagent-driven development spec compliance review","subagent-driven development code quality review"],"zh":["子代理驱动开发","AI代理","开发方法","两阶段审查","高质量开发","快速迭代","开发效率","任务管理","代码质量"],"ja":["サブエージェント駆動開発","AIエージェント","開発手法","2段階のレビュー","高品質開発","迅速なイテレーション","開発効率","タスク管理","コード品質"],"ko":["서브 에이전트 주도 개발","AI 에이전트","개발 방법","2단계 검토","고품질 개발","빠른 반복","개발 효율","작업 관리","코드 품질"],"es":["subagent-driven-development","desarrollo de software","herramientas de desarrollo","revisión de calidad","revisión de especificaciones","CLI","Agente de IA","Herramientas de Agente de IA"],"fr":["subagent-driven-development","développement de logiciels","outils de développement","revue de qualité","revue de spécifications","CLI","Agent IA","Outils d''Agent IA"],"de":["subagent-driven-development","Software-Entwicklung","Entwicklungstools","Qualitätsüberprüfung","Spezifikationsüberprüfung","CLI","KI-Agent","KI-Agent-Tools"],"pt":["desenvolvimento dirigido por subagentes","subagentes frescos","revisão em duas etapas","qualidade de código","velocidade de iteração","gerenciamento de projetos","ferramentas de desenvolvimento"],"ru":["разработка на основе субагентов","субагенты","двухэтапное ревью","качество кода","скорость итерации","управление проектами","инструменты разработки"],"ar":["تطوير مدفوع بالوكيل الفرعي","وكلاء فرعيين","مراجعة على مرحلتين","جودة الكود","سرعة التكرار","إدارة المشاريع","أدوات التطوير"]}},"owner":"benjgrad","repo":"workout-ai","repoPath":"benjgrad/workout-ai","stars":0,"forks":0,"updatedAt":"2026-02-23T03:54:12Z","topics":[],"category":"community","skillMd":{"name":"subagent-driven-development","description":"Use when executing implementation plans with independent tasks in the current session","bodyPreview":"# Subagent-Driven Development\n\nExecute plan by dispatching fresh subagent per task, with two-stage review after each: spec compliance review first, then code quality review.\n\n**Core principle:** Fresh subagent per task + two-stage review (spec then quality) = high quality, fast iteration\n\n## When to Use\n\n```dot\ndigraph when_to_use {\n    \"Have implementation plan?\" [shape=diamond];\n    \"Tasks mostly independent?\" [shape=diamond];\n    \"Stay in this session?\" [shape=diamond];\n    \"subagent-driven-d","body":"# Subagent-Driven Development\n\nExecute plan by dispatching fresh subagent per task, with two-stage review after each: spec compliance review first, then code quality review.\n\n**Core principle:** Fresh subagent per task + two-stage review (spec then quality) = high quality, fast iteration\n\n## When to Use\n\n```dot\ndigraph when_to_use {\n    \"Have implementation plan?\" [shape=diamond];\n    \"Tasks mostly independent?\" [shape=diamond];\n    \"Stay in this session?\" [shape=diamond];\n    \"subagent-driven-development\" [shape=box];\n    \"executing-plans\" [shape=box];\n    \"Manual execution or brainstorm first\" [shape=box];\n\n    \"Have implementation plan?\" -> \"Tasks mostly independent?\" [label=\"yes\"];\n    \"Have implementation plan?\" -> \"Manual execution or brainstorm first\" [label=\"no\"];\n    \"Tasks mostly independent?\" -> \"Stay in this session?\" [label=\"yes\"];\n    \"Tasks mostly independent?\" -> \"Manual execution or brainstorm first\" [label=\"no - tightly coupled\"];\n    \"Stay in this session?\" -> \"subagent-driven-development\" [label=\"yes\"];\n    \"Stay in this session?\" -> \"executing-plans\" [label=\"no - parallel session\"];\n}\n```\n\n**vs. Executing Plans (parallel session):**\n- Same session (no context switch)\n- Fresh subagent per task (no context pollution)\n- Two-stage review after each task: spec compliance first, then code quality\n- Faster iteration (no human-in-loop between tasks)\n\n## The Process\n\n```dot\ndigraph process {\n    rankdir=TB;\n\n    subgraph cluster_per_task {\n        label=\"Per Task\";\n        \"Dispatch implementer subagent (./implementer-prompt.md)\" [shape=box];\n        \"Implementer subagent asks questions?\" [shape=diamond];\n        \"Answer questions, provide context\" [shape=box];\n        \"Implementer subagent implements, tests, commits, self-reviews\" [shape=box];\n        \"Dispatch spec reviewer subagent (./spec-reviewer-prompt.md)\" [shape=box];\n        \"Spec reviewer subagent confirms code matches spec?\" [shape=diamond];\n        \"Implementer subagent fixes spec gaps\" [shape=box];\n        \"Dispatch code quality reviewer subagent (./code-quality-reviewer-prompt.md)\" [shape=box];\n        \"Code quality reviewer subagent approves?\" [shape=diamond];\n        \"Implementer subagent fixes quality issues\" [shape=box];\n        \"Mark task complete in TodoWrite\" [shape=box];\n    }\n\n    \"Read plan, extract all tasks with full text, note context, create TodoWrite\" [shape=box];\n    \"More tasks remain?\" [shape=diamond];\n    \"Dispatch final code reviewer subagent for entire implementation\" [shape=box];\n    \"Use superpowers:finishing-a-development-branch\" [shape=box style=filled fillcolor=lightgreen];\n\n    \"Read plan, extract all tasks with full text, note context, create TodoWrite\" -> \"Dispatch implementer subagent (./implementer-prompt.md)\";\n    \"Dispatch implementer subagent (./implementer-prompt.md)\" -> \"Implementer subagent asks questions?\";\n    \"Implementer subagent asks questions?\" -> \"Answer questions, provide context\" [label=\"yes\"];\n    \"Answer questions, provide context\" -> \"Dispatch implementer subagent (./implementer-prompt.md)\";\n    \"Implementer subagent asks questions?\" -> \"Implementer subagent implements, tests, commits, self-reviews\" [label=\"no\"];\n    \"Implementer subagent implements, tests, commits, self-reviews\" -> \"Dispatch spec reviewer subagent (./spec-reviewer-prompt.md)\";\n    \"Dispatch spec reviewer subagent (./spec-reviewer-prompt.md)\" -> \"Spec reviewer subagent confirms code matches spec?\";\n    \"Spec reviewer subagent confirms code matches spec?\" -> \"Implementer subagent fixes spec gaps\" [label=\"no\"];\n    \"Implementer subagent fixes spec gaps\" -> \"Dispatch spec reviewer subagent (./spec-reviewer-prompt.md)\" [label=\"re-review\"];\n    \"Spec reviewer subagent confirms code matches spec?\" -> \"Dispatch code quality reviewer subagent (./code-quality-reviewer-prompt.md)\" [label=\"yes\"];\n    \"Dispatch code quality reviewer subagent (./code-quality-reviewer-prompt.md)\" -> \"Code quality reviewer subagent approves?\";\n    \"Code quality reviewer subagent approves?\" -> \"Implementer subagent fixes quality issues\" [label=\"no\"];\n    \"Implementer subagent fixes quality issues\" -> \"Dispatch code quality reviewer subagent (./code-quality-reviewer-prompt.md)\" [label=\"re-review\"];\n    \"Code quality reviewer subagent approves?\" -> \"Mark task complete in TodoWrite\" [label=\"yes\"];\n    \"Mark task complete in TodoWrite\" -> \"More tasks remain?\";\n    \"More tasks remain?\" -> \"Dispatch implementer subagent (./implementer-prompt.md)\" [label=\"yes\"];\n    \"More tasks remain?\" -> \"Dispatch final code reviewer subagent for entire implementation\" [label=\"no\"];\n    \"Dispatch final code reviewer subagent for entire implementation\" -> \"Use superpowers:finishing-a-development-branch\";\n}\n```\n\n## Prompt Templates\n\n- `./implementer-prompt.md` - Dispatch implementer subagent\n- `./spec-reviewer-prompt.md` - Dispatch spec compliance reviewer subagent\n- `./code-quality-reviewer-prompt.md` - Dispatch code quality reviewer subagent\n\n## Example Workflow\n\n```\nYou: I''m using Subagent-Driven Development to execute this plan.\n\n[Read plan file once: docs/plans/feature-plan.md]\n[Extract all 5 tasks with full text and context]\n[Create TodoWrite with all tasks]\n\nTask 1: Hook installation script\n\n[Get Task 1 text and context (already extracted)]\n[Dispatch implementation subagent with full task text + context]\n\nImplementer: \"Before I begin - should the hook be installed at user or system level?\"\n\nYou: \"User level (~/.config/superpowers/hooks/)\"\n\nImplementer: \"Got it. Implementing now...\"\n[Later] Implementer:\n  - Implemented install-hook command\n  - Added tests, 5/5 passing\n  - Self-review: Found I missed --force flag, added it\n  - Committed\n\n[Dispatch spec compliance reviewer]\nSpec reviewer: ✅ Spec compliant - all requirements met, nothing extra\n\n[Get git SHAs, dispatch code quality reviewer]\nCode reviewer: Strengths: Good test coverage, clean. Issues: None. Approved.\n\n[Mark Task 1 complete]\n\nTask 2: Recovery modes\n\n[Get Task 2 text and context (already extracted)]\n[Dispatch implementation subagent with full task text + context]\n\nImplementer: [No questions, proceeds]\nImplementer:\n  - Added verify/repair modes\n  - 8/8 tests passing\n  - Self-review: All good\n  - Committed\n\n[Dispatch spec compliance reviewer]\nSpec reviewer: ❌ Issues:\n  - Missing: Progress reporting (spec says \"report every 100 items\")\n  - Extra: Added --json flag (not requested)\n\n[Implementer fixes issues]\nImplementer: Removed --json flag, added progress reporting\n\n[Spec reviewer reviews again]\nSpec reviewer: ✅ Spec compliant now\n\n[Dispatch code quality reviewer]\nCode reviewer: Strengths: Solid. Issues (Important): Magic number (100)\n\n[Implementer fixes]\nImplementer: Extracted PROGRESS_INTERVAL constant\n\n[Code reviewer reviews again]\nCode reviewer: ✅ Approved\n\n[Mark Task 2 complete]\n\n...\n\n[After all tasks]\n[Dispatch final code-reviewer]\nFinal reviewer: All requirements met, ready to merge\n\nDone!\n```\n\n## Advantages\n\n**vs. Manual execution:**\n- Subagents follow TDD naturally\n- Fresh context per task (no confusion)\n- Parallel-safe (subagents don''t interfere)\n- Subagent can ask questions (before AND during work)\n\n**vs. Executing Plans:**\n- Same session (no handoff)\n- Continuous progress (no waiting)\n- Review checkpoints automatic\n\n**Efficiency gains:**\n- No file reading overhead (controller provides full text)\n- Controller curates exactly what context is needed\n- Subagent gets complete information upfront\n- Questions surfaced before work begins (not after)\n\n**Quality gates:**\n- Self-review catches issues before handoff\n- Two-stage review: spec compliance, then code quality\n- Review loops ensure fixes actually work\n- Spec compliance prevents over/under-building\n- Code quality ensures implementation is well-built\n\n**Cost:**\n- More subagent invocations (implementer + 2 reviewers per task)\n- Controller does more prep work (extracting all tasks upfront)\n- Review loops add iterations\n- But catches issues early (cheaper than debugging later)\n\n## Red Flags\n\n**Never:**\n- Start implementation on main/master branch without explicit user consent\n- Skip reviews (spec compliance OR code quality)\n- Proceed with unfixed issues\n- Dispatch multiple implementation subagents in parallel (conflicts)\n- Make subagent read plan file (provide full text instead)\n- Skip scene-setting context (subagent needs to understand where task fits)\n- Ignore subagent questions (answer before letting them proceed)\n- Accept \"close enough\" on spec compliance (spec reviewer found issues = not done)\n- Skip review loops (reviewer found issues = implementer fixes = review again)\n- Let implementer self-review replace actual review (both are needed)\n- **Start code quality review before spec compliance is ✅** (wrong order)\n- Move to next task while either review has open issues\n\n**If subagent asks questions:**\n- Answer clearly and completely\n- Provide additional context if needed\n- Don''t rush them into implementation\n\n**If reviewer finds issues:**\n- Implementer (same subagent) fixes them\n- Reviewer reviews again\n- Repeat until approved\n- Don''t skip the re-review\n\n**If subagent fails task:**\n- Dispatch fix subagent with specific instructions\n- Don''t try to fix manually (context pollution)\n\n## Integration\n\n**Required workflow skills:**\n- **superpowers:writing-plans** - Creates the plan this skill executes\n- **superpowers:requesting-code-review** - Code review template for reviewer subagents\n- **superpowers:finishing-a-development-branch** - Complete development after all tasks\n\n**Subagents should use:**\n- **superpowers:test-driven-development** - Subagents follow TDD for each task\n\n**Alternative workflow:**\n- **superpowers:executing-plans** - Use for parallel session instead of same-session execution\n"},"lastSynced":"2026-03-07T04:07:39.514Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Agents requiring efficient task execution and high-quality iteration, such as Cursor, Windsurf, or Claude Code.","zh":"适用于需要高效任务执行和高质量迭代的自主代理，如Cursor、Windsurf或Claude Code。","ja":"タスクの効率的な実行と高品質のイテレーションを必要とするAutonomous Agentsに適しています。例としては、Cursor、Windsurf、またはClaude Codeなどがあります。","ko":"효율적인 작업 실행과 높은 품질의 반복이 필요한 자율 에이전트에 적합합니다. 예를 들어, Cursor, Windsurf 또는 Claude Code와 같은 에이전트가 있습니다.","es":"Ideal para Agentes Autónomos que requieren una ejecución de tareas eficiente y una iteración de alta calidad, como Cursor, Windsurf o Claude Code.","fr":"Idéal pour les Agents Autonomes nécessitant une exécution de tâches efficace et une itération de haute qualité, tels que Cursor, Windsurf ou Claude Code.","de":"Ideal für autonome Agenten, die eine effiziente Aufgabenausführung und eine hochwertige Iteration benötigen, wie z. B. Cursor, Windsurf oder Claude Code.","pt":"Ideal para Agentes Autônomos que requerem execução de tarefas eficiente e iteração de alta qualidade, como Cursor, Windsurf ou Claude Code.","ru":"Идеально для автономных агентов, требующих эффективного выполнения задач и высококачественной итерации, таких как Cursor, Windsurf или Claude Code.","ar":"مثالي للوكلاء المستقلين الذين يتطلبون تنفيذا كفؤا لل任务 وتكرار عالي الجودة، مثل Cursor أو Windsurf أو Claude Code."},"recommendation":{"en":"Empowers agents to execute plans by dispatching fresh subagents per task, leveraging two-stage reviews for spec compliance and code quality, ensuring high-quality and fast iteration through protocols like subagent-driven development.","zh":"通过为每个任务分派新的子代理，利用两阶段审查以确保规格符合性和代码质量，通过诸如子代理驱动的开发等协议，赋予代理执行计划的能力，确保高质量和快速的迭代。","ja":"各タスクごとに新しいサブエージェントを割り当てることで、仕様の準拠とコード品質を確保するための2段階のレビューを利用し、サブエージェント駆動の開発などのプロトコルを通じて、高品質で迅速なイテレーションを実現します。","ko":"각 작업마다 새로운 서브 에이전트를 할당함으로써, 사양 준수 및 코드 품질을 보장하기 위한 2단계 검토를 활용하여, 서브 에이전트 주도 개발과 같은 프로토콜을 통해, 고품질 및 빠른 반복을 보장하는 에이전트의 계획 실행을 가능하게 합니다.","es":"Habilita a los agentes a ejecutar planes mediante la asignación de subagentes frescos por tarea, aprovechando las revisiones de dos etapas para el cumplimiento de especificaciones y la calidad del código, garantizando una iteración rápida y de alta calidad a través de protocolos como el desarrollo impulsado por subagentes.","fr":"Permet aux agents d''exécuter des plans en affectant des sous-agents frais par tâche, en exploitant les examens en deux étapes pour la conformité aux spécifications et la qualité du code, assurant une itération rapide et de haute qualité via des protocoles tels que le développement piloté par sous-agent.","de":"Ermöglicht es Agenten, Pläne durch die Zuweisung frischer Subagenten pro Aufgabe auszuführen, indem sie zweistufige Überprüfungen für die Spezifikationskonformität und die Codequalität nutzen, um eine schnelle und hochwertige Iteration durch Protokolle wie die subagentengetriebene Entwicklung sicherzustellen.","pt":"Habilita os agentes a executar planos enviando subagentes frescos por tarefa, aproveitando revisões em duas etapas para conformidade com especificações e qualidade de código, garantindo iteração rápida e de alta qualidade por meio de protocolos como desenvolvimento impulsionado por subagentes.","ru":"Наделяет агентов возможностью выполнять планы, отправляя свежих субагентов на каждую задачу, используя двухэтапные обзоры для соблюдения спецификаций и качества кода, гарантируя высококачественную и быструю итерацию через протоколы, такие как разработка, управляемая субагентами.","ar":"تمكّن الوكلاء من تنفيذ الخطط من خلال إرسال وكلاء فرعيين جدد لكل مهمة، واستخدام استعراضات على مرحلتين للامتثال للمواصفات وجودة الشفرة، وضمان التكرار السريع والعالي الجودة من خلال بروتوكولات مثل التطوير الموجه بالوكيل الفرعي."},"useCases":{"en":["Dispatching subagents for independent tasks","Implementing two-stage review processes for quality assurance","Optimizing task execution for fast iteration"],"zh":["为独立任务分派子代理","实施两阶段审查过程以确保质量","优化任务执行以实现快速迭代"],"ja":["独立タスク用のサブエージェントの割り当て","品質保証のための2段階のレビュー処理の実装","高速イテレーションのためのタスク実行の最適化"],"ko":["독립 작업을 위한 서브 에이전트 할당","품질 보증을 위한 2단계 검토 프로세스 구현","빠른 반복을 위한 작업 실행 최적화"],"es":["Asignación de subagentes para tareas independientes","Implementación de procesos de revisión de dos etapas para la garantía de calidad","Optimización de la ejecución de tareas para una iteración rápida"],"fr":["Affectation de sous-agents pour des tâches indépendantes","Mise en œuvre de processus d''examen en deux étapes pour l''assurance qualité","Optimisation de l''exécution des tâches pour une itération rapide"],"de":["Zuweisung von Subagenten für unabhängige Aufgaben","Implementierung von zweistufigen Überprüfungsprozessen für die Qualitätsicherung","Optimierung der Aufgabenausführung für eine schnelle Iteration"],"pt":["Enviar subagentes para tarefas independentes","Implementar processos de revisão em duas etapas para garantia de qualidade","Otimizar a execução de tarefas para iteração rápida"],"ru":["Отправка субагентов для независимых задач","Реализация двухэтапных процессов обзора для обеспечения качества","Оптимизация выполнения задач для быстрой итерации"],"ar":["إرسال وكلاء فرعيين لمهام مستقلة","تنفيذ عمليات استعراض على مرحلتين لتأمين الجودة","تحسين تنفيذ المهام لتكرار سريع"]},"limitations":{"en":["Requires independent tasks","Needs two-stage review process implementation","Limited to agents capable of dispatching subagents"],"zh":["需要独立任务","需要两阶段审查过程的实现","仅适用于能够分派子代理的代理"],"ja":["独立タスクが必要","2段階のレビュー処理の実装が必要","サブエージェントを割り当てることができるエージェントのみに限定"],"ko":["독립 작업이 필요","2단계 검토 프로세스 구현이 필요","서브 에이전트를 할당할 수 있는 에이전트에만 제한"],"es":["Requiere tareas independientes","Necesita la implementación de un proceso de revisión de dos etapas","Limitado a agentes capaces de asignar subagentes"],"fr":["Nécessite des tâches indépendantes","Nécessite la mise en œuvre d''un processus d''examen en deux étapes","Limité aux agents capables d''affecter des sous-agents"],"de":["Erfordert unabhängige Aufgaben","Benötigt die Implementierung eines zweistufigen Überprüfungsprozesses","Eingeschränkt auf Agenten, die in der Lage sind, Subagenten zuzuweisen"],"pt":["Requer tarefas independentes","Necessita implementação de processo de revisão em duas etapas","Limitado a agentes capazes de enviar subagentes"],"ru":["Требует независимых задач","Требует реализации двухэтапного процесса обзора","Ограничен агентами, способными отправлять субагентов"],"ar":["يتطلب مهام مستقلة","يحتاج إلى تنفيذ عملية استعراض على مرحلتين","محدود بالوكلاء القادرين على إرسال وكلاء فرعيين"]},"version":4},"contentHash":"cb483bee1ad1478e363f95493adf4ab349d1cfc9eeec173a5aff260a882169aa","qualityScore":51}');
