INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('benjgrad/workout-ai/subagent-driven-development', 'subagent-driven-development', 'benjgrad', 'workout-ai', 'community', 'subagent-driven-development benjgrad workout-ai community Subagent-driven development executes plans by dispatching fresh subagents per task, with two-stage reviews for high-quality, fast iteration. This skill benefits developers working on independent tasks. 子代理驱动开发是一种通过分派新子代理执行任务并进行两阶段审查的开发方法，实现高质量和快速迭代 サブエージェント駆動開発は、タスクを新しいサブエージェントに割り当てて実行し、2段階のレビューを実施する開発手法であり、高品質と迅速なイテレーションを実現する 서브 에이전트 주도 개발은 새 서브 에이전트를 할당하여 작업을 실행하고 2단계 검토를 수행하는 개발 방법으로 고품질과 빠른 반복을 실현합니다 Subagent-driven-development es una técnica que utiliza subagentes frescos por tarea con revisión de especificaciones y calidad para mejorar la calidad y velocidad de los proyectos Subagent-driven-development est une technique qui utilise des sous-agents frais par tâche avec revue de spécifications et de qualité pour améliorer la qualité et la vitesse des projets Subagent-driven-development ist eine Technik, die frische Subagenten pro Aufgabe mit zweistufiger Überprüfung verwendet, um die Qualität und Geschwindigkeit von Projekten zu verbessern O desenvolvimento dirigido por subagentes é uma abordagem que executa planos por meio da dispatch de subagentes frescos por tarefa, com revisão em duas etapas Разработка на основе субагентов - это подход, который выполняет планы путем отправки новых субагентов на каждую задачу, с двухэтапным ревью تطوير مدفوع بالوكيل الفرعي هو نهج ينفذ الخطط من خلال إرسال وكلاء فرعيين جدد لكل مهمة، مع مراجعة على مرحلتين how to use subagent-driven development what is subagent-driven development subagent-driven development setup guide subagent-driven development vs traditional development subagent-driven development install subagent-driven development two-stage review subagent-driven development independent tasks subagent-driven development spec compliance review subagent-driven development code quality review 子代理驱动开发 AI代理 开发方法 两阶段审查 高质量开发 快速迭代 开发效率 任务管理 代码质量 Executes plans by dispatching fresh subagents per task Two-stage review process for spec compliance and code quality Supports independent tasks with fresh subagent allocation Enables high-quality, fast iteration with two-stage review Uses dot digraph for visualizing when to use subagent-driven development Implements core principle of fresh subagent per task plus two-stage review Subagent-driven development is a methodology that executes plans by dispatching fresh subagents per task, with two-stage reviews for spec compliance and code quality.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('diegoknsk/video-processing-engine-video-management-lambda/api-response-standardization', 'community', 'diegoknsk', 'video-processing-engine-video-management-lambda', 'diegoknsk/video-processing-engine-video-management-lambda', 'api-response-standardization', 0, 0, 51, '2026-03-01T21:39:26Z', '2026-03-07T13:10:23.594Z', '7a738207f7e3d87e3204bad122ccfcf607cba5f46d7f8eab4b3c1b37ee38376b', '{"id":"diegoknsk/video-processing-engine-video-management-lambda/api-response-standardization","name":"api-response-standardization","description":{"en":"The api-response-standardization skill standardizes API responses, including success and error messages, for AWS Lambda applications, benefiting developers with consistent output.","zh":"API响应标准化是一个用于标准化API响应格式的技术，包括成功和错误响应的封装和全局异常处理","ja":"APIレスポンス標準化は、APIのレスポンス形式を標準化する技術であり、成功およびエラー応答の封装とグローバル例外処理を含む","ko":"API 응답 표준화는 API 응답 형식을 표준화하는 기술로 성공 및 오류 응답의封装과 全局 예외 처리를 포함합니다","es":"La estandarización de respuestas de API permite un formato de respuesta único y consistente para respuestas de éxito y error","fr":"La standardisation des réponses d''API permet un format de réponse unique et cohérent pour les réponses de succès et d''erreur","de":"Die Standardisierung von API-Antworten ermöglicht ein einheitliches und konsistentes Antwortformat für Erfolgs- und Fehlerantworten","pt":"A padronização de respostas de API é essencial para garantir respostas consistentes e fáceis de entender. Ela envolve a implementação de um envelope de resposta e tratamento de exceções globais.","ru":"Стандартизация ответов API необходима для обеспечения последовательных и легко понимаемых ответов. Она включает в себя реализацию обёртки ответа и глобального обработки исключений.","ar":"توحيد استجابات واجهة برمجة التطبيقات ضروري لضمان استجابات متسقة وسهلة الفهم. يتضمن تنفيذ غلاف استجابة ومعالجة الاستثناءات العالمية"},"seo":{"title":{"en":"api-response-standardization: Standardizing API Responses...","zh":"API响应标准化Setup Guide - AIエージェント解决方案","ja":"APIレスポンス標準化Best Practices - AIエージェントの活用","ko":"API 응답 표준화 구축 가이드 - AI 에이전트 도구","es":"Guía de Configuración para API Response Standardization","fr":"Meilleures Pratiques pour l''API Response Standardization","de":"Einrichtungsleitfaden für API-Antwort-Standardisierung","pt":"Padronização de Respostas de API: Guia de Configuração","ru":"Стандартизация ответов API: Руководство по настройке ИИ А...","ar":"توحيد استجابات واجهة برمجة التطبيقات: دليل الإعداد لأدوات..."},"description":{"en":"Discover how to standardize API responses with api-response-standardization. Learn how to implement envelopes, handle exceptions, and more. Get started now!","zh":"了解API响应标准化的重要性和实施方法，包括-envelope响应、全局过滤和异常处理，以提高API的可靠性和可维护性","ja":"APIレスポンス標準化の導入方法とその重要性を学び、APIの信頼性と保守性を高める","ko":"API 응답 표준화를 구현하여 API의 신뢰성과 유지 보수성을 높이는 방법에 대해 알아보세요","es":"Aprende a implementar la estandarización de respuestas de API con AWS Lambda para un formato de respuesta único y consistente","fr":"Découvrez comment mettre en œuvre la standardisation des réponses d''API avec AWS Lambda pour un format de réponse unique et cohérent","de":"Erfahren Sie, wie Sie die Standardisierung von API-Antworten mit AWS Lambda für ein einheitliches und konsistentes Antwortformat implementieren","pt":"Aprenda a padronizar respostas de sucesso e erro da API com envelope de resposta e tratamento de exceções globais","ru":"Узнайте, как стандартизировать ответы API с помощью обёртки ответа и глобального обработки исключений для ИИ Агентов","ar":"تعرف على كيفية توحيد استجابات واجهة برمجة التطبيقات بنجاح وخطأ مع معالجة الاستثناءات العالمية لأدوات الذكاء الاصطناعي"},"definition":{"en":"api-response-standardization is a technique for standardizing API responses, including implementing envelopes and handling exceptions, to provide consistent output for API consumers.","zh":"API响应标准化是一种用于标准化API响应格式的技术，确保API响应的一致性和可靠性","ja":"APIレスポンス標準化は、APIのレスポンス形式を標準化する技術であり、API応答の一貫性と信頼性を確保する","ko":"API 응답 표준화는 API 응답 형식을 표준화하는 기술로 API 응답의 일관성과 신뢰성을 보장합니다","es":"La estandarización de respuestas de API es un proceso que implica la creación de un formato de respuesta único para respuestas de éxito y error","fr":"La standardisation des réponses d''API est un processus qui consiste à créer un format de réponse unique pour les réponses de succès et d''erreur","de":"Die Standardisierung von API-Antworten ist ein Prozess, der die Erstellung eines einheitlichen Antwortformats für Erfolgs- und Fehlerantworten beinhaltet","pt":"Padronização de respostas de API é a implementação de um formato único para respostas de sucesso e erro","ru":"Стандартизация ответов API - это реализация единого формата для ответов успеха и ошибки","ar":"توحيد استجابات واجهة برمجة التطبيقات هو تنفيذ تنسيق موحد لاستجابات النجاح والخطأ"},"features":{"en":["Implements envelope of response with success, data/error, and timestamp","Creates global filter to encapsulate 200/201 responses automatically","Handles exceptions globally and returns errors in a consistent format","Supports JSON contract for standardized responses","Enables padding of success and error responses in a unique format"],"zh":["标准化成功和错误响应的格式","实现Envelope响应（success、data/error、timestamp）","创建全局过滤器以自动封装200/201响应","全局异常处理以返回一致的错误格式","支持AWS Lambda和S3的集成"],"ja":["成功およびエラー応答の形式を標準化する","Envelope応答（success、data/error、timestamp）を実装する","グローバルフィルターを作成して200/201応答を自動的にカプセル化する","グローバル例外処理を実装して一貫したエラー形式を返す","AWS LambdaとS3の統合をサポートする"],"ko":["성공 및 오류 응답의 형식을 표준화합니다","Envelope 응답（success、data/error、timestamp）을 구현합니다","전역 필터를 생성하여 200/201 응답을 자동으로 캡슐화합니다","전역 예외 처리를 구현하여 일관된 오류 형식을 반환합니다","AWS Lambda와 S3의 통합을 지원합니다"],"es":["Implementación de un envelope de respuesta con success, data/error y timestamp","Creación de un filtro global para respuestas de éxito","Tratamiento de excepciones globales y retorno de errores en formato consistente","Compatibilidad con AWS Lambda","Soporte para respuestas de éxito y error en formato JSON"],"fr":["Mise en œuvre d''un enveloppe de réponse avec success, data/error et timestamp","Création d''un filtre global pour les réponses de succès","Traitement des exceptions globales et retour d''erreurs en format cohérent","Compatibilité avec AWS Lambda","Prise en charge des réponses de succès et d''erreur au format JSON"],"de":["Implementierung eines Antwort-Envelopes mit success, data/error und timestamp","Erstellung eines globalen Filters für Erfolgsantworten","Behandlung globaler Ausnahmen und Rückgabe von Fehlern im konsistenten Format","Kompatibilität mit AWS Lambda","Unterstützung für Erfolgs- und Fehlerantworten im JSON-Format"],"pt":["Implementação de envelope de resposta com success, data/error e timestamp","Tratamento de exceções globais para respostas de erro consistentes","Criação de filtro global para encapsular respostas 200/201 automaticamente","Padronização de respostas de sucesso e erro em um formato único","Suporte a contratos JSON para respostas de sucesso e erro"],"ru":["Реализация обёртки ответа с success, data/error и timestamp для ИИ Агентов","Глобальное обработки исключений для последовательных ответов ошибки","Создание глобального фильтра для автоматического封装 ответов 200/201","Стандартизация ответов успеха и ошибки в едином формате","Поддержка контрактов JSON для ответов успеха и ошибки"],"ar":["تنفيذ غلاف استجابة مع نجاح، بيانات / خطأ وتاريخ ووقت لأدوات الذكاء الاصطناعي","معالجة الاستثناءات العالمية لاستجابات خطأ متسقة","إنشاء مرشح عالمي لحزم استجابات 200/201 تلقائيًا","توحيد استجابات النجاح والخطأ في تنسيق موحد","دعم عقود JSON لاستجابات النجاح والخطأ"]},"keywords":{"en":["how to use api-response-standardization","api-response-standardization setup guide","standardizing api responses","api-response-standardization vs JSON API","api-response-standardization install","what is api-response-standardization","api-response-standardization alternative","implementing api envelopes","handling api exceptions"],"zh":["API响应标准化","AIエージェント","Envelope响应","全局过滤","异常处理","AWS Lambda","S3集成","API设计","API开发"],"ja":["APIレスポンス標準化","AIエージェント","Envelope応答","グローバルフィルター","例外処理","AWS Lambda","S3統合","API設計","API開発"],"ko":["API 응답 표준화","AI 에이전트","Envelope 응답","전역 필터","예외 처리","AWS Lambda","S3 통합","API 설계","API 개발"],"es":["estandarización de respuestas de API","AWS Lambda","envelope de respuesta","filtro global","excepciones globales","formato de respuesta único","API Response Standardization","Herramientas de AI para desarrolladores","Agentes de IA para desarrolladores"],"fr":["standardisation des réponses d''API","AWS Lambda","enveloppe de réponse","filtre global","exceptions globales","format de réponse unique","API Response Standardization","Outils d''IA pour les développeurs","Agents d''IA pour les développeurs"],"de":["Standardisierung von API-Antworten","AWS Lambda","Antwort-Enveloppe","globaler Filter","globale Ausnahmen","einheitliches Antwortformat","API Response Standardization","AI-Tools für Entwickler","AI-Agents für Entwickler"],"pt":["padronização de respostas de api","envelope de resposta","tratamento de exceções globais","filtro global","contratos json","api response standardization","amazon web services","aws lambda"],"ru":["стандартизация ответов api","обёртка ответа","глобальное обработки исключений","глобальный фильтр","контракты json","ии агенты","amazon web services","aws lambda"],"ar":["توحيد استجابات واجهة برمجة التطبيقات","غلاف استجابة","معالجة الاستثناءات العالمية","مرشح عالمي","عقود json","أدوات الذكاء الاصطناعي","amazon web services","aws lambda"]}},"owner":"diegoknsk","repo":"video-processing-engine-video-management-lambda","repoPath":"diegoknsk/video-processing-engine-video-management-lambda","stars":0,"forks":0,"updatedAt":"2026-03-01T21:39:26Z","topics":[],"category":"community","skillMd":{"name":"api-response-standardization","description":"Padroniza respostas de sucesso e erro da API em formato único (success, data/error, timestamp). Use quando padronizar respostas HTTP, criar envelope de API, formatar erros globais, ApiResponse, ApiErrorResponse, filtros de resposta ou middleware de exceção.","bodyPreview":"# API Response Standardization\n\n## Quando Usar\n\n- Padronizar **respostas de sucesso e erro** da API em um formato único\n- Implementar **envelope** de resposta (`success`, `data`/`error`, `timestamp`)\n- Criar **filtro global** para encapsular 200/201 automaticamente\n- Tratar **exceções** globalmente e retornar erros em formato consistente\n- Palavras-chave: \"padronizar resposta\", \"envelope API\", \"formato de erro\", \"ApiResponse\", \"GlobalException\"\n\n## Contrato JSON\n\n### Sucesso (200/201)\n\n```json\n{","body":"# API Response Standardization\n\n## Quando Usar\n\n- Padronizar **respostas de sucesso e erro** da API em um formato único\n- Implementar **envelope** de resposta (`success`, `data`/`error`, `timestamp`)\n- Criar **filtro global** para encapsular 200/201 automaticamente\n- Tratar **exceções** globalmente e retornar erros em formato consistente\n- Palavras-chave: \"padronizar resposta\", \"envelope API\", \"formato de erro\", \"ApiResponse\", \"GlobalException\"\n\n## Contrato JSON\n\n### Sucesso (200/201)\n\n```json\n{\n    \"success\": true,\n    \"data\": { ... },\n    \"timestamp\": \"2026-02-21T20:14:35.487525Z\"\n}\n```\n\n- `success`: sempre `true`\n- `data`: payload retornado pelo endpoint (objeto ou array)\n- `timestamp`: ISO 8601 UTC\n\n### Erro (4xx/5xx)\n\n```json\n{\n    \"success\": false,\n    \"error\": {\n        \"code\": \"Unauthorized\",\n        \"message\": \"Acesso não autorizado.\"\n    },\n    \"timestamp\": \"2026-02-21T20:14:26.9071028Z\"\n}\n```\n\n- `success`: sempre `false`\n- `error.code`: identificador do erro (ex.: Unauthorized, InvalidCredentials, BadRequest)\n- `error.message`: mensagem descritiva para o cliente\n- `timestamp`: ISO 8601 UTC\n\n## Implementação\n\n### 1. Modelos (Api/Models)\n\n**ApiResponse.cs** — resposta de sucesso:\n\n```csharp\nnamespace YourApi.Models;\n\npublic class ApiResponse<T>\n{\n    public bool Success { get; init; } = true;\n    public T? Data { get; init; }\n    public DateTime Timestamp { get; init; } = DateTime.UtcNow;\n\n    public static ApiResponse<T> CreateSuccess(T data) => new()\n    {\n        Success = true,\n        Data = data,\n        Timestamp = DateTime.UtcNow\n    };\n}\n```\n\n**ApiErrorResponse.cs** — resposta de erro:\n\n```csharp\nnamespace YourApi.Models;\n\npublic class ApiErrorResponse\n{\n    public bool Success { get; init; } = false;\n    public ErrorDetail Error { get; init; } = null!;\n    public DateTime Timestamp { get; init; } = DateTime.UtcNow;\n\n    public static ApiErrorResponse Create(string code, string message) => new()\n    {\n        Success = false,\n        Error = new ErrorDetail { Code = code, Message = message },\n        Timestamp = DateTime.UtcNow\n    };\n}\n\npublic class ErrorDetail\n{\n    public string Code { get; init; } = string.Empty;\n    public string Message { get; init; } = string.Empty;\n}\n```\n\n### 2. Filtro de sucesso (Api/Filters)\n\n**ApiResponseFilter.cs** — encapsula automaticamente 200/201 em `ApiResponse<T>`:\n\n```csharp\nusing Microsoft.AspNetCore.Mvc;\nusing Microsoft.AspNetCore.Mvc.Filters;\nusing YourApi.Models;\n\npublic class ApiResponseFilter : IActionFilter\n{\n    private readonly ILogger<ApiResponseFilter> _logger;\n\n    public ApiResponseFilter(ILogger<ApiResponseFilter> logger) => _logger = logger;\n\n    public void OnActionExecuting(ActionExecutingContext context) { }\n\n    public void OnActionExecuted(ActionExecutedContext context)\n    {\n        if (context.Result is OkObjectResult okResult)\n        {\n            context.Result = new ObjectResult(ApiResponse<object>.CreateSuccess(okResult.Value!))\n                { StatusCode = StatusCodes.Status200OK };\n            return;\n        }\n        if (context.Result is ObjectResult objectResult &&\n            (objectResult.StatusCode == StatusCodes.Status200OK || objectResult.StatusCode == StatusCodes.Status201Created))\n        {\n            context.Result = new ObjectResult(ApiResponse<object>.CreateSuccess(objectResult.Value!))\n                { StatusCode = objectResult.StatusCode };\n        }\n    }\n}\n```\n\nControllers continuam retornando `Ok(model)` ou `CreatedAtAction(..., model)`; o filtro envolve em `{ \"success\": true, \"data\": model, \"timestamp\": \"...\" }`.\n\n### 3. Middleware de exceção (Api/Middleware)\n\n**GlobalExceptionMiddleware.cs** — captura exceções, mapeia para (statusCode, code, message) e retorna `ApiErrorResponse`:\n\n```csharp\nusing System.Text.Json;\nusing Microsoft.AspNetCore.Http;\nusing YourApi.Models;\n\npublic class GlobalExceptionMiddleware\n{\n    private readonly RequestDelegate _next;\n    private readonly ILogger<GlobalExceptionMiddleware> _logger;\n\n    public GlobalExceptionMiddleware(RequestDelegate next, ILogger<GlobalExceptionMiddleware> logger)\n    {\n        _next = next;\n        _logger = logger;\n    }\n\n    public async Task InvokeAsync(HttpContext context)\n    {\n        try\n        {\n            await _next(context);\n        }\n        catch (Exception ex)\n        {\n            _logger.LogError(ex, \"Unhandled exception: {ExceptionType}\", ex.GetType().Name);\n            await HandleExceptionAsync(context, ex);\n        }\n    }\n\n    private static async Task HandleExceptionAsync(HttpContext context, Exception exception)\n    {\n        var (statusCode, code, message) = MapException(exception);\n        context.Response.StatusCode = statusCode;\n        context.Response.ContentType = \"application/json\";\n\n        var errorResponse = ApiErrorResponse.Create(code, message);\n        var options = new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.CamelCase };\n        await context.Response.WriteAsync(JsonSerializer.Serialize(errorResponse, options));\n    }\n\n    private static (int statusCode, string code, string message) MapException(Exception exception)\n    {\n        return exception switch\n        {\n            UnauthorizedAccessException => (StatusCodes.Status401Unauthorized, \"Unauthorized\", \"Acesso não autorizado.\"),\n            ArgumentException => (StatusCodes.Status400BadRequest, \"BadRequest\", \"Requisição inválida.\"),\n            KeyNotFoundException => (StatusCodes.Status404NotFound, \"NotFound\", \"Recurso não encontrado.\"),\n            _ => (StatusCodes.Status500InternalServerError, \"InternalServerError\", \"Erro interno do servidor.\")\n        };\n    }\n}\n```\n\n**Importante:** estender `MapException` com os tipos de exceção do domínio ou de SDKs (ex.: Cognito, EF Core). Sempre retornar tripla `(statusCode, code, message)` e usar `ApiErrorResponse.Create(code, message)`.\n\n### 4. Registro (Program.cs)\n\n```csharp\n// Filtro global de resposta (sucesso)\nbuilder.Services.AddControllers(options =>\n{\n    options.Filters.Add<ApiResponseFilter>();\n});\n\n// JSON: camelCase e timestamp consistente\nbuilder.Services.AddControllers()\n    .AddJsonOptions(options =>\n    {\n        options.JsonSerializerOptions.PropertyNamingPolicy = JsonNamingPolicy.CamelCase;\n        options.JsonSerializerOptions.DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull;\n    });\n\n// Middleware de exceção (deve estar cedo no pipeline)\nvar app = builder.Build();\napp.UseMiddleware<GlobalExceptionMiddleware>();\n// ... UseRouting, UseAuthorization, MapControllers\n```\n\n## Princípios\n\n- **Sucesso:** controllers retornam apenas o payload; o filtro adiciona `success`, `data` e `timestamp`.\n- **Erro:** exceções são tratadas no middleware; nunca retornar corpo de erro manualmente nos controllers para erros genéricos (401, 404, 500).\n- **Códigos de erro:** usar códigos estáveis (ex.: `Unauthorized`, `InvalidCredentials`) para que clientes possam tratar por `error.code`; `message` pode ser localizada ou mais amigável.\n- **Timestamp:** sempre UTC (ISO 8601) para auditoria e debugging.\n\n## Exclusões opcionais\n\n- Endpoints como `/health` que precisam de corpo específico: no filtro, não encapsular quando `context.ActionDescriptor.RouteValues[\"action\"] == \"Health\"` (ou excluir por atributo/controller).\n- Respostas que já são `ProblemDetails` ou outro contrato: o filtro só atua em `OkObjectResult` e `ObjectResult` com 200/201; demais resultados não são alterados.\n\n## Checklist de adoção em novo projeto\n\n1. Criar `ApiResponse<T>`, `ApiErrorResponse` e `ErrorDetail` em `Api/Models`.\n2. Criar `ApiResponseFilter` em `Api/Filters` e registrar em `AddControllers(options => options.Filters.Add<ApiResponseFilter>())`.\n3. Criar `GlobalExceptionMiddleware` em `Api/Middleware`, implementar `MapException` com exceções do projeto e registrar com `app.UseMiddleware<GlobalExceptionMiddleware>()`.\n4. Garantir que JSON use `PropertyNamingPolicy.CamelCase` para que o contrato saia como `success`, `data`, `error`, `timestamp`, `code`, `message`.\n"},"lastSynced":"2026-03-07T13:10:23.594Z","agentAnalysis":{"suitability":{"en":"Ideal for Cloud Agents needing standardized API response handling in AWS Lambda applications.","zh":"适合于需要在 AWS Lambda 应用中标准化 API 响应处理的 Cloud 代理。","ja":"AWS Lambda アプリケーションで標準化された API 応答処理を必要とする Cloud エージェントに適しています。","ko":"AWS Lambda 애플리케이션에서 표준화된 API 응답 처리가 필요한 클라우드 에이전트에 적합합니다.","es":"Ideal para agentes de Cloud que necesitan un manejo de respuestas de API estandarizadas en aplicaciones de AWS Lambda.","fr":"Idéal pour les agents Cloud nécessitant une gestion standardisée des réponses d''API dans les applications AWS Lambda.","de":"Ideal für Cloud-Agents, die ein standardisiertes API-Antwort-Handling in AWS Lambda-Anwendungen benötigen.","pt":"Ideal para agentes de nuvem que necessitam de tratamento de resposta de API padronizado em aplicações AWS Lambda.","ru":"Идеально для облачных агентов, требующих стандартизированного обработки ответов API в приложениях AWS Lambda.","ar":"مثالي لعميل السحابة الذين يحتاجون إلى معالجة استجابة واجهة برمجة التطبيقات الموحدة في تطبيقات AWS Lambda."},"recommendation":{"en":"Empowers agents to standardize API responses, including success and error messages, using a consistent envelope format with ''success'', ''data''/`error`, and ''timestamp'' fields, enabling global exception handling and filtering for 200/201 responses.","zh":"赋予代理标准化 API 响应的能力，包括成功和错误消息，使用一致的封装格式，包含 ''success''、''data''/''error'' 和 ''timestamp'' 字段，实现全局异常处理和 200/201 响应的过滤。","ja":"エージェントに API 応答を標準化する機能を付与し、成功およびエラー メッセージを含む一貫した封装形式 (''success''、''data''/''error''、''timestamp'' フィールド) を使用し、グローバル エラー ハンドリングと 200/201 応答のフィルタリングを可能にします。","ko":"에이전트에 API 응답을 표준화하는 기능을 부여하여 성공 및 오류 메시지를 포함한 일관된封装 형식(''success'', ''data''/''error'', ''timestamp'' 필드)을 사용하여全局 예외 처리 및 200/201 응답 필터링을 가능하게 합니다.","es":"Habilita a los agentes a estandarizar las respuestas de API, incluidos los mensajes de éxito y error, utilizando un formato de sobre consistente con los campos ''success'', ''data''/`error` y ''timestamp'', lo que permite el manejo de excepciones globales y el filtrado de respuestas 200/201.","fr":"Permet aux agents de standardiser les réponses d''API, y compris les messages de réussite et d''erreur, en utilisant un format d''enveloppe cohérent avec les champs ''success'', ''data''/`error` et ''timestamp'', ce qui permet la gestion d''exceptions globales et le filtrage des réponses 200/201.","de":"Ermöglicht es den Agents, API-Antworten zu standardisieren, einschließlich Erfolgs- und Fehlermeldungen, unter Verwendung eines konsistenten Umschlagformats mit den Feldern ''success'', ''data''/`error` und ''timestamp'', was eine globale Ausnahmehandhabung und Filterung von 200/201-Antworten ermöglicht.","pt":"Habilita os agentes a padronizar as respostas da API, incluindo mensagens de sucesso e erro, usando um formato de envelope consistente com campos ''success'', ''data''/`error` e ''timestamp'', permitindo tratamento de exceções global e filtragem para respostas 200/201.","ru":"Наделяет агентов возможностью стандартизировать ответы API, включая сообщения об успехе и ошибке, используя последовательный формат конверта с полями ''success'', ''data''/`error` и ''timestamp'', позволяя глобальное обработку исключений и фильтрацию для ответов 200/201.","ar":"تمكين الوكلاء من توحيد استجابات واجهة برمجة التطبيقات، بما في ذلك رسائل النجاح والخطأ، باستخدام تنسيق غلاف متسق مع مجالات ''success'' و ''data''/`error` و ''timestamp''، مما يسمح بمعالجة الاستثناءات العالمية وتصفية الاستجابات 200/201."},"useCases":{"en":["Standardizing API response formats for AWS Lambda functions","Implementing global error handling for consistent error messages","Creating a unified API response envelope for success and error responses"],"zh":["为 AWS Lambda 函数标准化 API 响应格式","实现全局错误处理以获得一致的错误消息","为成功和错误响应创建统一的 API 响应封装"],"ja":["AWS Lambda 関数の API 応答形式を標準化する","一貫したエラー メッセージを得るためのグローバル エラー ハンドリングを実装する","成功およびエラー 応答のための統一された API 応答封装を作成する"],"ko":["AWS Lambda 함수를 위한 API 응답 형식을 표준화하는 것","일관된 오류 메시지를 얻기 위한 전역 오류 처리를 구현하는 것","성공 및 오류 응답을 위한 통일된 API 응답封装을 생성하는 것"],"es":["Estandarizar formatos de respuestas de API para funciones de AWS Lambda","Implementar un manejo de errores global para mensajes de error coherentes","Crear un sobre de respuesta de API unificado para respuestas de éxito y error"],"fr":["Standardiser les formats de réponses d''API pour les fonctions AWS Lambda","Mettre en œuvre une gestion d''erreurs globale pour des messages d''erreur cohérents","Créer un enveloppe de réponse d''API unifiée pour les réponses de réussite et d''erreur"],"de":["Standardisieren von API-Antwortformaten für AWS Lambda-Funktionen","Implementieren einer globalen Fehlerbehandlung für konsistente Fehlermeldungen","Erstellen eines einheitlichen API-Antwort-Umschlags für Erfolgs- und Fehlerantworten"],"pt":["Padronizar formatos de resposta da API para funções AWS Lambda","Implementar tratamento de erros global para mensagens de erro consistentes","Criar um envelope de resposta da API unificado para respostas de sucesso e erro"],"ru":["Стандартизировать форматы ответов API для функций AWS Lambda","Реализовать глобальное обработку ошибок для последовательных сообщений об ошибках","Создать унифицированный конверт ответа API для ответов об успехе и ошибке"],"ar":["توحيد تنسيقات استجابة واجهة برمجة التطبيقات لتطبيقات AWS Lambda","تنفيذ معالجة الخطأ العالمية لرسائل الخطأ المتسقة","إنشاء غلاف استجابة واجهة برمجة التطبيقات الموحدة لاستجابات النجاح والخطأ"]},"limitations":{"en":["Specific to AWS Lambda applications","Requires JSON formatting for API responses"],"zh":["仅限于 AWS Lambda 应用","需要 JSON 格式的 API 响应"],"ja":["AWS Lambda アプリケーションに特有のもの","API 応答に JSON フォーマットが必要"],"ko":["AWS Lambda 애플리케이션에만 해당함","API 응답에 JSON 형식이 필요함"],"es":["Específico para aplicaciones de AWS Lambda","Requiere formato JSON para respuestas de API"],"fr":["Spécifique aux applications AWS Lambda","Nécessite un formatage JSON pour les réponses d''API"],"de":["Spezifisch für AWS Lambda-Anwendungen","Benötigt JSON-Formatierung für API-Antworten"],"pt":["Específico para aplicações AWS Lambda","Exige formatação JSON para respostas da API"],"ru":["Спецефичный для приложений AWS Lambda","Требует форматирования JSON для ответов API"],"ar":["محدد لتطبيقات AWS Lambda","يتطلب تنسيق JSON لاستجابات واجهة برمجة التطبيقات"]},"version":4},"contentHash":"7a738207f7e3d87e3204bad122ccfcf607cba5f46d7f8eab4b3c1b37ee38376b","qualityScore":51}');
